namespace support8_runtime_paths {
namespace fs = std::filesystem;

static string getenv_or_empty_(const char* name) {
    const char* value = std::getenv(name);
    return value ? string(value) : string();
}

static bool starts_with_(const string& value, const string& prefix) {
    return value.size() >= prefix.size() && value.compare(0, prefix.size(), prefix) == 0;
}

static fs::path detect_workspace_root_() {
    string env_root = getenv_or_empty_("TOP_TREE90_WORKSPACE_ROOT");
    if (!env_root.empty()) return fs::path(env_root);

    fs::path cur = fs::current_path();
    for (fs::path probe = cur; !probe.empty(); probe = probe.parent_path()) {
        if (fs::exists(probe / "branch_4" / "90")) return probe;
        if (probe.filename() == "branch_4" && fs::exists(probe / "90")) return probe.parent_path();
        if (probe.filename() == "90" && probe.parent_path().filename() == "branch_4") return probe.parent_path().parent_path();
        if (probe == probe.root_path()) break;
    }
    return cur;
}

static fs::path detect_branch4_root_() {
    string env_root = getenv_or_empty_("TOP_TREE90_BRANCH4_ROOT");
    if (!env_root.empty()) return fs::path(env_root);

    fs::path workspace_root = detect_workspace_root_();
    if (fs::exists(workspace_root / "branch_4")) return workspace_root / "branch_4";
    if (workspace_root.filename() == "branch_4") return workspace_root;
    return workspace_root;
}

static fs::path detect_archival_bundle_root_() {
    string env_root = getenv_or_empty_("TOP_TREE90_ARCHIVAL_ROOT");
    if (!env_root.empty()) return fs::path(env_root);

    fs::path branch4_root = detect_branch4_root_();
    if (fs::exists(branch4_root / "90")) return branch4_root / "90";
    if (branch4_root.filename() == "90" && branch4_root.parent_path().filename() == "branch_4") return branch4_root;
    return branch4_root;
}

static fs::path runtime_data_root_() {
    static fs::path cached = []() {
        string env_root = getenv_or_empty_("TOP_TREE90_DATA_ROOT");
        if (!env_root.empty()) return fs::path(env_root);

        fs::path archival_root = detect_archival_bundle_root_();
        if (!archival_root.empty() && archival_root != fs::path("/mnt/data")) return archival_root / "runtime";
        if (fs::exists("/mnt/data")) return fs::path("/mnt/data");
        return archival_root.empty() ? fs::current_path() / "runtime" : archival_root / "runtime";
    }();
    return cached;
}

static void ensure_parent_dirs_for_(const fs::path& path) {
    fs::path parent = path.parent_path();
    if (!parent.empty()) fs::create_directories(parent);
}

static string resolve_legacy_data_path_(const string& path) {
    static const string kLegacyPrefix = "/mnt/data/";
    if (!starts_with_(path, kLegacyPrefix)) return path;
    fs::path resolved = runtime_data_root_() / path.substr(kLegacyPrefix.size());
    return resolved.string();
}

static string runtime_bundle_path_(const string& basename) {
    return (runtime_data_root_() / basename).string();
}

static string archival_bundle_path_(const string& basename) {
    return (detect_archival_bundle_root_() / basename).string();
}

static string runtime_summary_() {
    ostringstream oss;
    oss << "workspaceRoot=" << detect_workspace_root_().string()
        << " branch4Root=" << detect_branch4_root_().string()
        << " archivalBundleRoot=" << detect_archival_bundle_root_().string()
        << " runtimeDataRoot=" << runtime_data_root_().string();
    return oss.str();
}
}

