static bool validate_schema_current_n6_regression_free_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                        const vector<GapRuleCandidate>& concrete_gap_rules,
                                                        const vector<SchemaRule>& schema_rules,
                                                        string* why) {
    SchemaCoverageStats stats;
    if (!scan_schema_rule_coverage_randomized_(6,
                                               20260308u,
                                               16,
                                               12,
                                               base_sound_rules,
                                               concrete_gap_rules,
                                               schema_rules,
                                               &stats,
                                               why)) return false;
    if (stats.schema_recovered_pairs != stats.concrete_recovered_pairs ||
        stats.schema_full_match_instances != stats.concrete_full_match_instances ||
        stats.schema_residual_gap_instances != 0) {
        if (why) *why = "schema n=6 regression detected\n" + schema_coverage_stats_to_string_(stats);
        return false;
    }
    return true;
}

static bool validate_schema_current_n7_regression_free_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                        const vector<GapRuleCandidate>& concrete_gap_rules,
                                                        const vector<SchemaRule>& schema_rules,
                                                        string* why) {
    SchemaCoverageStats stats;
    if (!scan_schema_rule_coverage_randomized_n7_(20260308u,
                                                  kSchemaRandomizedN7NumTrees,
                                                  kSchemaRandomizedN7SubsetsPerTree,
                                                  base_sound_rules,
                                                  concrete_gap_rules,
                                                  schema_rules,
                                                  &stats,
                                                  why)) return false;
    if (stats.schema_recovered_pairs != stats.concrete_recovered_pairs ||
        stats.schema_full_match_instances != stats.concrete_full_match_instances ||
        stats.schema_residual_gap_instances != 0) {
        if (why) *why = "schema n=7 regression detected\n" + schema_coverage_stats_to_string_(stats);
        return false;
    }
    return true;
}

static bool validate_schema_matches_concrete_on_current_n5_sample_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                                   const vector<GapRuleCandidate>& concrete_gap_rules,
                                                                   const vector<SchemaRule>& schema_rules,
                                                                   string* why) {
    auto instances = sample_canonical_sparse_instances_randomized_(5,
                                                                   kResidualGapRandomizedSeed,
                                                                   kResidualGapRandomizedNumTrees,
                                                                   kResidualGapRandomizedSubsetsPerTree);
    auto concrete_aug_rules = merge_sparse_rule_sets_(base_sound_rules,
                                                      concrete_gap_rules);
    for (const auto& inst : instances) {
        auto concrete = run_sparse_candidate_closure_(inst, concrete_aug_rules);
        auto schema = run_sparse_schema_augmented_closure_(inst, base_sound_rules, schema_rules);
        if (!concrete.consistent) {
            if (why) *why = "concrete augmented closure inconsistent on current n=5 sample";
            return false;
        }
        if (!schema.consistent) {
            if (why) *why = "schema closure inconsistent on current n=5 sample: " + schema.why;
            return false;
        }
        if (concrete.state.known_lca != schema.state.known_lca) {
            if (why) {
                *why = "schema vs concrete mismatch on current n=5 sample\ninstance=" + sparse_instance_to_string_(inst)
                     + "\nconcrete=" + sparse_known_lca_to_string_(concrete.state)
                     + "\nschema=" + sparse_known_lca_to_string_(schema.state);
            }
            return false;
        }
    }
    return true;
}

static SparseLcaInstance minimize_schema_residual_gap_core_(const SparseLcaInstance& instance,
                                                            const SparseLcaConstraint& target,
                                                            const vector<SparseRuleCandidate>& base_sound_rules,
                                                            const vector<SchemaRule>& schema_rules,
                                                            string* why) {
    auto fail = [&](const string& msg) { if (why) *why = msg; };
    SparseLcaInstance base = normalize_sparse_instance_basic_(instance);
    vector<SparseLcaConstraint> cons = base.constraints;
    size_t m = cons.size();
    bool found = false;
    SparseLcaInstance best;
    size_t best_size = numeric_limits<size_t>::max();
    string best_fp;
    size_t subsets = 1ull << m;
    for (size_t mask = 0; mask < subsets; ++mask) {
        SparseLcaInstance cand;
        cand.n = base.n;
        for (size_t i = 0; i < m; ++i) if (mask & (1ull << i)) cand.constraints.push_back(cons[i]);
        string oracle_why;
        auto oracle = exact_sparse_completion_oracle_(cand, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        auto it_forced = oracle.forced_pairwise_lca.find({min(target.u, target.v), max(target.u, target.v)});
        int forced = (it_forced == oracle.forced_pairwise_lca.end()) ? -1 : it_forced->second;
        if (forced != target.w) continue;
        auto closure = run_sparse_schema_augmented_closure_(cand, base_sound_rules, schema_rules);
        if (!closure.consistent) continue;
        int got = -1;
        if (lookup_known_lca_in_map_(closure.state.known_lca, target.u, target.v, &got) && got == target.w) continue;
        string fp = canonical_gap_family_fingerprint_(cand, target);
        if (!found || cand.constraints.size() < best_size ||
            (cand.constraints.size() == best_size && fp < best_fp)) {
            found = true;
            best = cand;
            best_size = cand.constraints.size();
            best_fp = fp;
        }
    }
    if (!found) {
        fail("no deletion-minimal schema residual gap core found");
        return SparseLcaInstance{};
    }
    return best;
}

static vector<SchemaResidualGapWitness> collect_schema_residual_gap_witnesses_(int n,
                                                                               uint32_t seed,
                                                                               int num_trees,
                                                                               int num_subsets_per_tree,
                                                                               const vector<SparseRuleCandidate>& base_sound_rules,
                                                                               const vector<SchemaRule>& schema_rules,
                                                                               string* why) {
    auto fail = [&](const string& msg) {
        if (why) *why = msg;
        return vector<SchemaResidualGapWitness>{};
    };
    vector<SchemaResidualGapWitness> out;
    auto instances = sample_canonical_sparse_instances_randomized_(n, seed, num_trees, num_subsets_per_tree);
    for (const auto& inst : instances) {
        string oracle_why;
        auto oracle = exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        auto schema = run_sparse_schema_augmented_closure_(inst, base_sound_rules, schema_rules);
        if (!schema.consistent) return fail("schema closure inconsistent while collecting schema residual witnesses: " + schema.why);
        auto missing = missing_forced_pairs_(schema, oracle);
        for (const auto& target : missing) {
            string min_why;
            auto core = minimize_schema_residual_gap_core_(inst, target, base_sound_rules, schema_rules, &min_why);
            if (core.n == 0) return fail("failed to minimize schema residual gap core: " + min_why);
            SchemaResidualGapWitness w;
            w.instance = inst;
            w.missing_target = normalize_sparse_constraint_(target);
            w.minimal_gap_core = core;
            w.family_fingerprint = canonical_gap_family_fingerprint_(core, target);
            out.push_back(w);
        }
    }
    sort(out.begin(), out.end(), [](const SchemaResidualGapWitness& a, const SchemaResidualGapWitness& b) {
        if (a.minimal_gap_core.constraints.size() != b.minimal_gap_core.constraints.size()) return a.minimal_gap_core.constraints.size() < b.minimal_gap_core.constraints.size();
        if (a.family_fingerprint != b.family_fingerprint) return a.family_fingerprint < b.family_fingerprint;
        return canonical_sparse_instance_fingerprint_(a.instance) < canonical_sparse_instance_fingerprint_(b.instance);
    });
    return out;
}

static vector<ResidualGapFamilySummary> classify_schema_residual_gap_families_(const vector<SchemaResidualGapWitness>& witnesses) {
    map<string, ResidualGapFamilySummary> agg;
    for (const auto& w : witnesses) {
        auto& slot = agg[w.family_fingerprint];
        if (slot.family_fingerprint.empty()) {
            slot.family_fingerprint = w.family_fingerprint;
            slot.target_fingerprint = canonical_gap_target_fingerprint_(w.missing_target);
            slot.representative_core = w.minimal_gap_core;
            slot.representative_target = w.missing_target;
        }
        ++slot.witness_count;
        if (slot.sample_instances.size() < 3) slot.sample_instances.push_back(w.instance);
    }
    vector<ResidualGapFamilySummary> out;
    for (auto& kv : agg) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const ResidualGapFamilySummary& a, const ResidualGapFamilySummary& b) {
        if (a.witness_count != b.witness_count) return a.witness_count > b.witness_count;
        return a.family_fingerprint < b.family_fingerprint;
    });
    return out;
}

static string classify_schema_promotion_status_(const SchemaStressStats& stats) {
    if (!stats.local_exact_pass) {
        return schema_promotion_status_to_string_(SchemaPromotionStatus::LocalExactOnly);
    }
    if (stats.one_extra_exact_attempted && stats.one_extra_exact_pass &&
        stats.current_n5_matches_concrete && stats.sampled_n6_pass && stats.sampled_n7_pass && stats.sampled_n8_pass &&
        stats.sampled_n7_residual_instances == 0 && stats.sampled_n8_residual_instances == 0) {
        return schema_promotion_status_to_string_(SchemaPromotionStatus::StrongEmpiricalCandidate);
    }
    if (stats.one_extra_exact_attempted && stats.one_extra_exact_pass) {
        return schema_promotion_status_to_string_(SchemaPromotionStatus::ExactPlusOneSupported);
    }
    if (stats.current_n5_matches_concrete) {
        return schema_promotion_status_to_string_(SchemaPromotionStatus::CurrentSampleSupported);
    }
    return schema_promotion_status_to_string_(SchemaPromotionStatus::LocalExactOnly);
}

static SchemaStressStats build_schema_stress_profile_(const SchemaRule& schema,
                                                      const vector<SchemaRuleFamilySummary>& families,
                                                      bool current_n5_matches_concrete,
                                                      const SchemaCoverageStats& n6_stats,
                                                      const SchemaCoverageStats& n7_stats,
                                                      const SchemaCoverageStats& n8_stats,
                                                      string* why) {
    SchemaStressStats stats;
    auto canon = canonicalize_schema_rule_(schema);
    stats.schema_fingerprint = canon.fingerprint;
    stats.human_readable_schema = canon.human_readable_schema;
    stats.support_size = schema_support_size_(canon);
    auto fam_it = find_if(families.begin(), families.end(), [&](const SchemaRuleFamilySummary& fam){ return fam.fingerprint == canon.fingerprint; });
    if (fam_it != families.end()) {
        stats.concrete_rule_count = fam_it->concrete_rule_count;
        stats.concrete_support = fam_it->total_support;
    }
    string local_why;
    stats.local_exact_pass = validate_schema_rule_local_exact_(canon, &local_why);
    if (!stats.local_exact_pass) {
        stats.why = local_why;
        stats.promotion_status = classify_schema_promotion_status_(stats);
        if (why) *why = local_why;
        return stats;
    }
    string ext_why;
    validate_schema_rule_exact_extension_(canon, stats.support_size + 1, &stats, &ext_why);
    if (!ext_why.empty()) stats.why = ext_why;
    stats.current_n5_matches_concrete = current_n5_matches_concrete;
    stats.sampled_n6_instances = n6_stats.canonical_instances;
    stats.sampled_n6_forced_pairs = n6_stats.total_forced_pairs;
    stats.sampled_n6_pass = (n6_stats.schema_residual_gap_instances == 0 &&
                             n6_stats.schema_full_match_instances == n6_stats.satisfiable_instances &&
                             n6_stats.canonical_instances > 0);
    stats.sampled_n7_instances = n7_stats.canonical_instances;
    stats.sampled_n7_forced_pairs = n7_stats.total_forced_pairs;
    stats.sampled_n7_residual_instances = n7_stats.schema_residual_gap_instances;
    stats.sampled_n7_pass = (n7_stats.schema_residual_gap_instances == 0 &&
                             n7_stats.schema_full_match_instances == n7_stats.satisfiable_instances &&
                             n7_stats.canonical_instances > 0);
    stats.sampled_n8_instances = n8_stats.canonical_instances;
    stats.sampled_n8_forced_pairs = n8_stats.total_forced_pairs;
    stats.sampled_n8_residual_instances = n8_stats.schema_residual_gap_instances;
    stats.sampled_n8_pass = (n8_stats.schema_residual_gap_instances == 0 &&
                             n8_stats.schema_full_match_instances == n8_stats.satisfiable_instances &&
                             n8_stats.canonical_instances > 0);
    stats.promotion_status = classify_schema_promotion_status_(stats);
    return stats;
}

static vector<SchemaStressStats> build_all_schema_stress_profiles_(const vector<SchemaRule>& schemas,
                                                                   const vector<SchemaRuleFamilySummary>& families,
                                                                   bool current_n5_matches_concrete,
                                                                   const SchemaCoverageStats& n6_stats,
                                                                   const SchemaCoverageStats& n7_stats,
                                                                   const SchemaCoverageStats& n8_stats,
                                                                   string* why) {
    vector<SchemaStressStats> out;
    for (const auto& schema : schemas) {
        string local_why;
        out.push_back(build_schema_stress_profile_(schema, families, current_n5_matches_concrete, n6_stats, n7_stats, n8_stats, &local_why));
        if (!local_why.empty() && why && why->empty()) *why = local_why;
    }
    sort(out.begin(), out.end(), [](const SchemaStressStats& a, const SchemaStressStats& b) {
        if (a.concrete_support != b.concrete_support) return a.concrete_support > b.concrete_support;
        return a.schema_fingerprint < b.schema_fingerprint;
    });
    return out;
}

static bool validate_minimal_ambiguous_anchor_(string* why) {
    SparseLcaInstance inst{4, {}};
    inst = canonicalize_sparse_instance_(inst);
    auto oracle = exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), why);
    if (!oracle.satisfiable) {
        if (why) *why = "minimal ambiguous anchor should be satisfiable";
        return false;
    }
    if (oracle.solution_count != 16) {
        if (why) *why = "minimal ambiguous anchor expected solution_count=16 but got " + to_string(oracle.solution_count);
        return false;
    }
    return true;
}

static bool validate_minimal_unique_anchor_(string* why) {
    SparseLcaInstance inst{4, {{2,3,4}}};
    inst = canonicalize_sparse_instance_(inst);
    auto oracle = exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), why);
    if (!oracle.satisfiable) {
        if (why) *why = "minimal unique anchor should be satisfiable";
        return false;
    }
    if (oracle.solution_count != 1) {
        if (why) *why = "minimal unique anchor expected solution_count=1 but got " + to_string(oracle.solution_count);
        return false;
    }
    return true;
}


static int lookup_table_or_(const map<pair<int,int>, int>& table, int u, int v, int fallback = -1) {
    auto it = table.find({u,v});
    return it == table.end() ? fallback : it->second;
}
static unordered_map<int,int> expected_link_full_parent_map_(const StaticRootedView& before_view,
                                                             int u, int v) {
    auto Cu = component_vertices_of_(before_view, u);
    auto Cv = component_vertices_of_(before_view, v);
    unordered_map<int,int> expected = restricted_parent_map_(before_view, Cv);
    auto rerooted = rerooted_parent_map_(before_view, Cu, u);
    for (auto& kv : rerooted) expected[kv.first] = kv.second;
    expected[u] = v;
    return expected;
}
static string make_link_static_law_failure_dump_(const SemanticSnapshot& before,
                                                 const SemanticSnapshot& after,
                                                 int u, int v, int eid,
                                                 const string& why) {
    StaticRootedView bv = make_static_rooted_view_(before);
    StaticRootedView av = make_static_rooted_view_(after);
    ensure_vertices_in_view_(bv, {u, v});
    ensure_vertices_in_view_(av, {u, v});
    auto Cu = component_vertices_of_(bv, u);
    auto Cv = component_vertices_of_(bv, v);
    vector<int> affected = Cu;
    affected.insert(affected.end(), Cv.begin(), Cv.end());
    affected = sorted_unique_copy_(affected);
    auto expected_parent = expected_link_full_parent_map_(bv, u, v);
    auto expected_lca = lca_table_from_parent_(affected, expected_parent);
    auto actual_parent = restricted_parent_map_(av, affected);
    auto actual_lca = extract_component_lca_table_(av, affected);
    ostringstream oss;
    oss << "LinkStaticLaw failure: " << why << "\n";
    oss << "u=" << u << " v=" << v << " eid=" << eid << "\n";
    oss << "before snapshot:\n" << semantic_snapshot_to_string(before) << "\n";
    oss << "after snapshot:\n" << semantic_snapshot_to_string(after) << "\n";
    oss << "before component partition:\n" << component_partition_to_string_(bv.component_vertices) << "\n";
    oss << "after component partition:\n" << component_partition_to_string_(av.component_vertices) << "\n";
    oss << "before pairwise LCA table:\n" << pairwise_lca_table_to_string_(extract_component_lca_table_(bv, affected)) << "\n";
    oss << "after pairwise LCA table:\n" << pairwise_lca_table_to_string_(actual_lca) << "\n";
    oss << "expected parent map:\n" << parent_map_to_string_(expected_parent) << "\n";
    oss << "actual parent map:\n" << parent_map_to_string_(actual_parent) << "\n";
    oss << "expected table:\n" << pairwise_lca_table_to_string_(expected_lca) << "\n";
    oss << "actual table:\n" << pairwise_lca_table_to_string_(actual_lca) << "\n";
    return oss.str();
}
