static string sparse_oracle_outcome_summary_(const SparseOracleOutcome& out) {
    vector<string> bits;
    if (out.uniqueness_equiv_failed) bits.push_back("uniquenessEquiv=counterexample");
    if (out.forced_parent_equiv_failed) bits.push_back("parentEquiv=counterexample");
    if (out.forced_lca_reconstruct_failed) bits.push_back("forcedLcaReconstruct=counterexample");
    if (bits.empty()) return "none";
    ostringstream oss;
    for (size_t i = 0; i < bits.size(); ++i) { if (i) oss << ' '; oss << bits[i]; }
    return oss.str();
}

static string sparse_counterexample_to_string_(const SparseOracleCounterexample& ex) {
    ostringstream oss;
    if (!ex.why.empty()) oss << ex.why << "\n";
    oss << sparse_witness_record_to_string_(ex.witness);
    return oss.str();
}
static void reset_invariant_stats_() { g_invariant_stats = {}; }
static void record_invariant_stats_(const SemanticSnapshot& s) {
    ++g_invariant_stats.validated_snapshots;
    if (s.has_payload) ++g_invariant_stats.snapshots_with_payload;
    if (!s.exposed_vertices.empty()) ++g_invariant_stats.snapshots_with_exposed_path;
    if (!s.pref_active_edges.empty()) ++g_invariant_stats.snapshots_with_preferred_edges;
    if (!s.active_zip_pairs.empty()) ++g_invariant_stats.snapshots_with_zip_pairs;
}

static bool validate_snapshot_invariants_(const SemanticSnapshot& s, string* why) {
    auto fail = [&](const string& msg) -> bool {
        if (why) *why = msg;
        return false;
    };
    if (!is_sorted_unique_vec_(s.active_edge_ids)) return fail("active_edge_ids must be sorted and unique");
    if (!is_sorted_unique_vec_(s.active_edge_endpoints)) return fail("active_edge_endpoints must be sorted and unique");
    if (!is_sorted_unique_vec_(s.represented_active_nodes)) return fail("represented_active_nodes must be sorted and unique");
    if (!is_sorted_unique_vec_(s.represented_parent_nodes)) return fail("represented_parent_nodes must be sorted and unique");
    if (!is_sorted_unique_vec_(s.represented_root_nodes)) return fail("represented_root_nodes must be sorted and unique");
    if (!is_sorted_unique_vec_(s.rooted_vertex_parent)) return fail("rooted_vertex_parent must be sorted and unique");
    if (!is_sorted_unique_vec_(s.rooted_vertex_root)) return fail("rooted_vertex_root must be sorted and unique");
    if (!is_sorted_unique_vec_(s.rooted_component_roots)) return fail("rooted_component_roots must be sorted and unique");
    if (s.include_preferred_state) {
        if (!is_sorted_unique_vec_(s.preferred_child)) return fail("preferred_child must be sorted and unique");
        if (!is_sorted_unique_vec_(s.preferred_parent)) return fail("preferred_parent must be sorted and unique");
        if (!is_sorted_unique_vec_(s.pref_active_edges)) return fail("pref_active_edges must be sorted and unique");
        if (!is_sorted_unique_vec_(s.pref_owner)) return fail("pref_owner must be sorted and unique");
        if (!is_sorted_unique_vec_(s.pref_inc)) return fail("pref_inc must be sorted and unique");
        if (!is_sorted_unique_vec_(s.active_zip_pairs)) return fail("active_zip_pairs must be sorted and unique");
        if (!is_sorted_unique_vec_(s.active_zip_levels)) return fail("active_zip_levels must be sorted and unique");
        if (!is_sorted_unique_vec_(s.active_zip_dirlevels)) return fail("active_zip_dirlevels must be sorted and unique");
    }

    unordered_set<int> active_set(s.active_edge_ids.begin(), s.active_edge_ids.end());
    vector<int> endpoint_ids;
    endpoint_ids.reserve(s.active_edge_endpoints.size());
    unordered_map<int, pair<int,int>> edge_endpoints;
    for (auto [eid, u, v] : s.active_edge_endpoints) {
        endpoint_ids.push_back(eid);
        edge_endpoints[eid] = {u, v};
        if (!active_set.count(eid)) return fail("active_edge_endpoints references inactive edge");
        if (u <= 0 || v <= 0) return fail("edge endpoints must be positive vertices");
        if (u == v) return fail("tree edge cannot connect a vertex to itself");
    }
    sort(endpoint_ids.begin(), endpoint_ids.end());
    if (endpoint_ids != s.active_edge_ids) return fail("active_edge_endpoints must cover exactly active_edge_ids");

    unordered_set<int> represented_active(s.represented_active_nodes.begin(), s.represented_active_nodes.end());
    for (int eid : s.active_edge_ids) {
        if (!represented_active.count(-eid - 1)) return fail("represented_active_nodes must include every active edge node");
    }
    for (int node : s.represented_active_nodes) {
        if (node < 0 && !active_set.count(-node - 1)) return fail("represented_active_nodes contains inactive edge node");
    }

    map<int,int> represented_parent;
    for (auto [child, parent] : s.represented_parent_nodes) {
        if (!represented_active.count(child)) return fail("represented_parent_nodes child is not active");
        if (!represented_active.count(parent)) return fail("represented_parent_nodes parent is not active");
        if (child == parent) return fail("represented_parent_nodes contains self-loop");
        if (represented_parent.count(child)) return fail("represented_parent_nodes gives multiple parents to one node");
        represented_parent[child] = parent;
    }
    for (int node : s.represented_active_nodes) {
        unordered_set<int> vis;
        int cur = node;
        while (represented_parent.count(cur)) {
            if (!vis.insert(cur).second) return fail("represented_parent_nodes contains a cycle");
            cur = represented_parent[cur];
        }
    }
    vector<pair<int,int>> expected_represented_roots;
    for (int node : s.represented_active_nodes) {
        int cur = node;
        unordered_set<int> vis;
        while (represented_parent.count(cur) && !vis.count(cur)) {
            vis.insert(cur);
            cur = represented_parent[cur];
        }
        expected_represented_roots.push_back({node, cur});
    }
    sort(expected_represented_roots.begin(), expected_represented_roots.end());
    if (expected_represented_roots != s.represented_root_nodes) return fail("represented_root_nodes must equal represented_parent_nodes closure");

    vector<int> active_vertices;
    for (int node : s.represented_active_nodes) if (node > 0) active_vertices.push_back(node);
    unordered_set<int> active_vertex_set(active_vertices.begin(), active_vertices.end());
    map<int,int> rooted_parent;
    for (auto [child, parent] : s.rooted_vertex_parent) {
        if (child <= 0 || parent <= 0) return fail("rooted_vertex_parent must contain positive vertex ids only");
        if (!active_vertex_set.count(child) || !active_vertex_set.count(parent)) return fail("rooted_vertex_parent references vertex outside represented_active_nodes");
        if (child == parent) return fail("rooted_vertex_parent contains self-loop");
        if (rooted_parent.count(child)) return fail("rooted_vertex_parent gives multiple parents to one vertex");
        rooted_parent[child] = parent;
    }
    for (int v : active_vertices) {
        unordered_set<int> vis;
        int cur = v;
        while (rooted_parent.count(cur)) {
            if (!vis.insert(cur).second) return fail("rooted_vertex_parent contains a cycle");
            cur = rooted_parent[cur];
        }
    }
    vector<pair<int,int>> expected_vertex_roots;
    for (int v : active_vertices) {
        int cur = v;
        unordered_set<int> vis;
        while (rooted_parent.count(cur) && !vis.count(cur)) {
            vis.insert(cur);
            cur = rooted_parent[cur];
        }
        expected_vertex_roots.push_back({v, cur});
    }
    sort(expected_vertex_roots.begin(), expected_vertex_roots.end());
    if (expected_vertex_roots != s.rooted_vertex_root) return fail("rooted_vertex_root must equal rooted_vertex_parent closure");
    vector<int> expected_component_roots;
    for (auto [v, r] : expected_vertex_roots) expected_component_roots.push_back(r);
    sort(expected_component_roots.begin(), expected_component_roots.end());
    expected_component_roots.erase(unique(expected_component_roots.begin(), expected_component_roots.end()), expected_component_roots.end());
    if (expected_component_roots != s.rooted_component_roots) return fail("rooted_component_roots must equal unique roots from rooted_vertex_root");

    unordered_map<int,int> child_edge;
    for (int eid : s.active_edge_ids) {
        int e = -eid - 1;
        auto [u, v] = edge_endpoints[eid];
        bool uv = represented_parent.count(e) && represented_parent[e] == u && represented_parent.count(v) && represented_parent[v] == e;
        bool vu = represented_parent.count(e) && represented_parent[e] == v && represented_parent.count(u) && represented_parent[u] == e;
        if (uv == vu) return fail("each active edge must induce exactly one owner-child orientation in represented_parent_nodes");
        int parent = uv ? u : v;
        int child = uv ? v : u;
        auto it = rooted_parent.find(child);
        if (it == rooted_parent.end() || it->second != parent) return fail("rooted_vertex_parent must agree with active edge orientation");
        if (child_edge.count(child) && child_edge[child] != eid) return fail("a rooted child vertex cannot be claimed by multiple active edges");
        child_edge[child] = eid;
    }

    if (s.exposed_vertices.empty()) {
        if (!s.exposed_edges.empty()) return fail("exposed_edges must be empty when exposed_vertices is empty");
    } else {
        vector<int> path = s.exposed_vertices;
        if (!is_sorted_unique_vec_(sorted_unique_copy_(path))) {
            // paths can repeat only if invalid; in a tree path vertices are unique
            if (path.size() != sorted_unique_copy_(path).size()) return fail("exposed_vertices must be a simple path");
        }
        if (s.exposed_edges.size() + 1 != s.exposed_vertices.size()) return fail("exposed_edges size must be path length minus one");
    }

    return true;
}

static string static_law_stats_to_string_(const StaticLawStats& s) {
    ostringstream oss;
    oss << "lcaReconstruct=" << s.lca_reconstruct_pass << "/" << s.lca_reconstruct_checks;
    oss << " linkStrong=" << s.link_strong_pass << "/" << s.link_strong_checks;
    oss << " linkLca=" << s.link_lca_pass << "/" << s.link_lca_checks;
    oss << " linkLcaReconstruct=" << s.link_lca_reconstruct_pass << "/" << s.link_lca_reconstruct_checks;
    oss << " cutC=" << s.cut_candidate_C_pass << "/" << s.cut_candidate_C_checks;
    oss << " cutD=" << s.cut_candidate_D_pass << "/" << s.cut_candidate_D_checks;
    oss << " cutDReconstruct=" << s.cut_candidate_D_reconstruct_pass << "/" << s.cut_candidate_D_reconstruct_checks;
    return oss.str();
}
static string static_law_outcome_summary_(const StaticLawOutcome& o) {
    ostringstream oss;
    oss << "lcaReconstruct=" << (o.lca_reconstruct_failed ? "counterexample" : "none");
    oss << " linkStrong=" << (o.link_strong_failed ? "counterexample" : "none");
    oss << " linkLca=" << (o.link_lca_failed ? "counterexample" : "none");
    oss << " linkLcaReconstruct=" << (o.link_lca_reconstruct_failed ? "counterexample" : "none");
    oss << " cutC=" << (o.cut_candidate_C_failed ? "counterexample" : "none");
    oss << " cutD=" << (o.cut_candidate_D_failed ? "counterexample" : "none");
    oss << " cutDReconstruct=" << (o.cut_candidate_D_reconstruct_failed ? "counterexample" : "none");
    return oss.str();
}

static string law_failure_record_to_string(const LawFailureRecord& fr) {
    ostringstream oss;
    if (!fr.law_name.empty()) oss << "law_name=" << fr.law_name << "\n";
    oss << "failing_step=" << fr.failing_step << "\n";
    if (!fr.failing_where.empty()) oss << "failing_where=" << fr.failing_where << "\n";
    if (!fr.first_diverging_helper_substep.empty()) oss << "first_diverging_helper_substep=" << fr.first_diverging_helper_substep << "\n";
    if (!fr.family_fingerprint.empty()) oss << "family_fingerprint=" << fr.family_fingerprint << "\n";
    oss << "ops:\n" << public_ops_to_string(fr.ops) << "\n";
    oss << fr.failure_dump;
    return oss.str();
}

static string extract_line_suffix_(const string& dump, const string& prefix) {
    istringstream iss(dump);
    string line;
    while (getline(iss, line)) if (line.rfind(prefix, 0) == 0) return line.substr(prefix.size());
    return {};
}
static string extract_failure_where_(const string& dump) {
    string s = extract_line_suffix_(dump, "Differential mismatch at ");
    if (!s.empty()) return s;
    s = extract_line_suffix_(dump, "Helper substep differential mismatch at ");
    if (!s.empty()) return s;
    s = extract_line_suffix_(dump, "Snapshot invariant violation at ");
    if (!s.empty()) return s;
    return {};
}
static string failure_record_to_string(const FailureRecord& fr) {
    ostringstream oss;
    oss << "failing_step=" << fr.failing_step << "\n";
    if (!fr.failing_where.empty()) oss << "failing_where=" << fr.failing_where << "\n";
    if (!fr.first_diverging_helper_substep.empty()) oss << "first_diverging_helper_substep=" << fr.first_diverging_helper_substep << "\n";
    oss << "ops:\n" << public_ops_to_string(fr.ops) << "\n";
    oss << fr.failure_dump;
    return oss.str();
}

template <class Pred>
static size_t minimize_failing_prefix_length_(size_t n, Pred pred) {
    size_t lo = 1, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (pred(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

static string semantic_snapshot_fingerprint_(const SemanticSnapshot& s) {
    return semantic_snapshot_to_string(s);
}


static bool record_law_failure_once_(StaticLawOutcome* outcome, const LawFailureRecord& record) {
    if (!outcome) return false;
    if (record.law_name == "LcaReconstructionTheorem") {
        if (outcome->lca_reconstruct_failed) return false;
        outcome->lca_reconstruct_failed = true;
        outcome->lca_reconstruct_failure = record;
        return true;
    }
    if (record.law_name == "LinkStaticLaw") {
        if (outcome->link_strong_failed) return false;
        outcome->link_strong_failed = true;
        outcome->link_strong_failure = record;
        return true;
    }
    if (record.law_name == "LinkLCABridgeLaw") {
        if (outcome->link_lca_failed) return false;
        outcome->link_lca_failed = true;
        outcome->link_lca_failure = record;
        return true;
    }
    if (record.law_name == "LinkLCABridgePlusReconstruction") {
        if (outcome->link_lca_reconstruct_failed) return false;
        outcome->link_lca_reconstruct_failed = true;
        outcome->link_lca_reconstruct_failure = record;
        return true;
    }
    if (record.law_name == "CutStaticLawCandidateC") {
        if (outcome->cut_candidate_C_failed) return false;
        outcome->cut_candidate_C_failed = true;
        outcome->cut_candidate_C_failure = record;
        return true;
    }
    if (record.law_name == "CutLCABridgeLawCandidateD") {
        if (outcome->cut_candidate_D_failed) return false;
        outcome->cut_candidate_D_failed = true;
        outcome->cut_candidate_D_failure = record;
        return true;
    }
    if (record.law_name == "CutLCABridgeLawCandidateDPlusReconstruction") {
        if (outcome->cut_candidate_D_reconstruct_failed) return false;
        outcome->cut_candidate_D_reconstruct_failed = true;
        outcome->cut_candidate_D_reconstruct_failure = record;
        return true;
    }
    return false;
}
static bool has_any_law_failure_(const StaticLawOutcome& outcome) {
    return outcome.lca_reconstruct_failed || outcome.link_strong_failed || outcome.link_lca_failed ||
           outcome.link_lca_reconstruct_failed || outcome.cut_candidate_C_failed ||
           outcome.cut_candidate_D_failed || outcome.cut_candidate_D_reconstruct_failed;
}
static LawFailureRecord make_law_failure_record_(const string& law_name,
                                                 uint32_t seed,
                                                 const vector<PublicOp>& ops_prefix,
                                                 size_t failing_step,
                                                 const string& failing_where,
                                                 const string& first_diverging_helper_substep,
                                                 const string& failure_dump,
                                                 const string& family_fingerprint = string()) {
    LawFailureRecord rec;
    rec.law_name = law_name;
    rec.seed = seed;
    rec.ops = ops_prefix;
    rec.failing_step = failing_step;
    rec.failing_where = failing_where;
    rec.first_diverging_helper_substep = first_diverging_helper_substep;
    rec.family_fingerprint = family_fingerprint;
    rec.failure_dump = failure_dump;
    return rec;
}
static bool evaluate_static_laws_for_transition_(const vector<PublicOp>& ops_prefix,
                                                 size_t step_index,
                                                 const PublicOp& op,
                                                 const SemanticSnapshot& before,
                                                 const SemanticSnapshot& after,
                                                 StaticLawStats* stats,
                                                 StaticLawOutcome* outcome,
                                                 LawFailureRecord* immediate_failure,
                                                 bool stop_on_failure,
                                                 uint32_t seed = 0) {
    auto emit_failure = [&](const string& law_name, const string& dump, const string& family_fingerprint = string()) -> bool {
        LawFailureRecord rec = make_law_failure_record_(law_name, seed, ops_prefix, step_index,
                                                        public_op_to_string(op), string(), dump,
                                                        family_fingerprint);
        record_law_failure_once_(outcome, rec);
        if (immediate_failure && immediate_failure->law_name.empty()) *immediate_failure = rec;
        return !stop_on_failure;
    };
    string why;
    bool ok_to_continue = true;

    if (stats) ++stats->lca_reconstruct_checks;
    if (validate_lca_reconstruction_theorem_(after, &why)) {
        if (stats) ++stats->lca_reconstruct_pass;
    } else {
        ok_to_continue = emit_failure("LcaReconstructionTheorem",
                                      make_lca_reconstruction_failure_dump_(after, why));
        if (!ok_to_continue) return false;
    }
    why.clear();

    switch (op.kind) {
        case PublicOpKind::Link: {
            if (stats) ++stats->link_strong_checks;
            if (validate_link_static_law_(before, after, op.a, op.b, op.c, &why)) {
                if (stats) ++stats->link_strong_pass;
            } else {
                ok_to_continue = emit_failure("LinkStaticLaw",
                                              make_link_static_law_failure_dump_(before, after, op.a, op.b, op.c, why));
                if (!ok_to_continue) return false;
            }
            why.clear();
            if (stats) ++stats->link_lca_checks;
            if (validate_link_lca_bridge_law_(before, after, op.a, op.b, op.c, &why)) {
                if (stats) ++stats->link_lca_pass;
            } else {
                ok_to_continue = emit_failure("LinkLCABridgeLaw",
                                              make_link_lca_bridge_failure_dump_(before, after, op.a, op.b, op.c, why));
                if (!ok_to_continue) return false;
            }
            why.clear();
            if (stats) ++stats->link_lca_reconstruct_checks;
            if (validate_link_lca_bridge_implies_reconstruction_(before, after, op.a, op.b, op.c, &why)) {
                if (stats) ++stats->link_lca_reconstruct_pass;
                return true;
            }
            return emit_failure("LinkLCABridgePlusReconstruction",
                                make_link_lca_reconstruction_failure_dump_(before, after, op.a, op.b, op.c, why));
        }
        case PublicOpKind::Cut: {
            string family = cut_delta_fingerprint_(before, after, op.a);
            if (stats) ++stats->cut_candidate_C_checks;
            if (validate_cut_static_law_candidate_C_(before, after, op.a, &why)) {
                if (stats) ++stats->cut_candidate_C_pass;
            } else {
                ok_to_continue = emit_failure("CutStaticLawCandidateC",
                                              make_cut_candidate_failure_dump_("CutStaticLawCandidateC", before, after, op.a, why, true, true),
                                              family);
                if (!ok_to_continue) return false;
            }
            why.clear();
            if (stats) ++stats->cut_candidate_D_checks;
            if (validate_cut_lca_bridge_law_candidate_D_(before, after, op.a, &why)) {
                if (stats) ++stats->cut_candidate_D_pass;
            } else {
                ok_to_continue = emit_failure("CutLCABridgeLawCandidateD",
                                              make_cut_candidate_failure_dump_("CutLCABridgeLawCandidateD", before, after, op.a, why, false, false),
                                              family);
                if (!ok_to_continue) return false;
            }
            why.clear();
            if (stats) ++stats->cut_candidate_D_reconstruct_checks;
            if (validate_cut_candidate_D_implies_reconstruction_(before, after, op.a, &why)) {
                if (stats) ++stats->cut_candidate_D_reconstruct_pass;
                return true;
            }
            return emit_failure("CutLCABridgeLawCandidateDPlusReconstruction",
                                make_cut_candidate_D_reconstruction_failure_dump_(before, after, op.a, why),
                                family);
        }
        default:
            return true;
    }
}

static bool run_sequence_with_law_checks_(const vector<PublicOp>& ops,
                                          LawFailureRecord* out,
                                          StaticLawStats* stats = nullptr,
                                          StaticLawOutcome* outcome = nullptr,
                                          SemanticSnapshot* final_snap = nullptr,
                                          bool stop_on_law_failure = true,
                                          bool only_last_transition = false,
                                          uint32_t seed = 0) {
    if (out) *out = LawFailureRecord{};
    DifferentialHarness h(kPublicOpLevels);
    SemanticSnapshot last_snap;
    try {
        last_snap = h.snapshot("law_replay(initial)");
        string why;
        if (!validate_snapshot_invariants_(last_snap, &why)) {
            throw runtime_error("Snapshot invariant violation at initial state\n" + why + "\n" + semantic_snapshot_to_string(last_snap));
        }
        record_invariant_stats_(last_snap);
    } catch (const exception& e) {
        if (out) {
            *out = make_law_failure_record_("StrictFailure", seed, ops, 0,
                                            extract_failure_where_(e.what()),
                                            extract_line_suffix_(e.what(), "first diverging helper substep: "),
                                            e.what());
        }
        return false;
    }
    for (size_t i = 0; i < ops.size(); ++i) {
        try {
            SemanticSnapshot before = h.snapshot("law_replay(before " + to_string(i) + ")");
            apply_public_op_strict_(h, ops[i]);
            last_snap = h.snapshot("law_replay(after " + to_string(i) + ")");
            string why;
            if (!validate_snapshot_invariants_(last_snap, &why)) {
                ostringstream oss;
                oss << "Snapshot invariant violation at law replay step " << i << " after " << public_op_to_string(ops[i]) << "\n";
                oss << why << "\n";
                oss << semantic_snapshot_to_string(last_snap) << "\n";
                oss << "ops:\n" << public_ops_to_string(vector<PublicOp>(ops.begin(), ops.begin() + i + 1));
                throw runtime_error(oss.str());
            }
            record_invariant_stats_(last_snap);
            if (!only_last_transition || i + 1 == ops.size()) {
                vector<PublicOp> prefix(ops.begin(), ops.begin() + i + 1);
                if (!evaluate_static_laws_for_transition_(prefix, i, ops[i], before, last_snap,
                                                          stats, outcome, out, stop_on_law_failure, seed)) {
                    return false;
                }
            }
        } catch (const exception& e) {
            if (out) {
                *out = make_law_failure_record_("StrictFailure", seed,
                                                vector<PublicOp>(ops.begin(), ops.begin() + min(ops.size(), i + 1)), i,
                                                extract_failure_where_(e.what()),
                                                extract_line_suffix_(e.what(), "first diverging helper substep: "),
                                                e.what());
            }
            return false;
        }
    }
    if (final_snap) *final_snap = last_snap;
    return true;
}

static bool replay_sequence_with_law_checks_(const vector<PublicOp>& ops, LawFailureRecord* out) {
    return run_sequence_with_law_checks_(ops, out, nullptr, nullptr, nullptr, true, false, 0);
}
static vector<PublicOp> minimize_law_failing_prefix_(const vector<PublicOp>& ops, LawFailureRecord* out) {
    LawFailureRecord initial;
    if (ops.empty() || replay_sequence_with_law_checks_(ops, &initial)) {
        if (out) *out = initial;
        return ops;
    }
    size_t best = minimize_failing_prefix_length_(ops.size(), [&](size_t len) {
        LawFailureRecord tmp;
        vector<PublicOp> pref(ops.begin(), ops.begin() + len);
        return !replay_sequence_with_law_checks_(pref, &tmp);
    });
    vector<PublicOp> minimized(ops.begin(), ops.begin() + best);
    LawFailureRecord minimized_record;
    bool ok = replay_sequence_with_law_checks_(minimized, &minimized_record);
    (void)ok;
    if (out) *out = minimized_record;
    return minimized;
}
static bool replay_sequence_for_target_law_(const vector<PublicOp>& ops,
                                            const string& target_law,
                                            LawFailureRecord* out) {
    if (out) *out = LawFailureRecord{};
    DifferentialHarness h(kPublicOpLevels);
    try {
        for (size_t i = 0; i < ops.size(); ++i) {
            SemanticSnapshot before = h.snapshot("target_law(before " + to_string(i) + ")");
            apply_public_op_strict_(h, ops[i]);
            SemanticSnapshot after = h.snapshot("target_law(after " + to_string(i) + ")");
            string why;
            bool interested = false;
            bool ok = true;
            string dump;
            string family;
            if (target_law == "LcaReconstructionTheorem") {
                interested = true;
                ok = validate_lca_reconstruction_theorem_(after, &why);
                if (!ok) dump = make_lca_reconstruction_failure_dump_(after, why);
            } else if (target_law == "LinkStaticLaw" && ops[i].kind == PublicOpKind::Link) {
                interested = true;
                ok = validate_link_static_law_(before, after, ops[i].a, ops[i].b, ops[i].c, &why);
                if (!ok) dump = make_link_static_law_failure_dump_(before, after, ops[i].a, ops[i].b, ops[i].c, why);
            } else if (target_law == "LinkLCABridgeLaw" && ops[i].kind == PublicOpKind::Link) {
                interested = true;
                ok = validate_link_lca_bridge_law_(before, after, ops[i].a, ops[i].b, ops[i].c, &why);
                if (!ok) dump = make_link_lca_bridge_failure_dump_(before, after, ops[i].a, ops[i].b, ops[i].c, why);
            } else if (target_law == "LinkLCABridgePlusReconstruction" && ops[i].kind == PublicOpKind::Link) {
                interested = true;
                ok = validate_link_lca_bridge_implies_reconstruction_(before, after, ops[i].a, ops[i].b, ops[i].c, &why);
                if (!ok) dump = make_link_lca_reconstruction_failure_dump_(before, after, ops[i].a, ops[i].b, ops[i].c, why);
            } else if (target_law == "CutStaticLawCandidateC" && ops[i].kind == PublicOpKind::Cut) {
                interested = true;
                ok = validate_cut_static_law_candidate_C_(before, after, ops[i].a, &why);
                family = cut_delta_fingerprint_(before, after, ops[i].a);
                if (!ok) dump = make_cut_candidate_failure_dump_(target_law, before, after, ops[i].a, why, true, true);
            } else if (target_law == "CutLCABridgeLawCandidateD" && ops[i].kind == PublicOpKind::Cut) {
                interested = true;
                ok = validate_cut_lca_bridge_law_candidate_D_(before, after, ops[i].a, &why);
                family = cut_delta_fingerprint_(before, after, ops[i].a);
                if (!ok) dump = make_cut_candidate_failure_dump_(target_law, before, after, ops[i].a, why, false, false);
            } else if (target_law == "CutLCABridgeLawCandidateDPlusReconstruction" && ops[i].kind == PublicOpKind::Cut) {
                interested = true;
                ok = validate_cut_candidate_D_implies_reconstruction_(before, after, ops[i].a, &why);
                family = cut_delta_fingerprint_(before, after, ops[i].a);
                if (!ok) dump = make_cut_candidate_D_reconstruction_failure_dump_(before, after, ops[i].a, why);
            }
            if (interested && !ok) {
                if (out) *out = make_law_failure_record_(target_law, 0,
                                                         vector<PublicOp>(ops.begin(), ops.begin() + i + 1),
                                                         i, public_op_to_string(ops[i]), string(), dump,
                                                         family);
                return false;
            }
        }
    } catch (const exception& e) {
        if (out) *out = make_law_failure_record_("StrictFailure", 0, ops, 0,
                                                 extract_failure_where_(e.what()),
                                                 extract_line_suffix_(e.what(), "first diverging helper substep: "),
                                                 e.what());
        return false;
    }
    return true;
}
static vector<PublicOp> minimize_specific_law_failing_prefix_(const vector<PublicOp>& ops,
                                                              const string& target_law,
                                                              LawFailureRecord* out) {
    LawFailureRecord initial;
    if (ops.empty() || replay_sequence_for_target_law_(ops, target_law, &initial)) {
        if (out) *out = initial;
        return ops;
    }
    size_t best = minimize_failing_prefix_length_(ops.size(), [&](size_t len) {
        LawFailureRecord tmp;
        vector<PublicOp> pref(ops.begin(), ops.begin() + len);
        return !replay_sequence_for_target_law_(pref, target_law, &tmp);
    });
    vector<PublicOp> minimized(ops.begin(), ops.begin() + best);
    LawFailureRecord minimized_record;
    bool ok = replay_sequence_for_target_law_(minimized, target_law, &minimized_record);
    (void)ok;
    if (out) *out = minimized_record;
    return minimized;
}

static void finalize_law_outcome_minimized_(StaticLawOutcome* outcome) {
    if (!outcome) return;
    if (outcome->lca_reconstruct_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->lca_reconstruct_failure.ops, "LcaReconstructionTheorem", &minimized);
        minimized.ops = ops;
        minimized.law_name = "LcaReconstructionTheorem";
        outcome->lca_reconstruct_failure = minimized;
    }
    if (outcome->link_strong_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->link_strong_failure.ops, "LinkStaticLaw", &minimized);
        minimized.ops = ops;
        minimized.law_name = "LinkStaticLaw";
        outcome->link_strong_failure = minimized;
    }
    if (outcome->link_lca_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->link_lca_failure.ops, "LinkLCABridgeLaw", &minimized);
        minimized.ops = ops;
        minimized.law_name = "LinkLCABridgeLaw";
        outcome->link_lca_failure = minimized;
    }
    if (outcome->link_lca_reconstruct_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->link_lca_reconstruct_failure.ops, "LinkLCABridgePlusReconstruction", &minimized);
        minimized.ops = ops;
        minimized.law_name = "LinkLCABridgePlusReconstruction";
        outcome->link_lca_reconstruct_failure = minimized;
    }
    if (outcome->cut_candidate_C_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->cut_candidate_C_failure.ops, "CutStaticLawCandidateC", &minimized);
        minimized.ops = ops;
        minimized.law_name = "CutStaticLawCandidateC";
        outcome->cut_candidate_C_failure = minimized;
    }
    if (outcome->cut_candidate_D_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->cut_candidate_D_failure.ops, "CutLCABridgeLawCandidateD", &minimized);
        minimized.ops = ops;
        minimized.law_name = "CutLCABridgeLawCandidateD";
        outcome->cut_candidate_D_failure = minimized;
    }
    if (outcome->cut_candidate_D_reconstruct_failed) {
        LawFailureRecord minimized;
        auto ops = minimize_specific_law_failing_prefix_(outcome->cut_candidate_D_reconstruct_failure.ops, "CutLCABridgeLawCandidateDPlusReconstruction", &minimized);
        minimized.ops = ops;
        minimized.law_name = "CutLCABridgeLawCandidateDPlusReconstruction";
        outcome->cut_candidate_D_reconstruct_failure = minimized;
    }
}

static bool replay_sequence_strict_(const vector<PublicOp>& ops, FailureRecord* out, SemanticSnapshot* final_snap = nullptr) {
    if (out) *out = FailureRecord{};
    DifferentialHarness h(kPublicOpLevels);
    SemanticSnapshot last_snap;
    try {
        last_snap = h.snapshot("replay_sequence(initial)");
        string why;
        if (!validate_snapshot_invariants_(last_snap, &why)) {
            throw runtime_error("Snapshot invariant violation at initial state\n" + why + "\n" + semantic_snapshot_to_string(last_snap));
        }
        record_invariant_stats_(last_snap);
    } catch (const exception& e) {
        if (out) {
            out->ops = ops;
            out->failing_step = 0;
            out->failure_dump = e.what();
            out->failing_where = extract_failure_where_(out->failure_dump);
            out->first_diverging_helper_substep = extract_line_suffix_(out->failure_dump, "first diverging helper substep: ");
        }
        return false;
    }
    for (size_t i = 0; i < ops.size(); ++i) {
        try {
            apply_public_op_strict_(h, ops[i]);
            last_snap = h.snapshot("replay_sequence(after " + to_string(i) + ")");
            string why;
            if (!validate_snapshot_invariants_(last_snap, &why)) {
                ostringstream oss;
                oss << "Snapshot invariant violation at replay step " << i << " after " << public_op_to_string(ops[i]) << "\n";
                oss << why << "\n";
                oss << semantic_snapshot_to_string(last_snap) << "\n";
                oss << "ops:\n" << public_ops_to_string(vector<PublicOp>(ops.begin(), ops.begin() + i + 1));
                throw runtime_error(oss.str());
            }
            record_invariant_stats_(last_snap);
        } catch (const exception& e) {
            if (out) {
                out->ops = vector<PublicOp>(ops.begin(), ops.begin() + i + 1);
                out->failing_step = i;
                out->failure_dump = e.what();
                out->failing_where = extract_failure_where_(out->failure_dump);
                if (out->failing_where.empty()) out->failing_where = public_op_to_string(ops[i]);
                out->first_diverging_helper_substep = extract_line_suffix_(out->failure_dump, "first diverging helper substep: ");
            }
            return false;
        }
    }
    if (final_snap) *final_snap = last_snap;
    return true;
}

static vector<PublicOp> minimize_failing_prefix_(const vector<PublicOp>& ops, FailureRecord* out) {
    FailureRecord initial;
    if (ops.empty() || replay_sequence_strict_(ops, &initial)) {
        if (out) *out = initial;
        return ops;
    }
    size_t best = minimize_failing_prefix_length_(ops.size(), [&](size_t len) {
        FailureRecord tmp;
        vector<PublicOp> pref(ops.begin(), ops.begin() + len);
        return !replay_sequence_strict_(pref, &tmp);
    });
    vector<PublicOp> minimized(ops.begin(), ops.begin() + best);
    FailureRecord minimized_record;
    bool ok = replay_sequence_strict_(minimized, &minimized_record);
    (void)ok;
    if (out) *out = minimized_record;
    return minimized;
}

struct ExhaustiveCoverageStats {
    int n = 0;
    int max_depth = 0;
    size_t explored_nodes = 0;
    size_t unique_states = 0;
    size_t transitions_checked = 0;
};
static ExhaustiveCoverageStats g_last_exhaustive_stats;
static string g_last_randomized_summary;

static bool exhaustive_explore_small_states_dfs_(
        const PublicOpModelState& model,
        int depth_left,
        vector<PublicOp>& prefix,
        unordered_map<string, int>& best_remaining_depth,
        unordered_set<string>& unique_fingerprints,
        ExhaustiveCoverageStats* stats,
        FailureRecord* out,
        StaticLawStats* law_stats = nullptr,
        StaticLawOutcome* law_outcome = nullptr) {
    LawFailureRecord law_replay_failure;
    SemanticSnapshot snap;
    if (!run_sequence_with_law_checks_(prefix, &law_replay_failure, law_stats, law_outcome, &snap,
                                       false, true, 0)) {
        if (out) {
            FailureRecord replay_failure;
            replay_failure.ops = law_replay_failure.ops;
            replay_failure.failing_step = law_replay_failure.failing_step;
            replay_failure.failing_where = law_replay_failure.failing_where;
            replay_failure.first_diverging_helper_substep = law_replay_failure.first_diverging_helper_substep;
            replay_failure.failure_dump = law_replay_failure.failure_dump;
            FailureRecord minimized;
            auto minimized_ops = minimize_failing_prefix_(replay_failure.ops, &minimized);
            minimized.ops = minimized_ops;
            *out = minimized;
        }
        return false;
    }
    if (stats) ++stats->explored_nodes;
    string fp = semantic_snapshot_fingerprint_(snap);
    if (unique_fingerprints.insert(fp).second && stats) ++stats->unique_states;
    auto it = best_remaining_depth.find(fp);
    if (it != best_remaining_depth.end() && it->second >= depth_left) return true;
    best_remaining_depth[fp] = depth_left;
    if (depth_left == 0) return true;
    vector<PublicOp> candidates = enumerate_valid_public_ops_(model);
    for (const PublicOp& op : candidates) {
        if (stats) ++stats->transitions_checked;
        PublicOpModelState next = model;
        bool ok = apply_public_op_model_(next, op);
        if (!ok) continue;
        prefix.push_back(op);
        bool child_ok = exhaustive_explore_small_states_dfs_(next, depth_left - 1, prefix,
                                                             best_remaining_depth, unique_fingerprints,
                                                             stats, out, law_stats, law_outcome);
        prefix.pop_back();
        if (!child_ok) return false;
    }
    return true;
}

static bool exhaustive_explore_small_states_(int n, int max_depth, ExhaustiveCoverageStats* stats, FailureRecord* out,
                                             StaticLawStats* law_stats = nullptr,
                                             StaticLawOutcome* law_outcome = nullptr) {
    if (stats) *stats = ExhaustiveCoverageStats{n, max_depth, 0, 0, 0};
    if (out) *out = FailureRecord{};
    if (law_stats) *law_stats = StaticLawStats{};
    if (law_outcome) *law_outcome = StaticLawOutcome{};
    reset_invariant_stats_();
    PublicOpModelState model(n);
    vector<PublicOp> prefix;
    unordered_map<string, int> best_remaining_depth;
    unordered_set<string> unique_fingerprints;
    bool ok = exhaustive_explore_small_states_dfs_(model, max_depth, prefix, best_remaining_depth, unique_fingerprints,
                                                   stats, out, law_stats, law_outcome);
    g_last_exhaustive_invariant_stats = g_invariant_stats;
    if (law_outcome) finalize_law_outcome_minimized_(law_outcome);
    return ok;
}


static CounterVector random_counter(int L, mt19937& rng) {
    CounterVector c(L);
    uniform_int_distribution<int> dist(0, 3);
    for (int i = 0; i <= L; ++i) c.a[i] = dist(rng);
    return c;
}
static MarkVector random_mark(int L, mt19937& rng) {
    MarkVector m(L);
    uniform_int_distribution<int> dist(0, 1);
    for (int i = 0; i <= L; ++i) m.a[i] = uint8_t(dist(rng));
    return m;
}
static void apply_fixture_payloads(DifferentialHarness& h, int L, int label) {
    CounterVector c(L); c.a = {1, 1, 1};
    MarkVector m(L); m.a = {1, 0, 1};
    h.update_counters(2, 100, label, c);
    h.update_counters(2, 200, label, c);
    h.update_marks(2, 100, label, m);
    h.update_marks(2, 200, label, m);
    h.update_vertex_marks(2, label, mark_one(L));
    h.update_counters(3, 200, label, c);
    h.update_counters(3, 300, label, c);
    h.update_marks(3, 200, label, m);
    h.update_marks(3, 300, label, m);
    h.update_vertex_marks(3, label, mark_one(L));
}
static DifferentialHarness build_chain_fixture(int L, int label) {
    DifferentialHarness h(L);
    assert(h.link(1, 2, 100));
    assert(h.link(2, 3, 200));
    assert(h.link(3, 4, 300));
    h.canonicalize(1, {1,2,3,4});
    h.set_level(2, 100, 200, 1);
    h.set_level(3, 200, 300, 1);
    apply_fixture_payloads(h, L, label);
    return h;
}
static void test_backend_and_algebra() {
    const int L = 2;
    ConcreteNeighborhoodBackend Nv(L);
    PaperMergeAlgebra alg(L, &Nv);
    Nv.attach_edge(2, 10);
    Nv.attach_edge(2, 20);
    Nv.set_level(2, 10, 20, 1);
    int label = 5;
    CounterVector c10(L); c10.a = {1, 2, 3};
    CounterVector c20(L); c20.a = {4, 5, 6};
    MarkVector m10(L); m10.a = {1, 0, 1};
    MarkVector m20(L); m20.a = {0, 1, 1};
    Nv.update_counters(2, 10, label, c10);
    Nv.update_counters(2, 20, label, c20);
    Nv.update_marks(2, 10, label, m10);
    Nv.update_marks(2, 20, label, m20);
    Nv.update_vertex_marks(2, label, mark_one(L));
    auto A = alg.make_leaf(1, 2, 10);
    auto B = alg.make_leaf(2, 3, 20);
    auto P = alg.make_point(2);
    auto C = alg.make_case3(A.get(), B.get(), P.get(), 1, 3, 2);
    LabelSlicePayload payload = alg.compute(*C, label);
    assert((int)payload.totalcnt.a.size() == L + 1);
    assert((int)payload.totalmarks.a.size() == L + 1);
    assert(payload.diagcnt_star.contains(1));
    assert(payload.diagcnt_star.contains(3));
    assert(payload.diagmarks_star.contains(1));
    assert(payload.diagmarks_star.contains(3));
}
