static bool replay_sequence_capture_last_transition_(const vector<PublicOp>& ops,
                                                    SemanticSnapshot* before_last,
                                                    SemanticSnapshot* after_last,
                                                    FailureRecord* out) {
    if (out) *out = FailureRecord{};
    DifferentialHarness h(kPublicOpLevels);
    try {
        SemanticSnapshot snap = h.snapshot("capture_last(initial)");
        string why;
        if (!validate_snapshot_invariants_(snap, &why)) {
            throw runtime_error("Snapshot invariant violation at capture initial\n" + why + "\n" + semantic_snapshot_to_string(snap));
        }
        for (size_t i = 0; i < ops.size(); ++i) {
            SemanticSnapshot before = h.snapshot("capture_last(before " + to_string(i) + ")");
            apply_public_op_strict_(h, ops[i]);
            SemanticSnapshot after = h.snapshot("capture_last(after " + to_string(i) + ")");
            if (!validate_snapshot_invariants_(after, &why)) {
                ostringstream oss;
                oss << "Snapshot invariant violation at capture step " << i << " after " << public_op_to_string(ops[i]) << "\n";
                oss << why << "\n" << semantic_snapshot_to_string(after);
                throw runtime_error(oss.str());
            }
            if (i + 1 == ops.size()) {
                if (before_last) *before_last = before;
                if (after_last) *after_last = after;
            }
        }
        return true;
    } catch (const exception& e) {
        if (out) {
            out->ops = ops;
            out->failing_step = ops.empty() ? 0 : ops.size() - 1;
            out->failure_dump = e.what();
            out->failing_where = extract_failure_where_(out->failure_dump);
            out->first_diverging_helper_substep = extract_line_suffix_(out->failure_dump, "first diverging helper substep: ");
        }
        return false;
    }
}

static vector<PublicOp> enumerate_cut_miner_ops_(const PublicOpModelState& state) {
    vector<PublicOp> out;
    for (const PublicOp& op : enumerate_valid_public_ops_(state)) {
        if (op.kind == PublicOpKind::Link || op.kind == PublicOpKind::Cut ||
            op.kind == PublicOpKind::Access || op.kind == PublicOpKind::Makeroot) {
            out.push_back(op);
        }
    }
    return out;
}

static bool scan_cut_terminal_sequences_dfs_(const PublicOpModelState& model,
                                             int depth_left,
                                             vector<PublicOp>& prefix,
                                             CutFamilyStats* stats,
                                             StaticLawOutcome* out) {
    if (depth_left == 0) return true;
    vector<PublicOp> candidates = enumerate_cut_miner_ops_(model);
    for (const PublicOp& op : candidates) {
        PublicOpModelState next = model;
        if (!apply_public_op_model_(next, op)) continue;
        prefix.push_back(op);
        if (op.kind == PublicOpKind::Cut) {
            if (stats) ++stats->cut_terminal_sequences;
            SemanticSnapshot before, after;
            FailureRecord strict_failure;
            if (!replay_sequence_capture_last_transition_(prefix, &before, &after, &strict_failure)) {
                prefix.pop_back();
                return false;
            }
            string whyC, whyD;
            bool okC = validate_cut_static_law_candidate_C_(before, after, op.a, &whyC);
            bool okD = validate_cut_lca_bridge_law_candidate_D_(before, after, op.a, &whyD);
            if (!okC || !okD) {
                if (stats) ++stats->failing_sequences;
                string fingerprint = cut_delta_fingerprint_(before, after, op.a);
                if (stats) {
                    ++stats->family_counts[fingerprint];
                    if (!stats->first_sequence.count(fingerprint)) {
                        stats->first_sequence[fingerprint] = prefix;
                        LawFailureRecord minimized;
                        string target_law = !okC ? "CutStaticLawCandidateC" : "CutLCABridgeLawCandidateD";
                        stats->minimized_sequence[fingerprint] = minimize_specific_law_failing_prefix_(prefix, target_law, &minimized);
                    }
                }
                if (!okC) {
                    LawFailureRecord rec = make_law_failure_record_(
                        "CutStaticLawCandidateC", 0, prefix, prefix.size() - 1,
                        public_op_to_string(op), string(),
                        make_cut_candidate_failure_dump_("CutStaticLawCandidateC", before, after, op.a, whyC, true, true),
                        fingerprint);
                    record_law_failure_once_(out, rec);
                }
                if (!okD) {
                    LawFailureRecord rec = make_law_failure_record_(
                        "CutLCABridgeLawCandidateD", 0, prefix, prefix.size() - 1,
                        public_op_to_string(op), string(),
                        make_cut_candidate_failure_dump_("CutLCABridgeLawCandidateD", before, after, op.a, whyD, false, false),
                        fingerprint);
                    record_law_failure_once_(out, rec);
                }
            }
        }
        if (!scan_cut_terminal_sequences_dfs_(next, depth_left - 1, prefix, stats, out)) {
            prefix.pop_back();
            return false;
        }
        prefix.pop_back();
    }
    return true;
}

static bool scan_cut_terminal_sequences_(int n,
                                         int max_prefix_depth,
                                         CutFamilyStats* stats,
                                         StaticLawOutcome* out) {
    if (stats) {
        *stats = CutFamilyStats{};
        stats->n = n;
        stats->max_prefix_depth = max_prefix_depth;
        stats->symmetry_aware = false;
    }
    if (out) *out = StaticLawOutcome{};
    PublicOpModelState model(n);
    vector<PublicOp> prefix;
    bool ok = scan_cut_terminal_sequences_dfs_(model, max_prefix_depth, prefix, stats, out);
    if (out) finalize_law_outcome_minimized_(out);
    return ok;
}

static bool scan_cut_terminal_sequences_symmetry_aware_dfs_(const PublicOpModelState& model,
                                                            int depth_left,
                                                            vector<PublicOp>& prefix,
                                                            unordered_set<string>* seen,
                                                            CutFamilyStats* stats,
                                                            StaticLawOutcome* out) {
    SemanticSnapshot current;
    FailureRecord strict_failure;
    if (!replay_sequence_strict_(prefix, &strict_failure, &current)) return false;
    if (stats) ++stats->visited_states;
    string key = to_string(depth_left) + "|" + canonical_lca_component_fingerprint_(make_static_rooted_view_(current));
    if (seen && !seen->insert(key).second) {
        if (stats) ++stats->pruned_states;
        return true;
    }
    if (depth_left == 0) return true;
    vector<PublicOp> candidates = enumerate_cut_miner_ops_(model);
    for (const PublicOp& op : candidates) {
        PublicOpModelState next = model;
        if (!apply_public_op_model_(next, op)) continue;
        prefix.push_back(op);
        if (op.kind == PublicOpKind::Cut) {
            if (stats) ++stats->cut_terminal_sequences;
            SemanticSnapshot before, after;
            if (!replay_sequence_capture_last_transition_(prefix, &before, &after, &strict_failure)) {
                prefix.pop_back();
                return false;
            }
            string whyC, whyD, whyDR;
            bool okC = validate_cut_static_law_candidate_C_(before, after, op.a, &whyC);
            bool okD = validate_cut_lca_bridge_law_candidate_D_(before, after, op.a, &whyD);
            bool okDR = validate_cut_candidate_D_implies_reconstruction_(before, after, op.a, &whyDR);
            if (!okC || !okD || !okDR) {
                if (stats) ++stats->failing_sequences;
                string fingerprint = cut_delta_fingerprint_(before, after, op.a);
                if (stats) {
                    ++stats->family_counts[fingerprint];
                    if (!stats->first_sequence.count(fingerprint)) {
                        stats->first_sequence[fingerprint] = prefix;
                        LawFailureRecord minimized;
                        string target_law = !okC ? "CutStaticLawCandidateC" : (!okD ? "CutLCABridgeLawCandidateD" : "CutLCABridgeLawCandidateDPlusReconstruction");
                        stats->minimized_sequence[fingerprint] = minimize_specific_law_failing_prefix_(prefix, target_law, &minimized);
                    }
                }
                if (!okC) {
                    LawFailureRecord rec = make_law_failure_record_(
                        "CutStaticLawCandidateC", 0, prefix, prefix.size() - 1,
                        public_op_to_string(op), string(),
                        make_cut_candidate_failure_dump_("CutStaticLawCandidateC", before, after, op.a, whyC, true, true),
                        fingerprint);
                    record_law_failure_once_(out, rec);
                }
                if (!okD) {
                    LawFailureRecord rec = make_law_failure_record_(
                        "CutLCABridgeLawCandidateD", 0, prefix, prefix.size() - 1,
                        public_op_to_string(op), string(),
                        make_cut_candidate_failure_dump_("CutLCABridgeLawCandidateD", before, after, op.a, whyD, false, false),
                        fingerprint);
                    record_law_failure_once_(out, rec);
                }
                if (!okDR) {
                    LawFailureRecord rec = make_law_failure_record_(
                        "CutLCABridgeLawCandidateDPlusReconstruction", 0, prefix, prefix.size() - 1,
                        public_op_to_string(op), string(),
                        make_cut_candidate_D_reconstruction_failure_dump_(before, after, op.a, whyDR),
                        fingerprint);
                    record_law_failure_once_(out, rec);
                }
            }
        }
        if (!scan_cut_terminal_sequences_symmetry_aware_dfs_(next, depth_left - 1, prefix, seen, stats, out)) {
            prefix.pop_back();
            return false;
        }
        prefix.pop_back();
    }
    return true;
}
static bool scan_cut_terminal_sequences_symmetry_aware_(int n,
                                                        int max_prefix_depth,
                                                        CutFamilyStats* stats,
                                                        StaticLawOutcome* out) {
    if (stats) {
        *stats = CutFamilyStats{};
        stats->n = n;
        stats->max_prefix_depth = max_prefix_depth;
        stats->symmetry_aware = true;
    }
    if (out) *out = StaticLawOutcome{};
    PublicOpModelState model(n);
    vector<PublicOp> prefix;
    unordered_set<string> seen;
    bool ok = scan_cut_terminal_sequences_symmetry_aware_dfs_(model, max_prefix_depth, prefix, &seen, stats, out);
    if (out) finalize_law_outcome_minimized_(out);
    return ok;
}

