static SparseLcaInstance make_full_sparse_instance_from_tree_(const StaticRootedTree& tree) {
    SparseLcaInstance inst;
    inst.n = tree.n;
    for (const auto& kv : full_pairwise_lca_table_from_tree_(tree)) {
        inst.constraints.push_back({kv.first.first, kv.first.second, kv.second});
    }
    return canonicalize_sparse_instance_(inst);
}

static void test_exact_sparse_oracle_small_chain() {
    StaticRootedTree tree = make_static_rooted_tree_(4, vector<int>{0, 0, 1, 2, 3});
    SparseLcaInstance inst = make_full_sparse_instance_from_tree_(tree);
    string why;
    auto oracle = exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &why);
    if (!oracle.satisfiable) throw runtime_error("small chain sparse oracle unexpectedly unsatisfiable: " + why);
    assert(oracle.solution_count == 1);
    assert(oracle.full_lca_table_forced);
    assert(oracle.rooted_parent_forest_forced);
}

