static void test_sparse_uniqueness_equivalence_small() {
    SparseLcaInstance empty{4, {}};
    string why;
    auto oracle_empty = exact_sparse_completion_oracle_(empty, numeric_limits<size_t>::max(), &why);
    bool ok = validate_sparse_uniqueness_equivalence_(empty, oracle_empty, &why);
    if (!ok) throw runtime_error("sparse uniqueness equivalence failed on empty instance\n" + why);
    ok = validate_sparse_forced_parent_equivalence_(empty, oracle_empty, &why);
    if (!ok) throw runtime_error("sparse forced-parent equivalence failed on empty instance\n" + why);

    StaticRootedTree chain = make_static_rooted_tree_(4, vector<int>{0, 0, 1, 2, 3});
    SparseLcaInstance full = make_full_sparse_instance_from_tree_(chain);
    auto oracle_full = exact_sparse_completion_oracle_(full, numeric_limits<size_t>::max(), &why);
    ok = validate_sparse_uniqueness_equivalence_(full, oracle_full, &why);
    if (!ok) throw runtime_error("sparse uniqueness equivalence failed on full chain instance\n" + why);
    ok = validate_sparse_forced_parent_equivalence_(full, oracle_full, &why);
    if (!ok) throw runtime_error("sparse forced-parent equivalence failed on full chain instance\n" + why);
}

