static void test_sparse_base_closure_root_rule() {
    SparseLcaInstance inst{4, {}};
    auto res = run_sparse_base_closure_(inst);
    if (!res.consistent) throw runtime_error("sparse base closure root rule inconsistent\n" + res.why);
    int got = -1;
    assert(lookup_known_lca_in_map_(res.state.known_lca, 1, 2, &got) && got == 1);
    assert(lookup_known_lca_in_map_(res.state.known_lca, 1, 3, &got) && got == 1);
    assert(lookup_known_lca_in_map_(res.state.known_lca, 1, 4, &got) && got == 1);
}

static void test_sparse_base_closure_witness_absorption() {
    SparseLcaInstance inst{4, {{2,3,4}}};
    auto res = run_sparse_base_closure_(inst);
    if (!res.consistent) throw runtime_error("sparse base closure witness absorption inconsistent\n" + res.why);
    int got = -1;
    assert(lookup_known_lca_in_map_(res.state.known_lca, 2, 4, &got) && got == 4);
    assert(lookup_known_lca_in_map_(res.state.known_lca, 3, 4, &got) && got == 4);
}

