static void test_sparse_rule_coverage_exhaustive_n4_smoke() {
    string why;
    g_last_minimal_forcing_motifs = mine_minimal_forcing_motifs_(4, 64, &why);
    if (!why.empty()) throw runtime_error("minimal forcing motif mining for exhaustive coverage failed\n" + why);
    auto rules = derive_rule_candidates_from_motifs_(g_last_minimal_forcing_motifs);
    g_last_sound_rule_candidates = filter_sound_rule_candidates_(rules, 4, &why);
    if (!why.empty()) {
        // keep the first counterexample explanation as a note, but do not fail if some candidates were simply filtered out.
    }
    SparseRuleCoverageStats stats;
    bool ok = scan_sparse_rule_coverage_exhaustive_(4, g_last_sound_rule_candidates, &stats, &why);
    if (!ok) throw runtime_error("sparse rule coverage exhaustive scan failed\n" + why);
    g_last_sparse_rule_exhaustive_stats = stats;
    g_last_residual_gap_families = mine_residual_gap_instances_(4, g_last_sound_rule_candidates, 5);
    assert(stats.canonical_instances > 0);
    assert(stats.satisfiable_instances > 0);
    assert(stats.base_recovered_pairs <= stats.candidate_recovered_pairs);
    assert(stats.candidate_recovered_pairs <= stats.total_forced_pairs);
}

