static void test_randomized_differential() {
    const int N = 6;
    const uint32_t seed = 20260308u;
    const int target_steps = 50;
    mt19937 rng(seed);
    PublicOpModelState model(N);
    vector<PublicOp> ops;
    for (int step = 0; step < target_steps; ++step) {
        vector<PublicOp> candidates = enumerate_valid_public_ops_(model);
        if (candidates.empty()) break;
        int idx = uniform_int_distribution<int>(0, (int)candidates.size() - 1)(rng);
        PublicOp op = candidates[idx];
        bool ok = apply_public_op_model_(model, op);
        if (!ok) throw runtime_error("model rejected generated op: " + public_op_to_string(op));
        ops.push_back(op);
    }
    LawFailureRecord law_failure;
    StaticLawStats law_stats;
    StaticLawOutcome law_outcome;
    if (!run_sequence_with_law_checks_(ops, &law_failure, &law_stats, &law_outcome, nullptr, false, false, seed)) {
        FailureRecord failure;
        failure.seed = seed;
        failure.ops = law_failure.ops;
        failure.failing_step = law_failure.failing_step;
        failure.failing_where = law_failure.failing_where;
        failure.first_diverging_helper_substep = law_failure.first_diverging_helper_substep;
        failure.failure_dump = law_failure.failure_dump;
        FailureRecord minimized_failure;
        vector<PublicOp> minimized = minimize_failing_prefix_(ops, &minimized_failure);
        minimized_failure.seed = seed;
        ostringstream oss;
        oss << failure.failure_dump << "\n";
        oss << "randomized seed: " << seed << "\n";
        oss << "operation sequence:\n" << public_ops_to_string(ops) << "\n";
        oss << "minimized failing prefix:\n" << public_ops_to_string(minimized) << "\n";
        if (!minimized_failure.failing_where.empty()) oss << "failing_where: " << minimized_failure.failing_where << "\n";
        if (!minimized_failure.first_diverging_helper_substep.empty()) {
            oss << "first diverging helper substep: " << minimized_failure.first_diverging_helper_substep << "\n";
        }
        throw runtime_error(oss.str());
    }
    finalize_law_outcome_minimized_(&law_outcome);
    g_last_randomized_law_stats = law_stats;
    g_last_randomized_law_outcome = law_outcome;
    g_last_randomized_summary = "randomized seed=" + to_string(seed) + " steps=" + to_string((int)ops.size())
        + " laws=" + static_law_stats_to_string_(law_stats)
        + " outcomes=" + static_law_outcome_summary_(law_outcome);
}




