static string solver_saturation_result_to_string_(const SolverSaturationResult& sat) {
    ostringstream oss;
    oss << "instance=" << sparse_instance_to_string_(sat.instance) << "\n";
    oss << "closure_pairwise_lca=" << pairwise_lca_table_to_string_(sat.closure_pairwise_lca) << "\n";
    oss << "oracle_forced_pairwise_lca=" << pairwise_lca_table_to_string_(sat.oracle_forced_pairwise_lca) << "\n";
    oss << "missing_forced_pairs=" << sparse_constraint_vec_to_string_(sat.missing_forced_pairs) << "\n";
    oss << "extra_derived_pairs=" << sparse_constraint_vec_to_string_(sat.extra_derived_pairs) << "\n";
    oss << "full_match=" << (sat.full_match ? "true" : "false") << "\n";
    if (!sat.why.empty()) oss << "why=" << sat.why << "\n";
    return oss.str();
}

static string saturation_theorem_stats_to_string_(const SaturationTheoremStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " rooted_trees=" << s.rooted_trees
        << " raw=" << s.raw_instances
        << " canonical=" << s.canonical_instances
        << " satisfiable=" << s.satisfiable_instances
        << " fullMatch=" << s.full_match_instances
        << " mismatch=" << s.mismatch_instances
        << " fullTable=" << s.full_table_instances
        << " uniqueCor=" << s.unique_completion_corollary_pass << '/' << s.satisfiable_instances
        << " parentCor=" << s.forced_parent_corollary_pass << '/' << s.satisfiable_instances
        << " reconstructCor=" << s.reconstruction_corollary_pass << '/' << s.satisfiable_instances;
    return oss.str();
}

static SparseCompletionOracleResult cached_exact_sparse_completion_oracle_(const SparseLcaInstance& instance,
                                                                           size_t max_solutions,
                                                                           string* why);

static SparseCompletionOracleResult exact_sparse_completion_oracle_(const SparseLcaInstance& instance,
                                                                    size_t max_solutions,
                                                                    string* why) {
    return cached_exact_sparse_completion_oracle_(instance, max_solutions, why);
}

static SparseCompletionOracleResult cached_exact_sparse_completion_oracle_(const SparseLcaInstance& instance,
                                                                           size_t max_solutions,
                                                                           string* why) {
    auto canon = canonicalize_sparse_instance_(instance);
    if (max_solutions != numeric_limits<size_t>::max()) {
        return raw_exact_sparse_completion_oracle_(canon, max_solutions, why);
    }
    string key = canonical_sparse_instance_fingerprint_(canon);
    auto it = g_solver_oracle_cache.find(key);
    if (it != g_solver_oracle_cache.end()) {
        if (why) *why = "";
        return it->second;
    }
    string local_why;
    auto oracle = raw_exact_sparse_completion_oracle_(canon, max_solutions, &local_why);
    g_solver_oracle_cache.emplace(key, oracle);
    if (why) *why = local_why;
    return oracle;
}

static vector<int> depth_vector_from_tree_(const StaticRootedTree& tree) {
    vector<int> depth(tree.n + 1, -1);
    if (tree.n <= 0) return depth;
    queue<int> q;
    q.push(1);
    depth[1] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : tree.children[u]) {
            depth[v] = depth[u] + 1;
            q.push(v);
        }
    }
    return depth;
}

static int lca_in_tree_with_depth_vector_(const StaticRootedTree& tree, const vector<int>& depth, int u, int v) {
    if (u == v) return u;
    int du = depth[u], dv = depth[v];
    while (du > dv) { u = tree.parent[u]; --du; }
    while (dv > du) { v = tree.parent[v]; --dv; }
    while (u != v) { u = tree.parent[u]; v = tree.parent[v]; }
    return u;
}

static bool tree_satisfies_sparse_instance_with_depth_vector_(const StaticRootedTree& tree,
                                                              const vector<int>& depth,
                                                              const SparseLcaInstance& instance) {
    for (auto c : instance.constraints) {
        if (c.u == c.v) {
            if (c.w != c.u) return false;
            continue;
        }
        int got = lca_in_tree_with_depth_vector_(tree, depth, c.u, c.v);
        if (got != c.w) return false;
    }
    return true;
}

static vector<vector<int>> full_pairwise_lca_matrix_from_tree_with_depth_(const StaticRootedTree& tree,
                                                                          const vector<int>& depth) {
    vector<vector<int>> mat(tree.n + 1, vector<int>(tree.n + 1, 0));
    for (int u = 1; u <= tree.n; ++u) {
        mat[u][u] = u;
        for (int v = u + 1; v <= tree.n; ++v) {
            int w = lca_in_tree_with_depth_vector_(tree, depth, u, v);
            mat[u][v] = w;
            mat[v][u] = w;
        }
    }
    return mat;
}

static bool tree_satisfies_sparse_instance_with_lca_matrix_(const vector<vector<int>>& lca,
                                                            const SparseLcaInstance& instance) {
    for (auto c : instance.constraints) {
        if (c.u == c.v) {
            if (c.w != c.u) return false;
            continue;
        }
        if (lca[c.u][c.v] != c.w) return false;
    }
    return true;
}

static map<pair<int,int>, int> pairwise_lca_table_from_matrix_(const vector<vector<int>>& lca) {
    int n = (int)lca.size() - 1;
    map<pair<int,int>, int> table;
    for (int u = 1; u <= n; ++u) {
        for (int v = u + 1; v <= n; ++v) {
            table[{u, v}] = lca[u][v];
        }
    }
    return table;
}

struct BatchExactOracleState {
    SparseLcaInstance instance;
    SparseCompletionOracleResult out;
    bool first = true;
    map<pair<int,int>, int> common_lca;
    vector<int> common_parent;
    vector<vector<unsigned char>> common_ancestor;
};

static void finalize_batch_exact_oracle_state_(BatchExactOracleState* st) {
    if (!st->out.satisfiable) {
        st->out.completion_family_fingerprint = "unsat";
        return;
    }
    st->out.forced_pairwise_lca = st->common_lca;
    for (int v = 2; v <= st->instance.n; ++v) if (st->common_parent[v] > 0) st->out.forced_parent_edges.push_back({v, st->common_parent[v]});
    sort(st->out.forced_parent_edges.begin(), st->out.forced_parent_edges.end());
    for (int a = 1; a <= st->instance.n; ++a) {
        for (int b = 1; b <= st->instance.n; ++b) {
            if (a == b) continue;
            if (st->common_ancestor[a][b]) st->out.forced_ancestor_pairs.push_back({a, b});
        }
    }
    sort(st->out.forced_ancestor_pairs.begin(), st->out.forced_ancestor_pairs.end());
    st->out.full_lca_table_forced = (st->out.forced_pairwise_lca.size() == ((size_t)st->instance.n * (size_t)(st->instance.n - 1) / 2));
    st->out.rooted_parent_forest_forced = (st->out.forced_parent_edges.size() == (size_t)max(0, st->instance.n - 1));
    st->out.completion_family_fingerprint = canonical_completion_family_fingerprint_(st->out);
}

static bool prewarm_exact_sparse_completion_oracle_batch_same_n_(const vector<SparseLcaInstance>& raw_instances, string* why) {
    vector<SparseLcaInstance> instances;
    vector<string> keys;
    unordered_set<string> seen;
    int n = 0;
    for (const auto& raw : raw_instances) {
        auto canon = canonicalize_sparse_instance_(raw);
        if (canon.n <= 0) continue;
        if (n == 0) n = canon.n;
        if (canon.n != n) { if (why) *why = "mixed n in batch oracle prewarm"; return false; }
        string key = canonical_sparse_instance_fingerprint_(canon);
        if (g_solver_oracle_cache.find(key) != g_solver_oracle_cache.end()) continue;
        if (!seen.insert(key).second) continue;
        instances.push_back(canon);
        keys.push_back(key);
    }
    if (instances.empty()) { if (why) *why = ""; return true; }
    if (n <= 7) {
        for (size_t i = 0; i < instances.size(); ++i) {
            string local_why;
            auto oracle = raw_exact_sparse_completion_oracle_(instances[i], numeric_limits<size_t>::max(), &local_why);
            g_solver_oracle_cache.emplace(keys[i], oracle);
        }
        if (why) *why = "";
        return true;
    }
    vector<BatchExactOracleState> states(instances.size());
    for (size_t i = 0; i < instances.size(); ++i) {
        states[i].instance = instances[i];
        states[i].common_parent.assign(n + 1, INT_MIN);
        states[i].common_ancestor.assign(n + 1, vector<unsigned char>(n + 1, 1));
    }
    size_t tree_progress = 0;
    const size_t total_trees = [&]() {
        size_t out = 1;
        for (int i = 0; i < n - 2; ++i) out *= (size_t)n;
        return out;
    }();
    for_each_rooted_tree_prufer_stream_(n, [&](const StaticRootedTree& tree) {
        ++tree_progress;
#ifdef LOCAL_TEST
        if (tree_progress == 1 || tree_progress == total_trees || tree_progress % 500000 == 0) {
            cerr << "progress: batch_oracle_n" << n << ' ' << tree_progress << '/' << total_trees << "\n";
        }
#endif
        auto depth = depth_vector_from_tree_(tree);
        auto lca_matrix = full_pairwise_lca_matrix_from_tree_with_depth_(tree, depth);
        vector<size_t> sat_idx;
        sat_idx.reserve(states.size());
        for (size_t i = 0; i < states.size(); ++i) {
            if (tree_satisfies_sparse_instance_with_lca_matrix_(lca_matrix, states[i].instance)) sat_idx.push_back(i);
        }
        if (sat_idx.empty()) return false;
        auto lca_table = pairwise_lca_table_from_matrix_(lca_matrix);
        auto ancestor_pairs = ancestor_pairs_from_tree_(tree);
        string parent_fingerprint = parent_vector_to_string_(tree.parent);
        for (size_t idx : sat_idx) {
            auto& st = states[idx];
            accumulate_sparse_oracle_solution_from_item_(tree, lca_table, ancestor_pairs, parent_fingerprint, st.instance, numeric_limits<size_t>::max(), &st.out, &st.first, &st.common_lca, &st.common_parent, &st.common_ancestor);
        }
        return false;
    });
    for (size_t i = 0; i < states.size(); ++i) {
        finalize_batch_exact_oracle_state_(&states[i]);
        g_solver_oracle_cache.emplace(keys[i], states[i].out);
    }
    if (why) *why = "";
    return true;
}

static vector<SchemaRule> current_solver_schema_rules_() {
    map<string, SchemaRule> uniq;
    vector<SchemaRule> raw;
    raw.push_back(canonicalize_schema_rule_(SchemaRule{0, {SchemaAtom{2,3,2}, SchemaAtom{2,4,5}}, SchemaAtom{3,4,5}}));
    raw.push_back(canonicalize_schema_rule_(SchemaRule{0, {SchemaAtom{2,3,2}, SchemaAtom{2,4,4}, SchemaAtom{3,5,4}}, SchemaAtom{2,5,4}}));
    raw.push_back(canonicalize_schema_rule_(SchemaRule{0, {SchemaAtom{2,3,2}, SchemaAtom{2,4,2}, SchemaAtom{3,4,5}}, SchemaAtom{2,5,2}}));
    raw.push_back(canonicalize_schema_rule_(SchemaRule{0, {SchemaAtom{1,2,1}, SchemaAtom{2,3,3}, SchemaAtom{2,4,5}, SchemaAtom{3,4,3}}, SchemaAtom{3,5,3}}));
    for (const auto& s : raw) uniq.emplace(s.fingerprint, s);
    vector<SchemaRule> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const SchemaRule& a, const SchemaRule& b) {
        if (a.antecedents.size() != b.antecedents.size()) return a.antecedents.size() < b.antecedents.size();
        return a.fingerprint < b.fingerprint;
    });
    return out;
}

static SparseLcaInstance lifted_solver_counterexample_(int n) {
    SparseLcaInstance inst;
    inst.n = n;
    inst.constraints = {{2,3,1}, {2,4,2}};
    return canonicalize_sparse_instance_(inst);
}

static vector<SchemaRule> schema_rules_to_solver_system_(const vector<SchemaRule>& schemas) {
    map<string, SchemaRule> uniq;
    for (const auto& raw : schemas) {
        auto canon = canonicalize_schema_rule_(raw);
        uniq.emplace(canon.fingerprint, canon);
    }
    vector<SchemaRule> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const SchemaRule& a, const SchemaRule& b) {
        if (a.antecedents.size() != b.antecedents.size()) return a.antecedents.size() < b.antecedents.size();
        return a.fingerprint < b.fingerprint;
    });
    return out;
}

static vector<SparseLcaConstraint> extra_derived_pairs_(const SparseClosureResult& closure,
                                                        const SparseCompletionOracleResult& oracle) {
    vector<SparseLcaConstraint> extra;
    for (const auto& kv : closure.state.known_lca) {
        auto it = oracle.forced_pairwise_lca.find(kv.first);
        if (it == oracle.forced_pairwise_lca.end() || it->second != kv.second) {
            extra.push_back({kv.first.first, kv.first.second, kv.second});
        }
    }
    sort(extra.begin(), extra.end(), sparse_constraint_less_);
    return extra;
}

static bool closure_has_full_table_(const SolverSaturationResult& sat) {
    return sat.closure.consistent && sat.closure_pairwise_lca.size() == (size_t)sat.instance.n * (size_t)(sat.instance.n - 1) / 2;
}

static StaticRootedView make_static_view_from_pairwise_lca_table_(int n,
                                                                  const map<pair<int,int>, int>& table) {
    StaticRootedView view;
    for (int v = 1; v <= n; ++v) {
        view.vertices.push_back(v);
        view.root[v] = 1;
        view.lca[{v, v}] = v;
        view.path_vertices[{v, v}] = {v};
        view.path_edges[{v, v}] = {};
    }
    if (n >= 1) {
        view.component_roots = {1};
        view.component_vertices[1] = view.vertices;
    }
    for (const auto& kv : table) {
        int u = kv.first.first, v = kv.first.second, w = kv.second;
        view.lca[{u, v}] = w;
        view.lca[{v, u}] = w;
    }
    finalize_static_rooted_view_(&view);
    return view;
}

static string sparse_rule_set_fingerprint_(const vector<SparseRuleCandidate>& rules) {
    vector<string> fps;
    for (const auto& rule : rules) fps.push_back(canonical_rule_fingerprint_(rule));
    sort(fps.begin(), fps.end());
    ostringstream oss;
    for (size_t i = 0; i < fps.size(); ++i) {
        if (i) oss << '|';
        oss << fps[i];
    }
    return oss.str();
}

static string schema_rule_set_fingerprint_(const vector<SchemaRule>& schemas) {
    vector<string> fps;
    for (const auto& schema : schemas) fps.push_back(canonicalize_schema_rule_(schema).fingerprint);
    sort(fps.begin(), fps.end());
    ostringstream oss;
    for (size_t i = 0; i < fps.size(); ++i) {
        if (i) oss << '|';
        oss << fps[i];
    }
    return oss.str();
}

static string solver_completion_cache_key_(const SparseLcaInstance& instance,
                                           const vector<SparseRuleCandidate>& base_sound_rules,
                                           const vector<SchemaRule>& schema_rules) {
    SparseLcaInstance canon = canonicalize_sparse_instance_(instance);
    return canonical_sparse_instance_fingerprint_(canon)
        + "|base=" + sparse_rule_set_fingerprint_(base_sound_rules)
        + "|schema=" + schema_rule_set_fingerprint_(schema_rules);
}

static SolverSaturationResult compute_solver_completion_closure_uncached_(const SparseLcaInstance& instance,
                                                                          const vector<SparseRuleCandidate>& base_sound_rules,
                                                                          const vector<SchemaRule>& schema_rules,
                                                                          string* why) {
    SolverSaturationResult sat;
    sat.instance = canonicalize_sparse_instance_(instance);
    sat.closure = run_sparse_schema_augmented_closure_(sat.instance, base_sound_rules, schema_rules);
    string oracle_why;
    sat.oracle = cached_exact_sparse_completion_oracle_(sat.instance, numeric_limits<size_t>::max(), &oracle_why);
    sat.closure_pairwise_lca = sat.closure.state.known_lca;
    sat.oracle_forced_pairwise_lca = sat.oracle.forced_pairwise_lca;
    sat.missing_forced_pairs = missing_forced_pairs_(sat.closure, sat.oracle);
    sat.extra_derived_pairs = extra_derived_pairs_(sat.closure, sat.oracle);
    sat.full_match = sat.closure.consistent && sat.closure_pairwise_lca == sat.oracle_forced_pairwise_lca;
    if (!sat.closure.consistent) sat.why = "closure inconsistent: " + sat.closure.why;
    else if (!sat.oracle.satisfiable) sat.why = oracle_why.empty() ? "unsatisfiable instance" : oracle_why;
    else if (!sat.full_match) {
        sat.why = "saturation mismatch";
        if (!sat.missing_forced_pairs.empty()) sat.why += " missing=" + sparse_constraint_vec_to_string_(sat.missing_forced_pairs);
        if (!sat.extra_derived_pairs.empty()) sat.why += " extra=" + sparse_constraint_vec_to_string_(sat.extra_derived_pairs);
    }
    if (why) *why = sat.why;
    return sat;
}

static SolverSaturationResult run_solver_completion_closure_(const SparseLcaInstance& instance,
                                                             const vector<SparseRuleCandidate>& base_sound_rules,
                                                             const vector<SchemaRule>& schema_rules,
                                                             string* why) {
    string key = solver_completion_cache_key_(instance, base_sound_rules, schema_rules);
    auto it = g_solver_completion_cache.find(key);
    if (it != g_solver_completion_cache.end()) {
        if (why) *why = it->second.why;
        return it->second;
    }
    auto sat = compute_solver_completion_closure_uncached_(instance, base_sound_rules, schema_rules, why);
    g_solver_completion_cache.emplace(key, sat);
    return sat;
}

static bool validate_solver_saturation_instance_(const SparseLcaInstance& instance,
                                                 const vector<SparseRuleCandidate>& base_sound_rules,
                                                 const vector<SchemaRule>& schema_rules,
                                                 SolverSaturationResult* out,
                                                 string* why) {
    auto sat = run_solver_completion_closure_(instance, base_sound_rules, schema_rules, why);
    if (out) *out = sat;
    if (!sat.oracle.satisfiable) return false;
    return sat.full_match;
}

static bool validate_closure_full_table_equiv_unique_completion_(const SparseLcaInstance& instance,
                                                                 const SolverSaturationResult& sat,
                                                                 string* why) {
    bool closure_full = closure_has_full_table_(sat);
    bool unique = sat.oracle.satisfiable && sat.oracle.solution_count == 1;
    if (closure_full != unique) {
        if (why) {
            *why = "closure full table <-> unique completion failed for " + sparse_instance_to_string_(instance)
                 + " closure_full=" + string(closure_full ? "true" : "false")
                 + " unique=" + string(unique ? "true" : "false");
        }
        return false;
    }
    return true;
}

static bool validate_closure_full_table_equiv_forced_parent_(const SparseLcaInstance& instance,
                                                             const SolverSaturationResult& sat,
                                                             string* why) {
    bool closure_full = closure_has_full_table_(sat);
    bool forced_parent = sat.oracle.satisfiable && sat.oracle.rooted_parent_forest_forced;
    if (closure_full != forced_parent) {
        if (why) {
            *why = "closure full table <-> rooted parent forest forced failed for " + sparse_instance_to_string_(instance)
                 + " closure_full=" + string(closure_full ? "true" : "false")
                 + " forced_parent=" + string(forced_parent ? "true" : "false");
        }
        return false;
    }
    return true;
}

static bool validate_closure_full_table_implies_reconstruction_(const SparseLcaInstance& instance,
                                                                const SolverSaturationResult& sat,
                                                                string* why) {
    if (!closure_has_full_table_(sat)) return true;
    if (!sat.oracle.rooted_parent_forest_forced) {
        if (why) *why = "closure full table holds but exact oracle does not force rooted parent forest for " + sparse_instance_to_string_(instance);
        return false;
    }
    StaticRootedView view = make_static_view_from_pairwise_lca_table_(instance.n, sat.closure_pairwise_lca);
    auto rec = reconstruct_parent_forest_from_lca_(view);
    if (!rec.ok) {
        if (why) *why = "reconstruction from closure full table failed: " + rec.why;
        return false;
    }
    unordered_map<int,int> expected_parent;
    unordered_map<int,int> expected_root;
    for (auto [child, parent] : sat.oracle.forced_parent_edges) expected_parent[child] = parent;
    for (int v = 1; v <= instance.n; ++v) expected_root[v] = 1;
    if (!equal_parent_like_maps_(rec.parent, expected_parent)) {
        if (why) *why = "reconstructed parent forest from closure full table does not match exact oracle";
        return false;
    }
    if (!equal_parent_like_maps_(rec.root, expected_root)) {
        if (why) *why = "reconstructed root map from closure full table does not match exact oracle";
        return false;
    }
    return true;
}

static SparseLcaInstance minimize_saturation_counterexample_(const SparseLcaInstance& instance,
                                                             const vector<SparseRuleCandidate>& base_sound_rules,
                                                             const vector<SchemaRule>& schema_rules,
                                                             string* why) {
    SparseLcaInstance base = normalize_sparse_instance_basic_(instance);
    vector<SparseLcaConstraint> cons = base.constraints;
    size_t m = cons.size();
    bool found = false;
    SparseLcaInstance best;
    size_t best_size = numeric_limits<size_t>::max();
    string best_fp;
    size_t subsets = 1ull << m;
    for (size_t mask = 0; mask < subsets; ++mask) {
        SparseLcaInstance cand;
        cand.n = base.n;
        for (size_t i = 0; i < m; ++i) if (mask & (1ull << i)) cand.constraints.push_back(cons[i]);
        auto sat = run_solver_completion_closure_(cand, base_sound_rules, schema_rules, nullptr);
        if (!sat.oracle.satisfiable || sat.full_match) continue;
        string fp = canonical_sparse_instance_fingerprint_(canonicalize_sparse_instance_(cand));
        if (!found || cand.constraints.size() < best_size ||
            (cand.constraints.size() == best_size && fp < best_fp)) {
            found = true;
            best = canonicalize_sparse_instance_(cand);
            best_size = best.constraints.size();
            best_fp = fp;
        }
    }
    if (!found) {
        if (why) *why = "no deletion-minimal solver saturation counterexample found";
        return SparseLcaInstance{};
    }
    return best;
}

static void local_progress_(const char* tag, size_t done, size_t total) {
#ifdef LOCAL_TEST
    static unordered_map<string, size_t> last_progress;
    string key(tag);
    size_t& last = last_progress[key];
    size_t stride = 200;
    if (total <= 50) stride = 1;
    else if (total <= 500) stride = 25;
    else if (total <= 2000) stride = 100;
    if (done == 0 || done == total || done - last >= stride) {
        cerr << "progress: " << tag << ' ' << done << '/' << total << "\n";
        last = done;
    }
#endif
}

static bool scan_solver_saturation_theorem_exhaustive_(int n,
                                                       const vector<SparseRuleCandidate>& base_sound_rules,
                                                       const vector<SchemaRule>& schema_rules,
                                                       SaturationTheoremStats* stats,
                                                       SolverSaturationResult* first_failure,
                                                       string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(n);
    SaturationTheoremStats local;
    local.n = n;
    local.rooted_trees = enum_res.rooted_trees;
    local.raw_instances = enum_res.raw_instances;
    local.canonical_instances = enum_res.canonical_instances.size();
    SolverSaturationResult local_first_failure;
    bool have_failure = false;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("solver_exact_n" , progress_idx, enum_res.canonical_instances.size());
        auto sat = run_solver_completion_closure_(inst, base_sound_rules, schema_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first_failure = sat; have_failure = true; }
        }
        if (closure_has_full_table_(sat)) ++local.full_table_instances;
        string cw;
        if (validate_closure_full_table_equiv_unique_completion_(inst, sat, &cw)) ++local.unique_completion_corollary_pass;
        else if (!have_failure) { sat.why += "\nC1: " + cw; local_first_failure = sat; have_failure = true; }
        cw.clear();
        if (validate_closure_full_table_equiv_forced_parent_(inst, sat, &cw)) ++local.forced_parent_corollary_pass;
        else if (!have_failure) { sat.why += "\nC2: " + cw; local_first_failure = sat; have_failure = true; }
        cw.clear();
        if (validate_closure_full_table_implies_reconstruction_(inst, sat, &cw)) ++local.reconstruction_corollary_pass;
        else if (!have_failure) { sat.why += "\nC3: " + cw; local_first_failure = sat; have_failure = true; }
    }
    if (have_failure) {
        string min_why;
        auto min_inst = minimize_saturation_counterexample_(local_first_failure.instance, base_sound_rules, schema_rules, &min_why);
        if (min_inst.n > 0) local_first_failure = run_solver_completion_closure_(min_inst, base_sound_rules, schema_rules, nullptr);
        else if (!min_why.empty()) local_first_failure.why += "\nminimizer: " + min_why;
    }
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    return true;
}

static bool scan_solver_saturation_theorem_randomized_(int n,
                                                       uint32_t seed,
                                                       int num_trees,
                                                       int num_subsets_per_tree,
                                                       const vector<SparseRuleCandidate>& base_sound_rules,
                                                       const vector<SchemaRule>& schema_rules,
                                                       SaturationTheoremStats* stats,
                                                       SolverSaturationResult* first_failure,
                                                       string* why) {
    auto instances = sample_canonical_sparse_instances_randomized_(n, seed, num_trees, num_subsets_per_tree);
    SaturationTheoremStats local;
    local.n = n;
    local.canonical_instances = instances.size();
    SolverSaturationResult local_first_failure;
    bool have_failure = false;
    size_t progress_idx = 0;
    for (const auto& inst : instances) {
        ++progress_idx;
        local_progress_("solver_sampled_n", progress_idx, instances.size());
        auto sat = run_solver_completion_closure_(inst, base_sound_rules, schema_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first_failure = sat; have_failure = true; }
        }
        if (closure_has_full_table_(sat)) ++local.full_table_instances;
        string cw;
        if (validate_closure_full_table_equiv_unique_completion_(inst, sat, &cw)) ++local.unique_completion_corollary_pass;
        else if (!have_failure) { sat.why += "\nC1: " + cw; local_first_failure = sat; have_failure = true; }
        cw.clear();
        if (validate_closure_full_table_equiv_forced_parent_(inst, sat, &cw)) ++local.forced_parent_corollary_pass;
        else if (!have_failure) { sat.why += "\nC2: " + cw; local_first_failure = sat; have_failure = true; }
        cw.clear();
        if (validate_closure_full_table_implies_reconstruction_(inst, sat, &cw)) ++local.reconstruction_corollary_pass;
        else if (!have_failure) { sat.why += "\nC3: " + cw; local_first_failure = sat; have_failure = true; }
    }
    if (have_failure) {
        string min_why;
        auto min_inst = minimize_saturation_counterexample_(local_first_failure.instance, base_sound_rules, schema_rules, &min_why);
        if (min_inst.n > 0) local_first_failure = run_solver_completion_closure_(min_inst, base_sound_rules, schema_rules, nullptr);
        else if (!min_why.empty()) local_first_failure.why += "\nminimizer: " + min_why;
    }
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    return true;
}

static string build_solver_theorem_status_ledger_(const SaturationTheoremStats& exact_n5,
                                                  const SaturationTheoremStats& sampled_n6,
                                                  const SaturationTheoremStats& sampled_n7,
                                                  const SaturationTheoremStats& sampled_n8) {
    ostringstream oss;
    oss << "exact_n5: " << saturation_theorem_stats_to_string_(exact_n5) << "\n";
    oss << "sampled_n6: " << saturation_theorem_stats_to_string_(sampled_n6) << "\n";
    oss << "sampled_n7: " << saturation_theorem_stats_to_string_(sampled_n7) << "\n";
    oss << "sampled_n8: " << saturation_theorem_stats_to_string_(sampled_n8);
    return oss.str();
}

