static string mismatch_witness_to_string_(const MismatchWitness& w) {
    ostringstream oss;
    oss << "instance=" << sparse_instance_to_string_(w.instance) << "\n";
    oss << "missing_target=" << sparse_constraint_to_string_(w.missing_target) << "\n";
    oss << "minimal_core=" << sparse_instance_to_string_(w.minimal_core) << "\n";
    oss << "family_fingerprint=" << w.family_fingerprint << "\n";
    oss << "target_fingerprint=" << w.target_fingerprint << "\n";
    oss << "completion_family_fingerprint=" << w.completion_family_fingerprint << "\n";
    oss << "support=" << w.support_count << "\n";
    return oss.str();
}

static string mismatch_family_summary_to_string_(const MismatchFamilySummary& fam) {
    ostringstream oss;
    oss << "family_fingerprint=" << fam.family_fingerprint << "\n";
    oss << "target_fingerprint=" << fam.target_fingerprint << "\n";
    oss << "representative_core=" << sparse_instance_to_string_(fam.representative_core) << "\n";
    oss << "representative_target=" << sparse_constraint_to_string_(fam.representative_target) << "\n";
    oss << "witness_count=" << fam.witness_count << "\n";
    oss << "sample_instances=";
    for (size_t i = 0; i < fam.sample_instances.size(); ++i) {
        if (i) oss << " | ";
        oss << sparse_instance_to_string_(fam.sample_instances[i]);
    }
    oss << "\n";
    return oss.str();
}

static string repair_principle_candidate_to_string_(const RepairPrincipleCandidate& cand) {
    ostringstream oss;
    oss << "source_family=" << cand.source_family_fingerprint << "\n";
    oss << "family_support=" << cand.family_support << "\n";
    oss << "human_readable=" << cand.human_readable_principle << "\n";
    oss << sparse_rule_candidate_to_string_(cand.local_rule) << "\n";
    return oss.str();
}

