static bool scan_augmented_solver_saturation_theorem_exhaustive_(int n,
                                                                 const vector<SparseRuleCandidate>& base_sound_rules,
                                                                 const vector<SchemaRule>& schema_rules,
                                                                 const vector<SparseRuleCandidate>& extra_repair_rules,
                                                                 SaturationTheoremStats* stats,
                                                                 SolverSaturationResult* first_failure,
                                                                 string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(n);
    SaturationTheoremStats local;
    local.n = n;
    local.rooted_trees = enum_res.rooted_trees;
    local.raw_instances = enum_res.raw_instances;
    local.canonical_instances = enum_res.canonical_instances.size();
    SolverSaturationResult local_first_failure;
    bool first_failed = false;
    for (const auto& inst : enum_res.canonical_instances) {
        auto sat = run_augmented_solver_completion_closure_(inst, base_sound_rules, schema_rules, extra_repair_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!first_failed) {
                first_failed = true;
                local_first_failure = sat;
            }
        }
        if (closure_has_full_table_(sat)) ++local.full_table_instances;
        string cor_why;
        if (validate_augmented_closure_full_table_equiv_unique_completion_(inst, sat, &cor_why)) ++local.unique_completion_corollary_pass;
        if (validate_augmented_closure_full_table_equiv_forced_parent_(inst, sat, &cor_why)) ++local.forced_parent_corollary_pass;
        if (validate_augmented_closure_full_table_implies_reconstruction_(inst, sat, &cor_why)) ++local.reconstruction_corollary_pass;
    }
    if (first_failed) {
        string min_why;
        auto min_inst = minimize_saturation_counterexample_(local_first_failure.instance, merge_repair_rule_sets_(base_sound_rules, extra_repair_rules), schema_rules, &min_why);
        if (min_inst.n > 0) local_first_failure = run_augmented_solver_completion_closure_(min_inst, base_sound_rules, schema_rules, extra_repair_rules, nullptr);
    }
    if (stats) *stats = local;
    if (first_failure) *first_failure = local_first_failure;
    if (why) *why = first_failed ? local_first_failure.why : "";
    return true;
}

static string repair_subset_fingerprint_(const vector<SparseRuleCandidate>& rules) {
    vector<string> fps;
    for (const auto& r : rules) fps.push_back(canonical_rule_fingerprint_(r));
    sort(fps.begin(), fps.end());
    ostringstream oss;
    for (size_t i = 0; i < fps.size(); ++i) {
        if (i) oss << '|';
        oss << fps[i];
    }
    return oss.str();
}

static vector<SparseRuleCandidate> search_minimal_repair_subset_(const vector<RepairPrincipleCandidate>& sound_candidates,
                                                                 const vector<SparseRuleCandidate>& base_sound_rules,
                                                                 const vector<SchemaRule>& schema_rules,
                                                                 string* why) {
    if (sound_candidates.empty()) {
        if (why) *why = "no sound repair candidates";
        return {};
    }
    const int m = (int)sound_candidates.size();
    bool found = false;
    vector<SparseRuleCandidate> best;
    size_t best_subset_size = numeric_limits<size_t>::max();
    size_t best_mismatch_instances = numeric_limits<size_t>::max();
    size_t best_pair_witnesses = numeric_limits<size_t>::max();
    bool best_kills_top_family = false;
    string best_fp;
    string dominant_family_fp = g_last_solver_mismatch_family_summaries.empty() ? string() : g_last_solver_mismatch_family_summaries.front().family_fingerprint;
    for (int mask = 1; mask < (1 << m); ++mask) {
        vector<SparseRuleCandidate> subset;
        for (int i = 0; i < m; ++i) if (mask & (1 << i)) subset.push_back(sound_candidates[i].local_rule);
        SaturationTheoremStats stats;
        SolverSaturationResult failure;
        string local_why;
        if (!scan_augmented_solver_saturation_theorem_exhaustive_(5, base_sound_rules, schema_rules, subset, &stats, &failure, &local_why)) {
            if (why && why->empty()) *why = local_why;
            continue;
        }
        auto post = collect_post_repair_mismatch_witnesses_(5, base_sound_rules, schema_rules, subset, 0, &local_why);
        auto post_fams = classify_post_repair_mismatch_families_(post);
        bool kills_top = true;
        if (!dominant_family_fp.empty()) {
            for (const auto& fam : post_fams) if (fam.family_fingerprint == dominant_family_fp) { kills_top = false; break; }
        }
        size_t subset_size = subset.size();
        size_t pair_witnesses = post.size();
        string fp = repair_subset_fingerprint_(subset);
        bool better = false;
        if (!found) better = true;
        else if (subset_size != best_subset_size) better = subset_size < best_subset_size;
        else if (stats.mismatch_instances != best_mismatch_instances) better = stats.mismatch_instances < best_mismatch_instances;
        else if (pair_witnesses != best_pair_witnesses) better = pair_witnesses < best_pair_witnesses;
        else if (kills_top != best_kills_top_family) better = kills_top && !best_kills_top_family;
        else if (fp < best_fp) better = true;
        if (better) {
            found = true;
            best = subset;
            best_subset_size = subset_size;
            best_mismatch_instances = stats.mismatch_instances;
            best_pair_witnesses = pair_witnesses;
            best_kills_top_family = kills_top;
            best_fp = fp;
        }
    }
    if (!found && why) *why = "no repair subset evaluated";
    return best;
}

static string build_repair_status_ledger_() {
    ostringstream oss;
    oss << "mismatchWitnesses=" << g_last_solver_mismatch_witnesses.size() << "\n";
    oss << "mismatchFamilies=" << g_last_solver_mismatch_family_summaries.size() << "\n";
    if (!g_last_solver_mismatch_family_summaries.empty()) {
        oss << "dominantFamilySupport=" << g_last_solver_mismatch_family_summaries.front().witness_count << "\n";
        oss << "dominantFamilyFingerprint=" << g_last_solver_mismatch_family_summaries.front().family_fingerprint << "\n";
    }
    oss << "repairCandidates=" << g_last_repair_principle_candidates.size() << "\n";
    oss << "soundRepairCandidates=" << g_last_locally_exact_sound_repair_candidates.size() << "\n";
    oss << "minimalRepairSubsetSize=" << g_last_minimal_repair_subset.size() << "\n";
    oss << "augmentedExactN5=" << saturation_theorem_stats_to_string_(g_last_augmented_solver_saturation_exhaustive_n5_stats) << "\n";
    oss << "postRepairMismatchWitnesses=" << g_last_post_repair_mismatch_witnesses.size() << "\n";
    oss << "postRepairMismatchFamilies=" << g_last_post_repair_mismatch_family_summaries.size() << "\n";
    return oss.str();
}


