static bool scan_second_wave_augmented_solver_saturation_theorem_exhaustive_(int n,
                                                                              const vector<SparseRuleCandidate>& base_sound_rules,
                                                                              const vector<SchemaRule>& schema_rules,
                                                                              const vector<SparseRuleCandidate>& first_wave_repair_rules,
                                                                              const vector<SparseRuleCandidate>& second_wave_repair_rules,
                                                                              SaturationTheoremStats* stats,
                                                                              SolverSaturationResult* first_failure,
                                                                              string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(n);
    SaturationTheoremStats local;
    local.n = n;
    local.rooted_trees = enum_res.rooted_trees;
    local.raw_instances = enum_res.raw_instances;
    local.canonical_instances = enum_res.canonical_instances.size();
    SolverSaturationResult local_first_failure;
    bool first_failed = false;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("second_wave_exact_n", progress_idx, enum_res.canonical_instances.size());
        auto sat = run_second_wave_augmented_solver_completion_closure_(inst, base_sound_rules, schema_rules, first_wave_repair_rules, second_wave_repair_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!first_failed) {
                first_failed = true;
                local_first_failure = sat;
            }
        }
        if (closure_has_full_table_(sat)) ++local.full_table_instances;
        string cor_why;
        if (validate_second_wave_augmented_closure_full_table_equiv_unique_completion_(inst, sat, &cor_why)) ++local.unique_completion_corollary_pass;
        if (validate_second_wave_augmented_closure_full_table_equiv_forced_parent_(inst, sat, &cor_why)) ++local.forced_parent_corollary_pass;
        if (validate_second_wave_augmented_closure_full_table_implies_reconstruction_(inst, sat, &cor_why)) ++local.reconstruction_corollary_pass;
    }
    if (first_failed) {
        string min_why;
        auto all_repair = merge_repair_rule_sets_(first_wave_repair_rules, second_wave_repair_rules);
        auto min_inst = minimize_saturation_counterexample_(local_first_failure.instance,
                                                            merge_repair_rule_sets_(base_sound_rules, all_repair),
                                                            schema_rules,
                                                            &min_why);
        if (min_inst.n > 0) local_first_failure = run_second_wave_augmented_solver_completion_closure_(min_inst, base_sound_rules, schema_rules, first_wave_repair_rules, second_wave_repair_rules, nullptr);
    }
    if (stats) *stats = local;
    if (first_failure) *first_failure = local_first_failure;
    if (why) *why = first_failed ? local_first_failure.why : "";
    return true;
}

static vector<MismatchWitness> collect_post_second_wave_mismatch_witnesses_(int n,
                                                                             const vector<SparseRuleCandidate>& base_sound_rules,
                                                                             const vector<SchemaRule>& schema_rules,
                                                                             const vector<SparseRuleCandidate>& first_wave_repair_rules,
                                                                             const vector<SparseRuleCandidate>& second_wave_repair_rules,
                                                                             string* why) {
    auto all_repair = merge_repair_rule_sets_(first_wave_repair_rules, second_wave_repair_rules);
    return collect_solver_mismatch_witnesses_under_rules_(n, base_sound_rules, schema_rules, all_repair, 0, why);
}

static vector<MismatchFamilySummary> classify_post_second_wave_mismatch_families_(const vector<MismatchWitness>& witnesses) {
    return classify_solver_mismatch_families_(witnesses);
}

static vector<SparseRuleCandidate> search_minimal_second_wave_repair_subset_(const vector<RepairPrincipleCandidate>& sound_candidates,
                                                                              const vector<SparseRuleCandidate>& base_sound_rules,
                                                                              const vector<SchemaRule>& schema_rules,
                                                                              const vector<SparseRuleCandidate>& first_wave_repair_rules,
                                                                              string* why) {
    string dominant_family_fp = g_last_post_repair_mismatch_family_summaries.empty() ? string() : g_last_post_repair_mismatch_family_summaries.front().family_fingerprint;
    const int m = (int)sound_candidates.size();
    bool found = false;
    vector<SparseRuleCandidate> best;
    size_t best_subset_size = numeric_limits<size_t>::max();
    size_t best_mismatch_instances = numeric_limits<size_t>::max();
    size_t best_pair_witnesses = numeric_limits<size_t>::max();
    bool best_kills_top = false;
    string best_fp;
    int max_mask = (m == 0 ? 1 : (1 << m));
    for (int mask = 0; mask < max_mask; ++mask) {
        vector<SparseRuleCandidate> subset;
        for (int i = 0; i < m; ++i) if (mask & (1 << i)) subset.push_back(sound_candidates[i].local_rule);
        SaturationTheoremStats stats;
        SolverSaturationResult failure;
        string local_why;
        if (!scan_second_wave_augmented_solver_saturation_theorem_exhaustive_(5, base_sound_rules, schema_rules, first_wave_repair_rules, subset, &stats, &failure, &local_why)) {
            if (why && why->empty()) *why = local_why;
            continue;
        }
        auto post = collect_post_second_wave_mismatch_witnesses_(5, base_sound_rules, schema_rules, first_wave_repair_rules, subset, &local_why);
        auto post_fams = classify_post_second_wave_mismatch_families_(post);
        bool kills_top = dominant_family_fp.empty() ? true : !mismatch_family_present_(post_fams, dominant_family_fp);
        size_t subset_size = subset.size();
        size_t pair_witnesses = post.size();
        string fp = repair_subset_fingerprint_(subset);
        bool better = false;
        if (!found) better = true;
        else if (kills_top != best_kills_top) better = kills_top && !best_kills_top;
        else if (stats.mismatch_instances != best_mismatch_instances) better = stats.mismatch_instances < best_mismatch_instances;
        else if (pair_witnesses != best_pair_witnesses) better = pair_witnesses < best_pair_witnesses;
        else if (subset_size != best_subset_size) better = subset_size < best_subset_size;
        else if (fp < best_fp) better = true;
        if (better) {
            found = true;
            best = subset;
            best_subset_size = subset_size;
            best_mismatch_instances = stats.mismatch_instances;
            best_pair_witnesses = pair_witnesses;
            best_kills_top = kills_top;
            best_fp = fp;
        }
    }
    if (!found && why) *why = "no second-wave repair subset evaluated";
    return best;
}

static string classify_local_vs_nonlocal_frontier_(const RepairFrontierStats& stats) {
    if (stats.second_wave_instance_mismatches == 0 && stats.second_wave_pair_witnesses == 0) return "local_repair_still_promising";
    bool improved = (stats.second_wave_instance_mismatches < stats.first_wave_instance_mismatches)
                 || (stats.second_wave_pair_witnesses < stats.first_wave_pair_witnesses);
    if (improved) {
        if (stats.second_wave_dominant_family_eliminated) return "local_repair_still_promising";
        return "local_repair_improves_but_not_decisive";
    }
    return "nonlocal_gap_hypothesis_strengthened";
}

static string build_repair_frontier_ledger_(const RepairFrontierStats& stats) {
    ostringstream oss;
    oss << "baseInstanceMismatches=" << stats.base_instance_mismatches << "\n";
    oss << "basePairWitnesses=" << stats.base_pair_witnesses << "\n";
    oss << "firstWaveInstanceMismatches=" << stats.first_wave_instance_mismatches << "\n";
    oss << "firstWavePairWitnesses=" << stats.first_wave_pair_witnesses << "\n";
    oss << "secondWaveInstanceMismatches=" << stats.second_wave_instance_mismatches << "\n";
    oss << "secondWavePairWitnesses=" << stats.second_wave_pair_witnesses << "\n";
    oss << "firstWaveDominantFamilyEliminated=" << (stats.first_wave_dominant_family_eliminated ? "true" : "false") << "\n";
    oss << "secondWaveDominantFamilyEliminated=" << (stats.second_wave_dominant_family_eliminated ? "true" : "false") << "\n";
    oss << "frontierClassification=" << stats.frontier_classification << "\n";
    if (!stats.why.empty()) oss << "why=" << stats.why << "\n";
    return oss.str();
}


struct RetainedRuleAntecedentInstance {
    SparseLcaInstance antecedent_instance;
    SparseLcaConstraint instantiated_consequent{};
    string fingerprint;
    size_t embedding_count = 0;
};

static string retained_repair_rule_stress_stats_to_string_(const RetainedRepairRuleStressStats& s) {
    ostringstream oss;
    oss << "rule=" << s.rule_fingerprint
        << " supportSize=" << s.support_size
        << " localExact=" << (s.local_exact_pass ? "true" : "false")
        << " plusOneAttempted=" << (s.plus_one_exact_attempted ? "true" : "false")
        << " plusOnePass=" << (s.plus_one_exact_pass ? "true" : "false")
        << " targetN=" << s.plus_one_target_n
        << " checked=" << s.plus_one_instances_checked
        << " hits=" << s.plus_one_hits;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string repaired_theorem_stats_to_string_(const RepairedTheoremStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " canonical=" << s.canonical_instances
        << " satisfiable=" << s.satisfiable_instances
        << " fullMatch=" << s.full_match_instances
        << " mismatch=" << s.mismatch_instances
        << " pairWitnesses=" << s.pair_witnesses
        << " familyCount=" << s.family_count
        << " exactN5Verified=" << (s.exact_n5_verified ? "true" : "false");
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static vector<SparseRuleCandidate> retained_first_wave_repair_rules_();
static vector<SparseRuleCandidate> retained_second_wave_repair_rules_();
static vector<SparseRuleCandidate> retained_all_repair_rules_();
