static void ensure_first_wave_repair_results_ready_() {
    auto schemas = current_solver_schema_rules_();
    string why;
    cerr << "ensure: base exact n5\n";
    if (g_last_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                        &g_last_solver_saturation_exhaustive_n5_stats,
                                                        &g_last_solver_saturation_exhaustive_n5_failure,
                                                        &why)) {
            throw runtime_error("ensure_first_wave: solver saturation exhaustive n5 failed\n" + why);
        }
    }
    if (g_last_solver_mismatch_witnesses.empty()) {
        g_last_solver_mismatch_witnesses = collect_solver_mismatch_witnesses_(5, {}, schemas, 0, &why);
        if (!why.empty()) throw runtime_error("ensure_first_wave: collect solver mismatch witnesses failed\n" + why);
    }
    if (g_last_solver_mismatch_family_summaries.empty()) {
        g_last_solver_mismatch_family_summaries = classify_solver_mismatch_families_(g_last_solver_mismatch_witnesses);
    }
    if (g_last_repair_principle_candidates.empty()) {
        auto top = rank_mismatch_families_by_support_(g_last_solver_mismatch_family_summaries, 3);
        g_last_repair_principle_candidates = derive_repair_principles_from_top_families_(top);
    }
    if (g_last_locally_exact_sound_repair_candidates.empty()) {
        g_last_locally_exact_sound_repair_candidates = filter_locally_exact_sound_repair_candidates_(g_last_repair_principle_candidates, &why);
        if (!why.empty() && g_last_locally_exact_sound_repair_candidates.empty()) {
            throw runtime_error("ensure_first_wave: filter locally exact sound repair candidates failed\n" + why);
        }
    }
    if (g_last_minimal_repair_subset.empty()) {
        g_last_minimal_repair_subset = search_minimal_repair_subset_(g_last_locally_exact_sound_repair_candidates, {}, schemas, &why);
        if (g_last_minimal_repair_subset.empty()) throw runtime_error("ensure_first_wave: minimal repair subset empty\n" + why);
    }
    cerr << "ensure: first-wave exact n5\n";
    if (g_last_augmented_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_augmented_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                                  g_last_minimal_repair_subset,
                                                                  &g_last_augmented_solver_saturation_exhaustive_n5_stats,
                                                                  &g_last_augmented_solver_saturation_exhaustive_n5_failure,
                                                                  &why)) {
            throw runtime_error("ensure_first_wave: augmented exhaustive n5 failed\n" + why);
        }
    }
    if (g_last_post_repair_mismatch_witnesses.empty()) {
        g_last_post_repair_mismatch_witnesses = collect_post_repair_mismatch_witnesses_full_(5, {}, schemas, g_last_minimal_repair_subset, &why);
        if (!why.empty()) throw runtime_error("ensure_first_wave: post-repair mismatch witness collection failed\n" + why);
    }
    if (g_last_post_repair_mismatch_family_summaries.empty()) {
        g_last_post_repair_mismatch_family_summaries = classify_post_repair_mismatch_families_(g_last_post_repair_mismatch_witnesses);
    }
    g_last_repair_status_ledger = build_repair_status_ledger_();
}

static void ensure_second_wave_repair_results_ready_() {
    ensure_first_wave_repair_results_ready_();
    auto schemas = current_solver_schema_rules_();
    string why;
    if (g_last_second_wave_repair_principle_candidates.empty()) {
        auto top = rank_post_repair_mismatch_families_by_support_(g_last_post_repair_mismatch_family_summaries, 3);
        g_last_second_wave_repair_principle_candidates = derive_second_wave_repair_principles_(top);
    }
    if (g_last_locally_exact_sound_second_wave_repairs.empty()) {
        g_last_locally_exact_sound_second_wave_repairs = filter_locally_exact_sound_second_wave_repairs_(g_last_second_wave_repair_principle_candidates, &why);
        if (!why.empty() && g_last_locally_exact_sound_second_wave_repairs.empty() && !g_last_second_wave_repair_principle_candidates.empty()) {
            throw runtime_error("ensure_second_wave: filter locally exact sound second-wave repairs failed\n" + why);
        }
    }
    if (g_last_minimal_second_wave_repair_subset.empty() && !g_last_locally_exact_sound_second_wave_repairs.empty()) {
        g_last_minimal_second_wave_repair_subset = search_minimal_second_wave_repair_subset_(g_last_locally_exact_sound_second_wave_repairs,
                                                                                             {}, schemas,
                                                                                             g_last_minimal_repair_subset,
                                                                                             &why);
        if (g_last_minimal_second_wave_repair_subset.empty()) {
            throw runtime_error("ensure_second_wave: minimal second-wave repair subset empty\n" + why);
        }
    }
    cerr << "ensure: second-wave exact n5\n";
    if (g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_second_wave_augmented_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                                              g_last_minimal_repair_subset,
                                                                              g_last_minimal_second_wave_repair_subset,
                                                                              &g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats,
                                                                              &g_last_second_wave_augmented_solver_saturation_exhaustive_n5_failure,
                                                                              &why)) {
            throw runtime_error("ensure_second_wave: second-wave augmented exhaustive n5 failed\n" + why);
        }
    }
    if (g_last_post_second_wave_mismatch_witnesses.empty()) {
        g_last_post_second_wave_mismatch_witnesses = collect_post_second_wave_mismatch_witnesses_(5, {}, schemas,
                                                                                                  g_last_minimal_repair_subset,
                                                                                                  g_last_minimal_second_wave_repair_subset,
                                                                                                  &why);
        if (!why.empty()) throw runtime_error("ensure_second_wave: post-second-wave mismatch witness collection failed\n" + why);
    }
    if (g_last_post_second_wave_mismatch_family_summaries.empty()) {
        g_last_post_second_wave_mismatch_family_summaries = classify_post_second_wave_mismatch_families_(g_last_post_second_wave_mismatch_witnesses);
    }
    g_last_second_wave_repair_stats = {};
    g_last_second_wave_repair_stats.derived_candidates = g_last_second_wave_repair_principle_candidates.size();
    g_last_second_wave_repair_stats.locally_exact_sound_candidates = g_last_locally_exact_sound_second_wave_repairs.size();
    g_last_second_wave_repair_stats.chosen_subset_size = g_last_minimal_second_wave_repair_subset.size();
    g_last_second_wave_repair_stats.before_instance_mismatches = g_last_augmented_solver_saturation_exhaustive_n5_stats.mismatch_instances;
    g_last_second_wave_repair_stats.before_pair_witnesses = g_last_post_repair_mismatch_witnesses.size();
    g_last_second_wave_repair_stats.after_instance_mismatches = g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats.mismatch_instances;
    g_last_second_wave_repair_stats.after_pair_witnesses = g_last_post_second_wave_mismatch_witnesses.size();
    string dominant_post_fp = g_last_post_repair_mismatch_family_summaries.empty() ? string() : g_last_post_repair_mismatch_family_summaries.front().family_fingerprint;
    g_last_second_wave_repair_stats.dominant_family_eliminated = dominant_post_fp.empty() ? false : !mismatch_family_present_(g_last_post_second_wave_mismatch_family_summaries, dominant_post_fp);

    g_last_repair_frontier_stats = {};
    g_last_repair_frontier_stats.base_instance_mismatches = g_last_solver_saturation_exhaustive_n5_stats.mismatch_instances;
    g_last_repair_frontier_stats.base_pair_witnesses = g_last_solver_mismatch_witnesses.size();
    g_last_repair_frontier_stats.first_wave_instance_mismatches = g_last_augmented_solver_saturation_exhaustive_n5_stats.mismatch_instances;
    g_last_repair_frontier_stats.first_wave_pair_witnesses = g_last_post_repair_mismatch_witnesses.size();
    g_last_repair_frontier_stats.second_wave_instance_mismatches = g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats.mismatch_instances;
    g_last_repair_frontier_stats.second_wave_pair_witnesses = g_last_post_second_wave_mismatch_witnesses.size();
    string dominant_base_fp = g_last_solver_mismatch_family_summaries.empty() ? string() : g_last_solver_mismatch_family_summaries.front().family_fingerprint;
    g_last_repair_frontier_stats.first_wave_dominant_family_eliminated = dominant_base_fp.empty() ? false : !mismatch_family_present_(g_last_post_repair_mismatch_family_summaries, dominant_base_fp);
    g_last_repair_frontier_stats.second_wave_dominant_family_eliminated = dominant_post_fp.empty() ? false : !mismatch_family_present_(g_last_post_second_wave_mismatch_family_summaries, dominant_post_fp);
    g_last_repair_frontier_stats.frontier_classification = classify_local_vs_nonlocal_frontier_(g_last_repair_frontier_stats);
    g_last_repair_frontier_ledger = build_repair_frontier_ledger_(g_last_repair_frontier_stats);
}

static vector<SparseRuleCandidate> retained_first_wave_repair_rules_() {
    if (!g_last_retained_first_wave_repair_rules.empty()) return g_last_retained_first_wave_repair_rules;
    SparseRuleCandidate rule;
    rule.n = 4;
    rule.antecedents = {normalize_sparse_constraint_({2,3,1}), normalize_sparse_constraint_({2,4,4})};
    sort(rule.antecedents.begin(), rule.antecedents.end(), sparse_constraint_less_);
    rule.consequent = normalize_sparse_constraint_({3,4,1});
    rule = canonicalize_rule_candidate_(rule);
    g_last_retained_first_wave_repair_rules = {rule};
    return g_last_retained_first_wave_repair_rules;
}

static vector<SparseRuleCandidate> retained_second_wave_repair_rules_() {
    if (!g_last_retained_second_wave_repair_rules.empty()) return g_last_retained_second_wave_repair_rules;
    SparseRuleCandidate rule;
    rule.n = 4;
    rule.antecedents = {normalize_sparse_constraint_({2,3,1}), normalize_sparse_constraint_({2,4,2})};
    sort(rule.antecedents.begin(), rule.antecedents.end(), sparse_constraint_less_);
    rule.consequent = normalize_sparse_constraint_({3,4,1});
    rule = canonicalize_rule_candidate_(rule);
    g_last_retained_second_wave_repair_rules = {rule};
    return g_last_retained_second_wave_repair_rules;
}

static vector<SparseRuleCandidate> retained_all_repair_rules_() {
    if (!g_last_retained_all_repair_rules.empty()) return g_last_retained_all_repair_rules;
    g_last_retained_all_repair_rules = merge_repair_rule_sets_(retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_());
    return g_last_retained_all_repair_rules;
}

static string retained_repair_rule_set_fingerprint_() {
    return sparse_rule_set_fingerprint_(retained_all_repair_rules_());
}

