static void ensure_repaired_mismatch_families_light_() {
    if (!g_last_repaired_theorem_mismatch_family_summaries.empty()) return;
    auto schemas = current_solver_schema_rules_();
    string why;
    g_last_retained_first_wave_repair_rules = retained_first_wave_repair_rules_();
    g_last_retained_second_wave_repair_rules = retained_second_wave_repair_rules_();
    g_last_retained_all_repair_rules = retained_all_repair_rules_();
    if (g_last_repaired_theorem_exact_n5_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_exhaustive_n5_({}, schemas,
                                                                    g_last_retained_first_wave_repair_rules,
                                                                    g_last_retained_second_wave_repair_rules,
                                                                    &g_last_repaired_theorem_exact_n5_stats,
                                                                    &g_last_repaired_theorem_exact_n5_failure,
                                                                    &why)) {
            throw runtime_error("ensure_repaired_mismatch_families_light: exact n5 scan failed\n" + why);
        }
    }
    if (g_last_repaired_theorem_mismatch_witnesses.empty() && g_last_repaired_theorem_exact_n5_stats.mismatch_instances > 0) {
        g_last_repaired_theorem_mismatch_witnesses = collect_repaired_theorem_mismatch_witnesses_(5, {}, schemas,
                                                                                                   g_last_retained_first_wave_repair_rules,
                                                                                                   g_last_retained_second_wave_repair_rules,
                                                                                                   &why);
        if (!why.empty()) throw runtime_error("ensure_repaired_mismatch_families_light: witness collection failed\n" + why);
    }
    if (g_last_repaired_theorem_mismatch_family_summaries.empty() && !g_last_repaired_theorem_mismatch_witnesses.empty()) {
        g_last_repaired_theorem_mismatch_family_summaries = classify_repaired_theorem_mismatch_families_(g_last_repaired_theorem_mismatch_witnesses);
    }
}

static RetainedRuleAntecedentInstance instantiate_retained_rule_under_mapping_(const SparseRuleCandidate& raw_rule,
                                                                               const vector<int>& mapping,
                                                                               int target_n) {
    auto rule = canonicalize_rule_candidate_(raw_rule);
    RetainedRuleAntecedentInstance out;
    out.antecedent_instance.n = target_n;
    for (const auto& c : rule.antecedents) out.antecedent_instance.constraints.push_back(apply_mapping_to_sparse_constraint_(c, mapping));
    out.antecedent_instance = canonicalize_sparse_instance_(out.antecedent_instance);
    out.instantiated_consequent = apply_mapping_to_sparse_constraint_(rule.consequent, mapping);
    out.fingerprint = canonical_sparse_instance_fingerprint_(out.antecedent_instance) + "|" + sparse_constraint_to_string_(out.instantiated_consequent);
    return out;
}

static vector<RetainedRuleAntecedentInstance> collect_unique_retained_rule_antecedent_instances_(const SparseRuleCandidate& raw_rule,
                                                                                                  int target_n,
                                                                                                  size_t* total_embeddings,
                                                                                                  string* why) {
    auto rule = canonicalize_rule_candidate_(raw_rule);
    if (total_embeddings) *total_embeddings = 0;
    map<string, RetainedRuleAntecedentInstance> uniq;
    auto vertices = sparse_rule_vertices_(rule);
    for_each_root_preserving_injection_(vertices, target_n, [&](const vector<int>& mapping) {
        if (total_embeddings) ++*total_embeddings;
        auto inst = instantiate_retained_rule_under_mapping_(rule, mapping, target_n);
        auto& slot = uniq[inst.fingerprint];
        if (slot.fingerprint.empty()) slot = inst;
        ++slot.embedding_count;
        return false;
    });
    vector<RetainedRuleAntecedentInstance> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const RetainedRuleAntecedentInstance& a, const RetainedRuleAntecedentInstance& b) {
        return a.fingerprint < b.fingerprint;
    });
    if (why) *why = "";
    return out;
}

static bool validate_retained_repair_rule_exact_extension_full_(const SparseRuleCandidate& raw_rule,
                                                                RetainedRepairRuleStressStats* stats,
                                                                string* why) {
    auto rule = canonicalize_rule_candidate_(raw_rule);
    RetainedRepairRuleStressStats local;
    local.rule_fingerprint = rule.fingerprint;
    local.support_size = repair_principle_support_size_(rule);
    local.local_exact_pass = validate_repair_principle_local_exact_(rule, why);
    if (!local.local_exact_pass) {
        local.why = why ? *why : string();
        if (stats) *stats = local;
        return false;
    }
    local.plus_one_exact_attempted = true;
    local.plus_one_target_n = local.support_size + 1;
    size_t total_embeddings = 0;
    string collect_why;
    auto instances = collect_unique_retained_rule_antecedent_instances_(rule, local.plus_one_target_n, &total_embeddings, &collect_why);
    if (!collect_why.empty()) {
        if (why) *why = collect_why;
        local.why = collect_why;
        if (stats) *stats = local;
        return false;
    }
    local.plus_one_instances_checked = instances.size();
    for (const auto& inst : instances) {
        string oracle_why;
        auto oracle = exact_sparse_completion_oracle_(inst.antecedent_instance, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        ++local.plus_one_hits;
        auto it = oracle.forced_pairwise_lca.find({inst.instantiated_consequent.u, inst.instantiated_consequent.v});
        int forced = (it == oracle.forced_pairwise_lca.end()) ? -1 : it->second;
        if (forced != inst.instantiated_consequent.w) {
            local.plus_one_exact_pass = false;
            local.why = "retained repair rule exact extension failed on antecedent-only instance "
                       + sparse_instance_to_string_(inst.antecedent_instance)
                       + " with consequent " + sparse_constraint_to_string_(inst.instantiated_consequent)
                       + "; forced value=" + (it == oracle.forced_pairwise_lca.end() ? string("<missing>") : to_string(forced));
            if (why) *why = local.why;
            if (stats) *stats = local;
            return false;
        }
    }
    local.plus_one_exact_pass = true;
    if (stats) *stats = local;
    if (why) *why = "";
    return true;
}

static vector<RetainedRepairRuleStressStats> build_retained_repair_rule_stress_profiles_() {
    auto rules = retained_all_repair_rules_();
    vector<RetainedRepairRuleStressStats> out;
    for (const auto& rule : rules) {
        RetainedRepairRuleStressStats stats;
        string why;
        validate_retained_repair_rule_exact_extension_full_(rule, &stats, &why);
        if (!why.empty() && stats.why.empty()) stats.why = why;
        out.push_back(stats);
    }
    sort(out.begin(), out.end(), [](const RetainedRepairRuleStressStats& a, const RetainedRepairRuleStressStats& b) {
        return a.rule_fingerprint < b.rule_fingerprint;
    });
    return out;
}

static SolverSaturationResult run_repaired_solver_completion_closure_(const SparseLcaInstance& instance,
                                                                      const vector<SparseRuleCandidate>& base_sound_rules,
                                                                      const vector<SchemaRule>& schema_rules,
                                                                      const vector<SparseRuleCandidate>& first_wave_rules,
                                                                      const vector<SparseRuleCandidate>& second_wave_rules,
                                                                      string* why) {
    auto all_repair = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
    return run_augmented_solver_completion_closure_(instance, base_sound_rules, schema_rules, all_repair, why);
}


static vector<MismatchFamilySummary> classify_repaired_theorem_mismatch_families_(const vector<MismatchWitness>& witnesses) {
    return classify_solver_mismatch_families_(witnesses);
}

static vector<MismatchWitness> collect_repaired_theorem_mismatch_witnesses_(int n,
                                                                            const vector<SparseRuleCandidate>& base_sound_rules,
                                                                            const vector<SchemaRule>& schema_rules,
                                                                            const vector<SparseRuleCandidate>& first_wave_rules,
                                                                            const vector<SparseRuleCandidate>& second_wave_rules,
                                                                            string* why) {
    auto all_repair = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
    return collect_solver_mismatch_witnesses_under_rules_(n, base_sound_rules, schema_rules, all_repair, 0, why);
}

static bool scan_repaired_solver_saturation_theorem_exhaustive_n5_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                                   const vector<SchemaRule>& schema_rules,
                                                                   const vector<SparseRuleCandidate>& first_wave_rules,
                                                                   const vector<SparseRuleCandidate>& second_wave_rules,
                                                                   RepairedTheoremStats* stats,
                                                                   SolverSaturationResult* first_failure,
                                                                   string* why) {
    SaturationTheoremStats raw;
    SolverSaturationResult raw_failure;
    string local_why;
    if (!scan_second_wave_augmented_solver_saturation_theorem_exhaustive_(5, base_sound_rules, schema_rules,
                                                                          first_wave_rules, second_wave_rules,
                                                                          &raw, &raw_failure, &local_why)) {
        if (why) *why = local_why;
        return false;
    }
    auto witnesses = collect_repaired_theorem_mismatch_witnesses_(5, base_sound_rules, schema_rules, first_wave_rules, second_wave_rules, &local_why);
    if (!local_why.empty()) {
        if (why) *why = local_why;
        return false;
    }
    auto families = classify_solver_mismatch_families_(witnesses);
    RepairedTheoremStats local;
    local.n = 5;
    local.canonical_instances = raw.canonical_instances;
    local.satisfiable_instances = raw.satisfiable_instances;
    local.full_match_instances = raw.full_match_instances;
    local.mismatch_instances = raw.mismatch_instances;
    local.pair_witnesses = witnesses.size();
    local.family_count = families.size();
    local.exact_n5_verified = (raw.mismatch_instances == 0 && witnesses.empty() && families.empty() && raw.full_match_instances == raw.satisfiable_instances);
    if (stats) *stats = local;
    if (first_failure) *first_failure = raw_failure;
    if (why) *why = local_why;
    return true;
}

static bool scan_repaired_solver_saturation_theorem_randomized_(int n,
                                                                uint32_t seed,
                                                                int num_trees,
                                                                int num_subsets_per_tree,
                                                                const vector<SparseRuleCandidate>& base_sound_rules,
                                                                const vector<SchemaRule>& schema_rules,
                                                                const vector<SparseRuleCandidate>& first_wave_rules,
                                                                const vector<SparseRuleCandidate>& second_wave_rules,
                                                                RepairedTheoremStats* stats,
                                                                SolverSaturationResult* first_failure,
                                                                string* why) {
    auto instances = sample_canonical_sparse_instances_randomized_(n, seed, num_trees, num_subsets_per_tree);
    RepairedTheoremStats local;
    local.n = n;
    local.canonical_instances = instances.size();
    SolverSaturationResult local_first_failure;
    bool have_failure = false;
    size_t pair_witnesses = 0;
    size_t progress_idx = 0;
    for (const auto& inst : instances) {
        ++progress_idx;
        local_progress_("repaired_sampled_n", progress_idx, instances.size());
        auto sat = run_repaired_solver_completion_closure_(inst, base_sound_rules, schema_rules, first_wave_rules, second_wave_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        pair_witnesses += sat.missing_forced_pairs.size();
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first_failure = sat; have_failure = true; }
        }
    }
    local.pair_witnesses = pair_witnesses;
    local.exact_n5_verified = false;
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    if (why) *why = have_failure ? local_first_failure.why : string();
    return true;
}

struct BoundedExactEnumerationResult {
    size_t rooted_trees = 0;
    size_t raw_instances = 0;
    vector<SparseLcaInstance> canonical_instances;
};

static void generate_pair_index_subsets_up_to_k_(int m, int k, vector<vector<int>>* out) {
    vector<int> cur;
    function<void(int,int)> dfs = [&](int idx, int left) {
        out->push_back(cur);
        if (left == 0) return;
        for (int i = idx; i < m; ++i) {
            cur.push_back(i);
            dfs(i + 1, left - 1);
            cur.pop_back();
        }
    };
    out->clear();
    dfs(0, k);
}

static void generate_pair_index_subsets_exact_k_(int m, int k, vector<vector<int>>* out) {
    vector<int> cur;
    function<void(int,int)> dfs = [&](int idx, int need) {
        if (need == 0) {
            out->push_back(cur);
            return;
        }
        if (idx >= m) return;
        for (int i = idx; i <= m - need; ++i) {
            cur.push_back(i);
            dfs(i + 1, need - 1);
            cur.pop_back();
        }
    };
    out->clear();
    if (k < 0 || k > m) return;
    dfs(0, k);
}


static SparseLcaInstance canonicalize_sparse_instance_small_support_root_preserving_(const SparseLcaInstance& instance) {
    SparseLcaInstance base = normalize_sparse_instance_basic_(instance);
    static unordered_map<string, SparseLcaInstance> cache;
    string base_fp = sparse_instance_to_string_(base);
    auto it = cache.find(base_fp);
    if (it != cache.end()) return it->second;

    vector<int> used;
    used.reserve(base.constraints.size() * 3 + 1);
    used.push_back(1);
    for (const auto& c : base.constraints) {
        used.push_back(c.u);
        used.push_back(c.v);
        used.push_back(c.w);
    }
    sort(used.begin(), used.end());
    used.erase(unique(used.begin(), used.end()), used.end());

    vector<int> active_nonroot;
    for (int v : used) if (v != 1) active_nonroot.push_back(v);
    if (active_nonroot.empty()) {
        cache.emplace(base_fp, base);
        return base;
    }

    sort(active_nonroot.begin(), active_nonroot.end());
    vector<int> target_labels(active_nonroot.size(), 0);
    for (size_t i = 0; i < active_nonroot.size(); ++i) target_labels[i] = int(i) + 2;

    vector<int> perm = active_nonroot;
    SparseLcaInstance best;
    string best_fp;
    bool first = true;
    do {
        vector<int> image(base.n + 1, 0);
        image[1] = 1;
        for (size_t i = 0; i < perm.size(); ++i) image[perm[i]] = target_labels[i];
        SparseLcaInstance cur;
        cur.n = base.n;
        cur.constraints.reserve(base.constraints.size());
        for (const auto& c : base.constraints) {
            SparseLcaConstraint t{image[c.u], image[c.v], image[c.w]};
            cur.constraints.push_back(normalize_sparse_constraint_(t));
        }
        sort(cur.constraints.begin(), cur.constraints.end(), sparse_constraint_less_);
        cur.constraints.erase(unique(cur.constraints.begin(), cur.constraints.end(), [](const auto& a, const auto& b) {
            return a.u == b.u && a.v == b.v && a.w == b.w;
        }), cur.constraints.end());
        string fp = sparse_instance_to_string_(cur);
        if (first || fp < best_fp) {
            first = false;
            best = cur;
            best_fp = fp;
        }
    } while (next_permutation(perm.begin(), perm.end()));

    if (first) best = base;
    cache.emplace(base_fp, best);
    return best;
}

static BoundedExactEnumerationResult enumerate_canonical_sparse_instances_exactly_k_constraints_direct_small_(int n,
                                                                                                              int exact_constraints) {
    static map<pair<int,int>, BoundedExactEnumerationResult> cache;
    auto key = make_pair(n, exact_constraints);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;

    BoundedExactEnumerationResult res;
    res.rooted_trees = 0;
    auto pairs = all_unordered_vertex_pairs_(n);
    vector<vector<int>> pair_subsets;
    generate_pair_index_subsets_exact_k_((int)pairs.size(), exact_constraints, &pair_subsets);
    size_t raw_per_subset = 1;
    for (int i = 0; i < exact_constraints; ++i) raw_per_subset *= (size_t)n;
    res.raw_instances = pair_subsets.size() * raw_per_subset;

    unordered_map<string, SparseLcaInstance> uniq;
    uniq.reserve(min<size_t>(res.raw_instances, 1u << 20));
    size_t pair_subset_idx = 0;
    for (const auto& sub : pair_subsets) {
        ++pair_subset_idx;
        local_progress_("bounded_enum_direct_exact_pairs", pair_subset_idx, pair_subsets.size());
        SparseLcaInstance inst;
        inst.n = n;
        inst.constraints.resize(sub.size());
        function<void(size_t)> dfs = [&](size_t pos) {
            if (pos == sub.size()) {
                auto canon = canonicalize_sparse_instance_small_support_root_preserving_(inst);
                uniq.emplace(sparse_instance_to_string_(canon), canon);
                return;
            }
            auto [u, v] = pairs[sub[pos]];
            for (int w = 1; w <= n; ++w) {
                inst.constraints[pos] = {u, v, w};
                dfs(pos + 1);
            }
        };
        dfs(0);
    }
    res.canonical_instances.reserve(uniq.size());
    for (const auto& kv : uniq) res.canonical_instances.push_back(kv.second);
    sort(res.canonical_instances.begin(), res.canonical_instances.end(), [](const SparseLcaInstance& a, const SparseLcaInstance& b) {
        return sparse_instance_to_string_(a) < sparse_instance_to_string_(b);
    });
    cache.emplace(key, res);
    return res;
}

__attribute__((optimize("O3"))) static BoundedExactEnumerationResult enumerate_canonical_sparse_instances_bounded_by_constraints_(int n,
                                                                                                   int max_constraints) {
    static map<pair<int,int>, BoundedExactEnumerationResult> cache;
    auto key = make_pair(n, max_constraints);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;

    BoundedExactEnumerationResult res;
    auto tree_reps = cached_static_tree_representatives_root_preserving_(n);
    res.rooted_trees = tree_reps.size();
    auto pairs = all_unordered_vertex_pairs_(n);
    vector<vector<int>> subsets;
    generate_pair_index_subsets_up_to_k_((int)pairs.size(), max_constraints, &subsets);
    res.raw_instances = tree_reps.size() * subsets.size();
    unordered_map<string, SparseLcaInstance> uniq;
    uniq.reserve(tree_reps.size() * min<size_t>(subsets.size(), static_cast<size_t>(4096)));
    size_t tree_idx = 0;
    for (const auto* item : tree_reps) {
        ++tree_idx;
        local_progress_("bounded_enum_trees", tree_idx, tree_reps.size());
        for (const auto& sub : subsets) {
            SparseLcaInstance inst;
            inst.n = n;
            inst.constraints.reserve(sub.size());
            for (int idx : sub) {
                int u = pairs[idx].first, v = pairs[idx].second;
                inst.constraints.push_back({u, v, item->lca_table.at({u, v})});
            }
            inst = canonicalize_sparse_instance_(inst);
            uniq.emplace(canonical_sparse_instance_fingerprint_(inst), inst);
        }
    }
    res.canonical_instances.reserve(uniq.size());
    for (const auto& kv : uniq) res.canonical_instances.push_back(kv.second);
    sort(res.canonical_instances.begin(), res.canonical_instances.end(), [](const SparseLcaInstance& a, const SparseLcaInstance& b) {
        return canonical_sparse_instance_fingerprint_(a) < canonical_sparse_instance_fingerprint_(b);
    });
    cache.emplace(key, res);
    return res;
}

__attribute__((optimize("O3"))) static BoundedExactEnumerationResult enumerate_canonical_sparse_instances_exactly_k_constraints_(int n,
                                                                                                  int exact_constraints) {
    if (n >= 7 && exact_constraints <= 3) {
        return enumerate_canonical_sparse_instances_exactly_k_constraints_direct_small_(n, exact_constraints);
    }
    static map<pair<int,int>, BoundedExactEnumerationResult> cache;
    auto key = make_pair(n, exact_constraints);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;

    BoundedExactEnumerationResult res;
    auto tree_reps = cached_static_tree_representatives_root_preserving_(n);
    res.rooted_trees = tree_reps.size();
    auto pairs = all_unordered_vertex_pairs_(n);
    vector<vector<int>> subsets;
    generate_pair_index_subsets_exact_k_((int)pairs.size(), exact_constraints, &subsets);
    res.raw_instances = tree_reps.size() * subsets.size();
    unordered_map<string, SparseLcaInstance> uniq;
    uniq.reserve(tree_reps.size() * min<size_t>(subsets.size(), static_cast<size_t>(4096)));
    size_t tree_idx = 0;
    for (const auto* item : tree_reps) {
        ++tree_idx;
        local_progress_("bounded_enum_exact_trees", tree_idx, tree_reps.size());
        for (const auto& sub : subsets) {
            SparseLcaInstance inst;
            inst.n = n;
            inst.constraints.reserve(sub.size());
            for (int idx2 : sub) {
                int u = pairs[idx2].first, v = pairs[idx2].second;
                inst.constraints.push_back({u, v, item->lca_table.at({u, v})});
            }
            inst = canonicalize_sparse_instance_(inst);
            uniq.emplace(canonical_sparse_instance_fingerprint_(inst), inst);
        }
    }
    res.canonical_instances.reserve(uniq.size());
    for (const auto& kv : uniq) res.canonical_instances.push_back(kv.second);
    sort(res.canonical_instances.begin(), res.canonical_instances.end(), [](const SparseLcaInstance& a, const SparseLcaInstance& b) {
        return canonical_sparse_instance_fingerprint_(a) < canonical_sparse_instance_fingerprint_(b);
    });
    cache.emplace(key, res);
    return res;
}

static bool scan_repaired_solver_saturation_theorem_bounded_exact_n6_(int max_constraints,
                                                                      const vector<SparseRuleCandidate>& base_sound_rules,
                                                                      const vector<SchemaRule>& schema_rules,
                                                                      const vector<SparseRuleCandidate>& first_wave_rules,
                                                                      const vector<SparseRuleCandidate>& second_wave_rules,
                                                                      RepairedTheoremStats* stats,
                                                                      SolverSaturationResult* first_failure,
                                                                      string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_bounded_by_constraints_(6, max_constraints);
    RepairedTheoremStats local;
    local.n = 6;
    local.canonical_instances = enum_res.canonical_instances.size();
    SolverSaturationResult local_first_failure;
    bool have_failure = false;
    vector<MismatchWitness> witnesses;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("bounded_exact_n6", progress_idx, enum_res.canonical_instances.size());
        auto sat = run_repaired_solver_completion_closure_(inst, base_sound_rules, schema_rules, first_wave_rules, second_wave_rules, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first_failure = sat; have_failure = true; }
            auto missing = compute_missing_forced_pairs_from_solver_result_(sat);
            for (const auto& target : missing) {
                string min_why;
                auto all_repair = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
                auto core = minimize_missing_forced_pair_core_under_rules_(inst, target, base_sound_rules, schema_rules, all_repair, &min_why);
                if (core.n == 0) {
                    if (why) *why = min_why;
                    return false;
                }
                auto canon = canonicalize_minimal_forcing_motif_(core, target);
                MismatchWitness w;
                w.instance = inst;
                w.missing_target = canon.target_consequent;
                w.minimal_core = canon.motif_instance;
                w.family_fingerprint = canon.fingerprint;
                w.target_fingerprint = canonical_mismatch_target_fingerprint_(canon.target_consequent);
                w.completion_family_fingerprint = sat.oracle.completion_family_fingerprint;
                w.support_count = 1;
                witnesses.push_back(w);
            }
        }
    }
    auto families = classify_solver_mismatch_families_(witnesses);
    local.pair_witnesses = witnesses.size();
    local.family_count = families.size();
    local.exact_n5_verified = false;
    local.why = string("bounded_exact_n6 max_constraints=") + to_string(max_constraints)
              + string(" raw=") + to_string(enum_res.raw_instances)
              + string(" canonical=") + to_string(enum_res.canonical_instances.size());
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    if (why) *why = local.why;
    return true;
}

static string classify_repaired_theorem_status_(const RepairedTheoremStats& exact_n5,
                                                const vector<RetainedRepairRuleStressStats>& rule_stats,
                                                const RepairedTheoremStats& sampled_n6,
                                                const RepairedTheoremStats& sampled_n7,
                                                const RepairedTheoremStats& sampled_n8,
                                                const RepairedTheoremStats* sampled_n9,
                                                const RepairedTheoremStats* bounded_exact_n6) {
    if (!exact_n5.exact_n5_verified) return "refuted_at_exact_n5";
    bool all_plus_one = true;
    for (const auto& rs : rule_stats) all_plus_one = all_plus_one && rs.plus_one_exact_pass;
    if (!all_plus_one) return "exact_n5_verified_only";
    bool sampled_ok = sampled_n6.mismatch_instances == 0 && sampled_n7.mismatch_instances == 0 && sampled_n8.mismatch_instances == 0;
    if (sampled_n9 && sampled_n9->canonical_instances > 0) sampled_ok = sampled_ok && sampled_n9->mismatch_instances == 0;
    if (!sampled_ok) return "exact_n5_plus_rule_extension_supported";
    if (bounded_exact_n6 && bounded_exact_n6->canonical_instances > 0 && bounded_exact_n6->mismatch_instances == 0) return "bounded_n6_exact_supported";
    return "strong_empirical_repaired_candidate";
}

static string build_repaired_theorem_ledger_(const RepairedTheoremStats& exact_n5,
                                             const vector<RetainedRepairRuleStressStats>& rule_stats,
                                             const RepairedTheoremStats& sampled_n6,
                                             const RepairedTheoremStats& sampled_n7,
                                             const RepairedTheoremStats& sampled_n8,
                                             const RepairedTheoremStats* sampled_n9,
                                             const RepairedTheoremStats* bounded_exact_n6,
                                             const string& status) {
    ostringstream oss;
    oss << "status=" << status << "\n";
    oss << "exact_n5=" << repaired_theorem_stats_to_string_(exact_n5) << "\n";
    for (const auto& rs : rule_stats) oss << "rule=" << retained_repair_rule_stress_stats_to_string_(rs) << "\n";
    oss << "sampled_n6=" << repaired_theorem_stats_to_string_(sampled_n6) << "\n";
    oss << "sampled_n7=" << repaired_theorem_stats_to_string_(sampled_n7) << "\n";
    oss << "sampled_n8=" << repaired_theorem_stats_to_string_(sampled_n8) << "\n";
    if (sampled_n9 && sampled_n9->canonical_instances > 0) oss << "sampled_n9=" << repaired_theorem_stats_to_string_(*sampled_n9) << "\n";
    if (bounded_exact_n6 && bounded_exact_n6->canonical_instances > 0) oss << "bounded_exact_n6=" << repaired_theorem_stats_to_string_(*bounded_exact_n6) << "\n";
    return oss.str();
}

static string classify_repaired_frontier_(const RepairedTheoremStats& exact_n5,
                                          const vector<RetainedRepairRuleStressStats>& rule_stats,
                                          const RepairedTheoremStats& sampled_n6,
                                          const RepairedTheoremStats& sampled_n7,
                                          const RepairedTheoremStats& sampled_n8,
                                          const RepairedTheoremStats* sampled_n9,
                                          const RepairedTheoremStats* bounded_exact_n6) {
    if (!exact_n5.exact_n5_verified) return "nonlocal_gap_hypothesis_reopened";
    bool all_plus_one = true;
    for (const auto& rs : rule_stats) all_plus_one = all_plus_one && rs.plus_one_exact_pass;
    bool sampled_ok = sampled_n6.mismatch_instances == 0 && sampled_n7.mismatch_instances == 0 && sampled_n8.mismatch_instances == 0;
    if (sampled_n9 && sampled_n9->canonical_instances > 0) sampled_ok = sampled_ok && sampled_n9->mismatch_instances == 0;
    bool bounded_ok = bounded_exact_n6 && bounded_exact_n6->canonical_instances > 0 && bounded_exact_n6->mismatch_instances == 0;
    if (all_plus_one && sampled_ok && bounded_ok) return "repaired_local_system_still_promising";
    if (all_plus_one && sampled_ok) return "repaired_system_empirically_strong_but_not_yet_exact_beyond_n5";
    return "nonlocal_gap_hypothesis_reopened";
}

static string build_repaired_frontier_ledger_(const RepairedTheoremStats& exact_n5,
                                              const RepairedTheoremStats& sampled_n6,
                                              const RepairedTheoremStats& sampled_n7,
                                              const RepairedTheoremStats& sampled_n8,
                                              const RepairedTheoremStats* sampled_n9,
                                              const RepairedTheoremStats* bounded_exact_n6,
                                              const string& frontier) {
    ostringstream oss;
    oss << "frontier=" << frontier << "\n";
    oss << "exact_n5=" << repaired_theorem_stats_to_string_(exact_n5) << "\n";
    oss << "sampled_n6=" << repaired_theorem_stats_to_string_(sampled_n6) << "\n";
    oss << "sampled_n7=" << repaired_theorem_stats_to_string_(sampled_n7) << "\n";
    oss << "sampled_n8=" << repaired_theorem_stats_to_string_(sampled_n8) << "\n";
    if (sampled_n9 && sampled_n9->canonical_instances > 0) oss << "sampled_n9=" << repaired_theorem_stats_to_string_(*sampled_n9) << "\n";
    if (bounded_exact_n6 && bounded_exact_n6->canonical_instances > 0) oss << "bounded_exact_n6=" << repaired_theorem_stats_to_string_(*bounded_exact_n6) << "\n";
    return oss.str();
}

