static vector<MismatchWitness> collect_repaired_theorem_mismatch_witnesses_from_instance_(const SparseLcaInstance& instance,
                                                                                           const vector<SparseRuleCandidate>& base_sound_rules,
                                                                                           const vector<SchemaRule>& schema_rules,
                                                                                           const vector<SparseRuleCandidate>& first_wave_rules,
                                                                                           const vector<SparseRuleCandidate>& second_wave_rules,
                                                                                           string* why) {
    vector<MismatchWitness> out;
    auto sat = run_repaired_solver_completion_closure_(instance, base_sound_rules, schema_rules, first_wave_rules, second_wave_rules, nullptr);
    if (!sat.oracle.satisfiable) return out;
    auto missing = compute_missing_forced_pairs_from_solver_result_(sat);
    auto all_repair = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
    for (const auto& target : missing) {
        string min_why;
        auto core = minimize_missing_forced_pair_core_under_rules_(instance, target, base_sound_rules, schema_rules, all_repair, &min_why);
        if (core.n == 0) {
            if (why) *why = min_why;
            return {};
        }
        auto canon = canonicalize_minimal_forcing_motif_(core, target);
        MismatchWitness w;
        w.instance = canonicalize_sparse_instance_(instance);
        w.missing_target = canon.target_consequent;
        w.minimal_core = canon.motif_instance;
        w.family_fingerprint = canon.fingerprint;
        w.target_fingerprint = canonical_mismatch_target_fingerprint_(canon.target_consequent);
        w.completion_family_fingerprint = sat.oracle.completion_family_fingerprint;
        w.support_count = 1;
        out.push_back(w);
    }
    return out;
}

static void ensure_repaired_theorem_baseline_ready_() {
    auto schemas = current_solver_schema_rules_();
    string why;

    if (g_last_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                        &g_last_solver_saturation_exhaustive_n5_stats,
                                                        &g_last_solver_saturation_exhaustive_n5_failure,
                                                        &why)) {
            throw runtime_error("ensure_repaired: base exact n5 scan failed\n" + why);
        }
    }

    g_last_retained_first_wave_repair_rules = retained_first_wave_repair_rules_();
    g_last_retained_second_wave_repair_rules = retained_second_wave_repair_rules_();
    g_last_retained_all_repair_rules = retained_all_repair_rules_();
    cerr << "ensure: first-wave exact n5\n";
    if (g_last_augmented_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_augmented_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                                  g_last_retained_first_wave_repair_rules,
                                                                  &g_last_augmented_solver_saturation_exhaustive_n5_stats,
                                                                  &g_last_augmented_solver_saturation_exhaustive_n5_failure,
                                                                  &why)) {
            throw runtime_error("ensure_repaired: first-wave exact n5 scan failed\n" + why);
        }
    }
    cerr << "ensure: second-wave exact n5\n";
    if (g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats.canonical_instances == 0) {
        if (!scan_second_wave_augmented_solver_saturation_theorem_exhaustive_(5, {}, schemas,
                                                                              g_last_retained_first_wave_repair_rules,
                                                                              g_last_retained_second_wave_repair_rules,
                                                                              &g_last_second_wave_augmented_solver_saturation_exhaustive_n5_stats,
                                                                              &g_last_second_wave_augmented_solver_saturation_exhaustive_n5_failure,
                                                                              &why)) {
            throw runtime_error("ensure_repaired: second-wave exact n5 scan failed\n" + why);
        }
    }
    cerr << "ensure: retained repair extension profiles\n";
    if (g_last_retained_repair_rule_stress_profiles.empty()) {
        g_last_retained_repair_rule_stress_profiles = build_retained_repair_rule_stress_profiles_();
    }
    cerr << "ensure: repaired exact n5\n";
    if (g_last_repaired_theorem_exact_n5_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_exhaustive_n5_({}, schemas,
                                                                    g_last_retained_first_wave_repair_rules,
                                                                    g_last_retained_second_wave_repair_rules,
                                                                    &g_last_repaired_theorem_exact_n5_stats,
                                                                    &g_last_repaired_theorem_exact_n5_failure,
                                                                    &why)) {
            throw runtime_error("ensure_repaired: exact n5 scan failed\n" + why);
        }
        if (g_last_repaired_theorem_exact_n5_stats.mismatch_instances > 0) {
            g_last_repaired_theorem_mismatch_witnesses = collect_repaired_theorem_mismatch_witnesses_(5, {}, schemas,
                                                                                                       g_last_retained_first_wave_repair_rules,
                                                                                                       g_last_retained_second_wave_repair_rules,
                                                                                                       &why);
            if (!why.empty()) throw runtime_error("ensure_repaired: repaired theorem mismatch witness collection failed\n" + why);
            g_last_repaired_theorem_mismatch_family_summaries = classify_repaired_theorem_mismatch_families_(g_last_repaired_theorem_mismatch_witnesses);
        }
    }
    cerr << "ensure: repaired sampled n6\n";
    if (g_last_repaired_theorem_sampled_n6_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_randomized_(6, kSchemaRandomizedSeed,
                                                                 kSchemaRandomizedN6NumTrees,
                                                                 kSchemaRandomizedN6SubsetsPerTree,
                                                                 {}, schemas,
                                                                 g_last_retained_first_wave_repair_rules,
                                                                 g_last_retained_second_wave_repair_rules,
                                                                 &g_last_repaired_theorem_sampled_n6_stats,
                                                                 &g_last_repaired_theorem_sampled_n6_failure,
                                                                 &why)) throw runtime_error("ensure_repaired: sampled n6 failed\n" + why);
    }
    cerr << "ensure: repaired sampled n7\n";
    if (g_last_repaired_theorem_sampled_n7_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_randomized_(7, kSchemaRandomizedSeed,
                                                                 kSchemaRandomizedN7NumTrees,
                                                                 kSchemaRandomizedN7SubsetsPerTree,
                                                                 {}, schemas,
                                                                 g_last_retained_first_wave_repair_rules,
                                                                 g_last_retained_second_wave_repair_rules,
                                                                 &g_last_repaired_theorem_sampled_n7_stats,
                                                                 &g_last_repaired_theorem_sampled_n7_failure,
                                                                 &why)) throw runtime_error("ensure_repaired: sampled n7 failed\n" + why);
    }
    cerr << "ensure: repaired sampled n8\n";
    if (g_last_repaired_theorem_sampled_n8_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_randomized_(8, kSchemaRandomizedSeed,
                                                                 kSchemaRandomizedN8NumTrees,
                                                                 kSchemaRandomizedN8SubsetsPerTree,
                                                                 {}, schemas,
                                                                 g_last_retained_first_wave_repair_rules,
                                                                 g_last_retained_second_wave_repair_rules,
                                                                 &g_last_repaired_theorem_sampled_n8_stats,
                                                                 &g_last_repaired_theorem_sampled_n8_failure,
                                                                 &why)) throw runtime_error("ensure_repaired: sampled n8 failed\n" + why);
    }
    cerr << "ensure: repaired sampled n9\n";
    if (kRepairedRandomizedN9NumTrees > 0 && kRepairedRandomizedN9SubsetsPerTree > 0 && g_last_repaired_theorem_sampled_n9_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_randomized_(9, kRepairedRandomizedSeed,
                                                                 kRepairedRandomizedN9NumTrees,
                                                                 kRepairedRandomizedN9SubsetsPerTree,
                                                                 {}, schemas,
                                                                 g_last_retained_first_wave_repair_rules,
                                                                 g_last_retained_second_wave_repair_rules,
                                                                 &g_last_repaired_theorem_sampled_n9_stats,
                                                                 &g_last_repaired_theorem_sampled_n9_failure,
                                                                 &why)) throw runtime_error("ensure_repaired: sampled n9 failed\n" + why);
    }
    cerr << "ensure: repaired bounded exact n6\n";
    if (g_last_repaired_theorem_bounded_exact_n6_stats.canonical_instances == 0) {
        if (!scan_repaired_solver_saturation_theorem_bounded_exact_n6_(kRepairedBoundedExactN6MaxConstraints,
                                                                       {}, schemas,
                                                                       g_last_retained_first_wave_repair_rules,
                                                                       g_last_retained_second_wave_repair_rules,
                                                                       &g_last_repaired_theorem_bounded_exact_n6_stats,
                                                                       &g_last_repaired_theorem_bounded_exact_n6_failure,
                                                                       &why)) throw runtime_error("ensure_repaired: bounded exact n6 failed\n" + why);
    }
    g_last_repaired_theorem_status = classify_repaired_theorem_status_(g_last_repaired_theorem_exact_n5_stats,
                                                                       g_last_retained_repair_rule_stress_profiles,
                                                                       g_last_repaired_theorem_sampled_n6_stats,
                                                                       g_last_repaired_theorem_sampled_n7_stats,
                                                                       g_last_repaired_theorem_sampled_n8_stats,
                                                                       &g_last_repaired_theorem_sampled_n9_stats,
                                                                       &g_last_repaired_theorem_bounded_exact_n6_stats);
    g_last_repaired_theorem_ledger = build_repaired_theorem_ledger_(g_last_repaired_theorem_exact_n5_stats,
                                                                    g_last_retained_repair_rule_stress_profiles,
                                                                    g_last_repaired_theorem_sampled_n6_stats,
                                                                    g_last_repaired_theorem_sampled_n7_stats,
                                                                    g_last_repaired_theorem_sampled_n8_stats,
                                                                    &g_last_repaired_theorem_sampled_n9_stats,
                                                                    &g_last_repaired_theorem_bounded_exact_n6_stats,
                                                                    g_last_repaired_theorem_status);
    g_last_repaired_frontier_classification = classify_repaired_frontier_(g_last_repaired_theorem_exact_n5_stats,
                                                                          g_last_retained_repair_rule_stress_profiles,
                                                                          g_last_repaired_theorem_sampled_n6_stats,
                                                                          g_last_repaired_theorem_sampled_n7_stats,
                                                                          g_last_repaired_theorem_sampled_n8_stats,
                                                                          &g_last_repaired_theorem_sampled_n9_stats,
                                                                          &g_last_repaired_theorem_bounded_exact_n6_stats);
    g_last_repaired_frontier_ledger = build_repaired_frontier_ledger_(g_last_repaired_theorem_exact_n5_stats,
                                                                      g_last_repaired_theorem_sampled_n6_stats,
                                                                      g_last_repaired_theorem_sampled_n7_stats,
                                                                      g_last_repaired_theorem_sampled_n8_stats,
                                                                      &g_last_repaired_theorem_sampled_n9_stats,
                                                                      &g_last_repaired_theorem_bounded_exact_n6_stats,
                                                                      g_last_repaired_frontier_classification);
}


static string third_wave_repair_stats_to_string_(const ThirdWaveRepairStats& s) {
    ostringstream oss;
    oss << "derived=" << s.derived_candidates
        << " localExactSound=" << s.locally_exact_sound_candidates
        << " plusOnePass=" << s.plus_one_exact_pass_candidates
        << " chosenSubset=" << s.chosen_subset_size
        << " beforeInstanceMismatch=" << s.before_instance_mismatches
        << " beforePairWitnesses=" << s.before_pair_witnesses
        << " afterInstanceMismatch=" << s.after_instance_mismatches
        << " afterPairWitnesses=" << s.after_pair_witnesses
        << " dominantEliminated=" << (s.dominant_family_eliminated ? "true" : "false");
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string nonlocal_completion_pattern_to_string_(const NonlocalCompletionPattern& p) {
    ostringstream oss;
    oss << "fingerprint=" << p.fingerprint << " support=" << p.support
        << " target=" << sparse_constraint_to_string_(p.target)
        << " reps=" << p.representative_instances.size();
    if (!p.why_nonlocal.empty()) oss << " why=" << p.why_nonlocal;
    return oss.str();
}

static string locality_obstruction_witness_to_string_(const LocalityObstructionWitness& w) {
    ostringstream oss;
    oss << "fingerprint=" << w.fingerprint
        << " supportBound=" << w.support_bound
        << " target=" << sparse_constraint_to_string_(w.target)
        << " a=" << sparse_instance_to_string_(w.a)
        << " b=" << sparse_instance_to_string_(w.b);
    if (!w.why.empty()) oss << " why=" << w.why;
    return oss.str();
}

static bool collect_repaired_theorem_residual_baseline_(RepairedTheoremStats* exact_n5,
                                                        RepairedTheoremStats* bounded_n6,
                                                        RepairedTheoremStats* sampled_n6,
                                                        RepairedTheoremStats* sampled_n7,
                                                        RepairedTheoremStats* sampled_n8,
                                                        RepairedTheoremStats* sampled_n9,
                                                        string* why) {
    ensure_repaired_theorem_baseline_ready_();
    if (exact_n5) *exact_n5 = g_last_repaired_theorem_exact_n5_stats;
    if (bounded_n6) *bounded_n6 = g_last_repaired_theorem_bounded_exact_n6_stats;
    if (sampled_n6) *sampled_n6 = g_last_repaired_theorem_sampled_n6_stats;
    if (sampled_n7) *sampled_n7 = g_last_repaired_theorem_sampled_n7_stats;
    if (sampled_n8) *sampled_n8 = g_last_repaired_theorem_sampled_n8_stats;
    if (sampled_n9) *sampled_n9 = g_last_repaired_theorem_sampled_n9_stats;
    if (why) *why = "";
    return true;
}

