static vector<RetainedRepairRuleStressStats> build_third_wave_repair_rule_stress_profiles_(const vector<RepairPrincipleCandidate>& candidates) {
    map<string, RetainedRepairRuleStressStats> uniq;
    for (const auto& cand : candidates) {
        RetainedRepairRuleStressStats stats;
        string why;
        validate_retained_repair_rule_exact_extension_full_(cand.local_rule, &stats, &why);
        if (!why.empty() && stats.why.empty()) stats.why = why;
        auto& slot = uniq[stats.rule_fingerprint];
        if (slot.rule_fingerprint.empty()) slot = stats;
    }
    vector<RetainedRepairRuleStressStats> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const RetainedRepairRuleStressStats& a, const RetainedRepairRuleStressStats& b) {
        return a.rule_fingerprint < b.rule_fingerprint;
    });
    return out;
}

static SolverSaturationResult run_third_wave_augmented_solver_completion_closure_(const SparseLcaInstance& instance,
                                                                                   const vector<SparseRuleCandidate>& base_sound_rules,
                                                                                   const vector<SchemaRule>& schema_rules,
                                                                                   const vector<SparseRuleCandidate>& first_wave_rules,
                                                                                   const vector<SparseRuleCandidate>& second_wave_rules,
                                                                                   const vector<SparseRuleCandidate>& third_wave_rules,
                                                                                   string* why) {
    auto merged12 = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
    auto all_repair = merge_repair_rule_sets_(merged12, third_wave_rules);
    return run_augmented_solver_completion_closure_(instance, base_sound_rules, schema_rules, all_repair, why);
}

