static bool scan_third_wave_augmented_solver_saturation_theorem_exhaustive_n5_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                                                const vector<SchemaRule>& schema_rules,
                                                                                const vector<SparseRuleCandidate>& first_wave_rules,
                                                                                const vector<SparseRuleCandidate>& second_wave_rules,
                                                                                const vector<SparseRuleCandidate>& third_wave_rules,
                                                                                RepairedTheoremStats* stats,
                                                                                SolverSaturationResult* first_failure,
                                                                                string* why) {
    auto merged12 = merge_repair_rule_sets_(first_wave_rules, second_wave_rules);
    RepairedTheoremStats local;
    SolverSaturationResult local_failure;
    string local_why;
    if (!scan_repaired_solver_saturation_theorem_exhaustive_n5_(base_sound_rules, schema_rules,
                                                                merged12, third_wave_rules,
                                                                &local, &local_failure, &local_why)) {
        if (why) *why = local_why;
        return false;
    }
    if (stats) *stats = local;
    if (first_failure) *first_failure = local_failure;
    if (why) *why = local_why;
    return true;
}

