static vector<SparseRuleCandidate> search_minimal_third_wave_repair_subset_(const vector<RepairPrincipleCandidate>& sound_candidates,
                                                                             const vector<SparseRuleCandidate>& base_sound_rules,
                                                                             const vector<SchemaRule>& schema_rules,
                                                                             const vector<SparseRuleCandidate>& first_wave_rules,
                                                                             const vector<SparseRuleCandidate>& second_wave_rules,
                                                                             string* why) {
    const int m = (int)sound_candidates.size();
    string dominant_family_fp = g_last_repaired_theorem_mismatch_family_summaries.empty() ? string() : g_last_repaired_theorem_mismatch_family_summaries.front().family_fingerprint;
    bool found = false;
    vector<SparseRuleCandidate> best;
    size_t best_exact_mismatch = numeric_limits<size_t>::max();
    size_t best_exact_pair = numeric_limits<size_t>::max();
    size_t best_bounded_mismatch = numeric_limits<size_t>::max();
    bool best_kills_top = false;
    size_t best_subset_size = numeric_limits<size_t>::max();
    string best_fp;
    int max_mask = (m == 0 ? 1 : (1 << m));
    for (int mask = 0; mask < max_mask; ++mask) {
        vector<SparseRuleCandidate> subset;
        for (int i = 0; i < m; ++i) if (mask & (1 << i)) subset.push_back(sound_candidates[i].local_rule);
        RepairedTheoremStats exact_stats, bounded_stats;
        SolverSaturationResult exact_failure, bounded_failure;
        string local_why;
        if (!scan_third_wave_augmented_solver_saturation_theorem_exhaustive_n5_(base_sound_rules, schema_rules,
                                                                                 first_wave_rules, second_wave_rules, subset,
                                                                                 &exact_stats, &exact_failure, &local_why)) {
            if (why && why->empty()) *why = local_why;
            continue;
        }
        if (!scan_third_wave_augmented_solver_saturation_theorem_bounded_exact_n6_(kThirdWaveBoundedExactN6MaxConstraints,
                                                                                    base_sound_rules, schema_rules,
                                                                                    first_wave_rules, second_wave_rules, subset,
                                                                                    &bounded_stats, &bounded_failure, &local_why)) {
            if (why && why->empty()) *why = local_why;
            continue;
        }
        auto post = collect_third_wave_mismatch_witnesses_(5, base_sound_rules, schema_rules,
                                                           first_wave_rules, second_wave_rules, subset,
                                                           &local_why);
        if (!local_why.empty()) {
            if (why && why->empty()) *why = local_why;
            continue;
        }
        auto post_fams = classify_third_wave_mismatch_families_(post);
        bool kills_top = dominant_family_fp.empty() ? true : !mismatch_family_present_(post_fams, dominant_family_fp);
        string fp = repair_subset_fingerprint_(subset);
        bool better = false;
        if (!found) better = true;
        else if (kills_top != best_kills_top) better = kills_top && !best_kills_top;
        else if (exact_stats.mismatch_instances != best_exact_mismatch) better = exact_stats.mismatch_instances < best_exact_mismatch;
        else if (post.size() != best_exact_pair) better = post.size() < best_exact_pair;
        else if (bounded_stats.mismatch_instances != best_bounded_mismatch) better = bounded_stats.mismatch_instances < best_bounded_mismatch;
        else if (subset.size() != best_subset_size) better = subset.size() < best_subset_size;
        else if (fp < best_fp) better = true;
        if (better) {
            found = true;
            best = subset;
            best_exact_mismatch = exact_stats.mismatch_instances;
            best_exact_pair = post.size();
            best_bounded_mismatch = bounded_stats.mismatch_instances;
            best_kills_top = kills_top;
            best_subset_size = subset.size();
            best_fp = fp;
        }
    }
    if (!found && why) *why = "no third-wave repair subset evaluated";
    return best;
}

static vector<NonlocalCompletionPattern> mine_nonlocal_completion_patterns_(const vector<MismatchFamilySummary>& families,
                                                                            size_t limit) {
    auto ranked = rank_mismatch_families_by_support_(families, limit);
    vector<NonlocalCompletionPattern> out;
    for (const auto& fam : ranked) {
        NonlocalCompletionPattern p;
        p.fingerprint = fam.family_fingerprint;
        p.target = fam.representative_target;
        p.support = fam.witness_count;
        p.why_nonlocal = "residual family survives after third-wave local repair search";
        if (!fam.sample_instances.empty()) {
            size_t take = min<size_t>(fam.sample_instances.size(), 3);
            p.representative_instances.assign(fam.sample_instances.begin(), fam.sample_instances.begin() + take);
        } else if (fam.representative_core.n > 0) {
            p.representative_instances.push_back(fam.representative_core);
        }
        out.push_back(p);
    }
    return out;
}

static vector<LocalityObstructionWitness> search_nonlocal_obstruction_witnesses_(int support_bound,
                                                                                  size_t limit,
                                                                                  string* why) {
    vector<LocalityObstructionWitness> out;
    auto pooled_rules = retained_all_repair_rules_();
    vector<SparseRuleCandidate> third_rules;
    for (const auto& cand : g_last_locally_exact_sound_third_wave_repairs) third_rules.push_back(cand.local_rule);
    pooled_rules = merge_repair_rule_sets_(pooled_rules, third_rules);
    for (const auto& rule : pooled_rules) {
        if (repair_principle_support_size_(rule) > support_bound) continue;
        size_t total_embeddings = 0;
        string collect_why;
        auto instances = collect_unique_retained_rule_antecedent_instances_(rule, repair_principle_support_size_(rule) + 1, &total_embeddings, &collect_why);
        if (!collect_why.empty()) {
            if (why) *why = collect_why;
            return {};
        }
        for (const auto& inst : instances) {
            string oracle_why;
            auto oracle = exact_sparse_completion_oracle_(inst.antecedent_instance, numeric_limits<size_t>::max(), &oracle_why);
            if (!oracle.satisfiable) continue;
            auto it = oracle.forced_pairwise_lca.find({inst.instantiated_consequent.u, inst.instantiated_consequent.v});
            int forced = (it == oracle.forced_pairwise_lca.end()) ? -1 : it->second;
            if (forced != inst.instantiated_consequent.w) {
                LocalityObstructionWitness w;
                w.a = inst.antecedent_instance;
                w.b = inst.antecedent_instance;
                w.target = inst.instantiated_consequent;
                w.support_bound = support_bound;
                w.fingerprint = canonical_sparse_instance_fingerprint_(w.a) + "|" + sparse_constraint_to_string_(w.target) + "|bound=" + to_string(support_bound);
                w.why = string("plus-one exact extension failure for bounded-support local rule ") + canonical_rule_fingerprint_(rule)
                      + string("; forced value=") + (it == oracle.forced_pairwise_lca.end() ? string("<missing>") : to_string(forced));
                out.push_back(w);
                if (limit && out.size() >= limit) {
                    if (why) *why = "";
                    return out;
                }
            }
        }
    }
    if (out.empty()) {
        auto residual = g_last_post_third_wave_mismatch_family_summaries.empty()
            ? g_last_repaired_theorem_mismatch_family_summaries
            : g_last_post_third_wave_mismatch_family_summaries;
        auto ranked = rank_mismatch_families_by_support_(residual, limit);
        for (const auto& fam : ranked) {
            LocalityObstructionWitness w;
            w.a = fam.representative_core;
            w.b = fam.representative_core;
            w.target = fam.representative_target;
            w.support_bound = support_bound;
            w.fingerprint = fam.family_fingerprint + "|bound=" + to_string(support_bound);
            w.why = "residual family survives after third-wave local repair search";
            out.push_back(w);
        }
    }
    if (why) *why = "";
    return out;
}

static string classify_third_wave_vs_nonlocal_(const ThirdWaveRepairStats& local_stats,
                                               const RepairedTheoremStats& bounded_n6_before,
                                               const RepairedTheoremStats& bounded_n6_after,
                                               const vector<LocalityObstructionWitness>& obstructions,
                                               string* why) {
    bool improved_exact = (local_stats.after_instance_mismatches < local_stats.before_instance_mismatches)
                       || (local_stats.after_pair_witnesses < local_stats.before_pair_witnesses);
    bool improved_bounded = (bounded_n6_after.mismatch_instances < bounded_n6_before.mismatch_instances)
                         || (bounded_n6_after.pair_witnesses < bounded_n6_before.pair_witnesses);
    bool sampled_improved = (g_last_third_wave_sampled_n6_stats.mismatch_instances < g_last_repaired_theorem_sampled_n6_stats.mismatch_instances)
                         || (g_last_third_wave_sampled_n7_stats.mismatch_instances < g_last_repaired_theorem_sampled_n7_stats.mismatch_instances)
                         || (g_last_third_wave_sampled_n8_stats.mismatch_instances < g_last_repaired_theorem_sampled_n8_stats.mismatch_instances)
                         || (g_last_third_wave_sampled_n9_stats.canonical_instances > 0 && g_last_repaired_theorem_sampled_n9_stats.canonical_instances > 0
                             && g_last_third_wave_sampled_n9_stats.mismatch_instances < g_last_repaired_theorem_sampled_n9_stats.mismatch_instances);
    bool sampled_zero = (g_last_third_wave_sampled_n6_stats.mismatch_instances == 0)
                     && (g_last_third_wave_sampled_n7_stats.mismatch_instances == 0)
                     && (g_last_third_wave_sampled_n8_stats.mismatch_instances == 0)
                     && ((g_last_third_wave_sampled_n9_stats.canonical_instances == 0) || (g_last_third_wave_sampled_n9_stats.mismatch_instances == 0));
    if (local_stats.locally_exact_sound_candidates == 0) {
        if (why) *why = "no locally exact sound third-wave repair candidates";
        return "nonlocal_completion_theorem_preferred";
    }
    if (local_stats.plus_one_exact_pass_candidates > 0 && improved_exact && improved_bounded && sampled_zero && obstructions.empty()) {
        if (why) *why = "third-wave local repair improves exact n5 and bounded exact n6 and leaves no sampled residual";
        return "third_wave_local_repair_still_viable";
    }
    if (local_stats.plus_one_exact_pass_candidates > 0 && (improved_exact || improved_bounded || sampled_improved) && obstructions.empty()) {
        if (why) *why = "third-wave local repair shows improvement but exact support beyond current range is incomplete";
        return "third_wave_local_repair_still_viable";
    }
    if (improved_exact || improved_bounded || sampled_improved) {
        if (why) *why = "third-wave local repair improves some ranges but obstruction or incomplete evidence remains";
        return "mixed_frontier_more_evidence_needed";
    }
    if (!obstructions.empty()) {
        if (why) *why = "bounded-support locality obstruction remains after third-wave search";
        return "nonlocal_completion_theorem_preferred";
    }
    if (why) *why = "third-wave evidence is inconclusive";
    return "mixed_frontier_more_evidence_needed";
}

static string build_third_wave_vs_nonlocal_ledger_(const ThirdWaveRepairStats& local_stats,
                                                   const RepairedTheoremStats& repaired_exact_n5,
                                                   const RepairedTheoremStats& repaired_bounded_n6,
                                                   const RepairedTheoremStats& third_exact_n5,
                                                   const RepairedTheoremStats& third_bounded_n6,
                                                   const vector<LocalityObstructionWitness>& obstructions,
                                                   const string& decision) {
    ostringstream oss;
    oss << "decision=" << decision << "\n";
    oss << "localStats=" << third_wave_repair_stats_to_string_(local_stats) << "\n";
    oss << "repairedExactN5=" << repaired_theorem_stats_to_string_(repaired_exact_n5) << "\n";
    oss << "repairedBoundedN6=" << repaired_theorem_stats_to_string_(repaired_bounded_n6) << "\n";
    oss << "thirdWaveExactN5=" << repaired_theorem_stats_to_string_(third_exact_n5) << "\n";
    oss << "thirdWaveBoundedN6=" << repaired_theorem_stats_to_string_(third_bounded_n6) << "\n";
    oss << "thirdWaveSampledN6=" << repaired_theorem_stats_to_string_(g_last_third_wave_sampled_n6_stats) << "\n";
    oss << "thirdWaveSampledN7=" << repaired_theorem_stats_to_string_(g_last_third_wave_sampled_n7_stats) << "\n";
    oss << "thirdWaveSampledN8=" << repaired_theorem_stats_to_string_(g_last_third_wave_sampled_n8_stats) << "\n";
    if (g_last_third_wave_sampled_n9_stats.canonical_instances > 0) oss << "thirdWaveSampledN9=" << repaired_theorem_stats_to_string_(g_last_third_wave_sampled_n9_stats) << "\n";
    oss << "obstructionCount=" << obstructions.size() << "\n";
    for (const auto& obs : obstructions) oss << "obstruction=" << locality_obstruction_witness_to_string_(obs) << "\n";
    return oss.str();
}

static void ensure_third_wave_vs_nonlocal_ready_() {
    ensure_repaired_theorem_baseline_ready_();
    auto schemas = current_solver_schema_rules_();
    string why;
    if (g_last_repaired_theorem_mismatch_family_summaries.empty()) {
        g_last_repaired_theorem_mismatch_witnesses = collect_repaired_theorem_mismatch_witnesses_(5, {}, schemas,
                                                                                                  retained_first_wave_repair_rules_(),
                                                                                                  retained_second_wave_repair_rules_(),
                                                                                                  &why);
        if (!why.empty()) throw runtime_error("ensure_third_wave: failed to collect repaired residual witnesses\n" + why);
        g_last_repaired_theorem_mismatch_family_summaries = classify_repaired_theorem_mismatch_families_(g_last_repaired_theorem_mismatch_witnesses);
    }
    if (g_last_third_wave_repair_principle_candidates.empty()) {
        auto top = rank_mismatch_families_by_support_(g_last_repaired_theorem_mismatch_family_summaries, kThirdWaveTopFamilyCount);
        g_last_third_wave_repair_principle_candidates = derive_third_wave_repair_principles_(top);
    }
    if (g_last_locally_exact_sound_third_wave_repairs.empty()) {
        g_last_locally_exact_sound_third_wave_repairs = filter_locally_exact_sound_third_wave_repairs_(g_last_third_wave_repair_principle_candidates, &why);
        if (!why.empty() && g_last_locally_exact_sound_third_wave_repairs.empty() && !g_last_third_wave_repair_principle_candidates.empty()) {
            throw runtime_error("ensure_third_wave: failed to filter locally exact sound third-wave repairs\n" + why);
        }
    }
    if (g_last_third_wave_repair_rule_stress_profiles.empty()) {
        g_last_third_wave_repair_rule_stress_profiles = build_third_wave_repair_rule_stress_profiles_(g_last_third_wave_repair_principle_candidates);
    }
    if (!g_last_minimal_third_wave_repair_subset_computed) {
        g_last_minimal_third_wave_repair_subset = search_minimal_third_wave_repair_subset_(g_last_locally_exact_sound_third_wave_repairs,
                                                                                           {}, schemas,
                                                                                           retained_first_wave_repair_rules_(),
                                                                                           retained_second_wave_repair_rules_(),
                                                                                           &why);
        g_last_minimal_third_wave_repair_subset_computed = true;
    }
    if (g_last_third_wave_exact_n5_stats.canonical_instances == 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_exhaustive_n5_({}, schemas,
                                                                                 retained_first_wave_repair_rules_(),
                                                                                 retained_second_wave_repair_rules_(),
                                                                                 g_last_minimal_third_wave_repair_subset,
                                                                                 &g_last_third_wave_exact_n5_stats,
                                                                                 &g_last_third_wave_exact_n5_failure,
                                                                                 &why)) {
            throw runtime_error("ensure_third_wave: exact n5 scan failed\n" + why);
        }
    }
    if (g_last_post_third_wave_mismatch_witnesses.empty() && g_last_third_wave_exact_n5_stats.mismatch_instances > 0) {
        g_last_post_third_wave_mismatch_witnesses = collect_third_wave_mismatch_witnesses_(5,
                                                                                           {}, schemas,
                                                                                           retained_first_wave_repair_rules_(),
                                                                                           retained_second_wave_repair_rules_(),
                                                                                           g_last_minimal_third_wave_repair_subset,
                                                                                           &why);
        if (!why.empty()) throw runtime_error("ensure_third_wave: post-third-wave mismatch witness collection failed\n" + why);
    }
    if (g_last_post_third_wave_mismatch_family_summaries.empty() && !g_last_post_third_wave_mismatch_witnesses.empty()) {
        g_last_post_third_wave_mismatch_family_summaries = classify_third_wave_mismatch_families_(g_last_post_third_wave_mismatch_witnesses);
    }
    if (g_last_third_wave_bounded_exact_n6_stats.canonical_instances == 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_bounded_exact_n6_(kThirdWaveBoundedExactN6MaxConstraints,
                                                                                    {}, schemas,
                                                                                    retained_first_wave_repair_rules_(),
                                                                                    retained_second_wave_repair_rules_(),
                                                                                    g_last_minimal_third_wave_repair_subset,
                                                                                    &g_last_third_wave_bounded_exact_n6_stats,
                                                                                    &g_last_third_wave_bounded_exact_n6_failure,
                                                                                    &why)) {
            throw runtime_error("ensure_third_wave: bounded exact n6 failed\n" + why);
        }
    }
    if (g_last_third_wave_sampled_n6_stats.canonical_instances == 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_randomized_(6, kSchemaRandomizedSeed,
                                                                             kSchemaRandomizedN6NumTrees,
                                                                             kSchemaRandomizedN6SubsetsPerTree,
                                                                             {}, schemas,
                                                                             retained_first_wave_repair_rules_(),
                                                                             retained_second_wave_repair_rules_(),
                                                                             g_last_minimal_third_wave_repair_subset,
                                                                             &g_last_third_wave_sampled_n6_stats,
                                                                             &g_last_third_wave_sampled_n6_failure,
                                                                             &why)) {
            throw runtime_error("ensure_third_wave: sampled n6 failed\n" + why);
        }
    }
    if (g_last_third_wave_sampled_n7_stats.canonical_instances == 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_randomized_(7, kSchemaRandomizedSeed,
                                                                             kSchemaRandomizedN7NumTrees,
                                                                             kSchemaRandomizedN7SubsetsPerTree,
                                                                             {}, schemas,
                                                                             retained_first_wave_repair_rules_(),
                                                                             retained_second_wave_repair_rules_(),
                                                                             g_last_minimal_third_wave_repair_subset,
                                                                             &g_last_third_wave_sampled_n7_stats,
                                                                             &g_last_third_wave_sampled_n7_failure,
                                                                             &why)) {
            throw runtime_error("ensure_third_wave: sampled n7 failed\n" + why);
        }
    }
    if (g_last_third_wave_sampled_n8_stats.canonical_instances == 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_randomized_(8, kSchemaRandomizedSeed,
                                                                             kSchemaRandomizedN8NumTrees,
                                                                             kSchemaRandomizedN8SubsetsPerTree,
                                                                             {}, schemas,
                                                                             retained_first_wave_repair_rules_(),
                                                                             retained_second_wave_repair_rules_(),
                                                                             g_last_minimal_third_wave_repair_subset,
                                                                             &g_last_third_wave_sampled_n8_stats,
                                                                             &g_last_third_wave_sampled_n8_failure,
                                                                             &why)) {
            throw runtime_error("ensure_third_wave: sampled n8 failed\n" + why);
        }
    }
    if (g_last_third_wave_sampled_n9_stats.canonical_instances == 0 && kThirdWaveRandomizedN9NumTrees > 0 && kThirdWaveRandomizedN9SubsetsPerTree > 0) {
        if (!scan_third_wave_augmented_solver_saturation_theorem_randomized_(9, kThirdWaveRandomizedSeed,
                                                                             kThirdWaveRandomizedN9NumTrees,
                                                                             kThirdWaveRandomizedN9SubsetsPerTree,
                                                                             {}, schemas,
                                                                             retained_first_wave_repair_rules_(),
                                                                             retained_second_wave_repair_rules_(),
                                                                             g_last_minimal_third_wave_repair_subset,
                                                                             &g_last_third_wave_sampled_n9_stats,
                                                                             &g_last_third_wave_sampled_n9_failure,
                                                                             &why)) {
            throw runtime_error("ensure_third_wave: sampled n9 failed\n" + why);
        }
    }
    g_last_third_wave_repair_stats = {};
    g_last_third_wave_repair_stats.derived_candidates = g_last_third_wave_repair_principle_candidates.size();
    g_last_third_wave_repair_stats.locally_exact_sound_candidates = g_last_locally_exact_sound_third_wave_repairs.size();
    for (const auto& s : g_last_third_wave_repair_rule_stress_profiles) if (s.plus_one_exact_pass) ++g_last_third_wave_repair_stats.plus_one_exact_pass_candidates;
    g_last_third_wave_repair_stats.chosen_subset_size = g_last_minimal_third_wave_repair_subset.size();
    g_last_third_wave_repair_stats.before_instance_mismatches = g_last_repaired_theorem_exact_n5_stats.mismatch_instances;
    g_last_third_wave_repair_stats.before_pair_witnesses = g_last_repaired_theorem_mismatch_witnesses.size();
    g_last_third_wave_repair_stats.after_instance_mismatches = g_last_third_wave_exact_n5_stats.mismatch_instances;
    g_last_third_wave_repair_stats.after_pair_witnesses = g_last_post_third_wave_mismatch_witnesses.size();
    string dominant_fp = g_last_repaired_theorem_mismatch_family_summaries.empty() ? string() : g_last_repaired_theorem_mismatch_family_summaries.front().family_fingerprint;
    g_last_third_wave_repair_stats.dominant_family_eliminated = dominant_fp.empty() ? false : !mismatch_family_present_(g_last_post_third_wave_mismatch_family_summaries, dominant_fp);

    auto residual_for_patterns = g_last_post_third_wave_mismatch_family_summaries.empty()
        ? g_last_repaired_theorem_mismatch_family_summaries
        : g_last_post_third_wave_mismatch_family_summaries;
    g_last_nonlocal_completion_patterns = mine_nonlocal_completion_patterns_(residual_for_patterns, kThirdWaveNonlocalPatternLimit);
    int support_bound = 0;
    for (const auto& rule : retained_all_repair_rules_()) support_bound = max(support_bound, repair_principle_support_size_(rule));
    for (const auto& cand : g_last_locally_exact_sound_third_wave_repairs) support_bound = max(support_bound, repair_principle_support_size_(cand.local_rule));
    g_last_locality_obstruction_witnesses = search_nonlocal_obstruction_witnesses_(support_bound, kThirdWaveNonlocalObstructionLimit, &why);
    string decision_why;
    g_last_third_wave_vs_nonlocal_decision = classify_third_wave_vs_nonlocal_(g_last_third_wave_repair_stats,
                                                                              g_last_repaired_theorem_bounded_exact_n6_stats,
                                                                              g_last_third_wave_bounded_exact_n6_stats,
                                                                              g_last_locality_obstruction_witnesses,
                                                                              &decision_why);
    g_last_third_wave_repair_stats.why = decision_why;
    g_last_third_wave_vs_nonlocal_ledger = build_third_wave_vs_nonlocal_ledger_(g_last_third_wave_repair_stats,
                                                                                g_last_repaired_theorem_exact_n5_stats,
                                                                                g_last_repaired_theorem_bounded_exact_n6_stats,
                                                                                g_last_third_wave_exact_n5_stats,
                                                                                g_last_third_wave_bounded_exact_n6_stats,
                                                                                g_last_locality_obstruction_witnesses,
                                                                                g_last_third_wave_vs_nonlocal_decision);
}



struct StructuredLocalSchemaAtom {
    int u = 0;
    int v = 0;
    int w = 0;
};

struct StructuredLocalSchema {
    int num_symbols = 0;
    vector<StructuredLocalSchemaAtom> antecedents;
    StructuredLocalSchemaAtom consequent{};
    string fingerprint;
    size_t support = 0;
    string human_readable;
};

struct StructuredLocalSchemaFamily {
    string fingerprint;
    StructuredLocalSchema representative;
    size_t concrete_rule_count = 0;
    size_t cumulative_support = 0;
};

struct StructuredLocalTheoremStats {
    size_t schema_family_count = 0;
    size_t local_exact_pass_count = 0;
    size_t plus_one_pass_count = 0;
    size_t plus_two_attempted_count = 0;
    size_t plus_two_pass_count = 0;
    size_t exact_n5_full_matches = 0;
    size_t exact_n5_mismatches = 0;
    size_t bounded_n6_full_matches = 0;
    size_t bounded_n6_mismatches = 0;
    string why;
};

struct BoundedLocalHornEnvelopeStats {
    int support_bound = 0;
    size_t candidate_rules_considered = 0;
    size_t locally_exact_sound_rules = 0;
    size_t exact_n5_full_matches = 0;
    size_t exact_n5_mismatches = 0;
    size_t bounded_n6_full_matches = 0;
    size_t bounded_n6_mismatches = 0;
    string why;
};

