static SchemaAtom structured_local_atom_to_schema_atom_(const StructuredLocalSchemaAtom& a) {
    return SchemaAtom{a.u, a.v, a.w};
}

static StructuredLocalSchemaAtom schema_atom_to_structured_local_atom_(const SchemaAtom& a) {
    return StructuredLocalSchemaAtom{a.u, a.v, a.w};
}

static SchemaRule structured_local_schema_to_schema_rule_(const StructuredLocalSchema& raw) {
    SchemaRule base;
    base.num_symbols = raw.num_symbols;
    base.source_support = raw.support;
    base.source_rule_count = 1;
    for (const auto& a : raw.antecedents) base.antecedents.push_back(structured_local_atom_to_schema_atom_(a));
    base.consequent = structured_local_atom_to_schema_atom_(raw.consequent);
    auto out = canonicalize_schema_rule_(base);
    out.source_support = raw.support;
    out.source_rule_count = 1;
    out.human_readable_schema = schema_human_readable_(out);
    return out;
}

static StructuredLocalSchema schema_rule_to_structured_local_schema_(const SchemaRule& raw) {
    auto canon = canonicalize_schema_rule_(raw);
    StructuredLocalSchema out;
    out.num_symbols = canon.num_symbols;
    out.support = canon.source_support;
    for (const auto& a : canon.antecedents) out.antecedents.push_back(schema_atom_to_structured_local_atom_(a));
    out.consequent = schema_atom_to_structured_local_atom_(canon.consequent);
    out.fingerprint = canon.fingerprint;
    out.human_readable = schema_human_readable_(canon);
    return out;
}

static string structured_local_schema_to_string_(const StructuredLocalSchema& s) {
    ostringstream oss;
    oss << "schema=" << s.fingerprint << " support=" << s.support << " ";
    bool first = true;
    for (const auto& a : s.antecedents) {
        if (!first) oss << ", ";
        first = false;
        oss << '(' << a.u << ',' << a.v << "->" << a.w << ')';
    }
    oss << " => (" << s.consequent.u << ',' << s.consequent.v << "->" << s.consequent.w << ')';
    if (!s.human_readable.empty()) oss << " human=" << s.human_readable;
    return oss.str();
}

static string structured_local_family_to_string_(const StructuredLocalSchemaFamily& fam) {
    ostringstream oss;
    oss << "fingerprint=" << fam.fingerprint
        << " concreteRuleCount=" << fam.concrete_rule_count
        << " cumulativeSupport=" << fam.cumulative_support
        << " rep={" << structured_local_schema_to_string_(fam.representative) << "}";
    return oss.str();
}

static string structured_local_theorem_stats_to_string_(const StructuredLocalTheoremStats& s) {
    ostringstream oss;
    oss << "schemaFamilies=" << s.schema_family_count
        << " localExactPass=" << s.local_exact_pass_count
        << " plusOnePass=" << s.plus_one_pass_count
        << " plusTwoAttempted=" << s.plus_two_attempted_count
        << " plusTwoPass=" << s.plus_two_pass_count
        << " exactN5=" << s.exact_n5_full_matches << "/" << (s.exact_n5_full_matches + s.exact_n5_mismatches)
        << " boundedN6=" << s.bounded_n6_full_matches << "/" << (s.bounded_n6_full_matches + s.bounded_n6_mismatches);
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string bounded_local_horn_envelope_stats_to_string_(const BoundedLocalHornEnvelopeStats& s) {
    ostringstream oss;
    oss << "supportBound=" << s.support_bound
        << " candidateRulesConsidered=" << s.candidate_rules_considered
        << " locallyExactSoundRules=" << s.locally_exact_sound_rules
        << " exactN5=" << s.exact_n5_full_matches << "/" << (s.exact_n5_full_matches + s.exact_n5_mismatches)
        << " boundedN6=" << s.bounded_n6_full_matches << "/" << (s.bounded_n6_full_matches + s.bounded_n6_mismatches);
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string locality_obstruction_certificate_to_string_(const LocalityObstructionCertificate& c) {
    ostringstream oss;
    oss << "supportBound=" << c.support_bound
        << " instance=" << sparse_instance_to_string_(c.instance)
        << " target=" << sparse_constraint_to_string_(c.target)
        << " fingerprint=" << c.instance_fingerprint;
    if (!c.reason.empty()) oss << " reason=" << c.reason;
    return oss.str();
}

static size_t lookup_rule_support_from_candidates_(const SparseRuleCandidate& raw_rule,
                                                   const vector<RepairPrincipleCandidate>& cands) {
    string fp = canonicalize_rule_candidate_(raw_rule).fingerprint;
    size_t best = 0;
    for (const auto& cand : cands) {
        if (canonicalize_rule_candidate_(cand.local_rule).fingerprint == fp) {
            best = max(best, cand.family_support ? cand.family_support : cand.local_rule.support_count);
        }
    }
    return best;
}

static StructuredLocalSchema generalize_sparse_rule_to_structured_local_schema_(const SparseRuleCandidate& raw_rule,
                                                                                size_t support_hint) {
    auto compressed = compress_sparse_rule_candidate_to_support_domain_(raw_rule);
    SchemaRule tmp;
    tmp.num_symbols = max(1, compressed.n);
    tmp.source_rule_count = 1;
    tmp.source_support = support_hint ? support_hint : max<size_t>(1, compressed.support_count);
    for (const auto& c : compressed.antecedents) tmp.antecedents.push_back(constraint_to_schema_atom_(c));
    tmp.consequent = constraint_to_schema_atom_(compressed.consequent);
    auto canon = canonicalize_schema_rule_(tmp);
    canon.source_support = tmp.source_support;
    canon.source_rule_count = 1;
    canon.human_readable_schema = schema_human_readable_(canon);
    return schema_rule_to_structured_local_schema_(canon);
}

static vector<SparseRuleCandidate> retained_third_wave_repair_rules_() {
    if (!g_last_retained_third_wave_repair_rules.empty()) return g_last_retained_third_wave_repair_rules;
    SparseRuleCandidate rule;
    rule.n = 4;
    rule.antecedents = {normalize_sparse_constraint_({2,3,2}), normalize_sparse_constraint_({2,4,4})};
    sort(rule.antecedents.begin(), rule.antecedents.end(), sparse_constraint_less_);
    rule.consequent = normalize_sparse_constraint_({3,4,4});
    rule = canonicalize_rule_candidate_(rule);
    g_last_retained_third_wave_repair_rules = {rule};
    return g_last_retained_third_wave_repair_rules;
}

static string retained_third_wave_rule_set_fingerprint_() {
    return sparse_rule_set_fingerprint_(retained_third_wave_repair_rules_());
}

static vector<StructuredLocalSchemaFamily> generalize_third_wave_to_structured_local_schemas_(const vector<SparseRuleCandidate>& retained_third_wave_rules) {
    map<string, StructuredLocalSchemaFamily> agg;
    for (const auto& rule : retained_third_wave_rules) {
        size_t support_hint = lookup_rule_support_from_candidates_(rule, g_last_locally_exact_sound_third_wave_repairs);
        auto schema = generalize_sparse_rule_to_structured_local_schema_(rule, support_hint ? support_hint : 1);
        auto& slot = agg[schema.fingerprint];
        if (slot.fingerprint.empty()) {
            slot.fingerprint = schema.fingerprint;
            slot.representative = schema;
        }
        ++slot.concrete_rule_count;
        slot.cumulative_support += max<size_t>(1, support_hint ? support_hint : 1);
        slot.representative.support = slot.cumulative_support;
    }
    vector<StructuredLocalSchemaFamily> out;
    for (auto& kv : agg) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const StructuredLocalSchemaFamily& a, const StructuredLocalSchemaFamily& b) {
        if (a.cumulative_support != b.cumulative_support) return a.cumulative_support > b.cumulative_support;
        return a.fingerprint < b.fingerprint;
    });
    return out;
}

