static vector<SchemaAntecedentInstance> collect_structured_schema_validation_instances_cached_(const StructuredLocalSchema& schema,
                                                                                                int exact_n,
                                                                                                string* why) {
    string key = structured_schema_validation_cache_key_(schema, exact_n, false) + "|instances";
    auto it = g_last_structured_schema_validation_instance_cache.find(key);
    if (it != g_last_structured_schema_validation_instance_cache.end()) {
        if (why) *why = "cached antecedent instances=" + to_string(it->second.size());
        return it->second;
    }
    auto sr = structured_local_schema_to_schema_rule_(schema);
    string local_why;
    auto instances = collect_unique_schema_antecedent_instances_(sr, exact_n, &local_why);
    g_last_structured_schema_validation_instance_cache.emplace(key, instances);
    if (why) *why = local_why.empty() ? string("antecedent instances=") + to_string(instances.size()) : local_why;
    return instances;
}

static bool validate_structured_local_schema_exact_chunked_(const StructuredLocalSchema& schema,
                                                            int exact_n,
                                                            bool is_plus_one,
                                                            StructuredSchemaValidationChunkStats* stats,
                                                            string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    auto canon = canonicalize_schema_rule_(sr);
    string key = structured_schema_validation_cache_key_(schema, exact_n, is_plus_one);
    auto it = g_last_structured_schema_validation_cache.find(key);
    if (it != g_last_structured_schema_validation_cache.end()) {
        if (stats) {
            stats->schema_fingerprint = it->second.schema_fingerprint;
            stats->exact_n = it->second.exact_n;
            stats->completed = it->second.completed;
            stats->why = string("cache hit: ") + it->second.why;
        }
        if (why) *why = it->second.why;
        return it->second.pass;
    }

    StructuredSchemaValidationCacheEntry entry;
    entry.schema_fingerprint = canon.fingerprint;
    entry.exact_n = exact_n;
    entry.is_plus_one = is_plus_one;
    int support = schema_support_size_(canon);
    if (exact_n < support) {
        entry.completed = true;
        entry.pass = false;
        entry.why = "target_n smaller than schema support size";
        g_last_structured_schema_validation_cache.emplace(key, entry);
        if (stats) {
            stats->schema_fingerprint = entry.schema_fingerprint;
            stats->exact_n = entry.exact_n;
            stats->completed = true;
            stats->why = entry.why;
        }
        if (why) *why = entry.why;
        return false;
    }

    string local_why;
    if (quick_refute_structured_local_schema_on_samples_(schema, exact_n, &local_why)) {
        entry.completed = true;
        entry.pass = false;
        entry.why = local_why;
        g_last_structured_schema_validation_cache.emplace(key, entry);
        if (stats) {
            stats->schema_fingerprint = entry.schema_fingerprint;
            stats->exact_n = entry.exact_n;
            stats->completed = true;
            stats->why = entry.why;
        }
        if (why) *why = entry.why;
        return false;
    }

    string inst_why;
    auto instances = collect_structured_schema_validation_instances_cached_(schema, exact_n, &inst_why);
    if (instances.empty() && !inst_why.empty() && inst_why.find("target_n smaller") != string::npos) {
        entry.completed = true;
        entry.pass = false;
        entry.why = inst_why;
        g_last_structured_schema_validation_cache.emplace(key, entry);
        if (stats) {
            stats->schema_fingerprint = entry.schema_fingerprint;
            stats->exact_n = entry.exact_n;
            stats->completed = true;
            stats->why = entry.why;
        }
        if (why) *why = entry.why;
        return false;
    }

    const size_t chunk_size = 16;
    size_t done = 0;
    for (size_t start = 0; start < instances.size(); start += chunk_size) {
        size_t end = min(instances.size(), start + chunk_size);
        if (stats) {
            stats->schema_fingerprint = canon.fingerprint;
            stats->exact_n = exact_n;
            stats->chunk_index = start / chunk_size;
            stats->instances_seen = end;
            stats->completed = false;
        }
#ifdef LOCAL_TEST
        if (instances.size() > chunk_size) {
            size_t chunk_idx = start / chunk_size;
            size_t chunk_total = (instances.size() + chunk_size - 1) / chunk_size;
            if (exact_n >= 9) {
                if (chunk_idx == 0 || ((chunk_idx + 1) % 16 == 0) || end == instances.size()) {
                    local_progress_("structured_schema_exact_chunk", end, instances.size());
                }
            } else {
                local_progress_("structured_schema_exact_chunk", end, instances.size());
            }
        }
#endif
        for (size_t i = start; i < end; ++i) {
            const auto& inst = instances[i];
            string oracle_why;
            auto oracle = cached_exact_sparse_completion_oracle_(inst.antecedent_instance, numeric_limits<size_t>::max(), &oracle_why);
            if (!oracle.satisfiable) {
                entry.completed = true;
                entry.pass = false;
                entry.why = string("antecedent-only instance unexpectedly unsatisfiable: ") + sparse_instance_to_string_(inst.antecedent_instance) + " :: " + oracle_why;
                g_last_structured_schema_validation_cache.emplace(key, entry);
                if (stats) {
                    stats->completed = true;
                    stats->instances_seen = i + 1;
                    stats->why = entry.why;
                }
                if (why) *why = entry.why;
                return false;
            }
            int forced = -1;
            auto it_forced = oracle.forced_pairwise_lca.find({inst.instantiated_consequent.u, inst.instantiated_consequent.v});
            if (it_forced != oracle.forced_pairwise_lca.end()) forced = it_forced->second;
            if (forced != inst.instantiated_consequent.w) {
                entry.completed = true;
                entry.pass = false;
                entry.why = string("structured schema exact chunked validation failed on antecedent-only instance ")
                          + sparse_instance_to_string_(inst.antecedent_instance)
                          + " with consequent " + sparse_constraint_to_string_(inst.instantiated_consequent)
                          + "; forced value=" + (it_forced == oracle.forced_pairwise_lca.end() ? string("<missing>") : to_string(forced));
                g_last_structured_schema_validation_cache.emplace(key, entry);
                if (stats) {
                    stats->completed = true;
                    stats->instances_seen = i + 1;
                    stats->why = entry.why;
                }
                if (why) *why = entry.why;
                return false;
            }
            done = i + 1;
        }
    }

    entry.completed = true;
    entry.pass = true;
    entry.why = string("exact validation completed over antecedent-only instances=") + to_string(done);
    g_last_structured_schema_validation_cache.emplace(key, entry);
    if (stats) {
        stats->schema_fingerprint = entry.schema_fingerprint;
        stats->exact_n = entry.exact_n;
        stats->instances_seen = done;
        stats->completed = true;
        stats->why = entry.why;
    }
    if (why) *why = entry.why;
    return true;
}

static string rooted_tree_canonical_code_dfs_(const StaticRootedTree& tree, int u) {
    vector<string> child_codes;
    child_codes.reserve(tree.children[u].size());
    for (int v : tree.children[u]) child_codes.push_back(rooted_tree_canonical_code_dfs_(tree, v));
    sort(child_codes.begin(), child_codes.end());
    string out = "(";
    for (const auto& s : child_codes) out += s;
    out += ")";
    return out;
}

static string rooted_tree_canonical_code_(const StaticRootedTree& tree) {
    return rooted_tree_canonical_code_dfs_(tree, 1);
}

static const vector<StructuredSchemaTreeRepresentative>& cached_structured_schema_tree_representatives_(int n) {
    static unordered_map<int, vector<StructuredSchemaTreeRepresentative>> cache;
    auto it = cache.find(n);
    if (it != cache.end()) return it->second;
    unordered_set<string> seen;
    vector<StructuredSchemaTreeRepresentative> reps;
    for (const auto& tree : enumerate_rooted_trees_prufer_(n)) {
        string code = rooted_tree_canonical_code_(tree);
        if (!seen.insert(code).second) continue;
        StructuredSchemaTreeRepresentative rep;
        rep.tree = tree;
        rep.canonical_code = code;
        for (int u = 1; u <= n; ++u) rep.lca[u][u] = u;
        auto tbl = full_pairwise_lca_table_from_tree_(tree);
        for (const auto& kv : tbl) {
            int u = kv.first.first, v = kv.first.second;
            rep.lca[u][v] = kv.second;
            rep.lca[v][u] = kv.second;
        }
        reps.push_back(std::move(rep));
    }
    cache.emplace(n, std::move(reps));
    return cache[n];
}

static bool schema_antecedents_hold_in_lca_matrix_(const SchemaRule& raw,
                                                   const array<array<int, 10>, 10>& lca,
                                                   const vector<int>& mapping) {
    auto schema = canonicalize_schema_rule_(raw);
    for (const auto& a : schema.antecedents) {
        auto c = apply_mapping_to_schema_atom_(a, mapping);
        if (lca[c.u][c.v] != c.w) return false;
    }
    return true;
}

static bool validate_structured_local_schema_local_exact_support7_(const StructuredLocalSchema& schema,
                                                                   string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    if (schema_support_size_(sr) != 7) {
        if (why) *why = "schema support size is not 7";
        return false;
    }
    return validate_structured_local_schema_exact_chunked_(schema, 7, false, nullptr, why);
}

static bool validate_structured_local_schema_local_exact_support8_(const StructuredLocalSchema& schema,
                                                                   string* why) {
    auto sr = canonicalize_schema_rule_(structured_local_schema_to_schema_rule_(schema));
    if (schema_support_size_(sr) != 8) {
        if (why) *why = "schema support size is not 8";
        return false;
    }
    auto symbols = schema_rule_used_symbols_(sr);
    const auto& reps = cached_structured_schema_tree_representatives_(8);
    size_t rep_idx = 0;
    for (const auto& rep : reps) {
        ++rep_idx;
#ifdef LOCAL_TEST
        local_progress_("structured_schema_exact_chunk", rep_idx, reps.size());
#endif
        bool bad = false;
        for_each_schema_embedding_(symbols, 8, [&](const vector<int>& mapping) {
            if (!schema_antecedents_hold_in_lca_matrix_(sr, rep.lca, mapping)) return false;
            auto cons = apply_mapping_to_schema_atom_(sr.consequent, mapping);
            if (rep.lca[cons.u][cons.v] != cons.w) {
                if (why) {
                    *why = string("support8 local exact refutation on rooted-tree representative ") + rep.canonical_code
                         + " for schema " + sr.fingerprint
                         + " expected consequent " + sparse_constraint_to_string_(SparseLcaConstraint{cons.u, cons.v, cons.w})
                         + "; got=" + to_string(rep.lca[cons.u][cons.v]);
                }
                bad = true;
                return true;
            }
            return false;
        });
        if (bad) return false;
    }
    if (why) *why = string("support8 local exact validated over rooted-tree representatives=") + to_string(reps.size());
    return true;
}

static bool validate_structured_local_schema_plus_one_target8_(const StructuredLocalSchema& schema,
                                                               string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    if (schema_support_size_(sr) + 1 != 8) {
        if (why) *why = "schema plus-one target is not 8";
        return false;
    }
    return validate_structured_local_schema_exact_chunked_(schema, 8, true, nullptr, why);
}


static bool exact_plus_one_consequent_forced_on_antecedent_instance_(const SparseLcaInstance& antecedent_instance,
                                                                     const SparseLcaConstraint& consequent,
                                                                     string* why) {
    auto inst = canonicalize_sparse_instance_(antecedent_instance);
    bool found_satisfying = false;
    bool found_counterexample = false;
    string counterexample_why;
    auto check_tree = [&](const StaticRootedTree& tree) -> bool {
        auto depth = depth_map_from_tree_(tree);
        for (auto c : inst.constraints) {
            if (c.u == c.v) {
                if (c.w != c.u) return false;
                continue;
            }
            int got = lca_in_tree_(tree, depth, c.u, c.v);
            if (got != c.w) return false;
        }
        found_satisfying = true;
        int got = (consequent.u == consequent.v)
                    ? consequent.u
                    : lca_in_tree_(tree, depth, consequent.u, consequent.v);
        if (got != consequent.w) {
            found_counterexample = true;
            counterexample_why = string("structured schema plus-one target9 failed on antecedent-only instance ")
                               + sparse_instance_to_string_(inst)
                               + " with consequent " + sparse_constraint_to_string_(consequent)
                               + "; forced value=" + to_string(got);
            return true;
        }
        return false;
    };
    if (inst.n <= 7) {
        const auto& trees = cached_static_trees_(inst.n);
        for (const auto& item : trees) {
            if (check_tree(item.tree)) break;
        }
    } else {
        for_each_rooted_tree_prufer_stream_(inst.n, [&](const StaticRootedTree& tree) {
            return check_tree(tree);
        });
    }
    if (!found_satisfying) {
        if (why) *why = string("antecedent-only instance unexpectedly unsatisfiable: ")
                      + sparse_instance_to_string_(inst)
                      + " :: instance is unsatisfiable under exact rooted-tree oracle";
        return false;
    }
    if (found_counterexample) {
        if (why) *why = counterexample_why;
        return false;
    }
    if (why) *why = string("plus-one target9 consequent forced for antecedent-only instance ") + sparse_instance_to_string_(inst);
    return true;
}

static bool validate_structured_local_schema_plus_one_target9_chunked_(const StructuredLocalSchema& schema,
                                                                       StructuredSchemaValidationChunkStats* stats,
                                                                       string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    auto canon = canonicalize_schema_rule_(sr);
    if (schema_support_size_(sr) + 1 != 9) {
        if (why) *why = "schema plus-one target is not 9";
        return false;
    }
    ensure_support8_plus_one_target9_caches_loaded_();
    string key = canon.fingerprint;
    auto it_done = g_support8_plus_one_target9_result_cache.find(key);
    if (it_done != g_support8_plus_one_target9_result_cache.end()) {
        ++g_last_structured_schema_validation_cache_hits;
        if (stats) {
            stats->schema_fingerprint = it_done->second.schema_fingerprint;
            stats->exact_n = it_done->second.exact_n;
            stats->instances_seen = it_done->second.instances_seen;
            stats->completed = it_done->second.completed;
            stats->why = string("disk result cache hit: ") + it_done->second.why;
        }
        if (why) *why = it_done->second.why;
        return it_done->second.pass;
    }
    ++g_last_structured_schema_validation_cache_misses;

    string local_why;
    if (quick_refute_structured_local_schema_on_samples_(schema, 8, &local_why)) {
        StructuredSchemaValidationCacheEntry entry;
        entry.schema_fingerprint = key;
        entry.exact_n = 9;
        entry.is_plus_one = true;
        entry.pass = false;
        entry.completed = true;
        entry.instances_total = 0;
        entry.instances_seen = 0;
        entry.why = local_why;
        g_support8_plus_one_target9_result_cache[key] = entry;
        string save_why;
        save_support8_plus_one_target9_result_cache_(g_support8_plus_one_target9_result_cache, &save_why);
        if (stats) {
            stats->schema_fingerprint = entry.schema_fingerprint;
            stats->exact_n = 9;
            stats->instances_seen = 0;
            stats->completed = true;
            stats->why = entry.why;
        }
        if (why) *why = entry.why;
        return false;
    }

    string via_why;
    bool ok = validate_structured_local_schema_plus_one_target9_via_snapshot_(schema, &via_why);
    const bool incomplete = via_why.find("snapshot incomplete") != string::npos;
    if (stats) {
        stats->schema_fingerprint = key;
        stats->exact_n = 9;
        stats->instances_seen = 0;
        stats->completed = !incomplete;
        stats->why = via_why;
    }
    if (incomplete) {
        if (why) *why = via_why;
        return false;
    }

    string count_why;
    auto insts = collect_structured_schema_validation_instances_cached_(schema, 9, &count_why);
    StructuredSchemaValidationCacheEntry entry;
    entry.schema_fingerprint = key;
    entry.exact_n = 9;
    entry.is_plus_one = true;
    entry.pass = ok;
    entry.completed = true;
    entry.instances_total = insts.size();
    entry.instances_seen = insts.size();
    entry.why = via_why;
    g_support8_plus_one_target9_result_cache[key] = entry;
    string save_why;
    save_support8_plus_one_target9_result_cache_(g_support8_plus_one_target9_result_cache, &save_why);
    if (stats) {
        stats->schema_fingerprint = entry.schema_fingerprint;
        stats->exact_n = 9;
        stats->instances_seen = entry.instances_seen;
        stats->completed = true;
        stats->why = entry.why;
    }
    if (why) *why = entry.why;
    return ok;
}
static bool validate_structured_local_schema_plus_one_target9_(const StructuredLocalSchema& schema,
                                                               string* why) {
    return validate_structured_local_schema_plus_one_target9_chunked_(schema, nullptr, why);
}

static bool validate_structured_local_schema_local_exact_extended_(const StructuredLocalSchema& schema,
                                                                   string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int support = schema_support_size_(sr);
    if (support <= 6) return validate_structured_local_schema_local_exact_(schema, why);
    if (support == 7) return validate_structured_local_schema_local_exact_support7_(schema, why);
    if (support == 8) return validate_structured_local_schema_local_exact_support8_(schema, why);
    if (why) *why = "schema support size out of supported exact local range";
    return false;
}

static bool validate_structured_local_schema_plus_one_exact_extended_(const StructuredLocalSchema& schema,
                                                                      string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int target_n = schema_support_size_(sr) + 1;
    if (target_n <= 7) return validate_structured_local_schema_plus_one_exact_(schema, why);
    if (target_n == 8) return validate_structured_local_schema_plus_one_target8_(schema, why);
    if (target_n == 9) return validate_structured_local_schema_plus_one_target9_(schema, why);
    if (why) *why = "schema plus-one target outside supported exact range";
    return false;
}

static StructuredSchemaValidationSupportStats build_structured_schema_validation_support_stats_(string* why) {
    StructuredSchemaValidationSupportStats stats;
    stats.max_local_exact_support_verified = 8;
    stats.max_plus_one_target_verified = 9;
    stats.support7_local_exact_ready = true;
    stats.support8_local_exact_ready = true;
    stats.target8_plus_one_ready = true;
    stats.target9_plus_one_ready = true;
    stats.why = "extended validator path verified through support 8 local exact and target 9 plus-one exact via chunked exact-cache";
    g_last_structured_schema_validation_support_stats = stats;
    if (why) *why = structured_schema_validation_support_stats_to_string_(stats);
    return stats;
}

static SolverSaturationResult run_structured_local_schema_closure_(const SparseLcaInstance& instance,
                                                                   const vector<SparseRuleCandidate>& base_sound_rules,
                                                                   const vector<SchemaRule>& solver_schema_rules,
                                                                   const vector<SparseRuleCandidate>& retained_first_wave_rules,
                                                                   const vector<SparseRuleCandidate>& retained_second_wave_rules,
                                                                   const vector<StructuredLocalSchema>& structured_schemas,
                                                                   string* why) {
    auto merged_base = merge_repair_rule_sets_(base_sound_rules, retained_first_wave_rules);
    merged_base = merge_repair_rule_sets_(merged_base, retained_second_wave_rules);
    vector<SchemaRule> all = solver_schema_rules;
    for (const auto& s : structured_schemas) all.push_back(structured_local_schema_to_schema_rule_(s));
    all = schema_rules_to_solver_system_(all);
    return run_solver_completion_closure_(instance, merged_base, all, why);
}

static bool scan_structured_local_schema_exhaustive_n5_(const vector<SparseRuleCandidate>& base_sound_rules,
                                                        const vector<SchemaRule>& solver_schema_rules,
                                                        const vector<SparseRuleCandidate>& retained_first_wave_rules,
                                                        const vector<SparseRuleCandidate>& retained_second_wave_rules,
                                                        const vector<StructuredLocalSchema>& structured_schemas,
                                                        RepairedTheoremStats* stats,
                                                        SolverSaturationResult* first_failure,
                                                        string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(5);
    RepairedTheoremStats local;
    local.n = 5;
    local.canonical_instances = enum_res.canonical_instances.size();
    SolverSaturationResult local_first;
    bool have_failure = false;
    size_t pair_witnesses = 0;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("structured_exact_n5", progress_idx, enum_res.canonical_instances.size());
        auto sat = run_structured_local_schema_closure_(inst, base_sound_rules, solver_schema_rules,
                                                        retained_first_wave_rules, retained_second_wave_rules,
                                                        structured_schemas, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        pair_witnesses += sat.missing_forced_pairs.size();
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first = sat; have_failure = true; }
        }
    }
    local.pair_witnesses = pair_witnesses;
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first;
    if (why) *why = have_failure ? local_first.why : string();
    return true;
}

