static vector<SparseRuleCandidate> enumerate_relevant_locally_exact_sound_rules_up_to_support_(int support_bound,
                                                                                                size_t limit,
                                                                                                string* why) {
    size_t considered = 0;
    map<string, SparseRuleCandidate> uniq;
    auto consider_rule = [&](const SparseRuleCandidate& raw) {
        ++considered;
        auto rule = canonicalize_rule_candidate_(raw);
        if (repair_principle_support_size_(rule) > support_bound) return;
        string local_why;
        if (!validate_repair_principle_local_exact_(rule, &local_why)) return;
        uniq.emplace(rule.fingerprint, rule);
    };

    vector<SparseRuleCandidate> seed_rules;
    for (const auto& r : retained_first_wave_repair_rules_()) seed_rules.push_back(r);
    for (const auto& r : retained_second_wave_repair_rules_()) seed_rules.push_back(r);
    for (const auto& r : retained_third_wave_repair_rules_()) seed_rules.push_back(r);

    if (limit && seed_rules.size() > limit) seed_rules.resize(limit);
    for (const auto& r : seed_rules) consider_rule(r);

    vector<SparseRuleCandidate> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const SparseRuleCandidate& a, const SparseRuleCandidate& b) {
        if (a.antecedents.size() != b.antecedents.size()) return a.antecedents.size() < b.antecedents.size();
        return a.fingerprint < b.fingerprint;
    });
    if (why) *why = "candidate_rules_considered=" + to_string(considered) + " locally_exact_sound=" + to_string(out.size());
    return out;
}

