static LocalityObstructionCertificate build_locality_obstruction_certificate_(const SparseLcaInstance& instance,
                                                                              const SparseLcaConstraint& target,
                                                                              int support_bound,
                                                                              string* why) {
    LocalityObstructionCertificate cert;
    cert.support_bound = support_bound;
    cert.instance = canonicalize_sparse_instance_(instance);
    cert.target = normalize_sparse_constraint_(target);
    cert.instance_fingerprint = canonical_sparse_instance_fingerprint_(cert.instance);
    cert.target_fingerprint = sparse_constraint_to_string_(cert.target);
    cert.reason = "bounded local Horn envelope of support <= " + to_string(support_bound)
                + " fails to derive a target forced by exact oracle";
    if (why) *why = cert.reason;
    return cert;
}

static vector<LocalityObstructionCertificate> build_locality_obstruction_certificates_from_failures_(const SolverSaturationResult& exact_failure,
                                                                                                      const SolverSaturationResult& bounded_failure,
                                                                                                      int support_bound) {
    vector<LocalityObstructionCertificate> out;
    if (exact_failure.instance.n > 0 && !exact_failure.missing_forced_pairs.empty()) {
        string why;
        out.push_back(build_locality_obstruction_certificate_(exact_failure.instance, exact_failure.missing_forced_pairs.front(), support_bound, &why));
    }
    if (bounded_failure.instance.n > 0 && !bounded_failure.missing_forced_pairs.empty()) {
        string why;
        auto cert = build_locality_obstruction_certificate_(bounded_failure.instance, bounded_failure.missing_forced_pairs.front(), support_bound, &why);
        if (out.empty() || cert.instance_fingerprint != out.front().instance_fingerprint || cert.target_fingerprint != out.front().target_fingerprint) {
            out.push_back(cert);
        }
    }
    return out;
}

static string classify_structured_local_vs_nonlocal_(const StructuredLocalTheoremStats& local_stats,
                                                     const BoundedLocalHornEnvelopeStats& envelope_stats,
                                                     const vector<LocalityObstructionCertificate>& certs,
                                                     string* why) {
    bool local_plus_one_complete = local_stats.schema_family_count > 0 && local_stats.plus_one_pass_count == local_stats.schema_family_count;
    bool local_exact_zero = local_stats.exact_n5_mismatches == 0 && local_stats.bounded_n6_mismatches == 0;
    bool envelope_zero = envelope_stats.exact_n5_mismatches == 0 && envelope_stats.bounded_n6_mismatches == 0;
    if (local_plus_one_complete && local_exact_zero && certs.empty()) {
        if (why) *why = "structured local schemas pass plus-one exact extension and leave no tested residual";
        return "structured_local_theorem_still_viable";
    }
    if (!envelope_zero && !certs.empty()) {
        if (why) *why = "bounded local Horn envelope still leaves residual and explicit locality obstruction certificates exist";
        return "bounded_local_repair_insufficient_nonlocal_preferred";
    }
    if (why) *why = "structured local schema or bounded envelope evidence is incomplete or mixed";
    return "mixed_frontier_more_evidence_needed";
}

static string build_local_vs_nonlocal_decision_ledger_(const StructuredLocalTheoremStats& local_stats,
                                                       const RepairedTheoremStats& local_exact_n5,
                                                       const RepairedTheoremStats& local_bounded_n6,
                                                       const BoundedLocalHornEnvelopeStats& envelope_stats,
                                                       const RepairedTheoremStats& envelope_exact_n5,
                                                       const RepairedTheoremStats& envelope_bounded_n6,
                                                       const vector<LocalityObstructionCertificate>& certs,
                                                       const string& decision) {
    ostringstream oss;
    oss << "decision=" << decision << "\n";
    oss << "structuredLocal=" << structured_local_theorem_stats_to_string_(local_stats) << "\n";
    oss << "structuredExactN5=" << repaired_theorem_stats_to_string_(local_exact_n5) << "\n";
    oss << "structuredBoundedN6=" << repaired_theorem_stats_to_string_(local_bounded_n6) << "\n";
    oss << "envelope=" << bounded_local_horn_envelope_stats_to_string_(envelope_stats) << "\n";
    oss << "envelopeExactN5=" << repaired_theorem_stats_to_string_(envelope_exact_n5) << "\n";
    oss << "envelopeBoundedN6=" << repaired_theorem_stats_to_string_(envelope_bounded_n6) << "\n";
    oss << "obstructionCertificates=" << certs.size() << "\n";
    for (const auto& cert : certs) oss << "certificate=" << locality_obstruction_certificate_to_string_(cert) << "\n";
    return oss.str();
}

static void ensure_structured_local_vs_nonlocal_ready_() {
    ensure_repaired_theorem_baseline_ready_();
    ensure_third_wave_vs_nonlocal_ready_();
    auto solver_schemas = current_solver_schema_rules_();
    string why;
    if (g_last_retained_third_wave_repair_rules.empty()) {
        g_last_retained_third_wave_repair_rules = retained_third_wave_repair_rules_();
    }
    if (g_last_structured_local_schema_families.empty()) {
        g_last_structured_local_schema_families = generalize_third_wave_to_structured_local_schemas_(g_last_retained_third_wave_repair_rules);
        g_last_structured_local_schemas.clear();
        for (const auto& fam : g_last_structured_local_schema_families) g_last_structured_local_schemas.push_back(fam.representative);
    }
    if (g_last_structured_local_theorem_stats.schema_family_count == 0) {
        g_last_structured_local_theorem_stats.schema_family_count = g_last_structured_local_schema_families.size();
        for (const auto& schema : g_last_structured_local_schemas) {
            string local_why;
            bool local_ok = validate_structured_local_schema_local_exact_(schema, &local_why);
            if (local_ok) ++g_last_structured_local_theorem_stats.local_exact_pass_count;
            bool plus_one_ok = false;
            if (local_ok) plus_one_ok = validate_structured_local_schema_plus_one_exact_(schema, &local_why);
            if (plus_one_ok) ++g_last_structured_local_theorem_stats.plus_one_pass_count;
            bool attempt_plus_two = schema.num_symbols <= 5;
            if (attempt_plus_two) {
                ++g_last_structured_local_theorem_stats.plus_two_attempted_count;
                if (validate_structured_local_schema_plus_two_exact_(schema, &local_why)) ++g_last_structured_local_theorem_stats.plus_two_pass_count;
            }
            if (!local_why.empty() && g_last_structured_local_theorem_stats.why.empty()) g_last_structured_local_theorem_stats.why = local_why;
        }
    }
    if (g_last_structured_local_exact_n5_stats.canonical_instances == 0) {
        if (!scan_structured_local_schema_exhaustive_n5_({}, solver_schemas,
                                                         retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                         g_last_structured_local_schemas,
                                                         &g_last_structured_local_exact_n5_stats,
                                                         &g_last_structured_local_exact_n5_failure,
                                                         &why)) {
            throw runtime_error("ensure_structured_local: exact n5 failed\n" + why);
        }
        g_last_structured_local_theorem_stats.exact_n5_full_matches = g_last_structured_local_exact_n5_stats.full_match_instances;
        g_last_structured_local_theorem_stats.exact_n5_mismatches = g_last_structured_local_exact_n5_stats.mismatch_instances;
    }
    if (g_last_structured_local_bounded_exact_n6_stats.canonical_instances == 0) {
        if (!scan_structured_local_schema_bounded_exact_n6_(kRepairedBoundedExactN6MaxConstraints, {}, solver_schemas,
                                                             retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                             g_last_structured_local_schemas,
                                                             &g_last_structured_local_bounded_exact_n6_stats,
                                                             &g_last_structured_local_bounded_exact_n6_failure,
                                                             &why)) {
            throw runtime_error("ensure_structured_local: bounded exact n6 failed\n" + why);
        }
        g_last_structured_local_theorem_stats.bounded_n6_full_matches = g_last_structured_local_bounded_exact_n6_stats.full_match_instances;
        g_last_structured_local_theorem_stats.bounded_n6_mismatches = g_last_structured_local_bounded_exact_n6_stats.mismatch_instances;
    }
    if (g_last_structured_local_sampled_n6_stats.canonical_instances == 0) {
        scan_structured_local_schema_randomized_(6, kSchemaRandomizedSeed, kSchemaRandomizedN6NumTrees, kSchemaRandomizedN6SubsetsPerTree,
                                                 {}, solver_schemas, retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                 g_last_structured_local_schemas,
                                                 &g_last_structured_local_sampled_n6_stats, &g_last_structured_local_sampled_n6_failure, &why);
    }
    if (g_last_structured_local_sampled_n7_stats.canonical_instances == 0) {
        scan_structured_local_schema_randomized_(7, kSchemaRandomizedSeed, kSchemaRandomizedN7NumTrees, kSchemaRandomizedN7SubsetsPerTree,
                                                 {}, solver_schemas, retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                 g_last_structured_local_schemas,
                                                 &g_last_structured_local_sampled_n7_stats, &g_last_structured_local_sampled_n7_failure, &why);
    }
    if (g_last_structured_local_sampled_n8_stats.canonical_instances == 0) {
        scan_structured_local_schema_randomized_(8, kSchemaRandomizedSeed, kSchemaRandomizedN8NumTrees, kSchemaRandomizedN8SubsetsPerTree,
                                                 {}, solver_schemas, retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                 g_last_structured_local_schemas,
                                                 &g_last_structured_local_sampled_n8_stats, &g_last_structured_local_sampled_n8_failure, &why);
    }
    int support_bound = 0;
    for (const auto& r : retained_all_repair_rules_()) support_bound = max(support_bound, repair_principle_support_size_(r));
    for (const auto& r : retained_third_wave_repair_rules_()) support_bound = max(support_bound, repair_principle_support_size_(r));
    if (g_last_bounded_local_horn_rule_universe.empty()) {
        string local_why;
        g_last_bounded_local_horn_rule_universe = enumerate_relevant_locally_exact_sound_rules_up_to_support_(support_bound, kBoundedLocalRelevantRuleLimit, &local_why);
        g_last_bounded_local_horn_envelope_stats.support_bound = support_bound;
        g_last_bounded_local_horn_envelope_stats.locally_exact_sound_rules = g_last_bounded_local_horn_rule_universe.size();
        size_t considered = 0;
        considered += retained_all_repair_rules_().size();
        considered += retained_third_wave_repair_rules_().size();
        g_last_bounded_local_horn_envelope_stats.candidate_rules_considered = considered;
        g_last_bounded_local_horn_envelope_stats.why = local_why;
    }
    if (g_last_bounded_local_envelope_exact_n5_stats.canonical_instances == 0) {
        if (!scan_bounded_local_horn_envelope_exhaustive_n5_({}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                             &g_last_bounded_local_envelope_exact_n5_stats,
                                                             &g_last_bounded_local_envelope_exact_n5_failure,
                                                             &why)) {
            throw runtime_error("ensure_structured_local: envelope exact n5 failed\n" + why);
        }
        g_last_bounded_local_horn_envelope_stats.exact_n5_full_matches = g_last_bounded_local_envelope_exact_n5_stats.full_match_instances;
        g_last_bounded_local_horn_envelope_stats.exact_n5_mismatches = g_last_bounded_local_envelope_exact_n5_stats.mismatch_instances;
    }
    if (g_last_bounded_local_envelope_bounded_exact_n6_stats.canonical_instances == 0) {
        if (!scan_bounded_local_horn_envelope_bounded_exact_n6_(kRepairedBoundedExactN6MaxConstraints, {}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                                 &g_last_bounded_local_envelope_bounded_exact_n6_stats,
                                                                 &g_last_bounded_local_envelope_bounded_exact_n6_failure,
                                                                 &why)) {
            throw runtime_error("ensure_structured_local: envelope bounded exact n6 failed\n" + why);
        }
        g_last_bounded_local_horn_envelope_stats.bounded_n6_full_matches = g_last_bounded_local_envelope_bounded_exact_n6_stats.full_match_instances;
        g_last_bounded_local_horn_envelope_stats.bounded_n6_mismatches = g_last_bounded_local_envelope_bounded_exact_n6_stats.mismatch_instances;
    }
    if (g_last_locality_obstruction_certificates.empty()) {
        #ifdef LOCAL_TEST
    cerr << "stage: obstruction recheck\n";
#endif
    g_last_locality_obstruction_certificates = build_locality_obstruction_certificates_from_failures_(
            g_last_bounded_local_envelope_exact_n5_failure,
            g_last_bounded_local_envelope_bounded_exact_n6_failure,
            support_bound);
    }
    string decision_why;
    g_last_structured_local_vs_nonlocal_decision = classify_structured_local_vs_nonlocal_(g_last_structured_local_theorem_stats,
                                                                                          g_last_bounded_local_horn_envelope_stats,
                                                                                          g_last_locality_obstruction_certificates,
                                                                                          &decision_why);
    if (g_last_structured_local_theorem_stats.why.empty()) g_last_structured_local_theorem_stats.why = decision_why;
    g_last_structured_local_vs_nonlocal_ledger = build_local_vs_nonlocal_decision_ledger_(
        g_last_structured_local_theorem_stats,
        g_last_structured_local_exact_n5_stats,
        g_last_structured_local_bounded_exact_n6_stats,
        g_last_bounded_local_horn_envelope_stats,
        g_last_bounded_local_envelope_exact_n5_stats,
        g_last_bounded_local_envelope_bounded_exact_n6_stats,
        g_last_locality_obstruction_certificates,
        g_last_structured_local_vs_nonlocal_decision);
}



static SingleSchemaSampledSupportStats build_single_schema_sampled_support_stats_(int n,
                                                                                         const vector<uint32_t>& seeds,
                                                                                         int num_trees_per_seed,
                                                                                         int num_subsets_per_tree,
                                                                                         const RepairedTheoremStats& stats,
                                                                                         bool same_as_local_envelope,
                                                                                         size_t obstruction_count,
                                                                                         const string& why) {
    SingleSchemaSampledSupportStats out;
    out.n = n;
    out.seeds = seeds;
    out.num_trees_per_seed = num_trees_per_seed;
    out.num_subsets_per_tree = num_subsets_per_tree;
    out.total_instances = stats.canonical_instances;
    out.full_match_instances = stats.full_match_instances;
    out.mismatch_instances = stats.mismatch_instances;
    out.pair_witnesses = stats.pair_witnesses;
    out.same_as_local_envelope = same_as_local_envelope;
    out.obstruction_count = obstruction_count;
    out.why = why;
    return out;
}

static string single_schema_sampled_support_to_string_(const SingleSchemaSampledSupportStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " seeds=" << s.seeds.size()
        << " treesPerSeed=" << s.num_trees_per_seed
        << " subsetsPerTree=" << s.num_subsets_per_tree
        << " totalInstances=" << s.total_instances
        << " fullMatch=" << s.full_match_instances
        << " mismatch=" << s.mismatch_instances
        << " pairWitnesses=" << s.pair_witnesses
        << " sameAsEnvelope=" << (s.same_as_local_envelope ? "true" : "false")
        << " obstructionCount=" << s.obstruction_count;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

