static string single_schema_theorem_stats_to_string_(const SingleSchemaTheoremStats& s) {
    ostringstream oss;
    oss << "localExact=" << (s.local_exact_pass ? "true" : "false")
        << " plusOne=" << (s.plus_one_pass ? "true" : "false")
        << " plusTwo=" << (s.plus_two_pass ? "true" : "false")
        << " plusThreeAttempted=" << (s.plus_three_attempted ? "true" : "false")
        << " plusThree=" << (s.plus_three_pass ? "true" : "false")
        << " eqN5=" << (s.exact_n5_equal_envelope ? "true" : "false")
        << " eqN6C3=" << (s.bounded_n6_c3_equal_envelope ? "true" : "false")
        << " eqN6C4=" << (s.bounded_n6_c4_equal_envelope ? "true" : "false")
        << " eqN9=" << (s.sampled_n9_equal_envelope ? "true" : "false")
        << " eqN10=" << (s.sampled_n10_equal_envelope ? "true" : "false")
        << " status=" << s.status;
    if (!s.why.empty()) oss << " why=" << s.why;
    if (!s.plus_three_why.empty()) oss << " plusThreeWhy=" << s.plus_three_why;
    return oss.str();
}

static StructuredLocalSchema single_structured_local_schema_() {
    SchemaRule raw;
    raw.num_symbols = 4;
    raw.antecedents = {SchemaAtom{2,3,2}, SchemaAtom{2,4,4}};
    raw.consequent = SchemaAtom{3,4,4};
    auto out = schema_rule_to_structured_local_schema_(canonicalize_schema_rule_(raw));
    if (!g_last_structured_local_schema_families.empty() &&
        g_last_structured_local_schema_families.front().fingerprint == out.fingerprint) {
        out.support = g_last_structured_local_schema_families.front().cumulative_support;
        out.human_readable = g_last_structured_local_schema_families.front().representative.human_readable;
    } else if (out.support == 0) {
        out.support = 1;
    }
    return out;
}

static string single_structured_local_schema_fingerprint_() {
    return single_structured_local_schema_().fingerprint;
}

static bool validate_single_schema_plus_three_exact_(const StructuredLocalSchema& schema,
                                                     string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    return validate_schema_rule_exact_extension_full_(sr, schema.num_symbols + 3, nullptr, why);
}

static SolverSaturationResult run_single_schema_theorem_closure_(const SparseLcaInstance& instance,
                                                                 const vector<SparseRuleCandidate>& base_sound_rules,
                                                                 const vector<SchemaRule>& solver_schema_rules,
                                                                 const vector<SparseRuleCandidate>& retained_first_wave_rules,
                                                                 const vector<SparseRuleCandidate>& retained_second_wave_rules,
                                                                 string* why) {
    vector<StructuredLocalSchema> schemas{single_structured_local_schema_()};
    return run_structured_local_schema_closure_(instance,
                                                base_sound_rules,
                                                solver_schema_rules,
                                                retained_first_wave_rules,
                                                retained_second_wave_rules,
                                                schemas,
                                                why);
}

