static vector<SparseLcaInstance> sample_canonical_sparse_instances_randomized_multi_seed_(int n,
                                                                                        const vector<uint32_t>& seeds,
                                                                                        int num_trees,
                                                                                        int num_subsets_per_tree) {
    map<string, SparseLcaInstance> uniq;
    for (uint32_t seed : seeds) {
        auto sampled = sample_canonical_sparse_instances_randomized_(n, seed, num_trees, num_subsets_per_tree);
        for (const auto& inst : sampled) uniq.emplace(canonical_sparse_instance_fingerprint_(inst), inst);
    }
    vector<SparseLcaInstance> out;
    out.reserve(uniq.size());
    for (const auto& kv : uniq) out.push_back(kv.second);
    return out;
}

static vector<SparseLcaInstance> build_shared_sampled_instance_pool_(int n,
                                                                               const vector<uint32_t>& seeds,
                                                                               int num_trees_per_seed,
                                                                               int num_subsets_per_tree,
                                                                               string* why) {
    auto instances = sample_canonical_sparse_instances_randomized_multi_seed_(n, seeds, num_trees_per_seed, num_subsets_per_tree);
    if (why) {
        *why = "n=" + to_string(n)
             + " seeds=" + to_string(seeds.size())
             + " treesPerSeed=" + to_string(num_trees_per_seed)
             + " subsetsPerTree=" + to_string(num_subsets_per_tree)
             + " totalInstances=" + to_string(instances.size());
    }
    return instances;
}

static bool scan_structured_local_schema_on_instances_(const vector<SparseLcaInstance>& instances,
                                                       const vector<SparseRuleCandidate>& base_sound_rules,
                                                       const vector<SchemaRule>& solver_schema_rules,
                                                       const vector<SparseRuleCandidate>& retained_first_wave_rules,
                                                       const vector<SparseRuleCandidate>& retained_second_wave_rules,
                                                       const vector<StructuredLocalSchema>& structured_schemas,
                                                       string label,
                                                       RepairedTheoremStats* stats,
                                                       SolverSaturationResult* first_failure,
                                                       string* why) {
    string prewarm_why;
    if (!prewarm_exact_sparse_completion_oracle_batch_same_n_(instances, &prewarm_why)) { if (why) *why = prewarm_why; return false; }
    RepairedTheoremStats local;
    local.n = instances.empty() ? 0 : instances.front().n;
    local.canonical_instances = instances.size();
    SolverSaturationResult local_first_failure;
    bool have_failure = false;
    size_t pair_witnesses = 0;
    size_t progress_idx = 0;
    for (const auto& inst : instances) {
        ++progress_idx;
        local_progress_(label.c_str(), progress_idx, instances.size());
        auto sat = run_structured_local_schema_closure_(inst, base_sound_rules, solver_schema_rules,
                                                        retained_first_wave_rules, retained_second_wave_rules,
                                                        structured_schemas, nullptr);
        if (!sat.oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        pair_witnesses += sat.missing_forced_pairs.size();
        if (sat.full_match) ++local.full_match_instances;
        else {
            ++local.mismatch_instances;
            if (!have_failure) { local_first_failure = sat; have_failure = true; }
        }
    }
    local.pair_witnesses = pair_witnesses;
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    if (why) *why = have_failure ? local_first_failure.why : string();
    return true;
}

