static bool compare_single_schema_vs_local_envelope_on_instances_(const vector<SparseLcaInstance>& instances,
                                                                  const vector<SparseRuleCandidate>& base_sound_rules,
                                                                  const vector<SchemaRule>& solver_schema_rules,
                                                                  const vector<SparseRuleCandidate>& retained_first_wave_rules,
                                                                  const vector<SparseRuleCandidate>& retained_second_wave_rules,
                                                                  const vector<SparseRuleCandidate>& rule_universe,
                                                                  string label,
                                                                  string* why) {
    size_t idx = 0;
    for (const auto& inst : instances) {
        ++idx;
        local_progress_(label.c_str(), idx, instances.size());
        auto a = run_single_schema_theorem_closure_(inst, base_sound_rules, solver_schema_rules,
                                                    retained_first_wave_rules, retained_second_wave_rules, nullptr);
        auto b = run_bounded_local_horn_envelope_closure_(inst, base_sound_rules, solver_schema_rules, rule_universe, nullptr);
        if (!a.oracle.satisfiable && !b.oracle.satisfiable) continue;
        if (a.oracle.satisfiable != b.oracle.satisfiable) {
            if (why) *why = "satisfiable mismatch on instance " + sparse_instance_to_string_(inst);
            return false;
        }
        if (a.closure_pairwise_lca != b.closure_pairwise_lca ||
            sparse_constraint_vec_to_string_(a.missing_forced_pairs) != sparse_constraint_vec_to_string_(b.missing_forced_pairs) ||
            sparse_constraint_vec_to_string_(a.extra_derived_pairs) != sparse_constraint_vec_to_string_(b.extra_derived_pairs)) {
            if (why) {
                *why = "single schema vs local envelope mismatch on instance " + sparse_instance_to_string_(inst)
                     + "\n[single]\n" + solver_saturation_result_to_string_(a)
                     + "\n[envelope]\n" + solver_saturation_result_to_string_(b);
            }
            return false;
        }
    }
    if (why) *why = "";
    return true;
}

static bool compare_single_schema_vs_local_envelope_n5_(string* why) {
    if (g_last_single_schema_exact_n5_stats.canonical_instances > 0 &&
        g_last_bounded_local_envelope_exact_n5_stats.canonical_instances > 0 &&
        g_last_single_schema_exact_n5_stats.mismatch_instances == 0 &&
        g_last_bounded_local_envelope_exact_n5_stats.mismatch_instances == 0 &&
        g_last_single_schema_exact_n5_stats.full_match_instances == g_last_single_schema_exact_n5_stats.satisfiable_instances &&
        g_last_bounded_local_envelope_exact_n5_stats.full_match_instances == g_last_bounded_local_envelope_exact_n5_stats.satisfiable_instances) {
        if (why) *why = "";
        return true;
    }
    auto enum_res = enumerate_canonical_sparse_instances_(5);
    return compare_single_schema_vs_local_envelope_on_instances_(enum_res.canonical_instances,
                                                                 {}, current_solver_schema_rules_(),
                                                                 retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                                 g_last_bounded_local_horn_rule_universe,
                                                                 "cmp_single_env_n5", why);
}

static bool compare_single_schema_vs_local_envelope_bounded_n6_(int max_constraints,
                                                                const RepairedTheoremStats& single_stats,
                                                                const RepairedTheoremStats& envelope_stats,
                                                                string* why) {
    if (single_stats.canonical_instances > 0 && envelope_stats.canonical_instances > 0 &&
        single_stats.mismatch_instances == 0 && envelope_stats.mismatch_instances == 0 &&
        single_stats.full_match_instances == single_stats.satisfiable_instances &&
        envelope_stats.full_match_instances == envelope_stats.satisfiable_instances) {
        if (why) *why = "";
        return true;
    }
    auto enum_res = enumerate_canonical_sparse_instances_bounded_by_constraints_(6, max_constraints);
    return compare_single_schema_vs_local_envelope_on_instances_(enum_res.canonical_instances,
                                                                 {}, current_solver_schema_rules_(),
                                                                 retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                                 g_last_bounded_local_horn_rule_universe,
                                                                 "cmp_single_env_n6", why);
}

static bool compare_single_schema_vs_local_envelope_randomized_(int n,
                                                                uint32_t seed,
                                                                int num_trees,
                                                                int num_subsets_per_tree,
                                                                const RepairedTheoremStats& single_stats,
                                                                const RepairedTheoremStats& envelope_stats,
                                                                string* why) {
    if (single_stats.canonical_instances > 0 && envelope_stats.canonical_instances > 0 &&
        single_stats.canonical_instances == envelope_stats.canonical_instances &&
        single_stats.satisfiable_instances == envelope_stats.satisfiable_instances &&
        single_stats.full_match_instances == single_stats.satisfiable_instances &&
        envelope_stats.full_match_instances == envelope_stats.satisfiable_instances &&
        single_stats.mismatch_instances == 0 && envelope_stats.mismatch_instances == 0 &&
        single_stats.pair_witnesses == 0 && envelope_stats.pair_witnesses == 0) {
        if (why) {
            *why = "carried forward perfect-match equality baseline for n=" + to_string(n)
                 + " canonicalInstances=" + to_string(single_stats.canonical_instances);
        }
        return true;
    }
    vector<SparseLcaInstance> instances;
    string pool_why;
    if (n == 9) {
        instances = build_shared_sampled_instance_pool_(n, single_schema_randomized_n9_seeds_(), num_trees, num_subsets_per_tree, &pool_why);
    } else if (n == 10) {
        instances = build_shared_sampled_instance_pool_(n, single_schema_randomized_n10_seeds_(), num_trees, num_subsets_per_tree, &pool_why);
    } else {
        instances = sample_canonical_sparse_instances_randomized_(n, seed, num_trees, num_subsets_per_tree);
        pool_why = "n=" + to_string(n) + " totalInstances=" + to_string(instances.size());
    }
    string prewarm_why;
    if (!prewarm_exact_sparse_completion_oracle_batch_same_n_(instances, &prewarm_why)) {
        if (why) *why = prewarm_why;
        return false;
    }
    string cmp_why;
    bool ok = compare_single_schema_vs_local_envelope_on_instances_(instances,
                                                                     {}, current_solver_schema_rules_(),
                                                                     retained_first_wave_repair_rules_(), retained_second_wave_repair_rules_(),
                                                                     g_last_bounded_local_horn_rule_universe,
                                                                     "cmp_single_env_sampled", &cmp_why);
    if (why) {
        *why = ok ? pool_why : (pool_why + "\n" + cmp_why);
    }
    return ok;
}


static bool same_sparse_constraint_(const SparseLcaConstraint& a,
                                   const SparseLcaConstraint& b) {
    return a.u == b.u && a.v == b.v && a.w == b.w;
}

static bool sparse_constraint_vec_exact_equal_(const vector<SparseLcaConstraint>& a,
                                               const vector<SparseLcaConstraint>& b) {
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i) {
        if (!same_sparse_constraint_(normalize_sparse_constraint_(a[i]), normalize_sparse_constraint_(b[i]))) return false;
    }
    return true;
}

static string single_schema_derivation_step_to_string_(const SingleSchemaDerivationStep& step) {
    ostringstream oss;
    oss << step.rule_kind << ": ";
    if (step.premises.empty()) oss << "[]";
    else oss << sparse_constraint_vec_to_string_(step.premises);
    oss << " => " << sparse_constraint_to_string_(step.conclusion);
    return oss.str();
}

static string single_schema_proof_certificate_to_string_(const SingleSchemaProofCertificate& cert) {
    ostringstream oss;
    oss << "instance=" << sparse_instance_to_string_(cert.instance) << "\n";
    oss << "complete=" << (cert.complete ? "true" : "false") << "\n";
    oss << "final_pairwise_lca=" << pairwise_lca_table_to_string_(cert.final_pairwise_lca) << "\n";
    oss << "stepCount=" << cert.steps.size() << "\n";
    for (size_t i = 0; i < cert.steps.size(); ++i) {
        oss << "step[" << i << "] " << single_schema_derivation_step_to_string_(cert.steps[i]) << "\n";
    }
    if (!cert.why.empty()) oss << "why=" << cert.why << "\n";
    return oss.str();
}

static string envelope_subsumption_stats_to_string_(const EnvelopeSubsumptionStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " instancesChecked=" << s.instances_checked
        << " envelopeDerivedPairs=" << s.envelope_derived_pairs
        << " schemaCertifiedPairs=" << s.schema_certified_pairs
        << " uncertifiedPairs=" << s.uncertified_pairs
        << " fullInstancePass=" << s.full_instance_pass
        << " fullInstanceFail=" << s.full_instance_fail
        << " maxCertificateSteps=" << s.max_certificate_steps;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static EnvelopeSubsumptionStats merge_envelope_subsumption_stats_(const EnvelopeSubsumptionStats& a,
                                                                  const EnvelopeSubsumptionStats& b) {
    EnvelopeSubsumptionStats out;
    out.n = max(a.n, b.n);
    out.instances_checked = a.instances_checked + b.instances_checked;
    out.envelope_derived_pairs = a.envelope_derived_pairs + b.envelope_derived_pairs;
    out.schema_certified_pairs = a.schema_certified_pairs + b.schema_certified_pairs;
    out.uncertified_pairs = a.uncertified_pairs + b.uncertified_pairs;
    out.full_instance_pass = a.full_instance_pass + b.full_instance_pass;
    out.full_instance_fail = a.full_instance_fail + b.full_instance_fail;
    out.max_certificate_steps = max(a.max_certificate_steps, b.max_certificate_steps);
    out.why = !b.why.empty() ? b.why : a.why;
    return out;
}

static ProofKernelContinuationStats proof_kernel_continuation_stats_from_envelope_subsumption_(const EnvelopeSubsumptionStats& s,
                                                                                                  int max_constraints,
                                                                                                  bool completed) {
    ProofKernelContinuationStats out;
    out.n = s.n;
    out.max_constraints = max_constraints;
    out.instances_checked = s.instances_checked;
    out.envelope_derived_pairs = s.envelope_derived_pairs;
    out.schema_certified_pairs = s.schema_certified_pairs;
    out.uncertified_pairs = s.uncertified_pairs;
    out.full_instance_pass = s.full_instance_pass;
    out.full_instance_fail = s.full_instance_fail;
    out.max_certificate_steps = s.max_certificate_steps;
    out.completed = completed;
    out.why = s.why;
    return out;
}

static string proof_kernel_continuation_stats_to_string_(const ProofKernelContinuationStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " maxConstraints=" << s.max_constraints
        << " instancesChecked=" << s.instances_checked
        << " envelopeDerivedPairs=" << s.envelope_derived_pairs
        << " schemaCertifiedPairs=" << s.schema_certified_pairs
        << " uncertifiedPairs=" << s.uncertified_pairs
        << " fullInstancePass=" << s.full_instance_pass
        << " fullInstanceFail=" << s.full_instance_fail
        << " maxCertificateSteps=" << s.max_certificate_steps
        << " completed=" << (s.completed ? "true" : "false");
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string envelope_rule_elimination_certificate_to_string_(const EnvelopeRuleEliminationCertificate& c) {
    ostringstream oss;
    oss << "ruleFingerprint=" << c.envelope_rule_fingerprint
        << " certifiedHits=" << c.certified_hits
        << " uncertifiedHits=" << c.uncertified_hits
        << " maxCertificateSteps=" << c.max_certificate_steps;
    if (!c.why.empty()) oss << " why=" << c.why;
    return oss.str();
}

static EnvelopeRuleEliminationStats build_envelope_rule_elimination_stats_(int n,
                                                                          int max_constraints,
                                                                          const vector<EnvelopeRuleEliminationCertificate>& certs,
                                                                          bool completed,
                                                                          const string& why) {
    EnvelopeRuleEliminationStats out;
    out.n = n;
    out.max_constraints = max_constraints;
    out.rules_in_universe = certs.size();
    out.completed = completed;
    out.why = why;
    for (const auto& c : certs) {
        out.certified_hits += c.certified_hits;
        out.uncertified_hits += c.uncertified_hits;
        if (c.uncertified_hits == 0) {
            ++out.fully_eliminated_rules;
        } else if (c.certified_hits != 0) {
            ++out.partially_eliminated_rules;
        } else {
            ++out.failed_rules;
        }
    }
    return out;
}

static string envelope_rule_elimination_stats_to_string_(const EnvelopeRuleEliminationStats& s) {
    ostringstream oss;
    oss << "n=" << s.n
        << " maxConstraints=" << s.max_constraints
        << " rulesInUniverse=" << s.rules_in_universe
        << " certifiedHits=" << s.certified_hits
        << " uncertifiedHits=" << s.uncertified_hits
        << " fullyEliminatedRules=" << s.fully_eliminated_rules
        << " partiallyEliminatedRules=" << s.partially_eliminated_rules
        << " failedRules=" << s.failed_rules
        << " completed=" << (s.completed ? "true" : "false");
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static vector<SparseRuleCandidate> reduced_local_envelope_rule_universe_() {
    if (!g_last_bounded_local_horn_rule_universe.empty()) return g_last_bounded_local_horn_rule_universe;
    string why;
    int support_bound = g_last_bounded_local_horn_envelope_stats.support_bound > 0 ? g_last_bounded_local_horn_envelope_stats.support_bound : 4;
    g_last_bounded_local_horn_rule_universe = enumerate_relevant_locally_exact_sound_rules_up_to_support_(support_bound,
                                                                                                            kBoundedLocalRelevantRuleLimit,
                                                                                                            &why);
    if (g_last_bounded_local_horn_envelope_stats.support_bound == 0)
        g_last_bounded_local_horn_envelope_stats.support_bound = support_bound;
    if (g_last_bounded_local_horn_envelope_stats.locally_exact_sound_rules == 0)
        g_last_bounded_local_horn_envelope_stats.locally_exact_sound_rules = g_last_bounded_local_horn_rule_universe.size();
    g_last_reduced_local_envelope_rule_universe_fingerprint = sparse_rule_set_fingerprint_(g_last_bounded_local_horn_rule_universe);
    return g_last_bounded_local_horn_rule_universe;
}

static string reduced_local_envelope_rule_universe_fingerprint_() {
    if (g_last_reduced_local_envelope_rule_universe_fingerprint.empty())
        g_last_reduced_local_envelope_rule_universe_fingerprint = sparse_rule_set_fingerprint_(reduced_local_envelope_rule_universe_());
    return g_last_reduced_local_envelope_rule_universe_fingerprint;
}

static vector<SparseRuleCandidate> current_single_schema_theorem_base_rules_(const vector<SparseRuleCandidate>& base_rules) {
    auto merged = merge_repair_rule_sets_(base_rules, retained_first_wave_repair_rules_());
    merged = merge_repair_rule_sets_(merged, retained_second_wave_repair_rules_());
    return merged;
}

static vector<SchemaRule> current_single_schema_theorem_schema_rules_(const StructuredLocalSchema& schema) {
    auto all = current_solver_schema_rules_();
    all.push_back(structured_local_schema_to_schema_rule_(schema));
    return schema_rules_to_solver_system_(all);
}

static bool candidate_rule_matches_exact_premises_and_conclusion_(const SparseRuleCandidate& raw,
                                                                  const vector<SparseLcaConstraint>& premises,
                                                                  const SparseLcaConstraint& conclusion,
                                                                  int n_target) {
    static unordered_map<string, bool> cache;
    auto rule = canonicalize_rule_candidate_(raw);
    string key = rule.fingerprint + "|n=" + to_string(n_target)
               + "|premises=" + sparse_constraint_vec_to_string_(premises)
               + "|conclusion=" + sparse_constraint_to_string_(conclusion);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;
    auto vertices = sparse_rule_vertices_(rule);
    bool found = false;
    for_each_root_preserving_injection_(vertices, n_target, [&](const vector<int>& mapping) {
        vector<SparseLcaConstraint> mapped_premises;
        mapped_premises.reserve(rule.antecedents.size());
        for (const auto& a : rule.antecedents) mapped_premises.push_back(apply_mapping_to_sparse_constraint_(a, mapping));
        auto cons = apply_mapping_to_sparse_constraint_(rule.consequent, mapping);
        if (same_sparse_constraint_(cons, conclusion) && sparse_constraint_vec_exact_equal_(mapped_premises, premises)) {
            found = true;
            return true;
        }
        return false;
    });
    cache.emplace(key, found);
    return found;
}

static bool schema_rule_matches_exact_premises_and_conclusion_(const SchemaRule& raw,
                                                               const vector<SparseLcaConstraint>& premises,
                                                               const SparseLcaConstraint& conclusion,
                                                               int n_target) {
    static unordered_map<string, bool> cache;
    auto schema = canonicalize_schema_rule_(raw);
    string key = schema.fingerprint + "|n=" + to_string(n_target)
               + "|premises=" + sparse_constraint_vec_to_string_(premises)
               + "|conclusion=" + sparse_constraint_to_string_(conclusion);
    auto it = cache.find(key);
    if (it != cache.end()) return it->second;
    auto symbols = schema_rule_used_symbols_(schema);
    bool found = false;
    for_each_schema_embedding_(symbols, n_target, [&](const vector<int>& mapping) {
        vector<SparseLcaConstraint> mapped_premises;
        mapped_premises.reserve(schema.antecedents.size());
        for (const auto& a : schema.antecedents) mapped_premises.push_back(apply_mapping_to_schema_atom_(a, mapping));
        auto cons = apply_mapping_to_schema_atom_(schema.consequent, mapping);
        if (same_sparse_constraint_(cons, conclusion) && sparse_constraint_vec_exact_equal_(mapped_premises, premises)) {
            found = true;
            return true;
        }
        return false;
    });
    cache.emplace(key, found);
    return found;
}

static bool validate_single_schema_proof_certificate_replay_(const SingleSchemaProofCertificate& cert,
                                                             const vector<SparseRuleCandidate>& base_rules,
                                                             const StructuredLocalSchema& schema,
                                                             string* why) {
    auto canon_inst = canonicalize_sparse_instance_(cert.instance);
    auto allowed_base_rules = current_single_schema_theorem_base_rules_(base_rules);
    auto allowed_schema_rules = current_single_schema_theorem_schema_rules_(schema);
    map<string, SparseRuleCandidate> base_by_fp;
    for (const auto& r : allowed_base_rules) base_by_fp[canonicalize_rule_candidate_(r).fingerprint] = canonicalize_rule_candidate_(r);
    map<string, SchemaRule> schema_by_fp;
    for (const auto& s : allowed_schema_rules) schema_by_fp[canonicalize_schema_rule_(s).fingerprint] = canonicalize_schema_rule_(s);
    map<pair<int,int>, int> known;
    auto fail = [&](const string& msg) -> bool { if (why) *why = msg; return false; };
    for (size_t idx = 0; idx < cert.steps.size(); ++idx) {
        auto step = cert.steps[idx];
        step.conclusion = normalize_sparse_constraint_(step.conclusion);
        for (auto& p : step.premises) p = normalize_sparse_constraint_(p);
        auto key = make_pair(step.conclusion.u, step.conclusion.v);
        if (known.count(key)) return fail("duplicate proof conclusion at step " + to_string(idx) + ": " + sparse_constraint_to_string_(step.conclusion));
        if (step.rule_kind == "seed") {
            if (!step.premises.empty()) return fail("seed step with premises at step " + to_string(idx));
            bool found = false;
            for (auto c : canon_inst.constraints) {
                if (same_sparse_constraint_(normalize_sparse_constraint_(c), step.conclusion)) { found = true; break; }
            }
            if (!found) return fail("seed step conclusion not in instance at step " + to_string(idx));
        } else if (step.rule_kind == "R0 root rule") {
            if (!step.premises.empty()) return fail("root rule step with premises at step " + to_string(idx));
            if (step.conclusion.u != 1 || step.conclusion.w != 1 || step.conclusion.v <= 1) {
                return fail("invalid root rule conclusion at step " + to_string(idx) + ": " + sparse_constraint_to_string_(step.conclusion));
            }
        } else if (step.rule_kind == "R2 witness absorption") {
            if (step.premises.size() != 1) return fail("R2 step must have one premise at step " + to_string(idx));
            int got = -1;
            if (!lookup_known_lca_in_map_(known, step.premises[0].u, step.premises[0].v, &got) || got != step.premises[0].w) {
                return fail("R2 premise missing at step " + to_string(idx));
            }
            auto c1 = normalize_sparse_constraint_({step.premises[0].u, step.premises[0].w, step.premises[0].w});
            auto c2 = normalize_sparse_constraint_({step.premises[0].v, step.premises[0].w, step.premises[0].w});
            if (!same_sparse_constraint_(step.conclusion, c1) && !same_sparse_constraint_(step.conclusion, c2)) {
                return fail("R2 conclusion does not match premise at step " + to_string(idx));
            }
        } else if (step.rule_kind.rfind("candidate rule ", 0) == 0) {
            string fp = step.rule_kind.substr(string("candidate rule ").size());
            auto it = base_by_fp.find(fp);
            if (it == base_by_fp.end()) return fail("unknown candidate rule fingerprint at step " + to_string(idx) + ": " + fp);
            for (const auto& p : step.premises) {
                int got = -1;
                if (!lookup_known_lca_in_map_(known, p.u, p.v, &got) || got != p.w) return fail("candidate rule premise missing at step " + to_string(idx));
            }
            if (!candidate_rule_matches_exact_premises_and_conclusion_(it->second, step.premises, step.conclusion, canon_inst.n)) {
                return fail("candidate rule exact application mismatch at step " + to_string(idx) + ": " + fp);
            }
        } else if (step.rule_kind.rfind("schema rule ", 0) == 0) {
            string fp = step.rule_kind.substr(string("schema rule ").size());
            auto it = schema_by_fp.find(fp);
            if (it == schema_by_fp.end()) return fail("unknown schema rule fingerprint at step " + to_string(idx) + ": " + fp);
            for (const auto& p : step.premises) {
                int got = -1;
                if (!lookup_known_lca_in_map_(known, p.u, p.v, &got) || got != p.w) return fail("schema rule premise missing at step " + to_string(idx));
            }
            if (!schema_rule_matches_exact_premises_and_conclusion_(it->second, step.premises, step.conclusion, canon_inst.n)) {
                return fail("schema rule exact application mismatch at step " + to_string(idx) + ": " + fp);
            }
        } else {
            return fail("unknown proof step kind at step " + to_string(idx) + ": " + step.rule_kind);
        }
        known[key] = step.conclusion.w;
    }
    if (known != cert.final_pairwise_lca) return fail("proof replay final table mismatch");
    if (why) *why = "";
    return true;
}

static SingleSchemaProofCertificate build_single_schema_proof_certificate_from_saturation_result_(const SparseLcaInstance& instance,
                                                                                                          const SolverSaturationResult& sat,
                                                                                                          const vector<SparseRuleCandidate>& base_rules,
                                                                                                          const StructuredLocalSchema& schema,
                                                                                                          string* why) {
    SingleSchemaProofCertificate cert;
    cert.instance = canonicalize_sparse_instance_(instance);
    cert.steps = sat.closure.state.proof_trace;
    cert.final_pairwise_lca = sat.closure_pairwise_lca;
    cert.complete = sat.oracle.satisfiable && sat.closure.consistent;
    cert.why = sat.why;
    string replay_why;
    if (cert.complete && !validate_single_schema_proof_certificate_replay_(cert, base_rules, schema, &replay_why)) {
        cert.complete = false;
        cert.why = "proof replay failed: " + replay_why;
    }
    if (why) *why = cert.why;
    return cert;
}

static SingleSchemaProofCertificate build_single_schema_proof_certificate_(const SparseLcaInstance& instance,
                                                                           const vector<SparseRuleCandidate>& base_rules,
                                                                           const StructuredLocalSchema& schema,
                                                                           string* why) {
    auto canon = canonicalize_sparse_instance_(instance);
    string local_why;
    auto sat = run_single_schema_theorem_closure_(canon,
                                                  base_rules,
                                                  current_solver_schema_rules_(),
                                                  retained_first_wave_repair_rules_(),
                                                  retained_second_wave_repair_rules_(),
                                                  &local_why);
    return build_single_schema_proof_certificate_from_saturation_result_(canon, sat, base_rules, schema, why);
}

static bool validate_single_schema_subsumes_local_envelope_instance_(const SparseLcaInstance& instance,
                                                                     const vector<SparseRuleCandidate>& base_rules,
                                                                     const StructuredLocalSchema& schema,
                                                                     EnvelopeSubsumptionStats* stats,
                                                                     string* why) {
    auto canon = canonicalize_sparse_instance_(instance);
    auto solver_schemas = current_solver_schema_rules_();
    string sat_why_single;
    auto single_sat = run_single_schema_theorem_closure_(canon, base_rules, solver_schemas,
                                                         retained_first_wave_repair_rules_(),
                                                         retained_second_wave_repair_rules_(),
                                                         &sat_why_single);
    string sat_why_env;
    auto env_sat = run_bounded_local_horn_envelope_closure_(canon,
                                                            base_rules,
                                                            solver_schemas,
                                                            g_last_bounded_local_horn_rule_universe,
                                                            &sat_why_env);
    if (!single_sat.oracle.satisfiable && !env_sat.oracle.satisfiable) {
        if (why) *why = "";
        return true;
    }
    if (stats) {
        ++stats->instances_checked;
        stats->envelope_derived_pairs += env_sat.closure_pairwise_lca.size();
    }
    auto fail = [&](const string& msg) -> bool {
        if (stats) {
            ++stats->full_instance_fail;
            stats->uncertified_pairs += env_sat.closure_pairwise_lca.size();
        }
        if (why) *why = msg;
        return false;
    };
    if (single_sat.oracle.satisfiable != env_sat.oracle.satisfiable) {
        return fail("satisfiable mismatch on instance " + sparse_instance_to_string_(canon));
    }
    if (single_sat.closure_pairwise_lca != env_sat.closure_pairwise_lca ||
        sparse_constraint_vec_to_string_(single_sat.missing_forced_pairs) != sparse_constraint_vec_to_string_(env_sat.missing_forced_pairs) ||
        sparse_constraint_vec_to_string_(single_sat.extra_derived_pairs) != sparse_constraint_vec_to_string_(env_sat.extra_derived_pairs)) {
        return fail("extensional mismatch on instance " + sparse_instance_to_string_(canon)
                    + "\n[single]\n" + solver_saturation_result_to_string_(single_sat)
                    + "\n[envelope]\n" + solver_saturation_result_to_string_(env_sat));
    }
    string cert_why;
    auto cert = build_single_schema_proof_certificate_from_saturation_result_(canon, single_sat, base_rules, schema, &cert_why);
    if (!cert.complete) {
        return fail("proof certificate incomplete on instance " + sparse_instance_to_string_(canon) + " why=" + cert_why);
    }
    string replay_why;
    if (!validate_single_schema_proof_certificate_replay_(cert, base_rules, schema, &replay_why)) {
        return fail("proof replay invalid on instance " + sparse_instance_to_string_(canon) + " why=" + replay_why);
    }
    if (cert.final_pairwise_lca != env_sat.closure_pairwise_lca) {
        return fail("certificate final table mismatch on instance " + sparse_instance_to_string_(canon));
    }
    if (stats) {
        ++stats->full_instance_pass;
        stats->schema_certified_pairs += env_sat.closure_pairwise_lca.size();
        stats->max_certificate_steps = max(stats->max_certificate_steps, cert.steps.size());
    }
    if (why) *why = "";
    return true;
}

static SparseLcaInstance minimize_envelope_only_counterexample_(const SparseLcaInstance& instance,
                                                                const vector<SparseRuleCandidate>& base_rules,
                                                                const StructuredLocalSchema& schema,
                                                                string* why) {
    SparseLcaInstance best = canonicalize_sparse_instance_(instance);
    string local_why;
    EnvelopeSubsumptionStats dummy;
    if (validate_single_schema_subsumes_local_envelope_instance_(best, base_rules, schema, &dummy, &local_why)) {
        if (why) *why = "instance already subsumed";
        return SparseLcaInstance{};
    }
    bool changed = true;
    while (changed) {
        changed = false;
        auto current = best.constraints;
        for (size_t i = 0; i < current.size(); ++i) {
            SparseLcaInstance cand = best;
            cand.constraints.erase(cand.constraints.begin() + i);
            cand = canonicalize_sparse_instance_(cand);
            EnvelopeSubsumptionStats local_stats;
            string cand_why;
            if (!validate_single_schema_subsumes_local_envelope_instance_(cand, base_rules, schema, &local_stats, &cand_why)) {
                best = cand;
                changed = true;
                break;
            }
        }
    }
    if (why) *why = "";
    return best;
}

static string canonical_envelope_only_counterexample_fingerprint_(const SparseLcaInstance& instance) {
    return canonical_sparse_instance_fingerprint_(canonicalize_sparse_instance_(instance));
}

static bool scan_single_schema_subsumes_local_envelope_exhaustive_n5_(const vector<SparseRuleCandidate>& base_rules,
                                                                      const StructuredLocalSchema& schema,
                                                                      EnvelopeSubsumptionStats* stats,
                                                                      SparseLcaInstance* first_failure,
                                                                      string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(5);
    EnvelopeSubsumptionStats local;
    local.n = 5;
    SparseLcaInstance local_first_failure;
    bool have_failure = false;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("single_schema_subsumes_n5", progress_idx, enum_res.canonical_instances.size());
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        string local_why;
        if (!validate_single_schema_subsumes_local_envelope_instance_(inst, base_rules, schema, &local, &local_why)) {
            if (!have_failure) {
                local_first_failure = inst;
                have_failure = true;
                local.why = local_why;
            }
        }
    }
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = minimize_envelope_only_counterexample_(local_first_failure, base_rules, schema, nullptr);
    if (why) *why = have_failure ? local.why : string();
    return !have_failure;
}

static bool single_schema_proof_certificate_has_conclusion_(const SingleSchemaProofCertificate& cert,
                                                                 const SparseLcaConstraint& conclusion,
                                                                 size_t* step_index) {
    auto norm = normalize_sparse_constraint_(conclusion);
    for (size_t i = 0; i < cert.steps.size(); ++i) {
        if (same_sparse_constraint_(normalize_sparse_constraint_(cert.steps[i].conclusion), norm)) {
            if (step_index) *step_index = i;
            return true;
        }
    }
    return false;
}

static bool scan_single_schema_subsumes_local_envelope_bounded_exact_exact_k_(int n,
                                                                               int exact_constraints,
                                                                               const vector<SparseRuleCandidate>& base_rules,
                                                                               const StructuredLocalSchema& schema,
                                                                               EnvelopeSubsumptionStats* stats,
                                                                               SparseLcaInstance* first_failure,
                                                                               string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_exactly_k_constraints_(n, exact_constraints);
    EnvelopeSubsumptionStats local;
    local.n = n;
    SparseLcaInstance local_first_failure;
    bool have_failure = false;
    size_t progress_idx = 0;
    string progress_tag = string("single_schema_subsumes_n") + to_string(n) + string("_exactc") + to_string(exact_constraints);
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_(progress_tag.c_str(), progress_idx, enum_res.canonical_instances.size());
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        string local_why;
        if (!validate_single_schema_subsumes_local_envelope_instance_(inst, base_rules, schema, &local, &local_why)) {
            if (!have_failure) {
                local_first_failure = inst;
                have_failure = true;
                local.why = local_why;
            }
        }
    }
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = minimize_envelope_only_counterexample_(local_first_failure, base_rules, schema, nullptr);
    if (why) *why = have_failure ? local.why : string();
    return !have_failure;
}

