static bool scan_envelope_rule_elimination_bounded_exact_exact_k_(int n,
                                                           int exact_constraints,
                                                           const vector<SparseRuleCandidate>& envelope_rules,
                                                           const vector<SparseRuleCandidate>& base_rules,
                                                           const StructuredLocalSchema& schema,
                                                           EnvelopeRuleEliminationStats* stats,
                                                           vector<EnvelopeRuleEliminationCertificate>* certs,
                                                           string* why) {
    vector<EnvelopeRuleEliminationCertificate> local_certs;
    string local_why;
    bool ok = validate_envelope_rule_elimination_on_exact_constraint_size_(envelope_rules,
                                                                           base_rules,
                                                                           schema,
                                                                           n,
                                                                           exact_constraints,
                                                                           &local_certs,
                                                                           &local_why);
    if (certs) *certs = local_certs;
    if (stats) *stats = build_envelope_rule_elimination_stats_(n, exact_constraints, local_certs, true, local_why);
    if (why) *why = local_why;
    return ok;
}

static bool scan_envelope_rule_elimination_bounded_exact_n7_constraint3_(const vector<SparseRuleCandidate>& envelope_rules,
                                                                         const vector<SparseRuleCandidate>& base_rules,
                                                                         const StructuredLocalSchema& schema,
                                                                         EnvelopeRuleEliminationStats* stats,
                                                                         vector<EnvelopeRuleEliminationCertificate>* certs,
                                                                         string* why) {
    vector<EnvelopeRuleEliminationCertificate> combined;
    bool ok = true;
    string fail_why;
    for (int exact_k = 0; exact_k <= kSingleSchemaBoundedExactN7Constraint3; ++exact_k) {
#ifdef LOCAL_TEST
        cerr << "stage: envelope elimination n7 k" << exact_k << "\n";
#endif
        EnvelopeRuleEliminationStats local_stats;
        vector<EnvelopeRuleEliminationCertificate> local_certs;
        string local_why;
        bool local_ok = scan_envelope_rule_elimination_bounded_exact_exact_k_(7,
                                                                              exact_k,
                                                                              envelope_rules,
                                                                              base_rules,
                                                                              schema,
                                                                              &local_stats,
                                                                              &local_certs,
                                                                              &local_why);
        combined = merge_envelope_rule_elimination_certificates_(combined, local_certs);
        if (!local_ok && fail_why.empty()) {
            fail_why = local_why;
            ok = false;
        }
    }
    auto final_certs = sort_envelope_rule_elimination_certificates_(combined);
    if (certs) *certs = final_certs;
    string final_why = ok ? string("all tested envelope rule firings certified") : fail_why;
    if (stats) *stats = build_envelope_rule_elimination_stats_(7,
                                                               kSingleSchemaBoundedExactN7Constraint3,
                                                               final_certs,
                                                               true,
                                                               final_why);
    if (why) *why = final_why;
    return ok;
}

static EnvelopeRuleEliminationCertificate build_envelope_rule_elimination_certificate_(const SparseRuleCandidate& envelope_rule,
                                                                                       const vector<SparseRuleCandidate>& base_rules,
                                                                                       const StructuredLocalSchema& schema,
                                                                                       int n,
                                                                                       int max_constraints,
                                                                                       string* why) {
    vector<EnvelopeRuleEliminationCertificate> certs;
    validate_envelope_rule_elimination_on_tested_domains_({envelope_rule}, base_rules, schema, n, max_constraints, &certs, why);
    if (!certs.empty()) return certs.front();
    EnvelopeRuleEliminationCertificate empty;
    empty.envelope_rule = canonicalize_rule_candidate_(envelope_rule);
    empty.envelope_rule_fingerprint = empty.envelope_rule.fingerprint;
    return empty;
}

static string build_single_schema_proof_ledger_(const EnvelopeSubsumptionStats& exact_n5,
                                                const EnvelopeSubsumptionStats& bounded_n6_c4,
                                                const ProofKernelContinuationStats* bounded_n6_c5,
                                                const ProofKernelContinuationStats* bounded_n7_c3,
                                                const vector<EnvelopeRuleEliminationCertificate>& certs,
                                                const SparseLcaInstance& counterexample) {
    ostringstream oss;
    oss << "singleSchema=" << structured_local_schema_to_string_(g_last_single_structured_local_schema) << "\n";
    oss << "reducedLocalEnvelopeFingerprint=" << reduced_local_envelope_rule_universe_fingerprint_() << "\n";
    oss << "exactN5Subsumption=" << envelope_subsumption_stats_to_string_(exact_n5) << "\n";
    oss << "boundedN6C4Subsumption=" << envelope_subsumption_stats_to_string_(bounded_n6_c4) << "\n";
    if (bounded_n6_c5) oss << "boundedN6C5Continuation=" << proof_kernel_continuation_stats_to_string_(*bounded_n6_c5) << "\n";
    if (bounded_n7_c3) oss << "boundedN7C3Continuation=" << proof_kernel_continuation_stats_to_string_(*bounded_n7_c3) << "\n";
    if (g_last_envelope_rule_elimination_n5_stats.rules_in_universe) oss << "envelopeEliminationN5=" << envelope_rule_elimination_stats_to_string_(g_last_envelope_rule_elimination_n5_stats) << "\n";
    if (g_last_envelope_rule_elimination_n6_c4_stats.rules_in_universe) oss << "envelopeEliminationN6C4=" << envelope_rule_elimination_stats_to_string_(g_last_envelope_rule_elimination_n6_c4_stats) << "\n";
    if (g_last_envelope_rule_elimination_n6_c5_stats.rules_in_universe) oss << "envelopeEliminationN6C5=" << envelope_rule_elimination_stats_to_string_(g_last_envelope_rule_elimination_n6_c5_stats) << "\n";
    if (g_last_envelope_rule_elimination_n7_c3_stats.rules_in_universe) oss << "envelopeEliminationN7C3=" << envelope_rule_elimination_stats_to_string_(g_last_envelope_rule_elimination_n7_c3_stats) << "\n";
    oss << "envelopeRuleEliminationCount=" << certs.size() << "\n";
    for (const auto& cert : certs) oss << "envelopeRuleElimination=" << envelope_rule_elimination_certificate_to_string_(cert) << "\n";
    if (counterexample.n > 0) {
        oss << "envelopeOnlyCounterexample=" << sparse_instance_to_string_(counterexample) << "\n";
        oss << "counterexampleFingerprint=" << canonical_envelope_only_counterexample_fingerprint_(counterexample) << "\n";
    } else {
        oss << "envelopeOnlyCounterexample=none\n";
    }
    return oss.str();
}

static string classify_single_schema_proof_kernel_status_(const EnvelopeSubsumptionStats& exact_n5,
                                                          const EnvelopeSubsumptionStats& bounded_n6_c4,
                                                          const ProofKernelContinuationStats* bounded_n6_c5,
                                                          const ProofKernelContinuationStats* bounded_n7_c3,
                                                          const EnvelopeRuleEliminationStats* elim_n6_c5,
                                                          const EnvelopeRuleEliminationStats* elim_n7_c3,
                                                          const SparseLcaInstance& counterexample) {
    bool exact_attempted = exact_n5.instances_checked > 0;
    bool bounded_c4_attempted = bounded_n6_c4.instances_checked > 0;
    bool bounded_c5_attempted = bounded_n6_c5 && bounded_n6_c5->completed && bounded_n6_c5->instances_checked > 0;
    bool bounded_n7_attempted = bounded_n7_c3 && bounded_n7_c3->completed && bounded_n7_c3->instances_checked > 0;
    bool n6_elim_supported = elim_n6_c5 && elim_n6_c5->completed && elim_n6_c5->rules_in_universe > 0 && elim_n6_c5->uncertified_hits == 0 && elim_n6_c5->failed_rules == 0;
    bool n7_elim_supported = elim_n7_c3 && elim_n7_c3->completed && elim_n7_c3->rules_in_universe > 0 && elim_n7_c3->uncertified_hits == 0 && elim_n7_c3->failed_rules == 0;

    if (exact_attempted && exact_n5.full_instance_fail > 0) return "single_schema_proof_kernel_counterexample_found";
    if (bounded_c4_attempted && bounded_n6_c4.full_instance_fail > 0) return "single_schema_extensional_but_not_proof_kernel";
    if (bounded_c5_attempted && bounded_n6_c5->full_instance_fail > 0) return "single_schema_extensional_but_not_proof_kernel";
    if (bounded_n7_attempted && bounded_n7_c3->full_instance_fail > 0) return "single_schema_extensional_but_not_proof_kernel";
    if (counterexample.n > 0) return "single_schema_extensional_but_not_proof_kernel";
    if (bounded_n7_attempted && n7_elim_supported) return "single_schema_extended_exact_elimination_supported";
    if (bounded_n7_attempted) return "single_schema_n7_c3_proof_kernel_supported";
    if (n6_elim_supported) return "single_schema_rule_elimination_supported";
    if (bounded_c5_attempted) return "single_schema_n6_c5_proof_kernel_supported";
    if (bounded_c4_attempted) return "single_schema_bounded_n6_proof_kernel_supported";
    if (exact_attempted) return "single_schema_n5_proof_kernel_supported";
    return "mixed_frontier_more_evidence_needed";
}


static bool proof_step_is_assumption_(const SingleSchemaDerivationStep& step) {
    return step.rule_kind == "seed";
}

static SparseLcaConstraint proof_motif_atom_to_constraint_(const ProofMotifAtom& a) {
    return normalize_sparse_constraint_({a.u, a.v, a.w});
}

static ProofMotifAtom sparse_constraint_to_proof_motif_atom_(const SparseLcaConstraint& c) {
    auto t = normalize_sparse_constraint_(c);
    return {t.u, t.v, t.w};
}

static SparseRuleCandidate proof_motif_to_rule_candidate_(const ProofMotif& motif) {
    SparseRuleCandidate raw;
    raw.n = motif.num_symbols;
    for (const auto& p : motif.premises) raw.antecedents.push_back(proof_motif_atom_to_constraint_(p));
    raw.consequent = proof_motif_atom_to_constraint_(motif.conclusion);
    raw.support_count = motif.support;
    return canonicalize_rule_candidate_(raw);
}

static int proof_motif_support_size_(const ProofMotif& motif) {
    return proof_motif_to_rule_candidate_(motif).n;
}

static ProofMotif generalize_derivation_step_to_proof_motif_(const SingleSchemaDerivationStep& step) {
    SparseRuleCandidate raw;
    for (const auto& p : step.premises) raw.antecedents.push_back(normalize_sparse_constraint_(p));
    raw.consequent = normalize_sparse_constraint_(step.conclusion);
    int maxv = 1;
    for (const auto& p : raw.antecedents) maxv = max({maxv, p.u, p.v, p.w});
    maxv = max({maxv, raw.consequent.u, raw.consequent.v, raw.consequent.w});
    raw.n = maxv;
    auto can = canonicalize_rule_candidate_(raw);
    ProofMotif out;
    out.num_symbols = can.n;
    out.fingerprint = can.fingerprint;
    out.human_readable = sparse_rule_candidate_to_string_(can);
    for (const auto& p : can.antecedents) out.premises.push_back(sparse_constraint_to_proof_motif_atom_(p));
    out.conclusion = sparse_constraint_to_proof_motif_atom_(can.consequent);
    return out;
}

static string canonical_proof_motif_fingerprint_(const ProofMotif& motif) {
    return proof_motif_to_rule_candidate_(motif).fingerprint;
}

static string proof_motif_human_readable_(const ProofMotif& motif) {
    return sparse_rule_candidate_to_string_(proof_motif_to_rule_candidate_(motif));
}

static bool validate_proof_motif_local_exact_(const ProofMotif& motif, string* why);
static bool validate_proof_motif_plus_one_exact_(const ProofMotif& motif, string* why);
static string proof_motif_basis_stats_to_string_(const ProofMotifBasisStats& s);

static string proof_step_occurrence_fingerprint_(const ProofStepOccurrence& occ) {
    return occ.domain_tag + "|" + occ.instance_fingerprint + "|" + to_string(occ.certificate_index) + "|" + to_string(occ.step_index);
}

static string proof_step_occurrence_human_readable_(const ProofStepOccurrence& occ) {
    ostringstream oss;
    oss << occ.domain_tag << " inst=" << occ.instance_fingerprint
        << " cert=" << occ.certificate_index
        << " step=" << occ.step_index
        << " motif=" << occ.motif_fingerprint;
    return oss.str();
}

static vector<ProofStepOccurrence> build_proof_step_occurrence_universe_(const vector<SingleSchemaProofCertificate>& certs) {
    vector<ProofStepOccurrence> out;
    for (size_t cert_idx = 0; cert_idx < certs.size(); ++cert_idx) {
        const auto& cert = certs[cert_idx];
        string inst_fp = canonical_sparse_instance_fingerprint_(canonicalize_sparse_instance_(cert.instance));
        string domain_tag = string("n") + to_string(cert.instance.n) + string("_m") + to_string(cert.instance.constraints.size());
        for (size_t step_idx = 0; step_idx < cert.steps.size(); ++step_idx) {
            const auto& step = cert.steps[step_idx];
            if (proof_step_is_assumption_(step)) continue;
            auto motif = generalize_derivation_step_to_proof_motif_(step);
            ProofStepOccurrence occ;
            occ.domain_tag = domain_tag;
            occ.instance_fingerprint = inst_fp;
            occ.certificate_index = cert_idx;
            occ.step_index = step_idx;
            occ.motif_fingerprint = motif.fingerprint;
            out.push_back(std::move(occ));
        }
    }
    return out;
}

static vector<string> build_proof_motif_coverage_signature_(const string& motif_fingerprint,
                                                             const vector<ProofStepOccurrence>& occs,
                                                             const vector<SingleSchemaProofCertificate>& certs) {
    (void)certs;
    vector<string> out;
    for (const auto& occ : occs) {
        if (occ.motif_fingerprint == motif_fingerprint) out.push_back(proof_step_occurrence_fingerprint_(occ));
    }
    return out;
}

static unordered_map<string, vector<string>> build_proof_motif_coverage_index_(const vector<ProofMotifFamily>& families,
                                                                                const vector<ProofStepOccurrence>& occs,
                                                                                const vector<SingleSchemaProofCertificate>& certs) {
    unordered_map<string, vector<string>> out;
    out.reserve(families.size() * 2 + 1);
    for (const auto& fam : families) {
        out.emplace(fam.fingerprint, build_proof_motif_coverage_signature_(fam.fingerprint, occs, certs));
    }
    return out;
}

static string proof_step_occurrence_signature_key_(const vector<string>& sig) {
    string out;
    for (const auto& x : sig) {
        out += x;
        out.push_back('\n');
    }
    return out;
}

static vector<ProofMotifFamily> prune_equivalent_proof_motif_families_(const vector<ProofMotifFamily>& families,
                                                                        const vector<ProofStepOccurrence>& occs,
                                                                        ProofMotifBasisSearchStats* stats,
                                                                        string* why) {
    auto coverage = build_proof_motif_coverage_index_(families, occs, {});
    unordered_map<string, ProofMotifFamily> rep_by_sig;
    size_t duplicate_removed = 0;
    size_t zero_removed = 0;
    for (const auto& fam : families) {
        auto it_cov = coverage.find(fam.fingerprint);
        vector<string> sig = it_cov == coverage.end() ? vector<string>() : it_cov->second;
        if (sig.empty()) {
            ++zero_removed;
            continue;
        }
        string key = proof_step_occurrence_signature_key_(sig);
        auto it = rep_by_sig.find(key);
        if (it == rep_by_sig.end()) {
            rep_by_sig.emplace(key, fam);
        } else {
            ++duplicate_removed;
            if (fam.cumulative_support > it->second.cumulative_support ||
                (fam.cumulative_support == it->second.cumulative_support && fam.fingerprint < it->second.fingerprint)) {
                it->second = fam;
            }
        }
    }
    vector<ProofMotifFamily> out;
    out.reserve(rep_by_sig.size());
    for (auto& kv : rep_by_sig) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.cumulative_support != b.cumulative_support) return a.cumulative_support > b.cumulative_support;
        return a.fingerprint < b.fingerprint;
    });
    if (stats) {
        stats->family_count = families.size();
        stats->occurrence_universe_size = occs.size();
        stats->duplicate_coverage_families_removed = duplicate_removed;
        stats->zero_unique_coverage_families_removed = zero_removed;
    }
    if (why) *why = "equivalent pruning duplicates=" + to_string(duplicate_removed) + " zero=" + to_string(zero_removed);
    return out;
}

static vector<ProofMotif> build_irredundant_proof_motif_basis_(const vector<ProofMotifFamily>& families,
                                                                const vector<ProofStepOccurrence>& occs,
                                                                ProofMotifBasisSearchStats* stats,
                                                                vector<ProofMotifIrreducibilityWitness>* witnesses,
                                                                string* why) {
    auto coverage = build_proof_motif_coverage_index_(families, occs, {});
    unordered_map<string, vector<string>> keep_cov = coverage;
    unordered_map<string, int> occ_count;
    for (const auto& kv : coverage) {
        for (const auto& occ_fp : kv.second) ++occ_count[occ_fp];
    }
    vector<ProofMotifFamily> ordered = families;
    sort(ordered.begin(), ordered.end(), [&](const auto& a, const auto& b) {
        size_t sa = coverage[a.fingerprint].size();
        size_t sb = coverage[b.fingerprint].size();
        if (sa != sb) return sa < sb;
        return a.fingerprint < b.fingerprint;
    });
    unordered_set<string> removed;
    size_t zero_unique_removed = 0;
    for (const auto& fam : ordered) {
        const auto& sig = coverage[fam.fingerprint];
        bool removable = !sig.empty();
        for (const auto& occ_fp : sig) {
            auto it = occ_count.find(occ_fp);
            if (it == occ_count.end() || it->second <= 1) {
                removable = false;
                break;
            }
        }
        if (removable) {
            removed.insert(fam.fingerprint);
            ++zero_unique_removed;
            for (const auto& occ_fp : sig) --occ_count[occ_fp];
        }
    }
    vector<ProofMotif> basis;
    for (const auto& fam : families) {
        if (!removed.count(fam.fingerprint)) basis.push_back(fam.representative);
    }
    if (stats) {
        stats->irredundant_basis_size = basis.size();
        stats->zero_unique_coverage_families_removed += zero_unique_removed;
    }
    if (witnesses) {
        witnesses->clear();
        unordered_set<string> basis_fp;
        for (const auto& m : basis) basis_fp.insert(m.fingerprint);
        unordered_map<string, int> final_count;
        for (const auto& fam : families) {
            if (!basis_fp.count(fam.fingerprint)) continue;
            for (const auto& occ_fp : coverage[fam.fingerprint]) ++final_count[occ_fp];
        }
        unordered_map<string, ProofStepOccurrence> occ_by_fp;
        for (const auto& occ : occs) occ_by_fp.emplace(proof_step_occurrence_fingerprint_(occ), occ);
        for (const auto& motif : basis) {
            ProofMotifIrreducibilityWitness wit;
            wit.dropped_motif_fingerprint = motif.fingerprint;
            for (const auto& occ_fp : coverage[motif.fingerprint]) {
                if (final_count[occ_fp] == 1) {
                    wit.uncovered_occurrence = occ_by_fp[occ_fp];
                    wit.why = "dropping motif leaves uncovered tested occurrence";
                    break;
                }
            }
            if (!wit.why.empty()) witnesses->push_back(std::move(wit));
        }
    }
    if (why) *why = "irredundant basis size=" + to_string(basis.size());
    return basis;
}

static vector<ProofMotif> search_minimal_proof_motif_basis_exact_(const vector<ProofMotifFamily>& families,
                                                                   const vector<ProofStepOccurrence>& occs,
                                                                   ProofMotifBasisSearchStats* stats,
                                                                   string* why) {
    if (stats) stats->exact_search_attempted = true;
    const size_t kHardLimit = 24;
    if (families.size() > kHardLimit) {
        if (stats) stats->exact_search_completed = false;
        if (why) *why = "exact basis search skipped because candidate count " + to_string(families.size()) + " > " + to_string(kHardLimit);
        return {};
    }
    vector<string> universe;
    universe.reserve(occs.size());
    for (const auto& occ : occs) universe.push_back(proof_step_occurrence_fingerprint_(occ));
    sort(universe.begin(), universe.end());
    universe.erase(unique(universe.begin(), universe.end()), universe.end());
    unordered_map<string, int> idx;
    for (size_t i = 0; i < universe.size(); ++i) idx[universe[i]] = (int)i;
    auto coverage_str = build_proof_motif_coverage_index_(families, occs, {});
    vector<vector<uint64_t>> masks(families.size(), vector<uint64_t>((universe.size() + 63) / 64, 0));
    for (size_t i = 0; i < families.size(); ++i) {
        for (const auto& occ_fp : coverage_str[families[i].fingerprint]) {
            int j = idx[occ_fp];
            masks[i][j >> 6] |= (1ULL << (j & 63));
        }
    }
    vector<uint64_t> full((universe.size() + 63) / 64, ~0ULL);
    if (!universe.empty() && (universe.size() & 63)) full.back() = (1ULL << (universe.size() & 63)) - 1ULL;
    vector<int> order(families.size());
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        size_t ca = coverage_str[families[a].fingerprint].size();
        size_t cb = coverage_str[families[b].fingerprint].size();
        if (ca != cb) return ca > cb;
        return families[a].fingerprint < families[b].fingerprint;
    });
    vector<int> best;
    function<void(size_t, vector<uint64_t>&, vector<int>&)> dfs = [&](size_t pos, vector<uint64_t>& covered, vector<int>& chosen) {
        if (!best.empty() && chosen.size() >= best.size()) return;
        bool done = true;
        for (size_t i = 0; i < full.size(); ++i) if ((covered[i] & full[i]) != full[i]) { done = false; break; }
        if (done) { best = chosen; return; }
        if (pos >= order.size()) return;
        int id = order[pos];
        auto next = covered;
        for (size_t i = 0; i < next.size(); ++i) next[i] |= masks[id][i];
        chosen.push_back(id);
        dfs(pos + 1, next, chosen);
        chosen.pop_back();
        dfs(pos + 1, covered, chosen);
    };
    vector<uint64_t> init(full.size(), 0ULL);
    vector<int> chosen;
    dfs(0, init, chosen);
    if (stats) stats->exact_search_completed = !best.empty();
    vector<ProofMotif> out;
    for (int id : best) out.push_back(families[id].representative);
    if (why) *why = best.empty() ? "exact basis search found no complete basis" : "exact basis size=" + to_string(best.size());
    return out;
}

static vector<ProofMotif> search_minimal_proof_motif_basis_hybrid_(const vector<ProofMotifFamily>& families,
                                                                    const vector<ProofStepOccurrence>& occs,
                                                                    ProofMotifBasisSearchStats* stats,
                                                                    string* why) {
    auto coverage = build_proof_motif_coverage_index_(families, occs, {});
    unordered_set<string> uncovered;
    for (const auto& occ : occs) uncovered.insert(proof_step_occurrence_fingerprint_(occ));
    vector<ProofMotif> basis;
    vector<ProofMotifFamily> rem = families;
    while (!uncovered.empty()) {
        size_t best_idx = rem.size();
        size_t best_gain = 0;
        for (size_t i = 0; i < rem.size(); ++i) {
            size_t gain = 0;
            for (const auto& occ_fp : coverage[rem[i].fingerprint]) if (uncovered.count(occ_fp)) ++gain;
            if (gain > best_gain || (gain == best_gain && best_idx == rem.size()) ||
                (gain == best_gain && best_idx < rem.size() && rem[i].fingerprint < rem[best_idx].fingerprint)) {
                best_gain = gain;
                best_idx = i;
            }
        }
        if (best_idx == rem.size() || best_gain == 0) break;
        basis.push_back(rem[best_idx].representative);
        for (const auto& occ_fp : coverage[rem[best_idx].fingerprint]) uncovered.erase(occ_fp);
        rem.erase(rem.begin() + best_idx);
    }
    unordered_set<string> basis_fp;
    for (const auto& m : basis) basis_fp.insert(m.fingerprint);
    unordered_map<string, int> count;
    for (const auto& m : basis) for (const auto& occ_fp : coverage[m.fingerprint]) ++count[occ_fp];
    vector<ProofMotif> pruned;
    for (const auto& m : basis) {
        bool removable = true;
        for (const auto& occ_fp : coverage[m.fingerprint]) if (count[occ_fp] <= 1) { removable = false; break; }
        if (removable) {
            for (const auto& occ_fp : coverage[m.fingerprint]) --count[occ_fp];
        } else pruned.push_back(m);
    }
    if (stats) stats->greedy_basis_size = pruned.size();
    if (why) *why = uncovered.empty() ? "hybrid basis size=" + to_string(pruned.size()) : "hybrid basis left uncovered occurrences=" + to_string(uncovered.size());
    return pruned;
}

static bool validate_proof_motif_basis_local_exact_(const vector<ProofMotif>& basis,
                                                     size_t* pass_count,
                                                     string* why) {
    size_t pass = 0;
    for (const auto& m : basis) {
        string local_why;
        if (validate_proof_motif_local_exact_(m, &local_why)) ++pass;
    }
    if (pass_count) *pass_count = pass;
    if (why) *why = "basis local exact pass=" + to_string(pass) + "/" + to_string(basis.size());
    return pass == basis.size();
}

static bool validate_proof_motif_basis_plus_one_exact_(const vector<ProofMotif>& basis,
                                                        size_t* pass_count,
                                                        size_t* attempt_count,
                                                        string* why) {
    size_t pass = 0;
    size_t attempt = min<size_t>(basis.size(), 12);
    for (size_t i = 0; i < attempt; ++i) {
        string local_why;
        if (validate_proof_motif_plus_one_exact_(basis[i], &local_why)) ++pass;
    }
    if (pass_count) *pass_count = pass;
    if (attempt_count) *attempt_count = attempt;
    if (why) *why = "basis plus-one pass=" + to_string(pass) + "/" + to_string(attempt) + " attempted";
    return pass == attempt;
}

static vector<ProofMotifIrreducibilityWitness> find_proof_motif_irreducibility_witnesses_(const vector<ProofMotif>& basis,
                                                                                            const vector<ProofStepOccurrence>& occs,
                                                                                            string* why) {
    vector<ProofMotifIrreducibilityWitness> out;
    vector<ProofMotifFamily> pseudo;
    pseudo.reserve(basis.size());
    for (const auto& m : basis) {
        ProofMotifFamily fam;
        fam.fingerprint = m.fingerprint;
        fam.representative = m;
        pseudo.push_back(fam);
    }
    ProofMotifBasisSearchStats dummy;
    auto basis2 = build_irredundant_proof_motif_basis_(pseudo, occs, &dummy, &out, why);
    (void)basis2;
    return out;
}

static string canonical_private_witness_fingerprint_(const ProofMotifPrivateWitness& witness) {
    return witness.motif_fingerprint + "|" + proof_step_occurrence_fingerprint_(witness.occurrence);
}

static string proof_motif_private_witness_human_readable_(const ProofMotifPrivateWitness& witness) {
    return string("motif=") + witness.motif_fingerprint + string(" occ=") + proof_step_occurrence_human_readable_(witness.occurrence);
}

static vector<ProofMotifPrivateWitness> build_proof_motif_private_witnesses_(const vector<ProofMotifFamily>& families,
                                                                              const vector<ProofStepOccurrence>& occs,
                                                                              const vector<SingleSchemaProofCertificate>& certs,
                                                                              string* why) {
    auto coverage = build_proof_motif_coverage_index_(families, occs, certs);
    unordered_map<string, int> occ_count;
    unordered_map<string, ProofStepOccurrence> occ_info;
    for (const auto& occ : occs) {
        string fp = proof_step_occurrence_fingerprint_(occ);
        occ_info.emplace(fp, occ);
    }
    for (const auto& kv : coverage) {
        for (const auto& occ_fp : kv.second) ++occ_count[occ_fp];
    }
    vector<ProofMotifPrivateWitness> out;
    out.reserve(families.size());
    for (const auto& fam : families) {
        auto it_cov = coverage.find(fam.fingerprint);
        if (it_cov == coverage.end()) continue;
        for (const auto& occ_fp : it_cov->second) {
            auto itc = occ_count.find(occ_fp);
            if (itc != occ_count.end() && itc->second == 1) {
                ProofMotifPrivateWitness witness;
                witness.motif_fingerprint = fam.fingerprint;
                auto ito = occ_info.find(occ_fp);
                if (ito != occ_info.end()) witness.occurrence = ito->second;
                witness.why = "private coverage witness";
                out.push_back(std::move(witness));
                break;
            }
        }
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.motif_fingerprint != b.motif_fingerprint) return a.motif_fingerprint < b.motif_fingerprint;
        return proof_step_occurrence_fingerprint_(a.occurrence) < proof_step_occurrence_fingerprint_(b.occurrence);
    });
    if (why) *why = "private witness count=" + to_string(out.size());
    return out;
}

static ProofMotifLowerBoundCertificate build_proof_motif_lower_bound_certificate_(const vector<ProofMotifFamily>& families,
                                                                                   const vector<ProofMotifPrivateWitness>& private_witnesses,
                                                                                   size_t current_best_upper_bound,
                                                                                   string* why) {
    set<string> private_fp;
    for (const auto& w : private_witnesses) private_fp.insert(w.motif_fingerprint);
    ProofMotifLowerBoundCertificate cert;
    cert.lower_bound = private_fp.size();
    cert.upper_bound = current_best_upper_bound;
    cert.private_witness_count = private_witnesses.size();
    cert.unresolved_family_count = families.size() >= private_fp.size() ? families.size() - private_fp.size() : 0;
    cert.exact_minimality_verified = (cert.upper_bound > 0 && cert.lower_bound == cert.upper_bound);
    cert.why = string("privateWitnessFamilies=") + to_string(private_fp.size());
    if (why) *why = cert.why;
    return cert;
}

static string proof_motif_lower_bound_certificate_to_string_(const ProofMotifLowerBoundCertificate& cert) {
    ostringstream oss;
    oss << "lowerBound=" << cert.lower_bound
        << " upperBound=" << cert.upper_bound
        << " privateWitnessCount=" << cert.private_witness_count
        << " unresolvedFamilyCount=" << cert.unresolved_family_count
        << " exactMinimalityVerified=" << (cert.exact_minimality_verified ? "true" : "false");
    if (!cert.why.empty()) oss << " why=" << cert.why;
    return oss.str();
}

static vector<ProofMotifFamily> extract_unresolved_proof_motif_core_(const vector<ProofMotifFamily>& families,
                                                                      const vector<ProofMotifPrivateWitness>& private_witnesses,
                                                                      string* why) {
    set<string> forced;
    for (const auto& w : private_witnesses) forced.insert(w.motif_fingerprint);
    vector<ProofMotifFamily> out;
    for (const auto& fam : families) if (!forced.count(fam.fingerprint)) out.push_back(fam);
    if (why) *why = "unresolved core size=" + to_string(out.size());
    return out;
}

static vector<ProofStepOccurrence> extract_uncovered_occurrences_after_basis_(const vector<ProofStepOccurrence>& occs,
                                                                               const vector<ProofMotif>& basis) {
    set<string> fp;
    for (const auto& m : basis) fp.insert(m.fingerprint);
    vector<ProofStepOccurrence> out;
    out.reserve(occs.size());
    for (const auto& occ : occs) if (!fp.count(occ.motif_fingerprint)) out.push_back(occ);
    return out;
}

static ProofMotifBasisSearchStats build_unresolved_core_stats_(const vector<ProofMotifFamily>& unresolved,
                                                                const vector<ProofStepOccurrence>& unresolved_occs) {
    ProofMotifBasisSearchStats s;
    s.family_count = unresolved.size();
    s.occurrence_universe_size = unresolved_occs.size();
    return s;
}

static string classify_proof_motif_minimality_status_(const ProofMotifLowerBoundCertificate& cert,
                                                       const ProofMotifBasisSearchStats& unresolved_core_stats,
                                                       const vector<ProofMotifIrreducibilityWitness>& witnesses,
                                                       string* why) {
    if (cert.exact_minimality_verified) {
        if (why) *why = "private witness lower bound equals best known upper bound";
        return "proof_motif_exact_minimal_basis_supported";
    }
    if (cert.private_witness_count > 0) {
        if (cert.unresolved_family_count == 0 && cert.upper_bound == cert.lower_bound) {
            if (why) *why = "all families forced by private witnesses";
            return "proof_motif_exact_minimal_basis_supported";
        }
        if (why) *why = "private witness lower bound established but gap remains";
        return "proof_motif_private_witness_supported";
    }
    if (!witnesses.empty()) {
        if (why) *why = "irredundibility witnesses exist but no full lower-bound certificate";
        return "proof_motif_irreducible_large_basis";
    }
    if (unresolved_core_stats.family_count > 0) {
        if (why) *why = "minimality gap unresolved";
        return "proof_motif_lower_bound_supported";
    }
    if (why) *why = "minimality analysis not fully completed";
    return "mixed_frontier_more_evidence_needed";
}

static string proof_motif_basis_search_stats_to_string_(const ProofMotifBasisSearchStats& s);

static string build_proof_motif_minimality_ledger_(const ProofMotifLowerBoundCertificate& cert,
                                                    const ProofMotifBasisSearchStats& unresolved_core_stats,
                                                    const vector<ProofMotifPrivateWitness>& private_witnesses,
                                                    const vector<ProofMotifIrreducibilityWitness>& witnesses,
                                                    const string& status) {
    ostringstream oss;
    oss << "lowerBoundCertificate=" << proof_motif_lower_bound_certificate_to_string_(cert) << "\n";
    oss << "unresolvedCoreStats=" << proof_motif_basis_search_stats_to_string_(unresolved_core_stats) << "\n";
    oss << "privateWitnessCount=" << private_witnesses.size() << "\n";
    for (size_t i = 0; i < min<size_t>(private_witnesses.size(), 10); ++i) {
        oss << "privateWitness[" << i << "] " << proof_motif_private_witness_human_readable_(private_witnesses[i]) << "\n";
    }
    oss << "irreducibilityWitnessCount=" << witnesses.size() << "\n";
    oss << "status=" << status << "\n";
    return oss.str();
}

static string proof_motif_basis_search_stats_to_string_(const ProofMotifBasisSearchStats& s) {
    ostringstream oss;
    oss << "familyCount=" << s.family_count
        << " occurrenceUniverseSize=" << s.occurrence_universe_size
        << " duplicateCoverageFamiliesRemoved=" << s.duplicate_coverage_families_removed
        << " zeroUniqueCoverageFamiliesRemoved=" << s.zero_unique_coverage_families_removed
        << " irredundantBasisSize=" << s.irredundant_basis_size
        << " exactSearchAttempted=" << (s.exact_search_attempted ? "true" : "false")
        << " exactSearchCompleted=" << (s.exact_search_completed ? "true" : "false")
        << " greedyBasisSize=" << s.greedy_basis_size
        << " bestKnownBasisSize=" << s.best_known_basis_size;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string classify_proof_motif_basis_status_(const ProofMotifBasisSearchStats& search_stats,
                                                  size_t basis_local_exact_pass_count,
                                                  size_t basis_plus_one_pass_count,
                                                  size_t basis_plus_one_attempt_count,
                                                  const ProofMotifBasisStats& exact_n5,
                                                  const ProofMotifBasisStats& bounded_n6,
                                                  const ProofMotifBasisStats& bounded_n7,
                                                  const vector<ProofMotifIrreducibilityWitness>& witnesses,
                                                  const SingleSchemaProofCertificate& counterexample,
                                                  string* why) {
    if (counterexample.instance.n > 0 || exact_n5.uncovered_steps || bounded_n6.uncovered_steps || bounded_n7.uncovered_steps) {
        if (why) *why = "compressed proof motif basis has uncovered steps or explicit counterexample";
        return "proof_motif_basis_counterexample_found";
    }
    if (search_stats.best_known_basis_size < search_stats.family_count &&
        search_stats.best_known_basis_size > 0) {
        if (basis_plus_one_attempt_count > 0 && basis_plus_one_pass_count == search_stats.best_known_basis_size) {
            if (why) *why = "compressed basis found and plus-one fully passed on basis";
            return "proof_motif_compressed_basis_plus_one_supported";
        }
        if (why) *why = "compressed basis smaller than family count";
        return "proof_motif_compressed_basis_supported";
    }
    if (search_stats.best_known_basis_size == search_stats.family_count && !witnesses.empty()) {
        if (why) *why = "no compression found and irreducibility witnesses exist";
        return "proof_motif_irreducible_large_basis";
    }
    if (search_stats.irredundant_basis_size > 0) {
        if (why) *why = "irredundant basis found";
        return "proof_motif_irredundant_basis_supported";
    }
    if (search_stats.family_count > 0) {
        if (why) *why = "motif compression baseline only";
        return "proof_motif_compression_supported";
    }
    if (why) *why = "proof motif basis search not fully completed";
    return "mixed_frontier_more_evidence_needed";
}

static string build_proof_motif_basis_ledger_(const ProofMotifBasisSearchStats& search_stats,
                                               size_t basis_local_exact_pass_count,
                                               size_t basis_plus_one_pass_count,
                                               size_t basis_plus_one_attempt_count,
                                               const ProofMotifBasisStats& exact_n5,
                                               const ProofMotifBasisStats& bounded_n6,
                                               const ProofMotifBasisStats& bounded_n7,
                                               const ProofMotifBasisStats& env_cover,
                                               const vector<ProofMotifIrreducibilityWitness>& witnesses,
                                               const string& status) {
    ostringstream oss;
    oss << "basisSearch=" << proof_motif_basis_search_stats_to_string_(search_stats) << "\n";
    oss << "basisLocalExactPass=" << basis_local_exact_pass_count << "\n";
    oss << "basisPlusOnePass=" << basis_plus_one_pass_count << "/" << basis_plus_one_attempt_count << "\n";
    oss << "basisExactN5=" << proof_motif_basis_stats_to_string_(exact_n5) << "\n";
    oss << "basisBoundedN6C5=" << proof_motif_basis_stats_to_string_(bounded_n6) << "\n";
    oss << "basisBoundedN7C3=" << proof_motif_basis_stats_to_string_(bounded_n7) << "\n";
    oss << "basisEnvelopeCover=" << proof_motif_basis_stats_to_string_(env_cover) << "\n";
    oss << "irreducibilityWitnessCount=" << witnesses.size() << "\n";
    for (size_t i = 0; i < min<size_t>(witnesses.size(), 10); ++i) {
        oss << "witness[" << i << "] motif=" << witnesses[i].dropped_motif_fingerprint
            << " occ=" << proof_step_occurrence_human_readable_(witnesses[i].uncovered_occurrence)
            << " why=" << witnesses[i].why << "\n";
    }
    oss << "status=" << status << "\n";
    return oss.str();
}



static size_t single_schema_proof_certificate_non_seed_step_count_(const SingleSchemaProofCertificate& cert) {
    size_t out = 0;
    for (const auto& step : cert.steps) if (!proof_step_is_assumption_(step)) ++out;
    return out;
}

static string single_schema_proof_certificate_cache_key_(const SparseLcaInstance& instance) {
    return canonical_sparse_instance_fingerprint_(canonicalize_sparse_instance_(instance));
}

static SingleSchemaProofCertificate cached_single_schema_proof_certificate_(const SparseLcaInstance& instance,
                                                                            const vector<SparseRuleCandidate>& base_rules,
                                                                            const StructuredLocalSchema& schema,
                                                                            bool* cache_hit,
                                                                            string* why) {
    string key = single_schema_proof_certificate_cache_key_(instance);
    auto it = g_single_schema_proof_certificate_cache.find(key);
    if (it != g_single_schema_proof_certificate_cache.end()) {
        if (cache_hit) *cache_hit = true;
        if (why) *why = it->second.why;
        return it->second;
    }
    string local_why;
    auto cert = build_single_schema_proof_certificate_(instance, base_rules, schema, &local_why);
    g_single_schema_proof_certificate_cache.emplace(key, cert);
    if (cache_hit) *cache_hit = false;
    if (why) *why = local_why;
    return cert;
}

