static vector<SingleSchemaProofCertificate> collect_single_schema_proof_certificates_exhaustive_n5_(const vector<SparseRuleCandidate>& base_rules,
                                                                                                     const StructuredLocalSchema& schema,
                                                                                                     string* why) {
    auto enum_res = enumerate_canonical_sparse_instances_(5);
    vector<SingleSchemaProofCertificate> out;
    out.reserve(enum_res.canonical_instances.size());
    ProofCertificateCorpusStats local;
    local.n = 5;
    local.max_constraints = -1;
    size_t progress_idx = 0;
    for (const auto& inst : enum_res.canonical_instances) {
        ++progress_idx;
        local_progress_("proof_motif_collect_n5", progress_idx, enum_res.canonical_instances.size());
        ++local.instances_enumerated;
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        bool cache_hit = false;
        string cert_why;
        auto cert = cached_single_schema_proof_certificate_(inst, base_rules, schema, &cache_hit, &cert_why);
        if (cache_hit) ++local.cache_hits; else ++local.cache_misses;
        if (!cert.complete) {
            local.completed = false;
            local.why = string("incomplete proof certificate on n5 instance ") + sparse_instance_to_string_(inst) + " why=" + cert_why;
            g_last_proof_certificate_corpus_stats_exact_n5 = local;
            if (why) *why = local.why;
            return {};
        }
        ++local.certificates_built;
        local.total_steps += single_schema_proof_certificate_non_seed_step_count_(cert);
        out.push_back(std::move(cert));
    }
    local.completed = true;
    local.why = "collected exact n5 proof certificates=" + to_string(out.size());
    g_last_proof_certificate_corpus_stats_exact_n5 = local;
    if (why) *why = local.why;
    return out;
}

