static bool validate_exact_minimal_basis_theorem_data_(string* why) {
    auto basis = authoritative_exact_minimal_proof_motif_basis_data_48_();
    bool ok = (basis.size() == 96);
    if (why) *why = string("basisSize=") + to_string(basis.size()) + (ok ? string("") : string(" expected=96"));
    return ok;
}

static bool ensure_exact_minimal_basis_theorem_data_ready_(string* why) {
    string local_why;
    bool ok = validate_exact_minimal_basis_theorem_data_(&local_why);
    if (ok && g_last_exact_minimal_basis_theorem_status.empty()) {
        g_last_exact_minimal_basis_theorem_status = "exact_minimal_basis_theorem_plus_one_partial";
        g_last_exact_minimal_basis_theorem_ledger = "authoritative exact minimal basis theorem data loaded without rerunning exhaustive theorem regressions";
    }
    if (why) *why = local_why;
    return ok;
}

