static StructuredLocalSchema parse_structured_local_schema_(const string& text) {
    StructuredLocalSchema schema;
    size_t num_pos = text.find("num=");
    if (num_pos == string::npos) throw runtime_error("parse_structured_local_schema_: missing num=");
    size_t ant_pos = text.find(" antecedents=[", num_pos);
    schema.num_symbols = stoi(text.substr(num_pos + 4, ant_pos - (num_pos + 4)));
    size_t ant_start = text.find("[", ant_pos);
    size_t ant_end = text.find("]", ant_start);
    string ants = text.substr(ant_start + 1, ant_end - ant_start - 1);
    schema.antecedents.clear();
    size_t p = 0;
    while (true) {
        size_t l = ants.find("(", p);
        if (l == string::npos) break;
        size_t r = ants.find(")", l);
        string tok = ants.substr(l + 1, r - l - 1);
        size_t arrow = tok.find("->");
        string lhs = tok.substr(0, arrow);
        int w = stoi(tok.substr(arrow + 2));
        size_t comma = lhs.find(",");
        int u = stoi(lhs.substr(0, comma));
        int v = stoi(lhs.substr(comma + 1));
        schema.antecedents.push_back(StructuredLocalSchemaAtom{u, v, w});
        p = r + 1;
    }
    size_t cons_arrow = text.find("] => (", ant_end);
    size_t cons_start = cons_arrow + 6;
    size_t cons_end = text.find(")", cons_start);
    string cons = text.substr(cons_start, cons_end - cons_start);
    size_t arrow = cons.find("->");
    string lhs = cons.substr(0, arrow);
    int w = stoi(cons.substr(arrow + 2));
    size_t comma = lhs.find(",");
    int u = stoi(lhs.substr(0, comma));
    int v = stoi(lhs.substr(comma + 1));
    schema.consequent = StructuredLocalSchemaAtom{u, v, w};
    schema.fingerprint = text.substr(0, cons_end + 1);
    size_t support_pos = text.find(" support=");
    schema.support = 0;
    if (support_pos != string::npos) {
        size_t s_start = support_pos + 9;
        size_t s_end = text.find(" ", s_start);
        schema.support = static_cast<size_t>(stoul(text.substr(s_start, s_end - s_start)));
    }
    size_t human_pos = text.find(" human=");
    if (human_pos != string::npos) schema.human_readable = text.substr(human_pos + 7);
    else schema.human_readable = text;
    return schema;
}

