static string authoritative_family_search_stats_to_string_(const AuthoritativeFamilySearchStats& s) {
    ostringstream oss;
    oss << "familyCount=" << s.family_count
        << " rawCandidates=" << s.raw_candidates
        << " canonicalCandidates=" << s.canonical_candidates
        << " deduplicatedCandidates=" << s.deduplicated_candidates
        << " localExactSurvivors=" << s.local_exact_survivors
        << " plusOneSurvivors=" << s.plus_one_survivors
        << " theoremPreservingSurvivors=" << s.theorem_preserving_survivors
        << " fingerprint=" << s.fingerprint;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

