static bool validate_exact_minimal_basis_motif_local_exact_(const ProofMotif& motif,
                                                            ProofMotifStressStats* stats,
                                                            string* why) {
    ProofMotifStressStats local;
    local.motif_fingerprint = canonical_proof_motif_fingerprint_(motif);
    local.support_size = proof_motif_support_size_(motif);
    local.local_exact_pass = validate_proof_motif_local_exact_(motif, &local.why);
    if (stats) *stats = local;
    if (why) *why = local.why;
    return local.local_exact_pass;
}

static bool validate_exact_minimal_basis_motif_plus_one_(const ProofMotif& motif,
                                                         ProofMotifStressStats* stats,
                                                         string* why) {
    ProofMotifStressStats local;
    local.motif_fingerprint = canonical_proof_motif_fingerprint_(motif);
    local.support_size = proof_motif_support_size_(motif);
    local.local_exact_pass = validate_proof_motif_local_exact_(motif, &local.why);
    local.plus_one_attempted = true;
    auto rule = proof_motif_to_rule_candidate_(motif);
    RetainedRepairRuleStressStats ext_stats;
    local.plus_one_pass = validate_retained_repair_rule_exact_extension_full_(rule, &ext_stats, &local.why);
    local.plus_one_target_n = ext_stats.plus_one_target_n;
    local.plus_one_instances_checked = ext_stats.plus_one_instances_checked;
    if (stats) *stats = local;
    if (why) *why = local.why;
    return local.plus_one_pass;
}

static vector<ProofMotifStressStats> build_exact_minimal_basis_stress_profiles_(const vector<ProofMotif>& basis,
                                                                                string* why) {
    vector<ProofMotifStressStats> out;
    out.reserve(basis.size());
    for (const auto& motif : basis) {
        ProofMotifStressStats s;
        string local_why;
        validate_exact_minimal_basis_motif_plus_one_(motif, &s, &local_why);
        out.push_back(std::move(s));
    }
    if (why) *why = "basis stress profiles=" + to_string(out.size());
    return out;
}

static vector<ProofMotifPlusOneFailureFamily> classify_proof_motif_plus_one_failures_(const vector<ProofMotifStressStats>& stats,
                                                                                       string* why) {
    map<string, ProofMotifPlusOneFailureFamily> agg;
    for (const auto& s : stats) {
        if (!s.plus_one_attempted || s.plus_one_pass) continue;
        string fp = s.motif_fingerprint + "|" + s.why;
        auto& fam = agg[fp];
        if (fam.failure_fingerprint.empty()) {
            fam.motif_fingerprint = s.motif_fingerprint;
            fam.failure_fingerprint = fp;
            fam.why = s.why;
        }
        ++fam.failure_count;
    }
    vector<ProofMotifPlusOneFailureFamily> out;
    for (auto& kv : agg) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.failure_count != b.failure_count) return a.failure_count > b.failure_count;
        return a.failure_fingerprint < b.failure_fingerprint;
    });
    if (why) *why = "plus-one failure families=" + to_string(out.size());
    return out;
}

static string proof_motif_stress_stats_to_string_(const ProofMotifStressStats& s) {
    ostringstream oss;
    oss << "motif=" << s.motif_fingerprint
        << " support=" << s.support_size
        << " localExact=" << (s.local_exact_pass ? "true" : "false")
        << " plusOneAttempted=" << (s.plus_one_attempted ? "true" : "false")
        << " plusOne=" << (s.plus_one_pass ? "true" : "false")
        << " plusOneTargetN=" << s.plus_one_target_n
        << " plusOneInstancesChecked=" << s.plus_one_instances_checked;
    if (!s.why.empty()) oss << " why=" << s.why;
    return oss.str();
}

static string proof_motif_plus_one_failure_family_to_string_(const ProofMotifPlusOneFailureFamily& fam) {
    ostringstream oss;
    oss << "motif=" << fam.motif_fingerprint
        << " failureFingerprint=" << fam.failure_fingerprint
        << " failureCount=" << fam.failure_count;
    if (!fam.why.empty()) oss << " why=" << fam.why;
    return oss.str();
}

static string classify_exact_minimal_basis_theorem_status_(const ExactMinimalBasisTheoremStats& exact_n5,
                                                           const ExactMinimalBasisTheoremStats& bounded_n6_c5,
                                                           const ExactMinimalBasisTheoremStats& bounded_n7_c3,
                                                           const vector<ProofMotifStressStats>& stress,
                                                           const vector<ProofMotifPlusOneFailureFamily>& failures,
                                                           string* why) {
    bool theorem_fail = exact_n5.mismatch_instances != 0 || bounded_n6_c5.mismatch_instances != 0 || bounded_n7_c3.mismatch_instances != 0 ||
                        !exact_n5.same_as_single_schema || !exact_n5.same_as_local_envelope ||
                        !bounded_n6_c5.same_as_single_schema || !bounded_n6_c5.same_as_local_envelope ||
                        !bounded_n7_c3.same_as_single_schema || !bounded_n7_c3.same_as_local_envelope;
    if (theorem_fail) {
        if (why) *why = "basis-only closure mismatch or extensional inequality";
        return "exact_minimal_basis_theorem_counterexample_found";
    }
    if (stress.empty()) {
        if (why) *why = "basis authoritative data fixed";
        return "exact_minimal_basis_data_fixed";
    }
    if (!failures.empty()) {
        if (why) *why = "tested exact domains pass; plus-one is partial";
        return "exact_minimal_basis_theorem_plus_one_partial";
    }
    if (why) *why = "basis-only theorem holds on tested exact domains";
    return "exact_minimal_basis_theorem_supported";
}

static string build_exact_minimal_basis_theorem_ledger_(const ExactMinimalBasisTheoremStats& exact_n5,
                                                        const ExactMinimalBasisTheoremStats& bounded_n6_c5,
                                                        const ExactMinimalBasisTheoremStats& bounded_n7_c3,
                                                        const vector<ProofMotifStressStats>& stress,
                                                        const vector<ProofMotifPlusOneFailureFamily>& failures,
                                                        const string& status) {
    ostringstream oss;
    oss << "basisFingerprint=" << exact_minimal_proof_motif_basis_fingerprint_() << "\n";
    oss << "basisSize=" << exact_minimal_proof_motif_basis_().size() << "\n";
    oss << "exactN5=" << exact_minimal_basis_theorem_stats_to_string_(exact_n5) << "\n";
    oss << "boundedN6C5=" << exact_minimal_basis_theorem_stats_to_string_(bounded_n6_c5) << "\n";
    oss << "boundedN7C3=" << exact_minimal_basis_theorem_stats_to_string_(bounded_n7_c3) << "\n";
    size_t pass_local = 0;
    size_t pass_plus = 0;
    for (const auto& s : stress) {
        if (s.local_exact_pass) ++pass_local;
        if (s.plus_one_attempted && s.plus_one_pass) ++pass_plus;
    }
    oss << "basisLocalExactPass=" << pass_local << "/" << stress.size() << "\n";
    oss << "basisPlusOnePass=" << pass_plus << "/" << stress.size() << "\n";
    oss << "plusOneFailureFamilyCount=" << failures.size() << "\n";
    size_t top = min<size_t>(failures.size(), 10);
    for (size_t i = 0; i < top; ++i) oss << "plusOneFailure[" << i << "]=" << proof_motif_plus_one_failure_family_to_string_(failures[i]) << "\n";
    oss << "status=" << status << "\n";
    return oss.str();
}

static void ensure_exact_minimal_basis_theorem_audits_ready_() {
    bool already_built = g_last_exact_minimal_basis_exact_n5_stats.instances_checked != 0 &&
                         g_last_exact_minimal_basis_bounded_n6_c5_stats.instances_checked != 0 &&
                         g_last_exact_minimal_basis_bounded_n7_c3_stats.instances_checked != 0;
    if (already_built) return;
    string ready_why;
    if (!ensure_exact_minimal_basis_theorem_data_ready_(&ready_why)) {
        throw runtime_error("exact minimal basis theorem data readiness failed\n" + ready_why);
    }
#ifdef LOCAL_TEST
    cerr << "stage: exact minimal basis begin\n";
#endif
    auto basis = exact_minimal_proof_motif_basis_();
    string why;
    validate_exact_minimal_basis_theorem_exhaustive_n5_({}, basis,
                                                        &g_last_exact_minimal_basis_exact_n5_stats,
                                                        &g_last_exact_minimal_basis_exact_n5_failure,
                                                        &why);
#ifdef LOCAL_TEST
    cerr << "stage: exact minimal basis n6 c5\n";
#endif
    validate_exact_minimal_basis_theorem_bounded_n6_constraint5_({}, basis,
                                                                 &g_last_exact_minimal_basis_bounded_n6_c5_stats,
                                                                 &g_last_exact_minimal_basis_bounded_n6_c5_failure,
                                                                 &why);
#ifdef LOCAL_TEST
    cerr << "stage: exact minimal basis n7 c3\n";
#endif
    validate_exact_minimal_basis_theorem_bounded_n7_constraint3_({}, basis,
                                                                 &g_last_exact_minimal_basis_bounded_n7_c3_stats,
                                                                 &g_last_exact_minimal_basis_bounded_n7_c3_failure,
                                                                 &why);
}

static void ensure_exact_minimal_basis_ready_() {
    bool already_built = g_last_exact_minimal_basis_exact_n5_stats.instances_checked != 0 &&
                         g_last_exact_minimal_basis_bounded_n6_c5_stats.instances_checked != 0 &&
                         g_last_exact_minimal_basis_bounded_n7_c3_stats.instances_checked != 0 &&
                         !g_last_exact_minimal_basis_stress_profiles.empty();
    if (already_built) return;
    ensure_exact_minimal_basis_theorem_audits_ready_();
    auto basis = exact_minimal_proof_motif_basis_();
    string why;
#ifdef LOCAL_TEST
    cerr << "stage: exact minimal basis stress\n";
#endif
    g_last_exact_minimal_basis_stress_profiles = build_exact_minimal_basis_stress_profiles_(basis, &why);
    g_last_proof_motif_plus_one_failure_families = classify_proof_motif_plus_one_failures_(g_last_exact_minimal_basis_stress_profiles, &why);
    g_last_exact_minimal_basis_theorem_status = classify_exact_minimal_basis_theorem_status_(g_last_exact_minimal_basis_exact_n5_stats,
                                                                                             g_last_exact_minimal_basis_bounded_n6_c5_stats,
                                                                                             g_last_exact_minimal_basis_bounded_n7_c3_stats,
                                                                                             g_last_exact_minimal_basis_stress_profiles,
                                                                                             g_last_proof_motif_plus_one_failure_families,
                                                                                             &why);
    g_last_exact_minimal_basis_theorem_ledger = build_exact_minimal_basis_theorem_ledger_(g_last_exact_minimal_basis_exact_n5_stats,
                                                                                           g_last_exact_minimal_basis_bounded_n6_c5_stats,
                                                                                           g_last_exact_minimal_basis_bounded_n7_c3_stats,
                                                                                           g_last_exact_minimal_basis_stress_profiles,
                                                                                           g_last_proof_motif_plus_one_failure_families,
                                                                                           g_last_exact_minimal_basis_theorem_status);
}

static ProofMotifPlusOneFailureWitness build_first_plus_one_failure_witness_for_motif_(const ProofMotif& motif,
                                                                                        bool* found,
                                                                                        string* why) {

    ProofMotifPlusOneFailureWitness out;
    if (found) *found = false;
    auto rule = proof_motif_to_rule_candidate_(motif);
    if (rule.antecedents.empty()) {
        if (why) *why = "zero-premise motif has no plus-one failure witness";
        return out;
    }
    size_t total_embeddings = 0;
    string collect_why;
    auto instances = collect_unique_retained_rule_antecedent_instances_(rule,
                                                                        repair_principle_support_size_(rule) + 1,
                                                                        &total_embeddings,
                                                                        &collect_why);
    if (!collect_why.empty()) {
        if (why) *why = collect_why;
        return out;
    }
    for (const auto& inst : instances) {
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst.antecedent_instance, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        auto it = oracle.forced_pairwise_lca.find({inst.instantiated_consequent.u, inst.instantiated_consequent.v});
        int forced = (it == oracle.forced_pairwise_lca.end()) ? -1 : it->second;
        if (forced != inst.instantiated_consequent.w) {
            out.motif_fingerprint = motif.fingerprint;
            out.motif = motif;
            out.instance = inst.antecedent_instance;
            out.blocked_target = inst.instantiated_consequent;
            out.family_fingerprint = canonical_mismatch_family_fingerprint_(inst.antecedent_instance,
                                                                            inst.instantiated_consequent);
            out.why = string("plus-one exact blocked; forced=") + (it == oracle.forced_pairwise_lca.end() ? string("<missing>") : to_string(forced));
            if (found) *found = true;
            if (why) *why = out.why;
            return out;
        }
    }
    if (why) *why = "no failing plus-one witness found";
    return out;
}

static vector<ProofMotifPlusOneFailureWitness> collect_exact_minimal_basis_plus_one_failure_witnesses_(const vector<ProofMotif>& basis,
                                                                                                        string* why) {
    ensure_exact_minimal_basis_theorem_data_ready_(nullptr);
    unordered_map<string, bool> plus_one_ok;
    for (const auto& s : g_last_exact_minimal_basis_stress_profiles) {
        plus_one_ok[s.motif_fingerprint] = s.plus_one_attempted && s.plus_one_pass;
    }
    vector<ProofMotifPlusOneFailureWitness> out;
    for (const auto& motif : basis) {
        auto it = plus_one_ok.find(motif.fingerprint);
        if (it != plus_one_ok.end() && it->second) continue;
        bool found = false;
        string local_why;
        auto wit = build_first_plus_one_failure_witness_for_motif_(motif, &found, &local_why);
        if (found) out.push_back(std::move(wit));
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.family_fingerprint != b.family_fingerprint) return a.family_fingerprint < b.family_fingerprint;
        return a.motif_fingerprint < b.motif_fingerprint;
    });
    if (why) *why = "plus-one failure witnesses=" + to_string(out.size());
    return out;
}

static vector<ProofMotifPlusOneFailureFamilySummary> classify_exact_minimal_basis_plus_one_failure_families_(const vector<ProofMotifPlusOneFailureWitness>& witnesses) {
    map<string, ProofMotifPlusOneFailureFamilySummary> agg;
    map<string, set<string>> motifs;
    for (const auto& w : witnesses) {
        auto& fam = agg[w.family_fingerprint];
        if (fam.family_fingerprint.empty()) {
            fam.family_fingerprint = w.family_fingerprint;
            fam.motif_fingerprint = w.motif_fingerprint;
            fam.representative_instance = w.instance;
            fam.representative_target = w.blocked_target;
            fam.why = w.why;
        }
        ++fam.witness_count;
        motifs[w.family_fingerprint].insert(w.motif_fingerprint);
    }
    vector<ProofMotifPlusOneFailureFamilySummary> out;
    for (auto& kv : agg) {
        kv.second.motif_count = motifs[kv.first].size();
        out.push_back(kv.second);
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.witness_count != b.witness_count) return a.witness_count > b.witness_count;
        if (a.motif_count != b.motif_count) return a.motif_count > b.motif_count;
        return a.family_fingerprint < b.family_fingerprint;
    });
    return out;
}

static vector<ProofMotifPlusOneFailureFamilySummary> rank_plus_one_failure_families_by_support_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                                size_t top_k) {
    vector<ProofMotifPlusOneFailureFamilySummary> out = families;
    if (out.size() > top_k) out.resize(top_k);
    return out;
}

static vector<ProofMotif> extract_plus_one_robust_basis_(const vector<ProofMotif>& basis,
                                                         const vector<ProofMotifStressStats>& stress_profiles,
                                                         string* why) {
    unordered_set<string> pass;
    for (const auto& s : stress_profiles) if (s.plus_one_attempted && s.plus_one_pass) pass.insert(s.motif_fingerprint);
    vector<ProofMotif> out;
    for (const auto& motif : basis) if (pass.count(motif.fingerprint)) out.push_back(motif);
    if (why) *why = "plus-one robust basis size=" + to_string(out.size()) + "/" + to_string(basis.size());
    return out;
}

static bool measure_robust_basis_coverage_(const vector<ProofMotif>& robust_basis,
                                           const vector<SingleSchemaProofCertificate>& certs,
                                           RobustBasisSubfamilyStats* stats,
                                           string* why) {
    RobustBasisSubfamilyStats local;
    local.total_basis_size = exact_minimal_proof_motif_basis_().size();
    local.robust_basis_size = robust_basis.size();
    set<string> fps;
    for (const auto& m : robust_basis) fps.insert(m.fingerprint);
    for (const auto& cert : certs) {
        for (const auto& step : cert.steps) {
            if (proof_step_is_assumption_(step)) continue;
            ++local.total_occurrences;
            auto motif = generalize_derivation_step_to_proof_motif_(step);
            if (fps.count(motif.fingerprint)) ++local.covered_occurrences;
            else ++local.uncovered_occurrences;
        }
    }
    local.why = "robust basis cover=" + to_string(local.covered_occurrences) + "/" + to_string(local.total_occurrences);
    if (stats) *stats = local;
    if (why) *why = local.why;
    return local.uncovered_occurrences == 0;
}

static StructuredLocalSchema basis_failure_family_to_schema_candidate_(const ProofMotifPlusOneFailureFamilySummary& fam) {
    SchemaRule raw;
    int maxv = 1;
    for (const auto& c : fam.representative_instance.constraints) {
        raw.antecedents.push_back(SchemaAtom{c.u, c.v, c.w});
        maxv = max(maxv, max(c.u, max(c.v, c.w)));
    }
    raw.consequent = SchemaAtom{fam.representative_target.u, fam.representative_target.v, fam.representative_target.w};
    maxv = max(maxv, max(fam.representative_target.u, max(fam.representative_target.v, fam.representative_target.w)));
    raw.num_symbols = maxv;
    auto canon = canonicalize_schema_rule_(raw);
    auto out = schema_rule_to_structured_local_schema_(canon);
    out.support = fam.witness_count;
    out.human_readable = structured_local_schema_to_string_(out);
    return out;
}

static vector<BasisSchemaCompressionCandidate> derive_basis_schema_compression_candidates_(const vector<ProofMotifPlusOneFailureFamilySummary>& top_families,
                                                                                           string* why) {
    map<string, BasisSchemaCompressionCandidate> uniq;
    for (const auto& fam : top_families) {
        auto schema = basis_failure_family_to_schema_candidate_(fam);
        auto& cand = uniq[schema.fingerprint];
        if (cand.schema.fingerprint.empty()) {
            cand.source_family_fingerprint = fam.family_fingerprint;
            cand.schema = schema;
            cand.family_support = fam.witness_count;
            cand.human_readable = structured_local_schema_to_string_(schema);
            cand.why = "derived from plus-one failure representative";
        } else {
            cand.family_support += fam.witness_count;
        }
    }
    vector<BasisSchemaCompressionCandidate> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.family_support != b.family_support) return a.family_support > b.family_support;
        return a.schema.fingerprint < b.schema.fingerprint;
    });
    if (why) *why = "schema compression candidates=" + to_string(out.size());
    return out;
}

static bool validate_basis_schema_compression_candidate_local_exact_(const StructuredLocalSchema& schema,
                                                                     string* why) {
    return validate_structured_local_schema_local_exact_(schema, why);
}

static bool validate_basis_schema_compression_candidate_plus_one_exact_(const StructuredLocalSchema& schema,
                                                                        string* why) {
    return validate_structured_local_schema_plus_one_exact_(schema, why);
}

static vector<BasisSchemaCompressionCandidate> filter_sound_and_plus_one_supported_schema_candidates_(const vector<BasisSchemaCompressionCandidate>& candidates,
                                                                                                      string* why) {
    vector<BasisSchemaCompressionCandidate> out;
    for (auto cand : candidates) {
        string local_why;
        cand.local_exact_pass = validate_basis_schema_compression_candidate_local_exact_(cand.schema, &local_why);
        if (cand.local_exact_pass) cand.plus_one_pass = validate_basis_schema_compression_candidate_plus_one_exact_(cand.schema, &local_why);
        if (!local_why.empty()) cand.why = local_why;
        if (cand.local_exact_pass && cand.plus_one_pass) out.push_back(cand);
    }
    if (why) *why = "sound plus-one schema candidates=" + to_string(out.size()) + "/" + to_string(candidates.size());
    return out;
}

static SolverSaturationResult run_basis_stabilization_candidate_closure_(const SparseLcaInstance& instance,
                                                                         const vector<SparseRuleCandidate>& base_rules,
                                                                         const vector<ProofMotif>& robust_basis,
                                                                         const vector<StructuredLocalSchema>& schema_candidates,
                                                                         string* why) {
    vector<SparseRuleCandidate> rules = base_rules;
    for (const auto& motif : robust_basis) rules.push_back(proof_motif_to_rule_candidate_(motif));
    vector<SchemaRule> schemas;
    for (const auto& schema : schema_candidates) schemas.push_back(structured_local_schema_to_schema_rule_(schema));
    schemas = schema_rules_to_solver_system_(schemas);
    return run_solver_completion_closure_(instance, rules, schemas, why);
}

static bool validate_basis_stabilization_candidate_on_instances_(const vector<SparseLcaInstance>& instances,
                                                                 const vector<SparseRuleCandidate>& base_rules,
                                                                 const vector<ProofMotif>& robust_basis,
                                                                 const vector<StructuredLocalSchema>& schema_candidates,
                                                                 const string& label,
                                                                 ExactMinimalBasisTheoremStats* stats,
                                                                 SolverSaturationResult* first_failure,
                                                                 string* why) {
    ExactMinimalBasisTheoremStats local;
    local.n = instances.empty() ? 0 : instances.front().n;
    if (label == "n5") local.max_constraints = -1;
    else if (label == "n6c5") local.max_constraints = 5;
    else if (label == "n7c3") local.max_constraints = 3;
    bool have_failure = false;
    SolverSaturationResult local_first_failure;
    for (size_t i = 0; i < instances.size(); ++i) {
        local_progress_(label.c_str(), i + 1, instances.size());
        const auto& inst = instances[i];
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        ++local.instances_checked;
        if (!oracle.satisfiable) continue;
        ++local.satisfiable_instances;
        auto sat = run_basis_stabilization_candidate_closure_(inst, base_rules, robust_basis, schema_candidates, nullptr);
        auto basis_sat = run_exact_minimal_basis_closure_(inst, base_rules, exact_minimal_proof_motif_basis_(), nullptr);
        if (sat.full_match && solver_saturation_extensional_equal_(sat, basis_sat)) {
            ++local.full_match_instances;
        } else {
            ++local.mismatch_instances;
            local.pair_witnesses += sat.missing_forced_pairs.size() + sat.extra_derived_pairs.size();
            local.same_as_single_schema = false;
            local.same_as_local_envelope = false;
            if (!have_failure) {
                have_failure = true;
                local_first_failure = sat;
                local.why = string("basis stabilization mismatch on instance ") + sparse_instance_to_string_(inst)
                           + "\n[stabilized]\n" + solver_saturation_result_to_string_(sat)
                           + "\n[minimal basis]\n" + solver_saturation_result_to_string_(basis_sat);
            }
        }
    }
    local.completed = true;
    if (stats) *stats = local;
    if (first_failure && have_failure) *first_failure = local_first_failure;
    if (why) *why = local.why;
    return !have_failure;
}

static bool validate_basis_stabilization_candidate_n5_(const vector<SparseRuleCandidate>& base_rules,
                                                       const vector<ProofMotif>& robust_basis,
                                                       const vector<StructuredLocalSchema>& schema_candidates,
                                                       ExactMinimalBasisTheoremStats* stats,
                                                       SolverSaturationResult* first_failure,
                                                       string* why) {
    auto instances = enumerate_canonical_sparse_instances_(5).canonical_instances;
    return validate_basis_stabilization_candidate_on_instances_(instances, base_rules, robust_basis, schema_candidates, "n5", stats, first_failure, why);
}

