static vector<ProofMotifPlusOneObstructionCertificate> build_proof_motif_plus_one_obstruction_certificates_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                                             string* why) {
    vector<ProofMotifPlusOneObstructionCertificate> out;
    for (const auto& fam : families) {
        ProofMotifPlusOneObstructionCertificate cert;
        cert.motif_fingerprint = fam.motif_fingerprint;
        cert.family_fingerprint = fam.family_fingerprint;
        cert.instance = fam.representative_instance;
        cert.target = fam.representative_target;
        cert.reason = fam.why.empty() ? string("plus-one representative obstruction") : fam.why;
        out.push_back(std::move(cert));
    }
    if (why) *why = "plus-one obstruction certificates=" + to_string(out.size());
    return out;
}

