static vector<BasisSchemaCompressionCandidate> search_sound_plus_one_schema_candidates_for_family_(const ProofMotifPlusOneFailureFamilySummary& family,
                                                                                                    const vector<SparseRuleCandidate>& base_rules,
                                                                                                    int symbol_bound,
                                                                                                    int antecedent_bound,
                                                                                                    SchemaCandidateUniverseStats* stats,
                                                                                                    vector<BasisSchemaCompressionCandidate>* all_candidates,
                                                                                                    string* why) {
    SchemaCandidateUniverseStats local;
    local.family_fingerprint = family.family_fingerprint;
    local.symbol_bound = symbol_bound;
    local.antecedent_bound = antecedent_bound;
    string enum_why;
    size_t raw_count = 0;
    auto schemas = enumerate_schema_candidates_for_failure_family_(family, symbol_bound, antecedent_bound, &raw_count, &enum_why);
    local.why = enum_why;
    local.raw_candidates = raw_count;
    local.canonical_candidates = schemas.size();
    vector<BasisSchemaCompressionCandidate> survivors;
    for (const auto& schema : schemas) {
        BasisSchemaCompressionCandidate cand;
        cand.source_family_fingerprint = family.family_fingerprint;
        cand.schema = schema;
        cand.family_support = family.witness_count;
        cand.human_readable = structured_local_schema_to_string_(schema);
        string local_why;
        cand.local_exact_pass = validate_basis_schema_compression_candidate_local_exact_(schema, &local_why);
        if (cand.local_exact_pass) ++local.local_exact_pass;
        if (cand.local_exact_pass) {
            cand.plus_one_pass = validate_basis_schema_compression_candidate_plus_one_exact_(schema, &local_why);
            if (cand.plus_one_pass) ++local.plus_one_pass;
        }
        if (cand.local_exact_pass && cand.plus_one_pass) {
            string pwhy1, pwhy2, pwhy3;
            bool ok1 = validate_schema_candidate_preserves_basis_theorem_n5_(schema, &pwhy1);
            bool ok2 = validate_schema_candidate_preserves_basis_theorem_n6_c5_(schema, &pwhy2);
            bool ok3 = validate_schema_candidate_preserves_basis_theorem_n7_c3_(schema, &pwhy3);
            cand.theorem_preserving_pass = ok1 && ok2 && ok3;
            if (cand.theorem_preserving_pass) ++local.theorem_preserving_pass;
            if (!pwhy1.empty()) cand.why = pwhy1;
            else if (!pwhy2.empty()) cand.why = pwhy2;
            else if (!pwhy3.empty()) cand.why = pwhy3;
        } else if (!local_why.empty()) {
            cand.why = local_why;
        }
        if (all_candidates) all_candidates->push_back(cand);
        if (cand.local_exact_pass && cand.plus_one_pass && cand.theorem_preserving_pass) survivors.push_back(cand);
    }
    if (local.canonical_candidates == 0 && !enum_why.empty()) {
        local.why = enum_why;
    }
    if (stats) *stats = local;
    if (why) *why = schema_candidate_universe_stats_to_string_(local);
    return survivors;
}

static FamilyLevelPlusOneObstructionCertificate build_family_level_plus_one_obstruction_certificate_(const ProofMotifPlusOneFailureFamilySummary& family,
                                                                                                      const SchemaCandidateUniverseStats& stats,
                                                                                                      string* why) {
    FamilyLevelPlusOneObstructionCertificate cert;
    cert.family_fingerprint = family.family_fingerprint;
    cert.witness_count = family.witness_count;
    cert.symbol_bound_tested = stats.symbol_bound;
    cert.antecedent_bound_tested = stats.antecedent_bound;
    cert.candidate_count_tested = stats.canonical_candidates;
    cert.local_exact_survivors = stats.local_exact_pass;
    cert.plus_one_survivors = stats.plus_one_pass;
    cert.theorem_preserving_survivors = stats.theorem_preserving_pass;
    if (stats.theorem_preserving_pass == 0) {
        cert.reason = "no theorem-preserving schema candidate in tested bounded family universe";
    } else if (stats.plus_one_pass == 0) {
        cert.reason = "no plus-one exact schema candidate in tested bounded family universe";
    } else if (stats.local_exact_pass == 0) {
        cert.reason = "no local exact schema candidate in tested bounded family universe";
    } else {
        cert.reason = "family-level obstruction not established";
    }
    if (why) *why = family_level_plus_one_obstruction_certificate_to_string_(cert);
    return cert;
}

static bool measure_augmented_robust_basis_coverage_(const vector<ProofMotif>& robust_basis,
                                                     const vector<StructuredLocalSchema>& schema_candidates,
                                                     RobustBasisSubfamilyStats* stats,
                                                     string* why) {
    RobustBasisSubfamilyStats local;
    local.total_basis_size = exact_minimal_proof_motif_basis_().size();
    local.robust_basis_size = robust_basis.size();
    set<string> robust_fps;
    for (const auto& m : robust_basis) robust_fps.insert(m.fingerprint);
    set<string> candidate_families;
    for (const auto& schema : schema_candidates) {
        for (const auto& cand : g_last_sound_plus_one_schema_candidates) {
            if (cand.schema.fingerprint == schema.fingerprint) candidate_families.insert(cand.source_family_fingerprint);
        }
    }
    unordered_map<string, string> motif_to_family;
    for (const auto& w : g_last_exact_minimal_basis_plus_one_failure_witnesses) motif_to_family.emplace(w.motif_fingerprint, w.family_fingerprint);
    for (const auto& cert : g_last_single_schema_proof_certificates_combined) {
        for (const auto& step : cert.steps) {
            if (proof_step_is_assumption_(step)) continue;
            ++local.total_occurrences;
            auto motif = generalize_derivation_step_to_proof_motif_(step);
            bool covered = robust_fps.count(motif.fingerprint) > 0;
            if (!covered) {
                auto it = motif_to_family.find(motif.fingerprint);
                if (it != motif_to_family.end() && candidate_families.count(it->second)) covered = true;
            }
            if (covered) ++local.covered_occurrences;
        }
    }
    local.uncovered_occurrences = local.total_occurrences - local.covered_occurrences;
    local.why = string("augmented robust cover proxy=") + to_string(local.covered_occurrences) + "/" + to_string(local.total_occurrences);
    if (stats) *stats = local;
    if (why) *why = local.why;
    return local.uncovered_occurrences == 0;
}

static SchemaCandidateUniverseStats scan_schema_candidate_universe_for_failure_family_(const ProofMotifPlusOneFailureFamilySummary& family,
                                                                                 const vector<SparseRuleCandidate>& base_rules,
                                                                                 int symbol_bound,
                                                                                 int antecedent_bound,
                                                                                 string* why) {
    SchemaCandidateUniverseStats stats;
    vector<BasisSchemaCompressionCandidate> all_candidates;
    (void)search_sound_plus_one_schema_candidates_for_family_(family,
                                                              base_rules,
                                                              symbol_bound,
                                                              antecedent_bound,
                                                              &stats,
                                                              &all_candidates,
                                                              why);
    return stats;
}

static string classify_basis_plus_one_direction_(const RobustBasisSubfamilyStats& robust_stats,
                                                 const RobustBasisSubfamilyStats& augmented_stats,
                                                 const vector<BasisSchemaCompressionCandidate>& sound_schema_candidates,
                                                 const ExactMinimalBasisTheoremStats* stab_n5,
                                                 const ExactMinimalBasisTheoremStats* stab_n6,
                                                 const ExactMinimalBasisTheoremStats* stab_n7,
                                                 const vector<FamilyLevelPlusOneObstructionCertificate>& family_obstruction_certs,
                                                 string* why) {
    bool stabilization_ok = stab_n5 && stab_n6 && stab_n7 &&
                            stab_n5->completed && stab_n6->completed && stab_n7->completed &&
                            stab_n5->mismatch_instances == 0 && stab_n6->mismatch_instances == 0 && stab_n7->mismatch_instances == 0;
    if (stabilization_ok && !sound_schema_candidates.empty()) {
        if (why) *why = "robust basis plus sound schema candidates preserve theorem on tested exact domains";
        return "basis_theorem_stabilization_promising";
    }
    if (!sound_schema_candidates.empty()) {
        if (why) *why = "sound plus-one schema candidates exist but theorem preservation is incomplete";
        return "basis_to_schema_compression_promising";
    }
    if (!family_obstruction_certs.empty()) {
        if (why) *why = "tested bounded schema universes for failure families yield no theorem-preserving plus-one schema candidates";
        return "support_bounded_plus_one_obstruction_supported";
    }
    if (augmented_stats.covered_occurrences > robust_stats.covered_occurrences) {
        if (why) *why = "augmented robust coverage improved but no fully sound theorem-preserving schema candidate survived";
        return "mixed_frontier_more_evidence_needed";
    }
    if (robust_stats.robust_basis_size > 0) {
        if (why) *why = "robust plus-one subbasis exists but no tested support-bounded schema candidate survives";
        return "mixed_frontier_more_evidence_needed";
    }
    if (why) *why = "no robust plus-one basis and no schema candidate survives tested bounded search";
    return "support_bounded_plus_one_obstruction_supported";
}

static string build_basis_plus_one_direction_ledger_(const RobustBasisSubfamilyStats& robust_stats,
                                                     const RobustBasisSubfamilyStats& augmented_stats,
                                                     const vector<ProofMotifPlusOneFailureWitness>& witnesses,
                                                     const vector<ProofMotifPlusOneFailureInventory>& inventories,
                                                     const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                     const vector<SchemaCandidateUniverseStats>& search_stats,
                                                     const vector<BasisSchemaCompressionCandidate>& all_candidates,
                                                     const vector<BasisSchemaCompressionCandidate>& sound_candidates,
                                                     const vector<ProofMotifPlusOneObstructionCertificate>& obstruction_certs,
                                                     const vector<FamilyLevelPlusOneObstructionCertificate>& family_obstruction_certs,
                                                     const string& status) {
    ostringstream oss;
    oss << "robustBasis=" << robust_basis_subfamily_stats_to_string_(robust_stats) << "\n";
    oss << "augmentedRobustBasis=" << robust_basis_subfamily_stats_to_string_(augmented_stats) << "\n";
    oss << "plusOneFailureWitnesses=" << witnesses.size() << "\n";
    oss << "plusOneFailureInventories=" << inventories.size() << "\n";
    for (size_t i = 0; i < min<size_t>(inventories.size(), 10); ++i) oss << "inventory[" << i << "]=" << proof_motif_plus_one_failure_inventory_to_string_(inventories[i]) << "\n";
    oss << "plusOneFailureFamilies=" << families.size() << "\n";
    for (size_t i = 0; i < min<size_t>(families.size(), 10); ++i) oss << "failureFamily[" << i << "]=" << proof_motif_plus_one_failure_family_summary_to_string_(families[i]) << "\n";
    oss << "schemaCandidateUniverseStats=" << search_stats.size() << "\n";
    for (size_t i = 0; i < min<size_t>(search_stats.size(), 10); ++i) oss << "schemaSearch[" << i << "]=" << schema_candidate_universe_stats_to_string_(search_stats[i]) << "\n";
    oss << "schemaCompressionCandidates=" << all_candidates.size() << "\n";
    for (size_t i = 0; i < min<size_t>(all_candidates.size(), 10); ++i) oss << "schemaCand[" << i << "]=" << basis_schema_compression_candidate_to_string_(all_candidates[i]) << "\n";
    oss << "soundPlusOneSchemaCandidates=" << sound_candidates.size() << "\n";
    oss << "representativeObstructionCertificates=" << obstruction_certs.size() << "\n";
    for (size_t i = 0; i < min<size_t>(obstruction_certs.size(), 10); ++i) oss << "reprObstruction[" << i << "]=" << proof_motif_plus_one_obstruction_certificate_to_string_(obstruction_certs[i]) << "\n";
    oss << "familyLevelObstructionCertificates=" << family_obstruction_certs.size() << "\n";
    for (size_t i = 0; i < min<size_t>(family_obstruction_certs.size(), 10); ++i) oss << "familyObstruction[" << i << "]=" << family_level_plus_one_obstruction_certificate_to_string_(family_obstruction_certs[i]) << "\n";
    oss << "status=" << status << "\n";
    return oss.str();
}

static void ensure_basis_plus_one_ready_() {
    if (!g_last_basis_plus_one_direction_status.empty()) return;
    ensure_exact_minimal_basis_theorem_data_ready_(nullptr);
#ifdef LOCAL_TEST
    cerr << "stage: basis plus-one analysis begin\n";
#endif
    string why;
    auto basis = exact_minimal_proof_motif_basis_();
    g_last_exact_minimal_basis_plus_one_failure_witnesses = collect_exact_minimal_basis_plus_one_failure_witnesses_(basis, &why);
    g_last_plus_one_failure_inventories = build_plus_one_failure_inventory_(g_last_exact_minimal_basis_plus_one_failure_witnesses, &why);
    g_last_exact_minimal_basis_plus_one_failure_family_summaries = classify_exact_minimal_basis_plus_one_failure_families_(g_last_exact_minimal_basis_plus_one_failure_witnesses);
    g_last_top_plus_one_failure_family_summaries = rank_plus_one_failure_families_by_support_(g_last_exact_minimal_basis_plus_one_failure_family_summaries, 8);
    g_last_plus_one_robust_basis = extract_plus_one_robust_basis_(basis, g_last_exact_minimal_basis_stress_profiles, &why);
    measure_robust_basis_coverage_(g_last_plus_one_robust_basis, g_last_single_schema_proof_certificates_combined, &g_last_robust_basis_stats, &why);

    g_last_basis_schema_compression_candidates.clear();
    g_last_sound_plus_one_schema_candidates.clear();
    g_last_schema_candidate_universe_stats.clear();
    g_last_family_level_plus_one_obstruction_certificates.clear();

    for (size_t fam_idx = 0; fam_idx < g_last_exact_minimal_basis_plus_one_failure_family_summaries.size(); ++fam_idx) {
        const auto& fam = g_last_exact_minimal_basis_plus_one_failure_family_summaries[fam_idx];
#ifdef LOCAL_TEST
        cerr << "stage: plus-one family schema search " << (fam_idx + 1) << "/" << g_last_exact_minimal_basis_plus_one_failure_family_summaries.size() << "\n";
#endif
        int symbol_bound = representative_symbol_bound_for_failure_family_(fam);
        int antecedent_bound = max(2, min(3, (int)fam.representative_instance.constraints.size()));
        SchemaCandidateUniverseStats stats;
        vector<BasisSchemaCompressionCandidate> all_for_family;
        auto sound_for_family = search_sound_plus_one_schema_candidates_for_family_(fam,
                                                                                   {},
                                                                                   symbol_bound,
                                                                                   antecedent_bound,
                                                                                   &stats,
                                                                                   &all_for_family,
                                                                                   &why);
        g_last_schema_candidate_universe_stats.push_back(stats);
        g_last_basis_schema_compression_candidates.insert(g_last_basis_schema_compression_candidates.end(),
                                                          all_for_family.begin(),
                                                          all_for_family.end());
        g_last_sound_plus_one_schema_candidates.insert(g_last_sound_plus_one_schema_candidates.end(),
                                                       sound_for_family.begin(),
                                                       sound_for_family.end());
        if (stats.theorem_preserving_pass == 0) {
            g_last_family_level_plus_one_obstruction_certificates.push_back(
                build_family_level_plus_one_obstruction_certificate_(fam, stats, &why));
        }
    }

    auto dedup_candidates = [](vector<BasisSchemaCompressionCandidate>& v) {
        map<string, BasisSchemaCompressionCandidate> uniq;
        for (auto cand : v) {
            auto& slot = uniq[cand.schema.fingerprint];
            if (slot.schema.fingerprint.empty()) {
                slot = cand;
            } else {
                slot.family_support += cand.family_support;
                slot.local_exact_pass = slot.local_exact_pass || cand.local_exact_pass;
                slot.plus_one_pass = slot.plus_one_pass || cand.plus_one_pass;
                slot.theorem_preserving_pass = slot.theorem_preserving_pass || cand.theorem_preserving_pass;
                if (slot.why.empty()) slot.why = cand.why;
            }
        }
        v.clear();
        for (auto& kv : uniq) v.push_back(kv.second);
        sort(v.begin(), v.end(), [](const auto& a, const auto& b) {
            if (a.family_support != b.family_support) return a.family_support > b.family_support;
            return a.schema.fingerprint < b.schema.fingerprint;
        });
    };
    dedup_candidates(g_last_basis_schema_compression_candidates);
    dedup_candidates(g_last_sound_plus_one_schema_candidates);

    vector<StructuredLocalSchema> sound_schemas;
    for (const auto& c : g_last_sound_plus_one_schema_candidates) sound_schemas.push_back(c.schema);
    if (!sound_schemas.empty()) {
        validate_basis_stabilization_candidate_n5_({}, g_last_plus_one_robust_basis, sound_schemas,
                                                   &g_last_basis_stabilization_n5_stats,
                                                   &g_last_basis_stabilization_n5_failure,
                                                   &why);
        validate_basis_stabilization_candidate_n6_c5_({}, g_last_plus_one_robust_basis, sound_schemas,
                                                      &g_last_basis_stabilization_n6_c5_stats,
                                                      &g_last_basis_stabilization_n6_c5_failure,
                                                      &why);
        validate_basis_stabilization_candidate_n7_c3_({}, g_last_plus_one_robust_basis, sound_schemas,
                                                      &g_last_basis_stabilization_n7_c3_stats,
                                                      &g_last_basis_stabilization_n7_c3_failure,
                                                      &why);
        measure_augmented_robust_basis_coverage_(g_last_plus_one_robust_basis, sound_schemas, &g_last_augmented_robust_basis_stats, &why);
    } else {
        g_last_basis_stabilization_n5_stats.n = 5;
        g_last_basis_stabilization_n5_stats.completed = false;
        g_last_basis_stabilization_n5_stats.why = "not attempted";
        g_last_basis_stabilization_n6_c5_stats.n = 6;
        g_last_basis_stabilization_n6_c5_stats.max_constraints = 5;
        g_last_basis_stabilization_n6_c5_stats.completed = false;
        g_last_basis_stabilization_n6_c5_stats.why = "not attempted";
        g_last_basis_stabilization_n7_c3_stats.n = 7;
        g_last_basis_stabilization_n7_c3_stats.max_constraints = 3;
        g_last_basis_stabilization_n7_c3_stats.completed = false;
        g_last_basis_stabilization_n7_c3_stats.why = "not attempted";
        g_last_augmented_robust_basis_stats = g_last_robust_basis_stats;
        g_last_augmented_robust_basis_stats.why = "no sound schema candidates; same as robust basis coverage";
    }

    g_last_proof_motif_plus_one_obstruction_certificates = build_proof_motif_plus_one_obstruction_certificates_(g_last_top_plus_one_failure_family_summaries, &why);
    g_last_basis_plus_one_direction_status = classify_basis_plus_one_direction_(g_last_robust_basis_stats,
                                                                                g_last_augmented_robust_basis_stats,
                                                                                g_last_sound_plus_one_schema_candidates,
                                                                                &g_last_basis_stabilization_n5_stats,
                                                                                &g_last_basis_stabilization_n6_c5_stats,
                                                                                &g_last_basis_stabilization_n7_c3_stats,
                                                                                g_last_family_level_plus_one_obstruction_certificates,
                                                                                &why);
    g_last_basis_plus_one_direction_ledger = build_basis_plus_one_direction_ledger_(g_last_robust_basis_stats,
                                                                                     g_last_augmented_robust_basis_stats,
                                                                                     g_last_exact_minimal_basis_plus_one_failure_witnesses,
                                                                                     g_last_plus_one_failure_inventories,
                                                                                     g_last_exact_minimal_basis_plus_one_failure_family_summaries,
                                                                                     g_last_schema_candidate_universe_stats,
                                                                                     g_last_basis_schema_compression_candidates,
                                                                                     g_last_sound_plus_one_schema_candidates,
                                                                                     g_last_proof_motif_plus_one_obstruction_certificates,
                                                                                     g_last_family_level_plus_one_obstruction_certificates,
                                                                                     g_last_basis_plus_one_direction_status);
}


