static GlobalSchemaCandidatePoolStats build_global_schema_candidate_pool_stats_(const vector<StructuredLocalSchema>& pool,
                                                                                string* why) {
    GlobalSchemaCandidatePoolStats stats;
    for (const auto& s : g_last_schema_candidate_universe_stats) {
        stats.raw_candidates += s.raw_candidates;
        stats.canonical_candidates += s.canonical_candidates;
    }
    stats.deduplicated_candidates = g_last_basis_schema_compression_candidates.size();
    stats.local_exact_survivors = pool.size();
    {
        set<string> plus_one_fp;
        for (const auto& cand : g_last_basis_schema_compression_candidates) {
            if (cand.local_exact_pass && cand.plus_one_pass) plus_one_fp.insert(cand.schema.fingerprint);
        }
        stats.plus_one_survivors = plus_one_fp.size();
    }
    vector<string> fps;
    for (const auto& s : pool) fps.push_back(s.fingerprint);
    sort(fps.begin(), fps.end());
    ostringstream fp;
    for (size_t i = 0; i < fps.size(); ++i) {
        if (i) fp << ";";
        fp << fps[i];
    }
    stats.fingerprint = fp.str();
    stats.why = "authoritative global schema candidate pool built from local-exact survivors of family-bounded candidate universe";
    if (why) *why = global_schema_candidate_pool_stats_to_string_(stats);
    return stats;
}

static vector<StructuredLocalSchema> exact_minimal_basis_global_schema_candidate_pool_() {
    if (!g_last_exact_minimal_basis_global_schema_candidate_pool.empty()) return g_last_exact_minimal_basis_global_schema_candidate_pool;
    string ready_why;
    if (!ensure_family_local_plus_one_schema_search_data_ready_(&ready_why)) {
        throw runtime_error(string("authoritative global schema candidate pool unavailable\n") + ready_why);
    }
    return g_last_exact_minimal_basis_global_schema_candidate_pool;
}

static string exact_minimal_basis_global_schema_candidate_pool_fingerprint_() {
    exact_minimal_basis_global_schema_candidate_pool_();
    return g_last_global_schema_candidate_pool_stats.fingerprint;
}


