static string solver_saturation_result_fingerprint_(const SolverSaturationResult& sat) {
    ostringstream oss;
    oss << (sat.oracle.satisfiable ? 'S' : 'U') << '|';
    bool first = true;
    for (const auto& kv : sat.closure_pairwise_lca) {
        if (!first) oss << ';';
        first = false;
        oss << kv.first.first << ',' << kv.first.second << ':' << kv.second;
    }
    oss << '|';
    first = true;
    for (const auto& c : sat.missing_forced_pairs) {
        if (!first) oss << ';';
        first = false;
        oss << c.u << ',' << c.v << "->" << c.w;
    }
    oss << '|';
    first = true;
    for (const auto& c : sat.extra_derived_pairs) {
        if (!first) oss << ';';
        first = false;
        oss << c.u << ',' << c.v << "->" << c.w;
    }
    return oss.str();
}

static string exact_domain_baseline_snapshot_fingerprint_(const ExactDomainBaselineSnapshot& snapshot) {
    ostringstream oss;
    oss << snapshot.domain_tag << '|' << snapshot.instances_checked << '|';
    for (size_t i = 0; i < snapshot.instance_fingerprints.size(); ++i) {
        if (i) oss << ';';
        oss << snapshot.instance_fingerprints[i] << '=' << snapshot.closure_fingerprints[i];
    }
    return oss.str();
}

static string exact_domain_baseline_snapshot_to_string_(const ExactDomainBaselineSnapshot& snapshot) {
    ostringstream oss;
    oss << "domain=" << snapshot.domain_tag
        << " instancesChecked=" << snapshot.instances_checked
        << " satisfiableStored=" << snapshot.satisfiable_instances.size();
    if (!snapshot.why.empty()) oss << " why=" << snapshot.why;
    return oss.str();
}

static ExactDomainBaselineSnapshot build_exact_minimal_basis_baseline_snapshot_from_instances_(const vector<SparseLcaInstance>& instances,
                                                                                                const vector<SparseRuleCandidate>& base_rules,
                                                                                                const vector<ProofMotif>& basis,
                                                                                                const string& domain_tag,
                                                                                                string* why) {
    ExactDomainBaselineSnapshot snapshot;
    snapshot.domain_tag = domain_tag;
    size_t progress_idx = 0;
    for (const auto& inst : instances) {
        ++progress_idx;
        local_progress_(domain_tag.c_str(), progress_idx, instances.size());
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        ++snapshot.instances_checked;
        if (!oracle.satisfiable) continue;
        auto sat = run_exact_minimal_basis_closure_(inst, base_rules, basis, nullptr);
        snapshot.satisfiable_instances.push_back(inst);
        snapshot.instance_fingerprints.push_back(canonical_sparse_instance_fingerprint_(inst));
        snapshot.closure_fingerprints.push_back(solver_saturation_result_fingerprint_(sat));
    }
    snapshot.why = "basis-only baseline snapshot built";
    if (why) *why = exact_domain_baseline_snapshot_to_string_(snapshot);
    return snapshot;
}

