static vector<StructuredLocalSchema> enumerate_out_of_pool_schema_candidates_for_failure_family_(const ProofMotifPlusOneFailureFamilySummary& family,
                                                                                                   int symbol_bound,
                                                                                                   int antecedent_bound,
                                                                                                   const vector<StructuredLocalSchema>& pool,
                                                                                                   string* why) {
    (void)pool;
    size_t raw = 0;
    string local_why;
    auto all = enumerate_schema_candidates_for_failure_family_(family, symbol_bound, antecedent_bound, &raw, &local_why);
    vector<StructuredLocalSchema> out;
    for (const auto& schema : all) {
        if (!schema_is_in_exact_minimal_basis_global_pool_(schema, nullptr)) out.push_back(schema);
    }
    if (why) *why = "family=" + family.family_fingerprint + " raw=" + to_string(raw) + " canonical=" + to_string(all.size()) + " outOfPool=" + to_string(out.size()) + " " + local_why;
    return out;
}

static vector<StructuredLocalSchema> enumerate_out_of_pool_merged_family_candidates_(const ProofMotifPlusOneFailureFamilySummary& fa,
                                                                                      const ProofMotifPlusOneFailureFamilySummary& fb,
                                                                                      int symbol_bound,
                                                                                      int antecedent_bound,
                                                                                      const vector<StructuredLocalSchema>& pool,
                                                                                      string* why) {
    (void)pool;
    map<tuple<int,int,int>, SchemaAtom> atom_map;
    auto add_constraint = [&](SparseLcaConstraint c) {
        c = normalize_sparse_constraint_(c);
        if (max(c.u, max(c.v, c.w)) > symbol_bound) return;
        SchemaAtom a{c.u, c.v, c.w};
        atom_map[{a.u, a.v, a.w}] = a;
    };
    for (const auto& w : g_last_exact_minimal_basis_plus_one_failure_witnesses) {
        if (w.family_fingerprint != fa.family_fingerprint && w.family_fingerprint != fb.family_fingerprint) continue;
        for (const auto& a : w.motif.premises) add_constraint({a.u, a.v, a.w});
        for (const auto& c : w.instance.constraints) add_constraint(c);
    }
    for (const auto& c : fa.representative_instance.constraints) add_constraint(c);
    for (const auto& c : fb.representative_instance.constraints) add_constraint(c);
    vector<SchemaAtom> pool_atoms;
    for (const auto& kv : atom_map) pool_atoms.push_back(kv.second);
    sort(pool_atoms.begin(), pool_atoms.end(), schema_atom_less_);
    vector<SchemaAtom> consequents;
    auto add_consequent = [&](SparseLcaConstraint c) {
        c = normalize_sparse_constraint_(c);
        if (max(c.u, max(c.v, c.w)) > symbol_bound) return;
        SchemaAtom a{c.u, c.v, c.w};
        for (const auto& ex : consequents) {
            if (ex.u == a.u && ex.v == a.v && ex.w == a.w) return;
        }
        consequents.push_back(a);
    };
    add_consequent(fa.representative_target);
    add_consequent(fb.representative_target);
    map<string, StructuredLocalSchema> uniq;
    size_t raw = 0;
    int max_pick = min<int>(antecedent_bound, (int)pool_atoms.size());
    for (const auto& consequent : consequents) {
        for (int need = 1; need <= max_pick; ++need) {
            vector<int> idxs;
            function<void(int,int)> dfs = [&](int start, int left) {
                if (left == 0) {
                    ++raw;
                    SchemaRule raw_rule;
                    raw_rule.num_symbols = max(symbol_bound, max(consequent.u, max(consequent.v, consequent.w)));
                    raw_rule.consequent = consequent;
                    bool tautological = false;
                    for (int idx : idxs) {
                        raw_rule.antecedents.push_back(pool_atoms[idx]);
                        if (pool_atoms[idx].u == consequent.u && pool_atoms[idx].v == consequent.v && pool_atoms[idx].w == consequent.w) tautological = true;
                    }
                    if (tautological) return;
                    auto canon = canonicalize_schema_rule_(raw_rule);
                    auto schema = schema_rule_to_structured_local_schema_(canon);
                    schema.support = fa.witness_count + fb.witness_count;
                    schema.human_readable = structured_local_schema_to_string_(schema);
                    uniq[schema.fingerprint] = schema;
                    return;
                }
                for (int i = start; i <= (int)pool_atoms.size() - left; ++i) {
                    idxs.push_back(i);
                    dfs(i + 1, left - 1);
                    idxs.pop_back();
                }
            };
            dfs(0, need);
        }
    }
    vector<StructuredLocalSchema> out;
    for (auto& kv : uniq) {
        if (!schema_is_in_exact_minimal_basis_global_pool_(kv.second, nullptr)) out.push_back(kv.second);
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.antecedents.size() != b.antecedents.size()) return a.antecedents.size() < b.antecedents.size();
        return a.fingerprint < b.fingerprint;
    });
    if (why) *why = "mergedFamilies=" + fa.family_fingerprint + " + " + fb.family_fingerprint + " raw=" + to_string(raw) + " canonical=" + to_string(uniq.size()) + " outOfPool=" + to_string(out.size());
    return out;
}


