static bool schema_refuted_on_instance_set_(const StructuredLocalSchema& schema,
                                             const vector<SparseLcaInstance>& instances,
                                             string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    auto symbols = schema_rule_used_symbols_(sr);
    for (const auto& inst : instances) {
        if (inst.n != schema_support_size_(sr) && inst.n != schema_support_size_(sr) + 1 && inst.n != 5 && inst.n != 6 && inst.n != 7) {
            ;
        }
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        bool bad = false;
        for_each_schema_embedding_(symbols, inst.n, [&](const vector<int>& mapping) {
            if (!schema_antecedents_hold_in_table_(sr, oracle.forced_pairwise_lca, mapping)) return false;
            auto cons = apply_mapping_to_schema_atom_(sr.consequent, mapping);
            auto it = oracle.forced_pairwise_lca.find({cons.u, cons.v});
            int forced = (it == oracle.forced_pairwise_lca.end()) ? -1 : it->second;
            if (forced != cons.w) {
                if (why) {
                    *why = string("instance-set refutation on ") + sparse_instance_to_string_(inst)
                         + " for schema " + schema.fingerprint
                         + " expected forced consequent " + sparse_constraint_to_string_(cons);
                }
                bad = true;
                return true;
            }
            return false;
        });
        if (bad) return true;
    }
    return false;
}

static vector<SparseLcaInstance> collect_quick_refutation_samples_for_target_n_(int target_n) {
    set<string> seen;
    vector<SparseLcaInstance> out;
    auto push_one = [&](const SparseLcaInstance& inst) {
        if (inst.n != target_n) return;
        string fp = canonical_sparse_instance_fingerprint_(inst);
        if (!seen.insert(fp).second) return;
        out.push_back(inst);
    };
    for (const auto& fam : exact_minimal_basis_plus_one_failure_family_summaries_()) push_one(fam.representative_instance);
    for (const auto& inv : g_last_plus_one_failure_inventories) {
        for (const auto& inst : inv.sample_instances) push_one(inst);
    }
    if (target_n == 9) {
        string pool_why;
        auto pool = build_support8_plus_one_target9_instance_pool_(&pool_why);
        size_t quick_limit = min<size_t>(256, pool.size());
        for (size_t i = 0; i < quick_limit; ++i) push_one(pool[i]);
    }
    return out;
}

static bool quick_refute_structured_local_schema_on_samples_(const StructuredLocalSchema& schema,
                                                             int target_n,
                                                             string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    auto symbols = schema_rule_used_symbols_(sr);
    auto samples = collect_quick_refutation_samples_for_target_n_(target_n);
    for (const auto& inst : samples) {
        string oracle_why;
        auto oracle = cached_exact_sparse_completion_oracle_(inst, numeric_limits<size_t>::max(), &oracle_why);
        if (!oracle.satisfiable) continue;
        bool bad = false;
        for_each_schema_embedding_(symbols, inst.n, [&](const vector<int>& mapping) {
            if (!schema_antecedents_hold_in_table_(sr, oracle.forced_pairwise_lca, mapping)) return false;
            auto cons = apply_mapping_to_schema_atom_(sr.consequent, mapping);
            auto it = oracle.forced_pairwise_lca.find({cons.u, cons.v});
            int forced = (it == oracle.forced_pairwise_lca.end()) ? -1 : it->second;
            if (forced != cons.w) {
                if (why) {
                    *why = string("quick refutation on sampled instance ") + sparse_instance_to_string_(inst)
                         + " for schema " + schema.fingerprint
                         + " expected forced consequent " + sparse_constraint_to_string_(cons);
                }
                bad = true;
                return true;
            }
            return false;
        });
        if (bad) return true;
    }
    return false;
}

static OutOfPoolSchemaValidationSummary validate_out_of_pool_schema_candidate_cached_(const StructuredLocalSchema& schema) {
    string fp = canonical_structured_local_schema_fingerprint_(schema);
    auto it = g_last_out_of_pool_schema_validation_cache.find(fp);
    if (it != g_last_out_of_pool_schema_validation_cache.end()) return it->second;
    OutOfPoolSchemaValidationSummary v;
    string local_why;
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int support = schema_support_size_(sr);
    if (support <= 0 || support > 6) {
        v.local_exact_pass = false;
        v.plus_one_pass = false;
        v.theorem_preserving_pass = false;
        v.why = "schema support size out of supported exact range";
        g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
        return v;
    }
    if (quick_refute_structured_local_schema_on_samples_(schema, support, &local_why)) {
        v.local_exact_pass = false;
        v.why = local_why;
        g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
        return v;
    }
    if (support == 5) {
        auto snap_n5 = build_exact_minimal_basis_baseline_snapshot_n5_(nullptr);
        if (schema_refuted_on_instance_set_(schema, snap_n5.satisfiable_instances, &local_why)) {
            v.local_exact_pass = false;
            v.why = local_why;
            g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
            return v;
        }
        v.local_exact_pass = true;
    } else {
        if (support == 6) {
            auto n6_instances = enumerate_bounded_instances_upto_constraints_(6, 5);
            if (schema_refuted_on_instance_set_(schema, n6_instances, &local_why)) {
                v.local_exact_pass = false;
                v.why = local_why;
                g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
                return v;
            }
        }
        v.local_exact_pass = validate_out_of_pool_schema_candidate_local_exact_(schema, &local_why);
    }
    if (v.local_exact_pass) {
        if (quick_refute_structured_local_schema_on_samples_(schema, support + 1, &local_why)) {
            v.plus_one_pass = false;
            v.why = local_why;
            g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
            return v;
        }
        if (support + 1 == 5) {
            auto snap_n5 = build_exact_minimal_basis_baseline_snapshot_n5_(nullptr);
            if (schema_refuted_on_instance_set_(schema, snap_n5.satisfiable_instances, &local_why)) {
                v.plus_one_pass = false;
                v.why = local_why;
                g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
                return v;
            }
            v.plus_one_pass = true;
        } else {
            if (support + 1 == 6) {
                auto n6_instances = enumerate_bounded_instances_upto_constraints_(6, 5);
                if (schema_refuted_on_instance_set_(schema, n6_instances, &local_why)) {
                    v.plus_one_pass = false;
                    v.why = local_why;
                    g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
                    return v;
                }
            }
            if (support + 1 == 7) {
                auto n7_instances = enumerate_bounded_instances_upto_constraints_(7, 3);
                if (schema_refuted_on_instance_set_(schema, n7_instances, &local_why)) {
                    v.plus_one_pass = false;
                    v.why = local_why;
                    g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
                    return v;
                }
            }
            v.plus_one_pass = validate_out_of_pool_schema_candidate_plus_one_exact_(schema, &local_why);
        }
    }
    if (v.local_exact_pass && v.plus_one_pass) {
        string p1, p2, p3;
        bool ok1 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n5_(schema, &p1);
        bool ok2 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n6_c5_(schema, &p2);
        bool ok3 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n7_c3_(schema, &p3);
        v.theorem_preserving_pass = ok1 && ok2 && ok3;
        if (!p1.empty()) v.why = p1;
        else if (!p2.empty()) v.why = p2;
        else if (!p3.empty()) v.why = p3;
        else if (!local_why.empty()) v.why = local_why;
    } else if (!local_why.empty()) {
        v.why = local_why;
    }
    g_last_out_of_pool_schema_validation_cache.emplace(fp, v);
    return v;
}

static OutOfPoolExpansionStats scan_out_of_pool_bounded_expansion_region_detailed_(const string& region_fp,
                                                                                    int symbol_bound,
                                                                                    int antecedent_bound,
                                                                                    size_t raw_candidates,
                                                                                    const vector<StructuredLocalSchema>& candidates,
                                                                                    const vector<SparseRuleCandidate>& base_rules,
                                                                                    vector<OutOfPoolExpansionCandidate>* out_candidates,
                                                                                    string* why) {
    (void)base_rules;
    OutOfPoolExpansionStats stats;
    stats.expansion_region_fingerprint = region_fp;
    stats.symbol_bound = symbol_bound;
    stats.antecedent_bound = antecedent_bound;
    stats.raw_candidates = raw_candidates;
    stats.canonical_candidates = candidates.size();
    stats.out_of_pool_candidates = candidates.size();
    for (size_t idx = 0; idx < candidates.size(); ++idx) {
        const auto& schema = candidates[idx];
#ifdef LOCAL_TEST
        if (idx == 0 || idx + 1 == candidates.size() || ((idx + 1) % 5 == 0)) {
            cerr << "stage: bounded expansion validate " << region_fp << " " << (idx + 1) << "/" << candidates.size() << "\n";
        }
#endif
        OutOfPoolExpansionCandidate cand;
        cand.expansion_region_fingerprint = region_fp;
        cand.schema = schema;
        auto summary = validate_out_of_pool_schema_candidate_cached_(schema);
        cand.local_exact_pass = summary.local_exact_pass;
        cand.plus_one_pass = summary.plus_one_pass;
        cand.theorem_preserving_pass = summary.theorem_preserving_pass;
        cand.why = summary.why;
        if (cand.local_exact_pass) ++stats.local_exact_survivors;
        if (cand.plus_one_pass) ++stats.plus_one_survivors;
        if (cand.theorem_preserving_pass) ++stats.theorem_preserving_survivors;
        if (out_candidates) out_candidates->push_back(cand);
    }
    stats.why = "bounded out-of-pool expansion region scanned";
    if (why) *why = out_of_pool_expansion_stats_to_string_(stats);
    return stats;
}

static OutOfPoolExpansionStats scan_out_of_pool_bounded_expansion_region_(const vector<StructuredLocalSchema>& candidates,
                                                                           const vector<SparseRuleCandidate>& base_rules,
                                                                           string* why) {
    vector<OutOfPoolExpansionCandidate> dummy;
    return scan_out_of_pool_bounded_expansion_region_detailed_("", 0, 0, candidates.size(), candidates, base_rules, &dummy, why);
}

static SchemaUniverseObstructionCertificate build_schema_universe_obstruction_certificate_(const CandidatePoolCompletenessStats& completeness,
                                                                                            const vector<OutOfPoolExpansionStats>& expansions,
                                                                                            string* why) {
    SchemaUniverseObstructionCertificate cert;
    cert.candidate_pool_complete_on_tested_universe = completeness.complete;
    bool found = false;
    for (const auto& e : expansions) if (e.theorem_preserving_survivors > 0) found = true;
    cert.out_of_pool_local_exact_survivors = g_last_out_of_pool_candidate_aggregate_stats.local_exact_survivors;
    cert.out_of_pool_plus_one_survivors = g_last_out_of_pool_candidate_aggregate_stats.plus_one_survivors;
    cert.out_of_pool_theorem_preserving_survivors = g_last_out_of_pool_candidate_aggregate_stats.theorem_preserving_survivors;
    cert.bounded_expansion_found_stabilizer = found || (g_last_out_of_pool_candidate_aggregate_stats.theorem_preserving_survivors > 0);
    const bool expansion_complete_for_claim = (g_last_bounded_expansion_region_specs.size() >= 28 && expansions.size() >= 28);
    if (cert.bounded_expansion_found_stabilizer) {
        cert.reason = "out-of-pool bounded expansion contains theorem-preserving plus-one-improving schema";
    } else if (completeness.complete && expansion_complete_for_claim && cert.out_of_pool_theorem_preserving_survivors == 0) {
        cert.reason = "candidate-pool completeness holds and all-family/all-pair bounded expansion found no theorem-preserving plus-one-improving out-of-pool schema";
    } else {
        cert.reason = "schema-universe obstruction not fully established";
    }
    if (why) *why = schema_universe_obstruction_certificate_to_string_(cert);
    return cert;
}

static string classify_candidate_pool_completeness_and_expansion_status_(const CandidatePoolCompletenessStats& completeness,
                                                                          const vector<OutOfPoolExpansionStats>& expansions,
                                                                          const SchemaUniverseObstructionCertificate& cert,
                                                                          string* why) {
    bool any_expansion_positive = false;
    for (const auto& e : expansions) if (e.theorem_preserving_survivors > 0) any_expansion_positive = true;
    const bool expansion_complete_for_claim = (g_last_bounded_expansion_region_specs.size() >= 28 && expansions.size() >= 28);
    if (any_expansion_positive || cert.out_of_pool_theorem_preserving_survivors > 0) {
        if (why) *why = "out-of-pool bounded expansion found theorem-preserving plus-one-improving candidate";
        return "bounded_pool_expansion_promising";
    }
    if (completeness.complete && expansion_complete_for_claim && cert.out_of_pool_theorem_preserving_survivors == 0) {
        if (why) *why = "candidate pool completeness holds on tested universe and all-family/all-pair bounded expansion found no stabilizer";
        return "support_bounded_schema_universe_obstruction_supported";
    }
    if (completeness.complete) {
        if (why) *why = "candidate pool completeness holds on tested universe; bounded expansion search remains partial";
        return "candidate_pool_completeness_supported";
    }
    if (why) *why = "completeness or bounded expansion remains unresolved";
    return "mixed_frontier_more_evidence_needed";
}

static string build_candidate_pool_completeness_and_expansion_ledger_(const CandidatePoolCompletenessStats& completeness,
                                                                       const vector<CandidatePoolCompletenessWitness>& witnesses,
                                                                       const vector<OutOfPoolExpansionStats>& expansions,
                                                                       const vector<OutOfPoolExpansionCandidate>& candidates,
                                                                       const SchemaUniverseObstructionCertificate& cert,
                                                                       const string& status) {
    ostringstream oss;
    oss << "candidatePoolCompleteness=" << candidate_pool_completeness_stats_to_string_(completeness) << "\n";
    oss << "candidatePoolCompletenessWitnesses=" << witnesses.size() << "\n";
    for (size_t i = 0; i < min<size_t>(witnesses.size(), 20); ++i) oss << "witness[" << i << "]=" << candidate_pool_completeness_witness_to_string_(witnesses[i]) << "\n";
    oss << "boundedExpansions=" << expansions.size() << "\n";
    for (size_t i = 0; i < expansions.size(); ++i) oss << "expansion[" << i << "]=" << out_of_pool_expansion_stats_to_string_(expansions[i]) << "\n";
    oss << "outOfPoolCandidatesExamined=" << candidates.size() << "\n";
    for (size_t i = 0; i < min<size_t>(candidates.size(), 20); ++i) oss << "candidate[" << i << "]=" << out_of_pool_expansion_candidate_to_string_(candidates[i]) << "\n";
    oss << "schemaUniverseObstruction=" << schema_universe_obstruction_certificate_to_string_(cert) << "\n";
    oss << "status=" << status << "\n";
    return oss.str();
}


static vector<BoundedExpansionRegionSpec> build_bounded_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                 string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    for (const auto& fam : families) {
        BoundedExpansionRegionSpec s;
        s.kind = "family_one_step";
        s.source_family_fingerprints = {fam.family_fingerprint};
        s.symbol_bound = min(representative_symbol_bound_for_failure_family_(fam) + 1, 7);
        s.antecedent_bound = 3;
        s.fingerprint = string("family-local:") + fam.family_fingerprint;
        specs.push_back(s);
    }
    for (size_t i = 0; i < families.size(); ++i) {
        for (size_t j = i + 1; j < families.size(); ++j) {
            BoundedExpansionRegionSpec s;
            s.kind = "pair_merged";
            s.source_family_fingerprints = {families[i].family_fingerprint, families[j].family_fingerprint};
            s.symbol_bound = min(representative_symbol_bound_for_failure_family_(families[i]) +
                                 representative_symbol_bound_for_failure_family_(families[j]), 7);
            s.antecedent_bound = 3;
            s.fingerprint = string("merged:") + families[i].family_fingerprint + string("||") + families[j].family_fingerprint;
            specs.push_back(s);
        }
    }
    if (why) *why = "bounded expansion region specs=" + to_string(specs.size());
    return specs;
}

static vector<BoundedExpansionRegionSpec> build_triple_family_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                       string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    for (size_t i = 0; i < families.size(); ++i) {
        for (size_t j = i + 1; j < families.size(); ++j) {
            for (size_t k = j + 1; k < families.size(); ++k) {
                BoundedExpansionRegionSpec s;
                s.kind = "triple_merged";
                s.source_family_fingerprints = {families[i].family_fingerprint, families[j].family_fingerprint, families[k].family_fingerprint};
                s.symbol_bound = min(representative_symbol_bound_for_failure_family_(families[i]) +
                                     representative_symbol_bound_for_failure_family_(families[j]) +
                                     representative_symbol_bound_for_failure_family_(families[k]), 7);
                s.antecedent_bound = 3;
                s.fingerprint = string("triple:") + families[i].family_fingerprint + string("||") + families[j].family_fingerprint + string("||") + families[k].family_fingerprint;
                specs.push_back(s);
            }
        }
    }
    if (why) *why = "triple family expansion region specs=" + to_string(specs.size());
    return specs;
}

static vector<BoundedExpansionRegionSpec> build_quadruple_family_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                          string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    for (size_t i = 0; i < families.size(); ++i) {
        for (size_t j = i + 1; j < families.size(); ++j) {
            for (size_t k = j + 1; k < families.size(); ++k) {
                for (size_t l = k + 1; l < families.size(); ++l) {
                    BoundedExpansionRegionSpec s;
                    s.kind = "quadruple_merged";
                    s.source_family_fingerprints = {families[i].family_fingerprint, families[j].family_fingerprint, families[k].family_fingerprint, families[l].family_fingerprint};
                    s.symbol_bound = min(representative_symbol_bound_for_failure_family_(families[i]) +
                                         representative_symbol_bound_for_failure_family_(families[j]) +
                                         representative_symbol_bound_for_failure_family_(families[k]) +
                                         representative_symbol_bound_for_failure_family_(families[l]), 7);
                    s.antecedent_bound = 3;
                    s.fingerprint = string("quadruple:") + families[i].family_fingerprint + string("||") + families[j].family_fingerprint + string("||") + families[k].family_fingerprint + string("||") + families[l].family_fingerprint;
                    specs.push_back(s);
                }
            }
        }
    }
    if (why) *why = "quadruple family expansion region specs=" + to_string(specs.size());
    return specs;
}

static vector<BoundedExpansionRegionSpec> build_quintuple_family_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                         string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    for (size_t i = 0; i < families.size(); ++i) {
        for (size_t j = i + 1; j < families.size(); ++j) {
            for (size_t k = j + 1; k < families.size(); ++k) {
                for (size_t l = k + 1; l < families.size(); ++l) {
                    for (size_t m = l + 1; m < families.size(); ++m) {
                        BoundedExpansionRegionSpec s;
                        s.kind = "quintuple_merged";
                        s.source_family_fingerprints = {families[i].family_fingerprint, families[j].family_fingerprint, families[k].family_fingerprint, families[l].family_fingerprint, families[m].family_fingerprint};
                        s.symbol_bound = min(representative_symbol_bound_for_failure_family_(families[i]) +
                                             representative_symbol_bound_for_failure_family_(families[j]) +
                                             representative_symbol_bound_for_failure_family_(families[k]) +
                                             representative_symbol_bound_for_failure_family_(families[l]) +
                                             representative_symbol_bound_for_failure_family_(families[m]), 7);
                        s.antecedent_bound = 3;
                        s.fingerprint = string("quintuple:") + families[i].family_fingerprint + string("||") + families[j].family_fingerprint + string("||") + families[k].family_fingerprint + string("||") + families[l].family_fingerprint + string("||") + families[m].family_fingerprint;
                        specs.push_back(s);
                    }
                }
            }
        }
    }
    if (why) *why = "quintuple family expansion region specs=" + to_string(specs.size());
    return specs;
}

static vector<BoundedExpansionRegionSpec> build_sextuple_family_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    for (size_t i = 0; i < families.size(); ++i) {
        vector<string> fps;
        int sym = 0;
        for (size_t j = 0; j < families.size(); ++j) if (j != i) {
            fps.push_back(families[j].family_fingerprint);
            sym += representative_symbol_bound_for_failure_family_(families[j]);
        }
        BoundedExpansionRegionSpec s;
        s.kind = "sextuple_merged";
        s.source_family_fingerprints = fps;
        s.symbol_bound = min(sym, 7);
        s.antecedent_bound = 3;
        s.fingerprint = "sextuple:";
        for (size_t k = 0; k < fps.size(); ++k) {
            if (k) s.fingerprint += "||";
            s.fingerprint += fps[k];
        }
        specs.push_back(s);
    }
    if (why) *why = "sextuple family expansion region specs=" + to_string(specs.size());
    return specs;
}

static vector<BoundedExpansionRegionSpec> build_septuple_family_expansion_region_specs_(const vector<ProofMotifPlusOneFailureFamilySummary>& families,
                                                                                string* why) {
    vector<BoundedExpansionRegionSpec> specs;
    BoundedExpansionRegionSpec s;
    s.kind = "septuple_merged";
    int sym = 0;
    s.fingerprint = "septuple:";
    for (size_t i = 0; i < families.size(); ++i) {
        s.source_family_fingerprints.push_back(families[i].family_fingerprint);
        sym += representative_symbol_bound_for_failure_family_(families[i]);
        if (i) s.fingerprint += "||";
        s.fingerprint += families[i].family_fingerprint;
    }
    s.symbol_bound = min(sym, 7);
    s.antecedent_bound = 3;
    specs.push_back(s);
    if (why) *why = "septuple family expansion region specs=" + to_string(specs.size());
    return specs;
}


