    vector<string> fps;
    fps.reserve(g_last_support_plus_one_local_exact_survivors.size());
    for (const auto& schema : g_last_support_plus_one_local_exact_survivors) fps.push_back(canonical_structured_local_schema_fingerprint_(schema));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    ostringstream oss;
