static vector<SparseLcaInstance> build_support8_plus_one_target9_instance_pool_(string* why) {
    auto survivors = support_plus_one_frontier_local_exact_survivors_();
    auto mixed_survivors = mixed_outside_bounded_frontier_local_exact_survivors_();
    map<string, SparseLcaInstance> uniq;
    auto absorb = [&](const vector<StructuredLocalSchema>& schemas) {
        for (const auto& schema : schemas) {
            string local_why;
            auto insts = collect_structured_schema_validation_instances_cached_(schema, 9, &local_why);
            for (const auto& inst : insts) uniq.emplace(canonical_sparse_instance_fingerprint_(inst.antecedent_instance), inst.antecedent_instance);
        }
    };
    absorb(survivors);
    absorb(mixed_survivors);
    vector<SparseLcaInstance> out;
    out.reserve(uniq.size());
    for (auto& kv : uniq) out.push_back(kv.second);
    if (why) *why = string("support8 target9 plus-one unique antecedent-only instances=") + to_string(out.size())
                  + " supportSurvivors=" + to_string(survivors.size())
                  + " mixedSurvivors=" + to_string(mixed_survivors.size());
    return out;
}

