static string serialize_forced_pairwise_lca_(const map<pair<int,int>, int>& forced) {
    ostringstream oss;
    bool first = true;
    for (const auto& kv : forced) {
        if (!first) oss << ';';
        first = false;
        oss << kv.first.first << ',' << kv.first.second << ',' << kv.second;
    }
    return oss.str();
}

static map<pair<int,int>, int> parse_forced_pairwise_lca_(const string& s) {
    map<pair<int,int>, int> out;
    size_t start = 0;
    while (start < s.size()) {
        size_t end = s.find(';', start);
        string token = s.substr(start, end == string::npos ? string::npos : end - start);
        if (!token.empty()) {
            vector<int> vals;
            size_t p = 0;
            while (p <= token.size()) {
                size_t comma = token.find(',', p);
                string part = token.substr(p, comma == string::npos ? string::npos : comma - p);
                if (!part.empty()) vals.push_back(stoi(part));
                if (comma == string::npos) break;
                p = comma + 1;
            }
            if (vals.size() == 3) out[{vals[0], vals[1]}] = vals[2];
        }
        if (end == string::npos) break;
        start = end + 1;
    }
    return out;
}

