static bool save_mixed_frontier_candidate_universe_(const vector<StructuredLocalSchema>& candidates, string* why) {
    ofstream fout(kMixedFrontierCandidateUniversePath);
    if (!fout) {
        if (why) *why = "failed to write mixed frontier candidate universe";
        return false;
    }
    vector<string> fps;
    fps.reserve(candidates.size());
    for (const auto& s : candidates) fps.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    for (const auto& fp : fps) fout << fp << '\n';
    if (why) *why = string("saved mixed frontier candidate universe=") + to_string(fps.size());
    return true;
}

static bool load_mixed_frontier_candidate_universe_(vector<StructuredLocalSchema>* candidates, string* why) {
    ifstream fin(kMixedFrontierCandidateUniversePath);
    if (!fin) {
        if (candidates) candidates->clear();
        if (why) *why = "no mixed frontier candidate universe file";
        return false;
    }
    vector<string> fps;
    string line;
    while (getline(fin, line)) if (!line.empty()) fps.push_back(line);
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    auto scope = build_bounded_schema_universe_scope_stats_(nullptr);
    auto spec = build_mixed_outside_bounded_frontier_spec_(scope, nullptr);
    auto all = enumerate_mixed_outside_bounded_frontier_candidates_(spec, nullptr);
    unordered_set<string> want(fps.begin(), fps.end());
    vector<StructuredLocalSchema> out;
    out.reserve(fps.size());
    for (const auto& s : all) {
        string fp = canonical_structured_local_schema_fingerprint_(s);
        if (want.count(fp)) out.push_back(s);
    }
    if (candidates) *candidates = out;
    if (why) *why = string("loaded mixed frontier candidate universe=") + to_string(out.size());
    return true;
}

static MixedOutsideBoundedCandidateTheoremData mixed_outside_bounded_candidate_theorem_data_() {
    MixedOutsideBoundedCandidateTheoremData d;
    vector<StructuredLocalSchema> candidates = g_last_mixed_outside_bounded_frontier_candidates;
    if (candidates.empty()) {
        string load_why;
        load_mixed_frontier_candidate_universe_(&candidates, &load_why);
        d.why = load_why;
    }
    auto scope = build_bounded_schema_universe_scope_stats_(nullptr);
    auto spec = build_mixed_outside_bounded_frontier_spec_(scope, nullptr);
    size_t raw = 0;
    string enum_why;
    auto all = enumerate_canonical_structured_local_schemas_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    d.raw_candidates = raw;
    d.canonical_candidates = all.size();
    d.outside_bounded_candidates = candidates.size();
    for (const auto& s : candidates) d.candidate_fingerprints.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end());
    d.candidate_fingerprints.erase(unique(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()), d.candidate_fingerprints.end());
    ostringstream oss;
    for (size_t i = 0; i < d.candidate_fingerprints.size(); ++i) { if (i) oss << ';'; oss << d.candidate_fingerprints[i]; }
    d.fingerprint = oss.str();
    if (d.why.empty()) d.why = enum_why;
    g_last_mixed_outside_bounded_candidate_theorem_data = d;
    return d;
}

