static SupportPlusOneFrontierPlusOneClosureStats build_support_plus_one_frontier_plus_one_closure_stats_(string* why) {
    SupportPlusOneFrontierPlusOneClosureStats stats;
    auto surv_data = support_plus_one_local_exact_survivor_theorem_data_();
    ensure_support8_plus_one_target9_caches_loaded_();
    stats.survivor_count = surv_data.survivor_count;
    const auto& surv = support_plus_one_frontier_local_exact_survivors_();
    for (const auto& fp : surv_data.survivor_fingerprints) {
        auto it = g_support8_plus_one_target9_result_cache.find(fp);
        if (it != g_support8_plus_one_target9_result_cache.end() && it->second.completed) {
            ++stats.completed_survivors;
            if (it->second.pass) {
                ++stats.plus_one_survivors;
                auto it_schema = find_if(surv.begin(), surv.end(), [&](const StructuredLocalSchema& s) {
                    return canonical_structured_local_schema_fingerprint_(s) == fp;
                });
                if (it_schema != surv.end()) {
                    string p1, p2, p3;
                    bool ok1 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n5_(*it_schema, &p1);
                    bool ok2 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n6_c5_(*it_schema, &p2);
                    bool ok3 = validate_out_of_pool_schema_candidate_preserves_basis_theorem_n7_c3_(*it_schema, &p3);
                    if (ok1 && ok2 && ok3) ++stats.theorem_preserving_survivors;
                }
            }
        }
    }
    stats.unsupported_plus_one_candidates = stats.survivor_count - stats.completed_survivors;
    stats.cache_hits = g_last_structured_schema_validation_cache_hits;
    stats.cache_misses = g_last_structured_schema_validation_cache_misses;
    stats.completed = (stats.unsupported_plus_one_candidates == 0);
    stats.why = string("support plus one plus-one closure completedSurvivors=") + to_string(stats.completed_survivors) + "/" + to_string(stats.survivor_count);
    g_last_support_plus_one_frontier_plus_one_closure_stats = stats;
    if (why) {
        ostringstream oss;
        oss << "supportPlusOnePlusOneClosure survivors=" << stats.survivor_count
            << " completedSurvivors=" << stats.completed_survivors
            << " plusOneSurvivors=" << stats.plus_one_survivors
            << " theoremPreservingSurvivors=" << stats.theorem_preserving_survivors
            << " unsupportedPlusOne=" << stats.unsupported_plus_one_candidates
            << " cacheHits=" << stats.cache_hits
            << " cacheMisses=" << stats.cache_misses
            << " completed=" << (stats.completed ? 1 : 0);
        if (!stats.why.empty()) oss << " why=" << stats.why;
        *why = oss.str();
    }
    return stats;
}

static string support_plus_one_frontier_plus_one_closure_stats_to_string_(const SupportPlusOneFrontierPlusOneClosureStats& stats) {
    ostringstream oss;
    oss << "supportPlusOnePlusOneClosure survivors=" << stats.survivor_count
        << " completedSurvivors=" << stats.completed_survivors
        << " plusOneSurvivors=" << stats.plus_one_survivors
        << " theoremPreservingSurvivors=" << stats.theorem_preserving_survivors
        << " unsupportedPlusOne=" << stats.unsupported_plus_one_candidates
        << " cacheHits=" << stats.cache_hits
        << " cacheMisses=" << stats.cache_misses
        << " completed=" << (stats.completed ? 1 : 0);
    if (!stats.why.empty()) oss << " why=" << stats.why;
    return oss.str();
}

static MixedOutsideBoundedFrontierSpec build_mixed_outside_bounded_frontier_spec_(const BoundedSchemaUniverseScopeStats& scope,
                                                                          string* why) {
    MixedOutsideBoundedFrontierSpec s;
    s.symbol_bound = scope.max_symbol_bound_tested + 1;
    s.antecedent_bound = scope.max_antecedent_bound_tested + 1;
    s.require_outside_bounded_scope = true;
    s.why = "minimal mixed frontier with symbol plus one and antecedent plus one";
    g_last_mixed_outside_bounded_frontier_spec = s;
    if (why) {
        ostringstream oss;
        oss << "mixedFrontierSpec symbolBound=" << s.symbol_bound
            << " antecedentBound=" << s.antecedent_bound
            << " requireOutside=" << (s.require_outside_bounded_scope ? 1 : 0)
            << " why=" << s.why;
        *why = oss.str();
    }
    return s;
}

static vector<StructuredLocalSchema> enumerate_mixed_outside_bounded_frontier_candidates_(const MixedOutsideBoundedFrontierSpec& spec,
                                                                                           string* why) {
    size_t raw = 0;
    string enum_why;
    auto all = enumerate_canonical_structured_local_schemas_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    string scope_why;
    auto scope = build_bounded_schema_universe_scope_stats_(&scope_why);
    vector<StructuredLocalSchema> out;
    out.reserve(all.size());
    for (const auto& schema : all) {
        string within_why;
        bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
        if (spec.require_outside_bounded_scope && within) continue;
        out.push_back(schema);
    }
    if (why) {
        ostringstream oss;
        oss << "mixedOutsideBoundedFrontier raw=" << raw
            << " canonical=" << all.size()
            << " outsideBounded=" << out.size();
        if (!enum_why.empty()) oss << " ; " << enum_why;
        *why = oss.str();
    }
    return out;
}

