static bool load_mixed_frontier_local_exact_survivors_(vector<StructuredLocalSchema>* survivors, string* why) {
    ifstream fin(kMixedFrontierLocalExactSurvivorPath);
    if (!fin) {
        if (survivors) survivors->clear();
        if (why) *why = "no mixed frontier local exact survivor file";
        return false;
    }
    vector<string> fps;
    string line;
    while (getline(fin, line)) if (!line.empty()) fps.push_back(line);
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    string spec_why;
    auto scope = build_bounded_schema_universe_scope_stats_(nullptr);
    auto spec = build_mixed_outside_bounded_frontier_spec_(scope, &spec_why);
    auto all = enumerate_mixed_outside_bounded_frontier_candidates_(spec, nullptr);
    vector<StructuredLocalSchema> out;
    unordered_set<string> want(fps.begin(), fps.end());
    for (const auto& s : all) {
        string fp = canonical_structured_local_schema_fingerprint_(s);
        if (want.count(fp)) out.push_back(s);
    }
    if (survivors) *survivors = out;
    if (why) *why = string("loaded mixed frontier local exact survivors=") + to_string(out.size());
    return true;
}

