static bool load_support8_local_exact_antecedent_index_(vector<Support8LocalExactAntecedentIndexEntry>* entries, string* why) {
    ifstream fin(kSupport8LocalExactAntecedentIndexPath);
    if (!fin) {
        if (entries) entries->clear();
        if (why) *why = "no support8 local exact antecedent index file";
        return false;
    }
    map<string, Support8LocalExactAntecedentIndexEntry> grouped;
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        vector<string> parts;
        size_t pos = 0;
        while (true) {
            size_t tab = line.find('	', pos);
            if (tab == string::npos) { parts.push_back(line.substr(pos)); break; }
            parts.push_back(line.substr(pos, tab - pos));
            pos = tab + 1;
        }
        if (parts.size() < 5) continue;
        auto& slot = grouped[parts[0]];
        slot.schema_fingerprint = parts[0];
        Support8LocalExactAntecedentIndexItem item;
        item.antecedent_quotient_fingerprint = parts[1];
        item.consequent.u = stoi(parts[2]);
        item.consequent.v = stoi(parts[3]);
        item.consequent.w = stoi(parts[4]);
        slot.items.push_back(item);
    }
    vector<Support8LocalExactAntecedentIndexEntry> out;
    for (auto& kv : grouped) {
        auto& e = kv.second;
        sort(e.items.begin(), e.items.end(), [](const auto& a, const auto& b) {
            if (a.antecedent_quotient_fingerprint != b.antecedent_quotient_fingerprint)
                return a.antecedent_quotient_fingerprint < b.antecedent_quotient_fingerprint;
            if (a.consequent.u != b.consequent.u) return a.consequent.u < b.consequent.u;
            if (a.consequent.v != b.consequent.v) return a.consequent.v < b.consequent.v;
            return a.consequent.w < b.consequent.w;
        });
        out.push_back(std::move(e));
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b){ return a.schema_fingerprint < b.schema_fingerprint; });
    if (entries) *entries = out;
    if (why) *why = string("loaded support8 local exact antecedent index schemaCount=") + to_string(out.size());
    return true;
}

static bool save_support8_local_exact_antecedent_index_(const vector<Support8LocalExactAntecedentIndexEntry>& entries, string* why) {
    ofstream fout(kSupport8LocalExactAntecedentIndexPath);
    if (!fout) {
        if (why) *why = "failed to write support8 local exact antecedent index";
        return false;
    }
    size_t rows = 0;
    for (const auto& e : entries) {
        for (const auto& item : e.items) {
            fout << e.schema_fingerprint << '	' << item.antecedent_quotient_fingerprint << '	'
                 << item.consequent.u << '	' << item.consequent.v << '	' << item.consequent.w << '\n';
            ++rows;
        }
    }
    if (why) *why = string("saved support8 local exact antecedent index rows=") + to_string(rows);
    return true;
}

static bool build_support8_local_exact_antecedent_index_(const vector<StructuredLocalSchema>& candidates, string* why) {
    map<string, Support8LocalExactAntecedentIndexEntry> grouped;
    size_t rows = 0;
    for (size_t i = 0; i < candidates.size(); ++i) {
#ifdef LOCAL_TEST
        local_progress_("support8_local_exact_antecedent_index", i + 1, candidates.size());
#endif
        const auto& schema = candidates[i];
        string schema_fp = canonical_structured_local_schema_fingerprint_(schema);
        string local_why;
        auto insts = collect_structured_schema_validation_instances_cached_(schema, 8, &local_why);
        auto& entry = grouped[schema_fp];
        entry.schema_fingerprint = schema_fp;
        for (const auto& inst : insts) {
            auto canon = canonicalize_support8_plus_one_antecedent_only_instance_(inst.antecedent_instance);
            Support8LocalExactAntecedentIndexItem item;
            item.antecedent_quotient_fingerprint = canon.quotient_fingerprint;
            item.consequent = map_consequent_under_antecedent_only_canonicalization_(inst.instantiated_consequent, canon);
            entry.items.push_back(item);
            ++rows;
        }
    }
    vector<Support8LocalExactAntecedentIndexEntry> entries;
    for (auto& kv : grouped) {
        auto& e = kv.second;
        sort(e.items.begin(), e.items.end(), [](const auto& a, const auto& b){
            if (a.antecedent_quotient_fingerprint != b.antecedent_quotient_fingerprint)
                return a.antecedent_quotient_fingerprint < b.antecedent_quotient_fingerprint;
            if (a.consequent.u != b.consequent.u) return a.consequent.u < b.consequent.u;
            if (a.consequent.v != b.consequent.v) return a.consequent.v < b.consequent.v;
            return a.consequent.w < b.consequent.w;
        });
        e.items.erase(unique(e.items.begin(), e.items.end(), [](const auto& a, const auto& b){
            return a.antecedent_quotient_fingerprint == b.antecedent_quotient_fingerprint &&
                   a.consequent.u == b.consequent.u && a.consequent.v == b.consequent.v && a.consequent.w == b.consequent.w;
        }), e.items.end());
        entries.push_back(std::move(e));
    }
    sort(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.schema_fingerprint < b.schema_fingerprint; });
    string save_why;
    bool ok = save_support8_local_exact_antecedent_index_(entries, &save_why);
    if (ok) {
        g_support8_local_exact_antecedent_index_entries = entries;
        g_support8_local_exact_antecedent_index_index.clear();
        for (size_t i = 0; i < entries.size(); ++i) g_support8_local_exact_antecedent_index_index[entries[i].schema_fingerprint] = i;
        g_support8_local_exact_antecedent_index_loaded = true;
    }
    if (why) {
        ostringstream oss;
        oss << "support8 local exact antecedent index rows=" << rows;
        if (!save_why.empty()) oss << " ; " << save_why;
        *why = oss.str();
    }
    return ok;
}

static void ensure_support8_local_exact_antecedent_index_loaded_() {
    if (g_support8_local_exact_antecedent_index_loaded) return;
    string why;
    if (!load_support8_local_exact_antecedent_index_(&g_support8_local_exact_antecedent_index_entries, &why)) {
        g_support8_local_exact_antecedent_index_entries.clear();
    }
    g_support8_local_exact_antecedent_index_index.clear();
    for (size_t i = 0; i < g_support8_local_exact_antecedent_index_entries.size(); ++i)
        g_support8_local_exact_antecedent_index_index[g_support8_local_exact_antecedent_index_entries[i].schema_fingerprint] = i;
    g_support8_local_exact_antecedent_index_loaded = true;
}

static bool load_support8_local_exact_oracle_snapshot_(vector<Support8LocalExactOracleSnapshotEntry>* entries, string* why) {
    ifstream fin(kSupport8LocalExactOracleSnapshotPath);
    if (!fin) {
        if (entries) entries->clear();
        if (why) *why = "no support8 local exact oracle snapshot";
        return false;
    }
    vector<Support8LocalExactOracleSnapshotEntry> out;
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        vector<string> parts;
        size_t pos = 0;
        while (true) {
            size_t tab = line.find('	', pos);
            if (tab == string::npos) { parts.push_back(line.substr(pos)); break; }
            parts.push_back(line.substr(pos, tab - pos));
            pos = tab + 1;
        }
        if (parts.size() < 4) continue;
        Support8LocalExactOracleSnapshotEntry e;
        e.antecedent_quotient_fingerprint = parts[0];
        e.satisfiable = (parts[1] == "1");
        e.forced_pairwise_lca = parse_forced_pairwise_lca_(parts[2]);
        e.why = parts[3];
        out.push_back(std::move(e));
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint < b.antecedent_quotient_fingerprint; });
    out.erase(unique(out.begin(), out.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint == b.antecedent_quotient_fingerprint; }), out.end());
    if (entries) *entries = out;
    if (why) *why = string("loaded support8 local exact oracle snapshot entries=") + to_string(out.size());
    return true;
}

static bool save_support8_local_exact_oracle_snapshot_(const vector<Support8LocalExactOracleSnapshotEntry>& entries, string* why) {
    ofstream fout(kSupport8LocalExactOracleSnapshotPath);
    if (!fout) {
        if (why) *why = "failed to write support8 local exact oracle snapshot";
        return false;
    }
    for (const auto& e : entries) {
        fout << e.antecedent_quotient_fingerprint << '	'
             << (e.satisfiable ? 1 : 0) << '	'
             << sanitize_tsv_field_(serialize_forced_pairwise_lca_(e.forced_pairwise_lca)) << '	'
             << sanitize_tsv_field_(e.why) << '\n';
    }
    if (why) *why = string("saved support8 local exact oracle snapshot entries=") + to_string(entries.size());
    return true;
}

static string support8_local_exact_oracle_snapshot_fingerprint_(const vector<Support8LocalExactOracleSnapshotEntry>& entries) {
    vector<string> fps;
    fps.reserve(entries.size());
    for (const auto& e : entries) fps.push_back(e.antecedent_quotient_fingerprint + "|" + (e.satisfiable ? "1" : "0") + "|" + serialize_forced_pairwise_lca_(e.forced_pairwise_lca));
    sort(fps.begin(), fps.end());
    ostringstream oss;
    for (size_t i = 0; i < fps.size(); ++i) { if (i) oss << ';'; oss << fps[i]; }
    return oss.str();
}

static Support8LocalExactOracleSnapshotStats build_support8_local_exact_oracle_snapshot_stats_(string* why) {
    Support8LocalExactOracleSnapshotStats stats;
    vector<Support8LocalExactOracleSnapshotEntry> entries;
    string local_why;
    load_support8_local_exact_oracle_snapshot_(&entries, &local_why);
    stats.total_quotient_classes = entries.size();
    for (const auto& e : entries) if (e.satisfiable) ++stats.satisfiable_classes;
    stats.fingerprint = support8_local_exact_oracle_snapshot_fingerprint_(entries);
    stats.why = local_why;
    g_last_support8_local_exact_oracle_snapshot_stats = stats;
    if (why) {
        ostringstream oss;
        oss << "support8LocalExactOracleSnapshot totalQuotientClasses=" << stats.total_quotient_classes
            << " satisfiableClasses=" << stats.satisfiable_classes
            << " fingerprint=" << stats.fingerprint;
        if (!stats.why.empty()) oss << " why=" << stats.why;
        *why = oss.str();
    }
    return stats;
}

static bool build_support8_local_exact_oracle_snapshot_(string* why) {
    vector<Support8LocalExactAntecedentIndexEntry> idx_entries;
    string idx_why;
    if (!load_support8_local_exact_antecedent_index_(&idx_entries, &idx_why)) {
        if (why) *why = idx_why;
        return false;
    }
    unordered_set<string> want;
    for (const auto& e : idx_entries) for (const auto& item : e.items) want.insert(item.antecedent_quotient_fingerprint);

    vector<Support8LocalExactOracleSnapshotEntry> entries;
    string load_why;
    load_support8_local_exact_oracle_snapshot_(&entries, &load_why);
    entries.erase(remove_if(entries.begin(), entries.end(), [&](const auto& e){ return !want.count(e.antecedent_quotient_fingerprint); }), entries.end());
    sort(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint < b.antecedent_quotient_fingerprint; });
    entries.erase(unique(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint == b.antecedent_quotient_fingerprint; }), entries.end());
    unordered_set<string> have;
    for (const auto& e : entries) have.insert(e.antecedent_quotient_fingerprint);
    vector<string> missing;
    for (const auto& fp : want) if (!have.count(fp)) missing.push_back(fp);
    sort(missing.begin(), missing.end());

    const size_t batch_size = 16;
    auto start = chrono::steady_clock::now();
    const double time_budget_sec = 85.0;
    size_t processed_now = 0;
    for (size_t start_idx = 0; start_idx < missing.size(); start_idx += batch_size) {
        double elapsed = chrono::duration<double>(chrono::steady_clock::now() - start).count();
        if (elapsed > time_budget_sec && processed_now > 0) break;
        size_t end_idx = min(missing.size(), start_idx + batch_size);
        vector<SparseLcaInstance> batch;
        batch.reserve(end_idx - start_idx);
        for (size_t i = start_idx; i < end_idx; ++i) batch.push_back(parse_sparse_instance_from_string_local_(missing[i]));
#ifdef LOCAL_TEST
        local_progress_("support8_local_exact_oracle_snapshot", start_idx + batch.size(), missing.size());
#endif
        string prewarm_why;
        if (!prewarm_exact_sparse_completion_oracle_batch_same_n_(batch, &prewarm_why)) {
            if (why) *why = prewarm_why;
            return false;
        }
        for (size_t i = 0; i < batch.size(); ++i) {
            string oracle_why;
            auto oracle = cached_exact_sparse_completion_oracle_(batch[i], numeric_limits<size_t>::max(), &oracle_why);
            Support8LocalExactOracleSnapshotEntry e;
            e.antecedent_quotient_fingerprint = missing[start_idx + i];
            e.satisfiable = oracle.satisfiable;
            e.forced_pairwise_lca = oracle.forced_pairwise_lca;
            e.why = oracle_why;
            entries.push_back(std::move(e));
            ++processed_now;
        }
        sort(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint < b.antecedent_quotient_fingerprint; });
        entries.erase(unique(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.antecedent_quotient_fingerprint == b.antecedent_quotient_fingerprint; }), entries.end());
        string save_why;
        save_support8_local_exact_oracle_snapshot_(entries, &save_why);
    }
    string final_save_why;
    save_support8_local_exact_oracle_snapshot_(entries, &final_save_why);
    g_support8_local_exact_oracle_snapshot_entries = entries;
    g_support8_local_exact_oracle_snapshot_index.clear();
    for (size_t i = 0; i < entries.size(); ++i) g_support8_local_exact_oracle_snapshot_index[entries[i].antecedent_quotient_fingerprint] = i;
    g_support8_local_exact_oracle_snapshot_loaded = true;
    string stats_why;
    auto stats = build_support8_local_exact_oracle_snapshot_stats_(&stats_why);
    if (why) {
        ostringstream oss;
        oss << idx_why
            << " ; existing=" << (entries.size() - processed_now)
            << " newlyBuilt=" << processed_now
            << " missingQuotientClasses=" << missing.size()
            << " ; " << stats_why;
        *why = oss.str();
    }
    return true;
}

static void ensure_support8_local_exact_oracle_snapshot_loaded_() {
    if (g_support8_local_exact_oracle_snapshot_loaded) return;
    string why;
    if (!load_support8_local_exact_oracle_snapshot_(&g_support8_local_exact_oracle_snapshot_entries, &why)) {
        g_support8_local_exact_oracle_snapshot_entries.clear();
    }
    g_support8_local_exact_oracle_snapshot_index.clear();
    for (size_t i = 0; i < g_support8_local_exact_oracle_snapshot_entries.size(); ++i)
        g_support8_local_exact_oracle_snapshot_index[g_support8_local_exact_oracle_snapshot_entries[i].antecedent_quotient_fingerprint] = i;
    g_support8_local_exact_oracle_snapshot_loaded = true;
}

static Support8LocalExactAntecedentIndexStats build_support8_local_exact_antecedent_index_stats_(string* why) {
    Support8LocalExactAntecedentIndexStats stats;
    vector<Support8LocalExactAntecedentIndexEntry> entries;
    string local_why;
    load_support8_local_exact_antecedent_index_(&entries, &local_why);
    stats.antecedent_count = entries.size();
    unordered_set<string> qfps;
    size_t rows = 0;
    vector<string> parts;
    for (const auto& e : entries) {
        for (const auto& item : e.items) { qfps.insert(item.antecedent_quotient_fingerprint); ++rows; }
    }
    stats.indexed_instances = rows;
    vector<string> keys(qfps.begin(), qfps.end());
    sort(keys.begin(), keys.end());
    ostringstream oss;
    for (size_t i = 0; i < keys.size(); ++i) { if (i) oss << ';'; oss << keys[i]; }
    stats.fingerprint = oss.str();
    stats.why = local_why;
    g_last_support8_local_exact_antecedent_index_stats = stats;
    if (why) {
        ostringstream s;
        s << "support8LocalExactAntecedentIndex antecedentCount=" << stats.antecedent_count
          << " indexedInstances=" << stats.indexed_instances
          << " fingerprint=" << stats.fingerprint;
        if (!stats.why.empty()) s << " why=" << stats.why;
        *why = s.str();
    }
    return stats;
}

static string support8_local_exact_antecedent_index_fingerprint_(const vector<Support8LocalExactAntecedentIndexEntry>& entries) {
    vector<string> parts;
    for (const auto& e : entries) {
        for (const auto& item : e.items) {
            parts.push_back(e.schema_fingerprint + "|" + item.antecedent_quotient_fingerprint + "|" + to_string(item.consequent.u) + "," + to_string(item.consequent.v) + "->" + to_string(item.consequent.w));
        }
    }
    sort(parts.begin(), parts.end());
    ostringstream oss;
    for (size_t i = 0; i < parts.size(); ++i) { if (i) oss << ';'; oss << parts[i]; }
    return oss.str();
}

static bool validate_mixed_frontier_schema_local_exact_via_snapshot_(const StructuredLocalSchema& schema, string* why) {
    ensure_support8_local_exact_oracle_snapshot_loaded_();
    ensure_support8_local_exact_antecedent_index_loaded_();
    const string schema_fp = canonical_structured_local_schema_fingerprint_(schema);
    auto it_schema = g_support8_local_exact_antecedent_index_index.find(schema_fp);
    if (it_schema == g_support8_local_exact_antecedent_index_index.end()) {
        if (why) *why = string("mixed frontier support8 local exact antecedent index missing schema ") + schema_fp;
        return false;
    }
    const auto& entry = g_support8_local_exact_antecedent_index_entries[it_schema->second];
    for (const auto& item : entry.items) {
        auto it_snap = g_support8_local_exact_oracle_snapshot_index.find(item.antecedent_quotient_fingerprint);
        if (it_snap == g_support8_local_exact_oracle_snapshot_index.end()) {
            if (why) *why = string("support8 local exact oracle snapshot incomplete for quotient antecedent ") + item.antecedent_quotient_fingerprint;
            return false;
        }
        const auto& snap = g_support8_local_exact_oracle_snapshot_entries[it_snap->second];
        if (!snap.satisfiable) {
            if (why) *why = string("support8 local exact antecedent quotient unexpectedly unsatisfiable: ") + item.antecedent_quotient_fingerprint;
            return false;
        }
        int u = min(item.consequent.u, item.consequent.v);
        int v = max(item.consequent.u, item.consequent.v);
        auto it_forced = snap.forced_pairwise_lca.find({u, v});
        if (it_forced == snap.forced_pairwise_lca.end() || it_forced->second != item.consequent.w) {
            if (why) {
                *why = string("mixed frontier local exact failed for schema ") + schema_fp
                     + " on antecedent quotient " + item.antecedent_quotient_fingerprint
                     + " expected consequent " + sparse_constraint_to_string_(item.consequent)
                     + "; forced value=" + (it_forced == snap.forced_pairwise_lca.end() ? string("<missing>") : to_string(it_forced->second));
            }
            return false;
        }
    }
    if (why) *why = string("mixed frontier local exact validated antecedent items=") + to_string(entry.items.size());
    return true;
}

static bool load_mixed_frontier_antecedent_quotient_index_(vector<SupportPlusOneAntecedentIndexEntry>* entries, string* why) {
    ifstream fin(kMixedFrontierAntecedentIndexPath);
    if (!fin) {
        if (entries) entries->clear();
        if (why) *why = "no mixed frontier antecedent index file";
        return false;
    }
    map<string, SupportPlusOneAntecedentIndexEntry> grouped;
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        vector<string> parts;
        size_t pos = 0;
        while (true) {
            size_t tab = line.find('	', pos);
            if (tab == string::npos) { parts.push_back(line.substr(pos)); break; }
            parts.push_back(line.substr(pos, tab - pos));
            pos = tab + 1;
        }
        if (parts.size() < 5) continue;
        auto& slot = grouped[parts[0]];
        slot.schema_fingerprint = parts[0];
        SupportPlusOneAntecedentIndexItem item;
        item.antecedent_instance_fingerprint = parts[1];
        item.consequent.u = stoi(parts[2]);
        item.consequent.v = stoi(parts[3]);
        item.consequent.w = stoi(parts[4]);
        slot.items.push_back(item);
    }
    vector<SupportPlusOneAntecedentIndexEntry> out;
    for (auto& kv : grouped) {
        auto& e = kv.second;
        sort(e.items.begin(), e.items.end(), [](const auto& a, const auto& b) {
            if (a.antecedent_instance_fingerprint != b.antecedent_instance_fingerprint)
                return a.antecedent_instance_fingerprint < b.antecedent_instance_fingerprint;
            if (a.consequent.u != b.consequent.u) return a.consequent.u < b.consequent.u;
            if (a.consequent.v != b.consequent.v) return a.consequent.v < b.consequent.v;
            return a.consequent.w < b.consequent.w;
        });
        out.push_back(std::move(e));
    }
    sort(out.begin(), out.end(), [](const auto& a, const auto& b){ return a.schema_fingerprint < b.schema_fingerprint; });
    if (entries) *entries = out;
    if (why) *why = string("loaded mixed frontier antecedent index schemaCount=") + to_string(out.size());
    return true;
}

static bool save_mixed_frontier_antecedent_quotient_index_(const vector<SupportPlusOneAntecedentIndexEntry>& entries, string* why) {
    ofstream fout(kMixedFrontierAntecedentIndexPath);
    if (!fout) {
        if (why) *why = "failed to write mixed frontier antecedent index";
        return false;
    }
    size_t rows = 0;
    for (const auto& e : entries) {
        for (const auto& item : e.items) {
            fout << e.schema_fingerprint << '	' << item.antecedent_instance_fingerprint << '	'
                 << item.consequent.u << '\t' << item.consequent.v << '\t' << item.consequent.w << '\n';
            ++rows;
        }
    }
    if (why) *why = string("saved mixed frontier antecedent index rows=") + to_string(rows);
    return true;
}

static bool build_mixed_frontier_antecedent_quotient_index_(const vector<StructuredLocalSchema>& survivors,
                                                             string* why) {
    map<string, SupportPlusOneAntecedentIndexEntry> grouped;
    size_t rows = 0;
    for (size_t i = 0; i < survivors.size(); ++i) {
#ifdef LOCAL_TEST
        local_progress_("mixed_frontier_antecedent_index", i + 1, survivors.size());
#endif
        const auto& schema = survivors[i];
        string schema_fp = canonical_structured_local_schema_fingerprint_(schema);
        string local_why;
        auto insts = collect_structured_schema_validation_instances_cached_(schema, 9, &local_why);
        auto& entry = grouped[schema_fp];
        entry.schema_fingerprint = schema_fp;
        for (const auto& inst : insts) {
            auto canon = canonicalize_support8_plus_one_antecedent_only_instance_(inst.antecedent_instance);
            SupportPlusOneAntecedentIndexItem item;
            item.antecedent_instance_fingerprint = canon.quotient_fingerprint;
            item.consequent = map_consequent_under_antecedent_only_canonicalization_(inst.instantiated_consequent, canon);
            entry.items.push_back(item);
            ++rows;
        }
    }
    vector<SupportPlusOneAntecedentIndexEntry> entries;
    for (auto& kv : grouped) {
        auto& e = kv.second;
        sort(e.items.begin(), e.items.end(), [](const auto& a, const auto& b) {
            if (a.antecedent_instance_fingerprint != b.antecedent_instance_fingerprint)
                return a.antecedent_instance_fingerprint < b.antecedent_instance_fingerprint;
            if (a.consequent.u != b.consequent.u) return a.consequent.u < b.consequent.u;
            if (a.consequent.v != b.consequent.v) return a.consequent.v < b.consequent.v;
            return a.consequent.w < b.consequent.w;
        });
        e.items.erase(unique(e.items.begin(), e.items.end(), [](const auto& a, const auto& b){
            return a.antecedent_instance_fingerprint == b.antecedent_instance_fingerprint &&
                   a.consequent.u == b.consequent.u && a.consequent.v == b.consequent.v && a.consequent.w == b.consequent.w;
        }), e.items.end());
        entries.push_back(std::move(e));
    }
    sort(entries.begin(), entries.end(), [](const auto& a, const auto& b){ return a.schema_fingerprint < b.schema_fingerprint; });
    string save_why;
    bool ok = save_mixed_frontier_antecedent_quotient_index_(entries, &save_why);
    if (ok) {
        g_mixed_frontier_antecedent_index_entries = entries;
        g_mixed_frontier_antecedent_index_index.clear();
        for (size_t i = 0; i < entries.size(); ++i) g_mixed_frontier_antecedent_index_index[entries[i].schema_fingerprint] = i;
        g_mixed_frontier_antecedent_index_loaded = true;
    }
    if (why) {
        ostringstream oss;
        oss << "mixed frontier antecedent quotient index rows=" << rows;
        if (!save_why.empty()) oss << " ; " << save_why;
        *why = oss.str();
    }
    return ok;
}

static void ensure_mixed_frontier_antecedent_index_loaded_() {
    if (g_mixed_frontier_antecedent_index_loaded) return;
    string why;
    if (!load_mixed_frontier_antecedent_quotient_index_(&g_mixed_frontier_antecedent_index_entries, &why)) {
        g_mixed_frontier_antecedent_index_entries.clear();
    }
    g_mixed_frontier_antecedent_index_index.clear();
    for (size_t i = 0; i < g_mixed_frontier_antecedent_index_entries.size(); ++i) g_mixed_frontier_antecedent_index_index[g_mixed_frontier_antecedent_index_entries[i].schema_fingerprint] = i;
    g_mixed_frontier_antecedent_index_loaded = true;
}

static bool validate_mixed_frontier_schema_plus_one_exact_(const StructuredLocalSchema& schema, string* why) {
    string snap_why;
    if (!build_support8_plus_one_target9_oracle_snapshot_(&snap_why)) {
        if (why) *why = snap_why;
        return false;
    }
    ensure_mixed_frontier_antecedent_index_loaded_();
    const string schema_fp = canonical_structured_local_schema_fingerprint_(schema);
    auto it_schema = g_mixed_frontier_antecedent_index_index.find(schema_fp);
    if (it_schema == g_mixed_frontier_antecedent_index_index.end()) {
        if (why) *why = string("mixed frontier antecedent index missing schema ") + schema_fp;
        return false;
    }
    const auto& entry = g_mixed_frontier_antecedent_index_entries[it_schema->second];
    for (const auto& item : entry.items) {
        auto it_snap = g_support8_plus_one_target9_oracle_snapshot_index.find(item.antecedent_instance_fingerprint);
        if (it_snap == g_support8_plus_one_target9_oracle_snapshot_index.end()) {
            if (why) *why = string("mixed frontier oracle snapshot incomplete for quotient antecedent ") + item.antecedent_instance_fingerprint;
            return false;
        }
        const auto& snap = g_support8_plus_one_target9_oracle_snapshot_entries[it_snap->second];
        if (!snap.satisfiable) {
            if (why) *why = string("mixed frontier antecedent quotient unexpectedly unsatisfiable: ") + item.antecedent_instance_fingerprint;
            return false;
        }
        int u = min(item.consequent.u, item.consequent.v);
        int v = max(item.consequent.u, item.consequent.v);
        auto it_forced = snap.forced_pairwise_lca.find({u, v});
        if (it_forced == snap.forced_pairwise_lca.end() || it_forced->second != item.consequent.w) {
            if (why) {
                *why = string("mixed frontier plus-one exact failed for schema ") + schema_fp
                     + " on antecedent quotient " + item.antecedent_instance_fingerprint
                     + " expected consequent " + sparse_constraint_to_string_(item.consequent)
                     + "; forced value=" + (it_forced == snap.forced_pairwise_lca.end() ? string("<missing>") : to_string(it_forced->second));
            }
            return false;
        }
    }
    if (why) *why = string("mixed frontier plus-one exact validated antecedent items=") + to_string(entry.items.size());
    return true;
}

