static vector<AntecedentShell5FrontierSpec> build_antecedent_shell5_frontier_specs_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                     string* why);
static vector<StructuredLocalSchema> enumerate_antecedent_shell5_frontier_candidates_(const AntecedentShell5FrontierSpec& spec,
                                                                                       size_t* raw_count,
                                                                                       string* why);

static string antecedent_shell5_candidate_universe_path_(const string& tag) {
    return string(kAntecedentShell5CandidateUniversePathPrefix) + tag + ".tsv";
}

static bool save_antecedent_shell5_candidate_universe_(const string& tag,
                                                       const vector<StructuredLocalSchema>& candidates,
                                                       string* why) {
    string path = antecedent_shell5_candidate_universe_path_(tag);
    ofstream fout(path);
    if (!fout) {
        if (why) *why = string("failed to write shell5 candidate universe tag=") + tag;
        return false;
    }
    vector<string> fps;
    for (const auto& s : candidates) fps.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    for (const auto& fp : fps) fout << fp << '\n';
    if (why) *why = string("saved shell5 candidate universe tag=") + tag + " count=" + to_string(fps.size());
    return true;
}

static bool load_antecedent_shell5_candidate_universe_(const string& tag,
                                                       vector<StructuredLocalSchema>* candidates,
                                                       string* why) {
    string path = antecedent_shell5_candidate_universe_path_(tag);
    ifstream fin(path);
    if (!fin) {
        if (candidates) candidates->clear();
        if (why) *why = string("no shell5 candidate universe file tag=") + tag;
        return false;
    }
    vector<string> fps;
    string line;
    while (getline(fin, line)) if (!line.empty()) fps.push_back(line);
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    string specs_why;
    auto specs = build_antecedent_shell5_frontier_specs_(build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell5FrontierSpec spec;
    bool found = false;
    for (const auto& s : specs) if (s.tag == tag) { spec = s; found = true; break; }
    vector<StructuredLocalSchema> out;
    if (found) {
        size_t raw = 0;
        auto all = enumerate_antecedent_shell5_frontier_candidates_(spec, &raw, nullptr);
        unordered_set<string> want(fps.begin(), fps.end());
        for (const auto& s : all) {
            string fp = canonical_structured_local_schema_fingerprint_(s);
            if (want.count(fp)) out.push_back(s);
        }
    }
    if (candidates) *candidates = out;
    if (why) *why = string("loaded shell5 candidate universe tag=") + tag + " count=" + to_string(out.size());
    return found;
}

static bool save_antecedent_shell5_local_exact_result_cache_(const string& tag,
                                                             const map<string, bool>& result,
                                                             string* why) {
    map<string, map<string,bool>> grouped;
    ifstream fin(kAntecedentShell5LocalExactResultCachePath);
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        vector<string> parts;
        size_t pos = 0;
        while (true) {
            size_t tab = line.find('\t', pos);
            if (tab == string::npos) { parts.push_back(line.substr(pos)); break; }
            parts.push_back(line.substr(pos, tab - pos));
            pos = tab + 1;
        }
        if (parts.size() < 3) continue;
        grouped[parts[0]][parts[1]] = (parts[2] == "1");
    }
    grouped[tag] = result;
    ofstream fout(kAntecedentShell5LocalExactResultCachePath);
    if (!fout) {
        if (why) *why = "failed to write antecedent shell5 local exact result cache";
        return false;
    }
    size_t rows = 0;
    for (const auto& tg : grouped) {
        for (const auto& kv : tg.second) {
            fout << tg.first << '\t' << kv.first << '\t' << (kv.second ? 1 : 0) << '\n';
            ++rows;
        }
    }
    if (why) *why = string("saved shell5 local exact result cache rows=") + to_string(rows);
    return true;
}

static bool save_antecedent_shell5_local_exact_progress_cache_(const string& tag,
                                                               size_t done,
                                                               size_t total,
                                                               string* why) {
    map<string, pair<size_t,size_t>> grouped;
    ifstream fin(kAntecedentShell5LocalExactProgressCachePath);
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        vector<string> parts;
        size_t pos = 0;
        while (true) {
            size_t tab = line.find('\t', pos);
            if (tab == string::npos) { parts.push_back(line.substr(pos)); break; }
            parts.push_back(line.substr(pos, tab - pos));
            pos = tab + 1;
        }
        if (parts.size() < 3) continue;
        grouped[parts[0]] = {stoull(parts[1]), stoull(parts[2])};
    }
    grouped[tag] = {done, total};
    ofstream fout(kAntecedentShell5LocalExactProgressCachePath);
    if (!fout) {
        if (why) *why = "failed to write antecedent shell5 local exact progress cache";
        return false;
    }
    for (const auto& kv : grouped) fout << kv.first << '\t' << kv.second.first << '\t' << kv.second.second << '\n';
    if (why) *why = string("saved shell5 local exact progress tag=") + tag + " done=" + to_string(done) + "/" + to_string(total);
    return true;
}

static bool save_antecedent_shell5_local_exact_survivors_(const string& tag,
                                                          const vector<StructuredLocalSchema>& survivors,
                                                          string* why) {
    map<string, vector<string>> grouped;
    ifstream fin(kAntecedentShell5LocalExactSurvivorPath);
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        size_t tab = line.find('\t');
        if (tab == string::npos) continue;
        grouped[line.substr(0, tab)].push_back(line.substr(tab + 1));
    }
    vector<string> fps;
    for (const auto& s : survivors) fps.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    grouped[tag] = fps;
    ofstream fout(kAntecedentShell5LocalExactSurvivorPath);
    if (!fout) {
        if (why) *why = "failed to write shell5 local exact survivor file";
        return false;
    }
    for (const auto& kv : grouped) {
        auto vals = kv.second;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        for (const auto& fp : vals) fout << kv.first << '\t' << fp << '\n';
    }
    if (why) *why = string("saved shell5 local exact survivors tag=") + tag + " count=" + to_string(fps.size());
    return true;
}

static bool load_antecedent_shell5_local_exact_survivors_(const string& tag,
                                                          vector<StructuredLocalSchema>* survivors,
                                                          string* why) {
    ifstream fin(kAntecedentShell5LocalExactSurvivorPath);
    if (!fin) {
        if (survivors) survivors->clear();
        if (why) *why = string("no shell5 local exact survivor file tag=") + tag;
        return false;
    }
    vector<string> fps;
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        size_t tab = line.find('\t');
        if (tab == string::npos) continue;
        if (line.substr(0, tab) == tag) fps.push_back(line.substr(tab + 1));
    }
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    vector<StructuredLocalSchema> all;
    load_antecedent_shell5_candidate_universe_(tag, &all, nullptr);
    unordered_set<string> want(fps.begin(), fps.end());
    vector<StructuredLocalSchema> out;
    for (const auto& s : all) {
        string fp = canonical_structured_local_schema_fingerprint_(s);
        if (want.count(fp)) out.push_back(s);
    }
    if (survivors) *survivors = out;
    if (why) *why = string("loaded shell5 local exact survivors tag=") + tag + " count=" + to_string(out.size());
    return !out.empty() || !fps.empty();
}

