static vector<AntecedentShell6FrontierSpec> build_antecedent_shell6_frontier_specs_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                     string* why) {
    vector<AntecedentShell6FrontierSpec> specs;
    {
        AntecedentShell6FrontierSpec s;
        s.tag = "antecedent_plus_three_frontier";
        s.symbol_bound = scope.max_symbol_bound_tested;
        s.antecedent_bound = scope.max_antecedent_bound_tested + 3;
        s.require_outside_bounded_scope = true;
        s.why = "support7 antecedent shell 6 frontier";
        specs.push_back(s);
    }
    {
        AntecedentShell6FrontierSpec s;
        s.tag = "support8_antecedent6_frontier";
        s.symbol_bound = scope.max_symbol_bound_tested + 1;
        s.antecedent_bound = scope.max_antecedent_bound_tested + 3;
        s.require_outside_bounded_scope = true;
        s.why = "support8 antecedent shell 6 frontier";
        specs.push_back(s);
    }
    g_last_antecedent_shell6_frontier_specs = specs;
    if (why) {
        ostringstream oss;
        oss << "antecedent shell6 specs=" << specs.size();
        for (const auto& s : specs) oss << " [tag=" << s.tag << ",symbolBound=" << s.symbol_bound << ",antecedentBound=" << s.antecedent_bound << "]";
        *why = oss.str();
    }
    return specs;
}

static vector<StructuredLocalSchema> enumerate_antecedent_shell6_frontier_candidates_(const AntecedentShell6FrontierSpec& spec,
                                                                                       size_t* raw_count,
                                                                                       string* why) {
    size_t raw = 0;
    string enum_why;
    auto out = enumerate_canonical_structured_local_schemas_exact_shape_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    string scope_why;
    auto scope = build_bounded_schema_universe_scope_stats_(&scope_why);
    vector<StructuredLocalSchema> filtered;
    filtered.reserve(out.size());
    for (const auto& schema : out) {
        string within_why;
        bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
        if (spec.require_outside_bounded_scope && within) continue;
        filtered.push_back(schema);
    }
    if (raw_count) *raw_count = raw;
    if (why) *why = string("antecedent shell6 frontier raw=") + to_string(raw) + " canonical=" + to_string(filtered.size()) + " tag=" + spec.tag;
    return filtered;
}

static AntecedentShell6CandidateTheoremData antecedent_shell6_candidate_theorem_data_(const string& tag,
                                                                                       string* why) {
    auto it = g_last_antecedent_shell6_candidate_theorem_data.find(tag);
    if (it != g_last_antecedent_shell6_candidate_theorem_data.end()) {
        if (why) *why = it->second.why;
        return it->second;
    }
    string specs_why;
    auto specs = build_antecedent_shell6_frontier_specs_(build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell6FrontierSpec spec;
    bool found = false;
    for (const auto& s : specs) if (s.tag == tag) { spec = s; found = true; break; }
    AntecedentShell6CandidateTheoremData d;
    d.tag = tag;
    if (!found) {
        d.why = string("unknown shell6 tag ") + tag;
        if (why) *why = d.why;
        return d;
    }
    vector<StructuredLocalSchema> candidates;
    string load_why;
    if (g_force_lower_frontier_fresh_rebuild ||
        !load_antecedent_shell6_candidate_universe_(tag, &candidates, &load_why)) {
        size_t raw = 0;
        candidates = enumerate_antecedent_shell6_frontier_candidates_(spec, &raw, &load_why);
        d.raw_candidates = raw;
        string save_why;
        save_antecedent_shell6_candidate_universe_(tag, candidates, &save_why);
        d.why = load_why + " ; " + save_why;
    } else {
        size_t raw = 0;
        enumerate_antecedent_shell6_frontier_candidates_(spec, &raw, nullptr);
        d.raw_candidates = raw;
        d.why = load_why;
    }
    d.canonical_candidates = candidates.size();
    d.outside_bounded_candidates = candidates.size();
    for (const auto& s : candidates) d.candidate_fingerprints.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end());
    d.candidate_fingerprints.erase(unique(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()), d.candidate_fingerprints.end());
    ostringstream oss;
    for (size_t i = 0; i < d.candidate_fingerprints.size(); ++i) { if (i) oss << ';'; oss << d.candidate_fingerprints[i]; }
    d.fingerprint = oss.str();
    g_last_antecedent_shell6_candidate_theorem_data[tag] = d;
    g_last_antecedent_shell6_frontier_candidates[tag] = candidates;
    if (why) *why = d.why;
    return d;
}

static bool validate_antecedent_shell6_candidate_theorem_data_(const string& tag,
                                                               string* why) {
    auto d = antecedent_shell6_candidate_theorem_data_(tag, nullptr);
    bool ok = (d.outside_bounded_candidates == d.candidate_fingerprints.size());
    if (why) {
        ostringstream oss;
        oss << "antecedentShell6CandidateTheoremData tag=" << tag << " raw=" << d.raw_candidates
            << " canonical=" << d.canonical_candidates << " outside=" << d.outside_bounded_candidates
            << " fingerprint=" << d.fingerprint;
        *why = oss.str();
    }
    return ok;
}

static vector<StructuredLocalSchema> antecedent_shell6_local_exact_survivors_(const string& tag,
                                                                               string* why) {
    auto it = g_last_antecedent_shell6_frontier_local_exact_survivors.find(tag);
    if (it != g_last_antecedent_shell6_frontier_local_exact_survivors.end()) {
        if (why) *why = string("cached shell6 local exact survivors tag=") + tag;
        return it->second;
    }
    vector<StructuredLocalSchema> out;
    string load_why;
    load_antecedent_shell6_local_exact_survivors_(tag, &out, &load_why);
    g_last_antecedent_shell6_frontier_local_exact_survivors[tag] = out;
    if (why) *why = load_why;
    return out;
}

static AntecedentShell6LocalExactSurvivorTheoremData antecedent_shell6_local_exact_survivor_theorem_data_(const string& tag,
                                                                                                           string* why) {
    auto it = g_last_antecedent_shell6_local_exact_survivor_theorem_data.find(tag);
    if (it != g_last_antecedent_shell6_local_exact_survivor_theorem_data.end()) {
        if (why) *why = it->second.why;
        return it->second;
    }
    AntecedentShell6LocalExactSurvivorTheoremData d;
    d.tag = tag;
    auto surv = antecedent_shell6_local_exact_survivors_(tag, nullptr);
    d.survivor_count = surv.size();
    for (const auto& s : surv) d.survivor_fingerprints.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(d.survivor_fingerprints.begin(), d.survivor_fingerprints.end());
    d.survivor_fingerprints.erase(unique(d.survivor_fingerprints.begin(), d.survivor_fingerprints.end()), d.survivor_fingerprints.end());
    ostringstream oss;
    for (size_t i = 0; i < d.survivor_fingerprints.size(); ++i) { if (i) oss << ';'; oss << d.survivor_fingerprints[i]; }
    d.fingerprint = oss.str();
    d.why = string("antecedent shell6 local exact survivor theorem data tag=") + tag;
    g_last_antecedent_shell6_local_exact_survivor_theorem_data[tag] = d;
    if (why) *why = d.why;
    return d;
}

static bool validate_antecedent_shell6_local_exact_survivor_theorem_data_(const string& tag,
                                                                          string* why) {
    auto d = antecedent_shell6_local_exact_survivor_theorem_data_(tag, nullptr);
    bool ok = (d.survivor_count == d.survivor_fingerprints.size());
    if (why) {
        ostringstream oss;
        oss << "antecedentShell6LocalExactSurvivorTheoremData tag=" << tag << " survivors=" << d.survivor_count
            << " fingerprint=" << d.fingerprint;
        *why = oss.str();
    }
    return ok;
}

static bool validate_antecedent_plus_three_frontier_schema_local_exact_(const StructuredLocalSchema& schema,
                                                                         string* why) {
    return validate_general_schema_candidate_local_exact_(schema, why);
}

static bool validate_support8_antecedent6_frontier_schema_local_exact_via_snapshot_(const StructuredLocalSchema& schema,
                                                                                     string* why) {
    return validate_mixed_frontier_schema_local_exact_via_snapshot_(schema, why);
}

static bool validate_antecedent_shell6_schema_plus_one_exact_(const StructuredLocalSchema& schema,
                                                              string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int support = schema_support_size_(sr);
    if (support == 7) return validate_structured_local_schema_plus_one_target8_(schema, why);
    if (support == 8) return validate_general_schema_candidate_plus_one_exact_(schema, why);
    if (why) *why = "antecedent shell6 plus-one support outside supported shell";
    return false;
}

