__attribute__((optimize("O0"))) static vector<GeneralStructuredSchemaFrontierSpec> build_general_structured_schema_frontier_specs_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                                   string* why) {
    vector<GeneralStructuredSchemaFrontierSpec> specs;
    {
        GeneralStructuredSchemaFrontierSpec s;
        s.tag = "support_plus_one_frontier";
        s.symbol_bound = scope.max_symbol_bound_tested + 1;
        s.antecedent_bound = scope.max_antecedent_bound_tested;
        s.require_outside_bounded_scope = true;
        s.why = "symbol bound plus one over bounded theorem scope";
        specs.push_back(s);
    }
    {
        GeneralStructuredSchemaFrontierSpec s;
        s.tag = "antecedent_plus_one_frontier";
        s.symbol_bound = scope.max_symbol_bound_tested;
        s.antecedent_bound = scope.max_antecedent_bound_tested + 1;
        s.require_outside_bounded_scope = true;
        s.why = "antecedent bound plus one over bounded theorem scope";
        specs.push_back(s);
    }
    g_last_general_structured_schema_frontier_specs = specs;
    if (why) {
        ostringstream oss;
        oss << "general structured schema frontier specs=" << specs.size();
        for (const auto& s : specs) oss << " [" << general_structured_schema_frontier_spec_to_string_(s) << "]";
        *why = oss.str();
    }
    return specs;
}

__attribute__((optimize("O0"))) static vector<StructuredLocalSchema> enumerate_canonical_structured_local_schemas_(int symbol_bound,
                                                                                   int antecedent_bound,
                                                                                   size_t* raw_count,
                                                                                   string* why) {
    ensure_basis_plus_one_theorem_data_ready_(nullptr);
    auto families = exact_minimal_basis_plus_one_failure_family_summaries_();
    vector<const ProofMotifPlusOneFailureFamilySummary*> fams;
    for (const auto& fam : families) fams.push_back(&fam);
    map<tuple<int,int,int>, SchemaAtom> atom_map;
    auto add_constraint = [&](SparseLcaConstraint c) {
        c = normalize_sparse_constraint_(c);
        if (max(c.u, max(c.v, c.w)) > symbol_bound) return;
        SchemaAtom a{c.u, c.v, c.w};
        atom_map[{a.u, a.v, a.w}] = a;
    };
    set<string> famfps;
    for (const auto* f : fams) if (f) famfps.insert(f->family_fingerprint);
    for (const auto& w : g_last_exact_minimal_basis_plus_one_failure_witnesses) {
        if (!famfps.count(w.family_fingerprint)) continue;
        for (const auto& a : w.motif.premises) add_constraint({a.u, a.v, a.w});
        for (const auto& c : w.instance.constraints) add_constraint(c);
    }
    size_t support_sum = 0;
    for (const auto* f : fams) {
        if (!f) continue;
        support_sum += f->witness_count;
        for (const auto& c : f->representative_instance.constraints) add_constraint(c);
    }
    vector<SchemaAtom> pool_atoms;
    for (const auto& kv : atom_map) pool_atoms.push_back(kv.second);
    sort(pool_atoms.begin(), pool_atoms.end(), schema_atom_less_);
    vector<SchemaAtom> consequents;
    auto add_consequent = [&](SparseLcaConstraint c) {
        c = normalize_sparse_constraint_(c);
        if (max(c.u, max(c.v, c.w)) > symbol_bound) return;
        SchemaAtom a{c.u, c.v, c.w};
        for (const auto& ex : consequents) if (ex.u == a.u && ex.v == a.v && ex.w == a.w) return;
        consequents.push_back(a);
    };
    for (const auto* f : fams) if (f) add_consequent(f->representative_target);
    map<string, StructuredLocalSchema> uniq;
    size_t raw = 0;
    int max_pick = min<int>(antecedent_bound, (int)pool_atoms.size());
    for (const auto& consequent : consequents) {
        for (int need = 1; need <= max_pick; ++need) {
            vector<int> idxs;
            function<void(int,int)> dfs = [&](int start, int left) {
                if (left == 0) {
                    ++raw;
                    SchemaRule raw_rule;
                    raw_rule.num_symbols = max(symbol_bound, max(consequent.u, max(consequent.v, consequent.w)));
                    raw_rule.consequent = consequent;
                    bool tautological = false;
                    for (int idx : idxs) {
                        raw_rule.antecedents.push_back(pool_atoms[idx]);
                        if (pool_atoms[idx].u == consequent.u && pool_atoms[idx].v == consequent.v && pool_atoms[idx].w == consequent.w) tautological = true;
                    }
                    if (tautological) return;
                    auto canon = canonicalize_schema_rule_(raw_rule);
                    auto schema = schema_rule_to_structured_local_schema_(canon);
                    schema.support = support_sum;
                    schema.human_readable = structured_local_schema_to_string_(schema);
                    uniq[schema.fingerprint] = schema;
                    return;
                }
                for (int i = start; i <= (int)pool_atoms.size() - left; ++i) {
                    idxs.push_back(i);
                    dfs(i + 1, left - 1);
                    idxs.pop_back();
                }
            };
            dfs(0, need);
        }
    }
    vector<StructuredLocalSchema> out;
    for (auto& kv : uniq) out.push_back(kv.second);
    sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.antecedents.size() != b.antecedents.size()) return a.antecedents.size() < b.antecedents.size();
        if (a.num_symbols != b.num_symbols) return a.num_symbols < b.num_symbols;
        return a.fingerprint < b.fingerprint;
    });
    if (raw_count) *raw_count = raw;
    if (why) *why = string("canonical structured local schema frontier raw=") + to_string(raw) + " canonical=" + to_string(out.size()) + " symbolBound=" + to_string(symbol_bound) + " antecedentBound=" + to_string(antecedent_bound);
    return out;
}

__attribute__((optimize("O0"))) static bool schema_is_within_bounded_obstruction_scope_(const StructuredLocalSchema& schema,
                                                         const BoundedSchemaUniverseScopeStats& scope,
                                                         string* why) {
    bool within = schema.num_symbols <= scope.max_symbol_bound_tested &&
                  (int)schema.antecedents.size() <= scope.max_antecedent_bound_tested;
    if (why) {
        *why = within ? "schema lies within bounded obstruction scope" : "schema lies outside bounded obstruction scope";
    }
    return within;
}

__attribute__((optimize("O0"))) static bool validate_general_schema_candidate_local_exact_(const StructuredLocalSchema& schema,
                                                           string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int support = schema_support_size_(sr);
    string local_why;
    int sample_n = min(support, 8);
    if (quick_refute_structured_local_schema_on_samples_(schema, sample_n, &local_why)) {
        if (why) *why = local_why;
        return false;
    }
    bool ok = validate_structured_local_schema_local_exact_extended_(schema, &local_why);
    if (why) *why = local_why;
    return ok;
}

__attribute__((optimize("O0"))) static bool validate_general_schema_candidate_plus_one_exact_(const StructuredLocalSchema& schema,
                                                              string* why) {
    auto canon_fp = canonical_structured_local_schema_fingerprint_(schema);
    const auto& surv = support_plus_one_frontier_local_exact_survivors_();
    bool in_support_plus_survivor = false;
    for (const auto& s : surv) {
        if (canonical_structured_local_schema_fingerprint_(s) == canon_fp) {
            in_support_plus_survivor = true;
            break;
        }
    }
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int target_n = schema_support_size_(sr) + 1;
    string local_why;
    bool ok = false;
    if (in_support_plus_survivor && target_n == 9) {
        ok = validate_structured_local_schema_plus_one_target9_(schema, &local_why);
        if (why) *why = local_why;
        return ok;
    }
    int sample_n = min(target_n, 8);
    if (sample_n > 0 && quick_refute_structured_local_schema_on_samples_(schema, sample_n, &local_why)) {
        if (why) *why = local_why;
        return false;
    }
    ok = validate_structured_local_schema_plus_one_exact_extended_(schema, &local_why);
    if (why) *why = local_why;
    return ok;
}

__attribute__((optimize("O0"))) static bool validate_general_schema_candidate_preserves_basis_theorem_n5_(const StructuredLocalSchema& schema,
                                                                          string* why) {
    return validate_out_of_pool_schema_candidate_preserves_basis_theorem_n5_(schema, why);
}

