__attribute__((optimize("O0"))) static GeneralStructuredSchemaFrontierStats scan_general_structured_schema_frontier_(const GeneralStructuredSchemaFrontierSpec& spec,
                                                                                     const vector<SparseRuleCandidate>& base_rules,
                                                                                     string* why) {
    (void)base_rules;
    GeneralStructuredSchemaFrontierStats stats;
    stats.tag = spec.tag;
    string scope_why;
    auto scope = build_bounded_schema_universe_scope_stats_(&scope_why);
    size_t raw = 0;
    string enum_why;
    auto all = enumerate_canonical_structured_local_schemas_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    stats.raw_candidates = raw;
    stats.canonical_candidates = all.size();
    g_last_general_structured_schema_frontier_candidates.clear();
    if (spec.tag == "support_plus_one_frontier") {
        vector<StructuredLocalSchema> outside_candidates;
        outside_candidates.reserve(all.size());
        for (const auto& schema : all) {
            string within_why;
            bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
            if (spec.require_outside_bounded_scope && within) continue;
            outside_candidates.push_back(schema);
        }
        const auto& surv = support_plus_one_frontier_local_exact_survivors_();
        string index_why;
        build_support_plus_one_antecedent_index_(surv, &index_why);
        string snapshot_why;
        build_support8_plus_one_target9_oracle_snapshot_(&snapshot_why);
        vector<StructuredLocalSchema> plus_one_survivor_schemas;
        stats.outside_bounded_candidates = outside_candidates.size();
        stats.local_exact_survivors = surv.size();
        stats.unsupported_local_exact_candidates = 0;
        stats.why = index_why + " ; " + snapshot_why;
        g_last_general_structured_schema_frontier_candidates = outside_candidates;
        for (size_t i = 0; i < surv.size(); ++i) {
            local_progress_(spec.tag.c_str(), i + 1, surv.size());
            const auto& schema = surv[i];
            string local_why;
            bool plus_one_ok = validate_general_schema_candidate_plus_one_exact_(schema, &local_why);
            if (plus_one_ok) {
                ++stats.plus_one_survivors;
                plus_one_survivor_schemas.push_back(schema);
            } else if (local_why.find("supported exact range") != string::npos || local_why.find("microchunk progress") != string::npos || local_why.find("not fully completed") != string::npos || local_why.find("progress ") != string::npos) ++stats.unsupported_plus_one_candidates;
        }
#ifdef LOCAL_TEST
        cerr << "support_plus_one frontier plusOneSurvivorsPrePreservation=" << plus_one_survivor_schemas.size() << "\n";
#endif
        for (const auto& schema : plus_one_survivor_schemas) {
            string quick_pres_why;
            if (!quick_refute_general_schema_candidate_preservation_(schema, &quick_pres_why)) {
                string p1, p2, p3;
                bool ok1 = validate_general_schema_candidate_preserves_basis_theorem_n5_(schema, &p1);
                bool ok2 = validate_general_schema_candidate_preserves_basis_theorem_n6_c5_(schema, &p2);
                bool ok3 = validate_general_schema_candidate_preserves_basis_theorem_n7_c3_(schema, &p3);
                if (ok1 && ok2 && ok3) ++stats.theorem_preserving_survivors;
            }
        }
    } else {
        for (size_t i = 0; i < all.size(); ++i) {
            local_progress_(spec.tag.c_str(), i + 1, all.size());
            const auto& schema = all[i];
            string within_why;
            bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
            if (spec.require_outside_bounded_scope && within) continue;
            ++stats.outside_bounded_candidates;
            g_last_general_structured_schema_frontier_candidates.push_back(schema);
            string local_why;
            bool local_ok = validate_general_schema_candidate_local_exact_(schema, &local_why);
            if (local_ok) ++stats.local_exact_survivors;
            else if (local_why.find("supported exact local range") != string::npos) ++stats.unsupported_local_exact_candidates;
            bool plus_one_ok = false;
            if (local_ok) {
                plus_one_ok = validate_general_schema_candidate_plus_one_exact_(schema, &local_why);
                if (plus_one_ok) ++stats.plus_one_survivors;
                else if (local_why.find("supported exact range") != string::npos || local_why.find("microchunk progress") != string::npos || local_why.find("not fully completed") != string::npos || local_why.find("progress ") != string::npos) ++stats.unsupported_plus_one_candidates;
            }
            if (local_ok && plus_one_ok) {
                string p1, p2, p3;
                bool ok1 = validate_general_schema_candidate_preserves_basis_theorem_n5_(schema, &p1);
                bool ok2 = validate_general_schema_candidate_preserves_basis_theorem_n6_c5_(schema, &p2);
                bool ok3 = validate_general_schema_candidate_preserves_basis_theorem_n7_c3_(schema, &p3);
                if (ok1 && ok2 && ok3) ++stats.theorem_preserving_survivors;
            }
        }
    }
    stats.completed = true;
    if (stats.why.empty()) stats.why = enum_why;
    else if (!enum_why.empty()) stats.why += string(" ; ") + enum_why;
    if (spec.tag == "support_plus_one_frontier") {
        g_last_support_plus_one_frontier_theorem_data.raw_candidates = stats.raw_candidates;
        g_last_support_plus_one_frontier_theorem_data.canonical_candidates = stats.canonical_candidates;
        g_last_support_plus_one_frontier_theorem_data.outside_bounded_candidates = stats.outside_bounded_candidates;
        g_last_support_plus_one_frontier_theorem_data.local_exact_survivors = stats.local_exact_survivors;
        g_last_support_plus_one_frontier_theorem_data.plus_one_survivors = stats.plus_one_survivors;
        g_last_support_plus_one_frontier_theorem_data.theorem_preserving_survivors = stats.theorem_preserving_survivors;
        g_last_support_plus_one_frontier_theorem_data.unsupported_local_exact_candidates = stats.unsupported_local_exact_candidates;
        g_last_support_plus_one_frontier_theorem_data.unsupported_plus_one_candidates = stats.unsupported_plus_one_candidates;
        g_last_support_plus_one_frontier_theorem_data.why = stats.why;
    } else if (spec.tag == "antecedent_plus_one_frontier") {
        g_last_antecedent_plus_one_frontier_theorem_data.raw_candidates = stats.raw_candidates;
        g_last_antecedent_plus_one_frontier_theorem_data.canonical_candidates = stats.canonical_candidates;
        g_last_antecedent_plus_one_frontier_theorem_data.outside_bounded_candidates = stats.outside_bounded_candidates;
        g_last_antecedent_plus_one_frontier_theorem_data.local_exact_survivors = stats.local_exact_survivors;
        g_last_antecedent_plus_one_frontier_theorem_data.plus_one_survivors = stats.plus_one_survivors;
        g_last_antecedent_plus_one_frontier_theorem_data.theorem_preserving_survivors = stats.theorem_preserving_survivors;
        g_last_antecedent_plus_one_frontier_theorem_data.unsupported_local_exact_candidates = stats.unsupported_local_exact_candidates;
        g_last_antecedent_plus_one_frontier_theorem_data.unsupported_plus_one_candidates = stats.unsupported_plus_one_candidates;
        g_last_antecedent_plus_one_frontier_theorem_data.why = stats.why;
    }
    if (why) *why = general_structured_schema_frontier_stats_to_string_(stats);
    return stats;
}

__attribute__((optimize("O0"))) static GeneralStructuredSchemaGapCertificate build_general_structured_schema_gap_certificate_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                               const vector<GeneralStructuredSchemaFrontierStats>& frontiers,
                                                                                               string* why) {
    (void)scope;
    GeneralStructuredSchemaGapCertificate cert;
    cert.bounded_chain_self_verified = g_last_family_chain_theorem_audit_stats.self_verified ||
                                      (g_last_bounded_family_chain_status == "support_bounded_schema_universe_obstruction_chain_self_verified");
    cert.tested_frontier_count = frontiers.size();
    for (const auto& f : frontiers) {
        cert.outside_bounded_local_exact_survivors += f.local_exact_survivors;
        cert.outside_bounded_plus_one_survivors += f.plus_one_survivors;
        cert.outside_bounded_theorem_preserving_survivors += f.theorem_preserving_survivors;
    }
    cert.why = "outside-bounded frontier gap certificate composed over minimal separate frontiers and mixed frontier if present";
    g_last_general_structured_schema_gap_certificate = cert;
    if (why) *why = general_structured_schema_gap_certificate_to_string_(cert);
    return cert;
}

