#define FILL(src,prefix)     t.prefix##_raw_candidates = src.raw_candidates;     t.prefix##_canonical_candidates = src.canonical_candidates;     t.prefix##_outside_bounded_candidates = src.outside_bounded_candidates;     t.prefix##_local_exact_survivors = src.local_exact_survivors;     t.prefix##_plus_one_survivors = src.plus_one_survivors;     t.prefix##_theorem_preserving_survivors = src.theorem_preserving_survivors;
