static bool load_antecedent_shell11_local_exact_survivors_(const string& tag, vector<StructuredLocalSchema>* out, string* why) {
    out->clear();
    ifstream fin(kAntecedentShell11LocalExactSurvivorPath);
    if (!fin) { if (why) *why = string("no shell11 local exact survivor file tag=") + tag; return false; }
    vector<StructuredLocalSchema> all; load_antecedent_shell11_candidate_universe_(tag, &all, nullptr);
    unordered_map<string, StructuredLocalSchema> by_fp; by_fp.reserve(all.size()*2+1);
    for (const auto& s : all) by_fp.emplace(canonical_structured_local_schema_fingerprint_(s), s);
    string line; while (getline(fin, line)) {
        auto pos = line.find('\t'); if (pos==string::npos) continue; if (line.substr(0,pos)!=tag) continue;
        string fp = line.substr(pos+1); auto it = by_fp.find(fp); if (it!=by_fp.end()) out->push_back(it->second);
    }
    if (why) *why = string("loaded shell11 local exact survivors tag=") + tag + " count=" + to_string(out->size());
    return true;
}

