static vector<AntecedentShell12FrontierSpec> build_antecedent_shell12_frontier_specs_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                     string* why) {
    vector<AntecedentShell12FrontierSpec> specs;
    { AntecedentShell12FrontierSpec s; s.tag = "antecedent_plus_nine_frontier"; s.symbol_bound = scope.max_symbol_bound_tested; s.antecedent_bound = scope.max_antecedent_bound_tested + 9; s.require_outside_bounded_scope = true; s.why = "support7 antecedent shell 12 frontier"; specs.push_back(s); }
    { AntecedentShell12FrontierSpec s; s.tag = "support8_antecedent12_frontier"; s.symbol_bound = scope.max_symbol_bound_tested + 1; s.antecedent_bound = scope.max_antecedent_bound_tested + 9; s.require_outside_bounded_scope = true; s.why = "support8 antecedent shell 12 frontier"; specs.push_back(s); }
    g_last_antecedent_shell12_frontier_specs = specs;
    if (why) { ostringstream oss; oss << "antecedent shell12 specs=" << specs.size(); for (const auto& s : specs) oss << " [tag=" << s.tag << ",symbolBound=" << s.symbol_bound << ",antecedentBound=" << s.antecedent_bound << "]"; *why = oss.str(); }
    return specs;
}

static vector<StructuredLocalSchema> enumerate_antecedent_shell12_frontier_candidates_(const AntecedentShell12FrontierSpec& spec,
                                                                                       size_t* raw_count,
                                                                                       string* why) {
    size_t raw = 0; string enum_why; auto out = enumerate_canonical_structured_local_schemas_exact_shape_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    string scope_why; auto scope = build_bounded_schema_universe_scope_stats_(&scope_why);
    vector<StructuredLocalSchema> filtered; filtered.reserve(out.size());
    for (const auto& schema : out) {
        string within_why; bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
        if (spec.require_outside_bounded_scope && within) continue; filtered.push_back(schema);
    }
    if (raw_count) *raw_count = raw;
    if (why) *why = string("antecedent shell12 frontier raw=") + to_string(raw) + " canonical=" + to_string(filtered.size()) + " tag=" + spec.tag;
    return filtered;
}

static AntecedentShell12CandidateTheoremData antecedent_shell12_candidate_theorem_data_(const string& tag, string* why) {
    auto it = g_last_antecedent_shell12_candidate_theorem_data.find(tag); if (it != g_last_antecedent_shell12_candidate_theorem_data.end()) { if (why) *why = it->second.why; return it->second; }
    string specs_why; auto specs = build_antecedent_shell12_frontier_specs_(build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell12FrontierSpec spec; bool found = false; for (const auto& s : specs) if (s.tag == tag) { spec = s; found = true; break; }
    AntecedentShell12CandidateTheoremData d; d.tag = tag; if (!found) { d.why = string("unknown shell12 tag ") + tag; if (why) *why = d.why; return d; }
    vector<StructuredLocalSchema> candidates; string load_why;
    if (g_force_lower_frontier_fresh_rebuild ||
        !load_antecedent_shell12_candidate_universe_(tag, &candidates, &load_why)) {
        size_t raw = 0; candidates = enumerate_antecedent_shell12_frontier_candidates_(spec, &raw, &load_why); d.raw_candidates = raw; string save_why; save_antecedent_shell12_candidate_universe_(tag, candidates, &save_why); d.why = load_why + " ; " + save_why;
    } else {
        size_t raw = 0; enumerate_antecedent_shell12_frontier_candidates_(spec, &raw, nullptr); d.raw_candidates = raw; d.why = load_why;
    }
    d.canonical_candidates = candidates.size(); d.outside_bounded_candidates = candidates.size();
    for (const auto& s : candidates) d.candidate_fingerprints.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()); d.candidate_fingerprints.erase(unique(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()), d.candidate_fingerprints.end());
    ostringstream oss; for (size_t i = 0; i < d.candidate_fingerprints.size(); ++i) { if (i) oss << ';'; oss << d.candidate_fingerprints[i]; } d.fingerprint = oss.str();
    g_last_antecedent_shell12_candidate_theorem_data[tag] = d; g_last_antecedent_shell12_frontier_candidates[tag] = candidates; if (why) *why = d.why; return d;
}

static bool validate_antecedent_shell12_candidate_theorem_data_(const string& tag, string* why) {
    auto d = antecedent_shell12_candidate_theorem_data_(tag, nullptr);
    bool ok = (d.outside_bounded_candidates == d.candidate_fingerprints.size());
    if (why) { ostringstream oss; oss << "antecedentShell12CandidateTheoremData tag=" << tag << " raw=" << d.raw_candidates << " canonical=" << d.canonical_candidates << " outside=" << d.outside_bounded_candidates << " fingerprint=" << d.fingerprint; *why = oss.str(); }
    return ok;
}

