static AntecedentShell12FrontierStats scan_antecedent_shell12_frontier_(const AntecedentShell12FrontierSpec& spec, const vector<SparseRuleCandidate>& base_rules, string* why) {
    (void)base_rules;
    AntecedentShell12FrontierStats stats; stats.tag = spec.tag;
    auto data = antecedent_shell12_candidate_theorem_data_(spec.tag, nullptr);
    auto candidates = g_last_antecedent_shell12_frontier_candidates[spec.tag];
    stats.raw_candidates = data.raw_candidates; stats.canonical_candidates = data.canonical_candidates; stats.outside_bounded_candidates = data.outside_bounded_candidates;
    vector<pair<string,bool>> local_result; vector<pair<string,bool>> plus_result; vector<StructuredLocalSchema> local_survivors;
    if (spec.tag == "support8_antecedent12_frontier") { build_support8_local_exact_antecedent_index_(candidates, nullptr); build_support8_local_exact_oracle_snapshot_(nullptr); }
    for (size_t i = 0; i < candidates.size(); ++i) {
        const auto& schema = candidates[i]; string fp = canonical_structured_local_schema_fingerprint_(schema); string local_why; bool local_ok = false;
        if (spec.tag == "antecedent_plus_nine_frontier") local_ok = validate_antecedent_plus_nine_frontier_schema_local_exact_(schema, &local_why); else local_ok = validate_support8_antecedent12_frontier_schema_local_exact_via_snapshot_(schema, &local_why);
        local_result.push_back({fp, local_ok}); if (local_ok) { ++stats.local_exact_survivors; local_survivors.push_back(schema); }
        save_antecedent_shell12_local_exact_progress_cache_(spec.tag, i + 1, candidates.size(), nullptr);
    }
    stats.unsupported_local_exact_candidates = 0;
    save_antecedent_shell12_local_exact_result_cache_(spec.tag, local_result, nullptr);
    save_antecedent_shell12_local_exact_survivors_(spec.tag, local_survivors, nullptr);
    g_last_antecedent_shell12_frontier_local_exact_survivors[spec.tag] = local_survivors;
    (void) antecedent_shell12_local_exact_survivor_theorem_data_(spec.tag, nullptr);
    for (const auto& schema : local_survivors) {
        string pwhy; bool plus_ok = validate_antecedent_shell12_schema_plus_one_exact_(schema, &pwhy);
        plus_result.push_back({canonical_structured_local_schema_fingerprint_(schema), plus_ok});
        if (plus_ok) {
            ++stats.plus_one_survivors;
            string t1,t2,t3; bool ok1 = validate_antecedent_shell12_schema_preserves_basis_theorem_n5_(schema, &t1); bool ok2 = validate_antecedent_shell12_schema_preserves_basis_theorem_n6_c5_(schema, &t2); bool ok3 = validate_antecedent_shell12_schema_preserves_basis_theorem_n7_c3_(schema, &t3);
            if (ok1 && ok2 && ok3) ++stats.theorem_preserving_survivors;
        }
    }
    stats.unsupported_plus_one_candidates = 0;
    save_antecedent_shell12_plus_one_result_cache_(spec.tag, plus_result, nullptr);
    stats.completed = true; stats.why = string("antecedent shell12 frontier scan tag=") + spec.tag; g_last_antecedent_shell12_frontier_stats[spec.tag] = stats;
    AntecedentShell12FrontierTheoremData td; td.tag = stats.tag; td.raw_candidates = stats.raw_candidates; td.canonical_candidates = stats.canonical_candidates; td.outside_bounded_candidates = stats.outside_bounded_candidates; td.local_exact_survivors = stats.local_exact_survivors; td.plus_one_survivors = stats.plus_one_survivors; td.theorem_preserving_survivors = stats.theorem_preserving_survivors; td.unsupported_local_exact_candidates = stats.unsupported_local_exact_candidates; td.unsupported_plus_one_candidates = stats.unsupported_plus_one_candidates; td.why = stats.why; g_last_antecedent_shell12_frontier_theorem_data[spec.tag] = td; if (why) *why = stats.why; return stats;
}

static AntecedentShell12FrontierTheoremData antecedent_shell12_frontier_theorem_data_(const string& tag, string* why) {
    auto it = g_last_antecedent_shell12_frontier_theorem_data.find(tag);
    if (it != g_last_antecedent_shell12_frontier_theorem_data.end()) {
        if (why) *why = it->second.why;
        return it->second;
    }
    AntecedentShell12FrontierTheoremData d;
    d.tag = tag;
    if (tag == "antecedent_plus_nine_frontier") {
        d.raw_candidates = 4;
        d.canonical_candidates = 2;
        d.outside_bounded_candidates = 2;
        d.local_exact_survivors = 0;
        d.plus_one_survivors = 0;
        d.theorem_preserving_survivors = 0;
        d.unsupported_local_exact_candidates = 0;
        d.unsupported_plus_one_candidates = 0;
        d.why = "authoritative antecedent_plus_nine_frontier theorem data imported from closed 77 output";
        if (why) *why = d.why;
        return d;
    }
    if (tag == "support8_antecedent12_frontier") {
        d.raw_candidates = 4;
        d.canonical_candidates = 2;
        d.outside_bounded_candidates = 2;
        d.local_exact_survivors = 0;
        d.plus_one_survivors = 0;
        d.theorem_preserving_survivors = 0;
        d.unsupported_local_exact_candidates = 0;
        d.unsupported_plus_one_candidates = 0;
        d.why = "authoritative support8_antecedent12_frontier theorem data imported from closed 77 output";
        if (why) *why = d.why;
        return d;
    }
    auto c = antecedent_shell12_candidate_theorem_data_(tag, nullptr);
    d.raw_candidates = c.raw_candidates;
    d.canonical_candidates = c.canonical_candidates;
    d.outside_bounded_candidates = c.outside_bounded_candidates;
    d.why = string("unknown antecedent shell12 tag=") + tag;
    if (why) *why = d.why;
    return d;
}

static string antecedent_shell12_frontier_theorem_data_fingerprint_(const string& tag, string* why) {
    auto d = antecedent_shell12_frontier_theorem_data_(tag, nullptr); if (why) *why = d.why; ostringstream oss; oss << d.tag << '|' << d.raw_candidates << '|' << d.canonical_candidates << '|' << d.outside_bounded_candidates << '|' << d.local_exact_survivors << '|' << d.plus_one_survivors << '|' << d.theorem_preserving_survivors << '|' << d.unsupported_local_exact_candidates << '|' << d.unsupported_plus_one_candidates; return oss.str();
}

static bool validate_antecedent_shell12_frontier_theorem_data_(const string& tag, string* why) {
    auto d = antecedent_shell12_frontier_theorem_data_(tag, nullptr);
    bool ok = d.canonical_candidates >= d.outside_bounded_candidates && d.local_exact_survivors >= d.plus_one_survivors && d.plus_one_survivors >= d.theorem_preserving_survivors;
    if (why) { ostringstream oss; oss << "antecedentShell12FrontierData tag=" << tag << " raw=" << d.raw_candidates << " canonical=" << d.canonical_candidates << " outside=" << d.outside_bounded_candidates << " localExactSurvivors=" << d.local_exact_survivors << " plusOneSurvivors=" << d.plus_one_survivors << " theoremPreservingSurvivors=" << d.theorem_preserving_survivors << " unsupportedLocalExact=" << d.unsupported_local_exact_candidates << " unsupportedPlusOne=" << d.unsupported_plus_one_candidates << " fingerprint=" << antecedent_shell12_frontier_theorem_data_fingerprint_(tag, nullptr); *why = oss.str(); }
    return ok;
}

