static Support8OutsideBoundedShellTailCertificate build_support8_outside_bounded_shell_tail_certificate_(const AntecedentShell12FrontierTheoremData& a7, const AntecedentShell12FrontierTheoremData& a8, string* why) {
    Support8OutsideBoundedShellTailCertificate cert;
    cert.antecedent_plus_nine_empty = (a7.outside_bounded_candidates == 0);
    cert.support8_antecedent12_empty = (a8.outside_bounded_candidates == 0);
    cert.total_outside_bounded_candidates = a7.outside_bounded_candidates + a8.outside_bounded_candidates;
    cert.why = "support<=8 shell tail exhaustion certificate";
    g_last_support8_outside_bounded_shell_tail_certificate = cert;
    if (why) { std::ostringstream oss; oss << "empty7=" << (cert.antecedent_plus_nine_empty?"true":"false") << " empty8=" << (cert.support8_antecedent12_empty?"true":"false") << " totalOutside=" << cert.total_outside_bounded_candidates; *why = oss.str(); }
    return cert;
}


