static string antecedent_shell13_candidate_universe_path_(const string& tag) {
    if (tag == "antecedent_plus_ten_frontier") return "/mnt/data/antecedent_plus_ten_candidate_universe_90.tsv";
    if (tag == "support8_antecedent13_frontier") return "/mnt/data/support8_antecedent13_candidate_universe_90.tsv";
    return string("/mnt/data/antecedent_shell13_candidate_universe_77_") + tag + ".tsv";
}

static bool save_antecedent_shell13_candidate_universe_(const string& tag, const vector<StructuredLocalSchema>& candidates, string* why) {
    string path = antecedent_shell13_candidate_universe_path_(tag);
    ofstream fout(path);
    if (!fout) { if (why) *why = string("failed to write shell13 candidate universe tag=") + tag; return false; }
    vector<string> fps;
    fps.reserve(candidates.size());
    for (const auto& s : candidates) fps.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    for (const auto& fp : fps) fout << fp << "\n";
    if (why) *why = string("saved shell13 candidate universe tag=") + tag + " count=" + to_string(fps.size());
    return true;
}

static bool load_antecedent_shell13_candidate_universe_(const string& tag, vector<StructuredLocalSchema>* out, string* why) {
    out->clear();
    string path = antecedent_shell13_candidate_universe_path_(tag);
    ifstream fin(path);
    if (!fin) { if (why) *why = string("no shell13 candidate universe file tag=") + tag; return false; }
    string specs_why; auto specs = build_antecedent_shell13_frontier_specs_(build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell13FrontierSpec spec; bool found=false; for (const auto& s : specs) if (s.tag==tag) { spec=s; found=true; break; }
    if (!found) { if (why) *why = string("unknown shell13 tag ")+tag; return false; }
    vector<StructuredLocalSchema> all; size_t raw=0; all = enumerate_antecedent_shell13_frontier_candidates_(spec, &raw, nullptr);
    unordered_map<string, StructuredLocalSchema> by_fp; by_fp.reserve(all.size()*2+1);
    for (const auto& s : all) by_fp.emplace(canonical_structured_local_schema_fingerprint_(s), s);
    string line; while (getline(fin, line)) { auto it = by_fp.find(line); if (it != by_fp.end()) out->push_back(it->second); }
    if (why) *why = string("loaded shell13 candidate universe tag=") + tag + " count=" + to_string(out->size());
    return true;
}

static bool save_antecedent_shell13_local_exact_result_cache_(const string& tag, const vector<pair<string,bool>>& rows, string* why) {
    (void)tag;
    ofstream fout(kAntecedentShell13LocalExactResultCachePath);
    if (!fout) { if (why) *why = "failed to write antecedent shell13 local exact result cache"; return false; }
    fout << "tag\tschema_fingerprint\tpass\n";
    for (const auto& row : rows) fout << tag << "\t" << row.first << "\t" << (row.second ? 1 : 0) << "\n";
    if (why) *why = string("saved shell13 local exact result cache rows=") + to_string(rows.size());
    return true;
}

static bool save_antecedent_shell13_local_exact_progress_cache_(const string& tag, size_t done, size_t total, string* why) {
    ofstream fout(kAntecedentShell13LocalExactProgressCachePath);
    if (!fout) { if (why) *why = "failed to write antecedent shell13 local exact progress cache"; return false; }
    fout << "tag\tdone\ttotal\n" << tag << "\t" << done << "\t" << total << "\n";
    if (why) *why = string("saved shell13 local exact progress tag=") + tag + " done=" + to_string(done) + "/" + to_string(total);
    return true;
}

static bool save_antecedent_shell13_local_exact_survivors_(const string& tag, const vector<StructuredLocalSchema>& survivors, string* why) {
    (void)tag;
    ofstream fout(kAntecedentShell13LocalExactSurvivorPath);
    if (!fout) { if (why) *why = "failed to write shell13 local exact survivor file"; return false; }
    vector<string> fps;
    for (const auto& s : survivors) fps.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    for (const auto& fp : fps) fout << tag << "\t" << fp << "\n";
    if (why) *why = string("saved shell13 local exact survivors tag=") + tag + " count=" + to_string(fps.size());
    return true;
}

static bool load_antecedent_shell13_local_exact_survivors_(const string& tag, vector<StructuredLocalSchema>* out, string* why) {
    out->clear();
    ifstream fin(kAntecedentShell13LocalExactSurvivorPath);
    if (!fin) { if (why) *why = string("no shell13 local exact survivor file tag=") + tag; return false; }
    vector<StructuredLocalSchema> all; load_antecedent_shell13_candidate_universe_(tag, &all, nullptr);
    unordered_map<string, StructuredLocalSchema> by_fp; by_fp.reserve(all.size()*2+1);
    for (const auto& s : all) by_fp.emplace(canonical_structured_local_schema_fingerprint_(s), s);
    string line; while (getline(fin, line)) {
        auto pos = line.find('	'); if (pos==string::npos) continue; if (line.substr(0,pos)!=tag) continue;
        string fp = line.substr(pos+1); auto it = by_fp.find(fp); if (it!=by_fp.end()) out->push_back(it->second);
    }
    if (why) *why = string("loaded shell13 local exact survivors tag=") + tag + " count=" + to_string(out->size());
    return true;
}

static bool save_antecedent_shell13_plus_one_result_cache_(const string& tag, const vector<pair<string,bool>>& rows, string* why) {
    (void)tag;
    ofstream fout(kAntecedentShell13PlusOneResultCachePath);
    if (!fout) { if (why) *why = "failed to write antecedent shell13 plus-one result cache"; return false; }
    fout << "tag\tschema_fingerprint\tpass\n";
    for (const auto& row : rows) fout << tag << "\t" << row.first << "\t" << (row.second ? 1 : 0) << "\n";
    if (why) *why = string("saved shell13 plus-one result cache rows=") + to_string(rows.size());
    return true;
}

static vector<AntecedentShell13FrontierSpec> build_antecedent_shell13_frontier_specs_(const BoundedSchemaUniverseScopeStats& scope,
                                                                                     string* why) {
    vector<AntecedentShell13FrontierSpec> specs;
    { AntecedentShell13FrontierSpec s; s.tag = "antecedent_plus_ten_frontier"; s.symbol_bound = scope.max_symbol_bound_tested; s.antecedent_bound = scope.max_antecedent_bound_tested + 10; s.require_outside_bounded_scope = true; s.why = "support7 antecedent shell 13 frontier"; specs.push_back(s); }
    { AntecedentShell13FrontierSpec s; s.tag = "support8_antecedent13_frontier"; s.symbol_bound = scope.max_symbol_bound_tested + 1; s.antecedent_bound = scope.max_antecedent_bound_tested + 10; s.require_outside_bounded_scope = true; s.why = "support8 antecedent shell 13 frontier"; specs.push_back(s); }
    g_last_antecedent_shell13_frontier_specs = specs;
    if (why) { ostringstream oss; oss << "antecedent shell13 specs=" << specs.size(); for (const auto& s : specs) oss << " [tag=" << s.tag << ",symbolBound=" << s.symbol_bound << ",antecedentBound=" << s.antecedent_bound << "]"; *why = oss.str(); }
    return specs;
}

static vector<StructuredLocalSchema> enumerate_antecedent_shell13_frontier_candidates_(const AntecedentShell13FrontierSpec& spec,
                                                                                       size_t* raw_count,
                                                                                       string* why) {
    size_t raw = 0; string enum_why; auto out = enumerate_canonical_structured_local_schemas_exact_shape_(spec.symbol_bound, spec.antecedent_bound, &raw, &enum_why);
    string scope_why; auto scope = build_bounded_schema_universe_scope_stats_(&scope_why);
    vector<StructuredLocalSchema> filtered; filtered.reserve(out.size());
    for (const auto& schema : out) {
        string within_why; bool within = schema_is_within_bounded_obstruction_scope_(schema, scope, &within_why);
        if (spec.require_outside_bounded_scope && within) continue; filtered.push_back(schema);
    }
    if (raw_count) *raw_count = raw;
    if (why) *why = string("antecedent shell13 frontier raw=") + to_string(raw) + " canonical=" + to_string(filtered.size()) + " tag=" + spec.tag;
    return filtered;
}

static AntecedentShell13CandidateTheoremData antecedent_shell13_candidate_theorem_data_(const string& tag, string* why) {
    auto it = g_last_antecedent_shell13_candidate_theorem_data.find(tag); if (it != g_last_antecedent_shell13_candidate_theorem_data.end()) { if (why) *why = it->second.why; return it->second; }
    string specs_why; auto specs = build_antecedent_shell13_frontier_specs_(build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell13FrontierSpec spec; bool found = false; for (const auto& s : specs) if (s.tag == tag) { spec = s; found = true; break; }
    AntecedentShell13CandidateTheoremData d; d.tag = tag; if (!found) { d.why = string("unknown shell13 tag ") + tag; if (why) *why = d.why; return d; }
    vector<StructuredLocalSchema> candidates; string load_why;
    if (g_force_lower_frontier_fresh_rebuild ||
        !load_antecedent_shell13_candidate_universe_(tag, &candidates, &load_why)) {
        size_t raw = 0; candidates = enumerate_antecedent_shell13_frontier_candidates_(spec, &raw, &load_why); d.raw_candidates = raw; string save_why; save_antecedent_shell13_candidate_universe_(tag, candidates, &save_why); d.why = load_why + " ; " + save_why;
    } else {
        size_t raw = 0; enumerate_antecedent_shell13_frontier_candidates_(spec, &raw, nullptr); d.raw_candidates = raw; d.why = load_why;
    }
    d.canonical_candidates = candidates.size(); d.outside_bounded_candidates = candidates.size();
    for (const auto& s : candidates) d.candidate_fingerprints.push_back(canonical_structured_local_schema_fingerprint_(s));
    sort(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()); d.candidate_fingerprints.erase(unique(d.candidate_fingerprints.begin(), d.candidate_fingerprints.end()), d.candidate_fingerprints.end());
    ostringstream oss; for (size_t i = 0; i < d.candidate_fingerprints.size(); ++i) { if (i) oss << ';'; oss << d.candidate_fingerprints[i]; } d.fingerprint = oss.str();
    g_last_antecedent_shell13_candidate_theorem_data[tag] = d; g_last_antecedent_shell13_frontier_candidates[tag] = candidates; if (why) *why = d.why; return d;
}

static bool validate_antecedent_shell13_candidate_theorem_data_(const string& tag, string* why) {
    auto d = antecedent_shell13_candidate_theorem_data_(tag, nullptr);
    bool ok = (d.outside_bounded_candidates == d.candidate_fingerprints.size());
    if (why) { ostringstream oss; oss << "antecedentShell12CandidateTheoremData tag=" << tag << " raw=" << d.raw_candidates << " canonical=" << d.canonical_candidates << " outside=" << d.outside_bounded_candidates << " fingerprint=" << d.fingerprint; *why = oss.str(); }
    return ok;
}

