static bool validate_antecedent_shell13_schema_plus_one_exact_(const StructuredLocalSchema& schema, string* why) {
    auto sr = structured_local_schema_to_schema_rule_(schema);
    int support = schema_support_size_(sr);
    if (support == 7) return validate_structured_local_schema_plus_one_target8_(schema, why);
    if (support == 8) return validate_general_schema_candidate_plus_one_exact_(schema, why);
    if (why) *why = "antecedent shell13 plus-one support outside supported shell";
    return false;
}

