static AntecedentShell15FrontierStats scan_antecedent_shell15_frontier_(const AntecedentShell15FrontierSpec& spec, const vector<SparseRuleCandidate>& base_rules, string* why) {
    (void)base_rules;
    AntecedentShell15FrontierStats stats; stats.tag = spec.tag;
    auto data = antecedent_shell15_candidate_theorem_data_(spec.tag, nullptr);
    auto candidates = g_last_antecedent_shell15_frontier_candidates[spec.tag];
    stats.raw_candidates = data.raw_candidates; stats.canonical_candidates = data.canonical_candidates; stats.outside_bounded_candidates = data.outside_bounded_candidates;
    vector<pair<string,bool>> local_result; vector<pair<string,bool>> plus_result; vector<StructuredLocalSchema> local_survivors;
    if (spec.tag == "support8_antecedent15_frontier") { build_support8_local_exact_antecedent_index_(candidates, nullptr); build_support8_local_exact_oracle_snapshot_(nullptr); }
    for (size_t i = 0; i < candidates.size(); ++i) {
        const auto& schema = candidates[i]; string fp = canonical_structured_local_schema_fingerprint_(schema); string local_why; bool local_ok = false;
        if (spec.tag == "antecedent_plus_twelve_frontier") local_ok = validate_antecedent_plus_twelve_frontier_schema_local_exact_(schema, &local_why); else local_ok = validate_support8_antecedent15_frontier_schema_local_exact_via_snapshot_(schema, &local_why);
        local_result.push_back({fp, local_ok}); if (local_ok) { ++stats.local_exact_survivors; local_survivors.push_back(schema); }
        save_antecedent_shell15_local_exact_progress_cache_(spec.tag, i + 1, candidates.size(), nullptr);
    }
    stats.unsupported_local_exact_candidates = 0;
    save_antecedent_shell15_local_exact_result_cache_(spec.tag, local_result, nullptr);
    save_antecedent_shell15_local_exact_survivors_(spec.tag, local_survivors, nullptr);
    g_last_antecedent_shell15_frontier_local_exact_survivors[spec.tag] = local_survivors;
    (void) antecedent_shell15_local_exact_survivor_theorem_data_(spec.tag, nullptr);
    for (const auto& schema : local_survivors) {
        string pwhy; bool plus_ok = validate_antecedent_shell15_schema_plus_one_exact_(schema, &pwhy);
        plus_result.push_back({canonical_structured_local_schema_fingerprint_(schema), plus_ok});
        if (plus_ok) {
            ++stats.plus_one_survivors;
            string t1,t2,t3; bool ok1 = validate_antecedent_shell15_schema_preserves_basis_theorem_n5_(schema, &t1); bool ok2 = validate_antecedent_shell15_schema_preserves_basis_theorem_n6_c5_(schema, &t2); bool ok3 = validate_antecedent_shell15_schema_preserves_basis_theorem_n7_c3_(schema, &t3);
            if (ok1 && ok2 && ok3) ++stats.theorem_preserving_survivors;
        }
    }
    stats.unsupported_plus_one_candidates = 0;
    save_antecedent_shell15_plus_one_result_cache_(spec.tag, plus_result, nullptr);
    stats.completed = true; stats.why = string("antecedent shell15 frontier scan tag=") + spec.tag; g_last_antecedent_shell15_frontier_stats[spec.tag] = stats;
    AntecedentShell15FrontierTheoremData td; td.tag = stats.tag; td.raw_candidates = stats.raw_candidates; td.canonical_candidates = stats.canonical_candidates; td.outside_bounded_candidates = stats.outside_bounded_candidates; td.local_exact_survivors = stats.local_exact_survivors; td.plus_one_survivors = stats.plus_one_survivors; td.theorem_preserving_survivors = stats.theorem_preserving_survivors; td.unsupported_local_exact_candidates = stats.unsupported_local_exact_candidates; td.unsupported_plus_one_candidates = stats.unsupported_plus_one_candidates; td.why = stats.why; g_last_antecedent_shell15_frontier_theorem_data[spec.tag] = td; if (why) *why = stats.why; return stats;
}

static vector<string> legacy_shell15_frontier_candidate_fingerprints_(const string& tag) {
    if (tag == "antecedent_plus_twelve_frontier") {
        return {
            "num=7 antecedents=[(1,2->1) (2,3->1) (2,3->2) (2,3->4) (2,4->2) (2,4->4) (3,4->1) (3,4->5)] => (2,3->3)",
            "num=7 antecedents=[(1,2->1) (2,3->1) (2,3->2) (2,3->4) (2,4->2) (2,4->4) (3,4->1) (3,4->5)] => (2,4->1)"
        };
    }
    if (tag == "support8_antecedent15_frontier") {
        return {
            "num=8 antecedents=[(1,2->1) (2,3->1) (2,3->2) (2,3->4) (2,4->2) (2,4->4) (3,4->1) (3,4->5)] => (2,3->3)",
            "num=8 antecedents=[(1,2->1) (2,3->1) (2,3->2) (2,3->4) (2,4->2) (2,4->4) (3,4->1) (3,4->5)] => (2,4->1)"
        };
    }
    return {};
}

static string shell15_frontier_fingerprint_from_strings_(vector<string> fps) {
    sort(fps.begin(), fps.end());
    fps.erase(unique(fps.begin(), fps.end()), fps.end());
    ostringstream oss;
    for (size_t i = 0; i < fps.size(); ++i) {
        if (i) oss << ';';
        oss << fps[i];
    }
    return oss.str();
}

static string antecedent_shell15_frontier_theorem_data_to_fingerprint_(const AntecedentShell15FrontierTheoremData& d) {
    ostringstream oss;
    oss << d.tag << '|' << d.raw_candidates << '|' << d.canonical_candidates << '|' << d.outside_bounded_candidates
        << '|' << d.local_exact_survivors << '|' << d.plus_one_survivors << '|' << d.theorem_preserving_survivors
        << '|' << d.unsupported_local_exact_candidates << '|' << d.unsupported_plus_one_candidates;
    return oss.str();
}

static void reset_shell15_frontier_runtime_audit_state_(const string& tag) {
    auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
    state = Shell15FrontierRuntimeAuditState{};
    state.tag = tag;
    state.fallback_reachable = true;
}

static string shell15_frontier_generation_audit_path_(const string& tag) {
    if (tag == "antecedent_plus_twelve_frontier") {
        return support8_runtime_paths::runtime_bundle_path_("antecedent_plus_twelve_frontier_generation_audit_90.tsv");
    }
    if (tag == "support8_antecedent15_frontier") {
        return support8_runtime_paths::runtime_bundle_path_("support8_antecedent15_frontier_generation_audit_90.tsv");
    }
    return support8_runtime_paths::runtime_bundle_path_(string("shell15_frontier_generation_audit_90_") + tag + ".tsv");
}

static map<string, string> read_shell15_metric_tsv_(const string& path) {
    map<string, string> out;
    ifstream fin(path);
    if (!fin) return out;
    string line;
    bool first = true;
    while (getline(fin, line)) {
        if (first) {
            first = false;
            continue;
        }
        if (line.empty()) continue;
        size_t tab = line.find('\t');
        if (tab == string::npos) continue;
        out[line.substr(0, tab)] = line.substr(tab + 1);
    }
    return out;
}

static bool parse_size_t_shell15_metric_(const string& text, size_t* out) {
    if (!out || text.empty()) return false;
    try {
        *out = static_cast<size_t>(stoull(text));
        return true;
    } catch (...) {
        return false;
    }
}

static string shell15_bool_cache_rows_fingerprint_(vector<pair<string, bool>> rows) {
    sort(rows.begin(), rows.end(), [](const pair<string, bool>& a, const pair<string, bool>& b) {
        return a.first < b.first;
    });
    ostringstream oss;
    for (size_t i = 0; i < rows.size(); ++i) {
        if (i) oss << ';';
        oss << rows[i].first << ':' << (rows[i].second ? 1 : 0);
    }
    return oss.str();
}

static string shell15_progress_cache_row_fingerprint_(const string& tag, size_t done, size_t total) {
    ostringstream oss;
    oss << tag << '|' << done << '|' << total;
    return oss.str();
}

static size_t count_true_shell15_bool_rows_(const vector<pair<string, bool>>& rows) {
    size_t count = 0;
    for (const auto& row : rows) if (row.second) ++count;
    return count;
}

static size_t compute_shell15_theorem_preserving_survivors_(
    const vector<StructuredLocalSchema>& local_survivors,
    const vector<pair<string, bool>>& plus_rows) {
    unordered_map<string, bool> plus_ok_by_fp;
    plus_ok_by_fp.reserve(plus_rows.size() * 2 + 1);
    for (const auto& row : plus_rows) plus_ok_by_fp[row.first] = row.second;
    size_t count = 0;
    for (const auto& schema : local_survivors) {
        const string fp = canonical_structured_local_schema_fingerprint_(schema);
        auto it = plus_ok_by_fp.find(fp);
        if (it == plus_ok_by_fp.end() || !it->second) continue;
        string t1, t2, t3;
        bool ok1 = validate_antecedent_shell15_schema_preserves_basis_theorem_n5_(schema, &t1);
        bool ok2 = validate_antecedent_shell15_schema_preserves_basis_theorem_n6_c5_(schema, &t2);
        bool ok3 = validate_antecedent_shell15_schema_preserves_basis_theorem_n7_c3_(schema, &t3);
        if (ok1 && ok2 && ok3) ++count;
    }
    return count;
}

static string shell15_frontier_runtime_fingerprint_(const Shell15FrontierRuntimeAuditState& state) {
    ostringstream oss;
    oss << state.tag << '|'
        << (state.fresh_runtime_generated ? "fresh" : "imported") << '|'
        << state.authoritative_source << '|'
        << state.constructor_name << '|'
        << (state.fallback_reachable ? 1 : 0) << '|'
        << (state.fallback_hit ? 1 : 0) << '|'
        << state.raw_candidates << '|'
        << state.canonical_candidates << '|'
        << state.outside_bounded_candidates << '|'
        << state.local_exact_survivors << '|'
        << state.plus_one_survivors << '|'
        << state.theorem_preserving_survivors << '|'
        << state.unsupported_local_exact_candidates << '|'
        << state.unsupported_plus_one_candidates << '|'
        << state.candidate_row_count << '|'
        << state.candidate_universe_fingerprint << '|'
        << state.local_exact_result_cache_fingerprint << '|'
        << state.local_exact_progress_cache_fingerprint << '|'
        << state.local_exact_survivor_fingerprint << '|'
        << state.plus_one_result_cache_fingerprint << '|'
        << state.imported_counts_fingerprint << '|'
        << state.imported_candidate_fingerprint << '|'
        << (state.imported_count_equality ? 1 : 0) << '|'
        << (state.imported_row_set_equality ? 1 : 0) << '|'
        << state.current_source_fingerprint << '|'
        << state.blocker << '|'
        << state.caveat;
    return oss.str();
}

static void refresh_shell15_frontier_pair_runtime_state_() {
    const auto it1 = g_last_shell15_frontier_runtime_audit_state.find("antecedent_plus_twelve_frontier");
    const auto it2 = g_last_shell15_frontier_runtime_audit_state.find("support8_antecedent15_frontier");
    g_last_shell15_frontier_pair_fresh_runtime_generated =
        it1 != g_last_shell15_frontier_runtime_audit_state.end() &&
        it2 != g_last_shell15_frontier_runtime_audit_state.end() &&
        it1->second.fresh_runtime_generated &&
        it2->second.fresh_runtime_generated &&
        !it1->second.fallback_hit &&
        !it2->second.fallback_hit;
    ostringstream oss;
    if (it1 != g_last_shell15_frontier_runtime_audit_state.end()) oss << it1->second.runtime_fingerprint;
    oss << '|';
    if (it2 != g_last_shell15_frontier_runtime_audit_state.end()) oss << it2->second.runtime_fingerprint;
    oss << '|' << (g_last_shell15_frontier_pair_fresh_runtime_generated ? 1 : 0);
    g_last_shell15_frontier_pair_runtime_fingerprint = oss.str();
}

static bool load_current_shell15_frontier_runtime_artifact_(
    const string& tag,
    AntecedentShell15FrontierTheoremData* out,
    string* why) {
    if (!out) {
        if (why) *why = "no output buffer provided";
        return false;
    }
    reset_shell15_frontier_runtime_audit_state_(tag);
    auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
    state.current_source_fingerprint =
        binary_fingerprint_for_audit_(current_bundle_metadata_().source_path);

    const string audit_path = shell15_frontier_generation_audit_path_(tag);
    if (!std::filesystem::exists(audit_path) ||
        !std::filesystem::is_regular_file(audit_path) ||
        std::filesystem::file_size(audit_path) == 0) {
        state.blocker = string("runtime shell15 frontier generation audit missing tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }

    auto metrics = read_shell15_metric_tsv_(audit_path);
    if (metrics["current_provenance_label"] != "fresh_current_runtime_generated") {
        state.blocker = string("runtime shell15 frontier audit not marked fresh tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }
    if (metrics["current_source_fingerprint"] != state.current_source_fingerprint) {
        state.blocker = string("runtime shell15 frontier audit source fingerprint stale tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }

    auto candidate = antecedent_shell15_candidate_theorem_data_(tag, nullptr);
    auto local_rows = load_tagged_shell15_bool_cache_rows_(kAntecedentShell15LocalExactResultCachePath, tag, nullptr);
    auto plus_rows = load_tagged_shell15_bool_cache_rows_(kAntecedentShell15PlusOneResultCachePath, tag, nullptr);
    size_t done = 0, total = 0;
    if (!load_tagged_shell15_progress_cache_row_(tag, &done, &total, nullptr)) {
        state.blocker = string("runtime shell15 frontier progress cache missing tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }
    auto local_survivors = antecedent_shell15_local_exact_survivors_(tag, nullptr);
    auto survivor_td = antecedent_shell15_local_exact_survivor_theorem_data_(tag, nullptr);
    auto imported = imported_antecedent_shell15_frontier_theorem_data_legacy_(tag, nullptr);

    state.raw_candidates = candidate.raw_candidates;
    state.canonical_candidates = candidate.canonical_candidates;
    state.outside_bounded_candidates = candidate.outside_bounded_candidates;
    state.local_exact_survivors = count_true_shell15_bool_rows_(local_rows);
    state.plus_one_survivors = count_true_shell15_bool_rows_(plus_rows);
    state.theorem_preserving_survivors =
        compute_shell15_theorem_preserving_survivors_(local_survivors, plus_rows);
    state.unsupported_local_exact_candidates = 0;
    state.unsupported_plus_one_candidates = 0;
    state.candidate_row_count = candidate.candidate_fingerprints.size();
    state.candidate_universe_fingerprint = candidate.fingerprint;
    state.local_exact_result_cache_fingerprint = shell15_bool_cache_rows_fingerprint_(local_rows);
    state.local_exact_progress_cache_fingerprint =
        shell15_progress_cache_row_fingerprint_(tag, done, total);
    state.local_exact_survivor_fingerprint =
        to_string(survivor_td.survivor_count) + "|" + survivor_td.fingerprint;
    state.plus_one_result_cache_fingerprint = shell15_bool_cache_rows_fingerprint_(plus_rows);
    state.imported_counts_fingerprint =
        antecedent_shell15_frontier_theorem_data_to_fingerprint_(imported);
    state.imported_candidate_fingerprint =
        shell15_frontier_fingerprint_from_strings_(legacy_shell15_frontier_candidate_fingerprints_(tag));

    AntecedentShell15FrontierTheoremData current;
    current.tag = tag;
    current.raw_candidates = state.raw_candidates;
    current.canonical_candidates = state.canonical_candidates;
    current.outside_bounded_candidates = state.outside_bounded_candidates;
    current.local_exact_survivors = state.local_exact_survivors;
    current.plus_one_survivors = state.plus_one_survivors;
    current.theorem_preserving_survivors = state.theorem_preserving_survivors;
    current.unsupported_local_exact_candidates = state.unsupported_local_exact_candidates;
    current.unsupported_plus_one_candidates = state.unsupported_plus_one_candidates;
    current.why = "authoritative shell15 frontier theorem data loaded from validated runtime artifact";

    state.imported_count_equality =
        antecedent_shell15_frontier_theorem_data_to_fingerprint_(current) ==
        state.imported_counts_fingerprint;
    state.imported_row_set_equality =
        state.candidate_universe_fingerprint == state.imported_candidate_fingerprint;

    auto check_metric_eq = [&](const string& key, const string& actual) {
        auto it = metrics.find(key);
        return it != metrics.end() && it->second == actual;
    };
    auto check_metric_size = [&](const string& key, size_t actual) {
        size_t parsed = 0;
        auto it = metrics.find(key);
        return it != metrics.end() && parse_size_t_shell15_metric_(it->second, &parsed) && parsed == actual;
    };

    const bool audit_matches =
        check_metric_eq("target_item", tag) &&
        check_metric_size("raw_candidates", state.raw_candidates) &&
        check_metric_size("canonical_candidates", state.canonical_candidates) &&
        check_metric_size("outside_bounded_candidates", state.outside_bounded_candidates) &&
        check_metric_size("local_exact_survivors", state.local_exact_survivors) &&
        check_metric_size("plus_one_survivors", state.plus_one_survivors) &&
        check_metric_size("theorem_preserving_survivors", state.theorem_preserving_survivors) &&
        check_metric_size("unsupported_local_exact_candidates", state.unsupported_local_exact_candidates) &&
        check_metric_size("unsupported_plus_one_candidates", state.unsupported_plus_one_candidates) &&
        check_metric_size("candidate_row_count", state.candidate_row_count) &&
        check_metric_eq("candidate_universe_fingerprint", state.candidate_universe_fingerprint) &&
        check_metric_eq("local_exact_result_cache_fingerprint", state.local_exact_result_cache_fingerprint) &&
        check_metric_eq("local_exact_progress_cache_fingerprint", state.local_exact_progress_cache_fingerprint) &&
        check_metric_eq("local_exact_survivor_fingerprint", state.local_exact_survivor_fingerprint) &&
        check_metric_eq("plus_one_result_cache_fingerprint", state.plus_one_result_cache_fingerprint) &&
        check_metric_eq("imported_counts_fingerprint", state.imported_counts_fingerprint) &&
        check_metric_eq("imported_candidate_fingerprint", state.imported_candidate_fingerprint) &&
        check_metric_eq("imported_count_equality", state.imported_count_equality ? "1" : "0") &&
        check_metric_eq("imported_row_set_equality", state.imported_row_set_equality ? "1" : "0") &&
        check_metric_eq("fallback_hit", "0");

    if (!audit_matches) {
        state.blocker = string("runtime shell15 frontier audit mismatch tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }
    if (!state.imported_count_equality || !state.imported_row_set_equality) {
        state.blocker = string("runtime shell15 frontier artifact equality check failed tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }

    state.fresh_runtime_generated = true;
    state.authoritative_source = "current_runtime_shell15_frontier_cache";
    state.constructor_name = "load_current_shell15_frontier_runtime_artifact_";
    state.fallback_hit = false;
    state.caveat =
        "Current authoritative path loaded validated shell15 frontier runtime artifacts; imported 84 data remains only as compatibility fallback and equality oracle.";
    state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
    current.why = state.caveat;
    *out = current;
    refresh_shell15_frontier_pair_runtime_state_();
    if (why) *why = "loaded validated runtime shell15 frontier artifact";
    return true;
}

static AntecedentShell15FrontierTheoremData imported_antecedent_shell15_frontier_theorem_data_legacy_(const string& tag,
                                                                                                       string* why) {
    AntecedentShell15FrontierTheoremData d;
    d.tag = tag;
    if (tag == "antecedent_plus_twelve_frontier" || tag == "support8_antecedent15_frontier") {
        d.raw_candidates = 4;
        d.canonical_candidates = 2;
        d.outside_bounded_candidates = 2;
        d.local_exact_survivors = 0;
        d.plus_one_survivors = 0;
        d.theorem_preserving_survivors = 0;
        d.unsupported_local_exact_candidates = 0;
        d.unsupported_plus_one_candidates = 0;
        d.why = string("authoritative ") + tag + " theorem data imported from closed 84 output";
        if (why) *why = d.why;
        return d;
    }
    d.why = string("authoritative shell15 theorem data unsupported tag=") + tag;
    if (why) *why = d.why;
    return d;
}

static AntecedentShell15FrontierTheoremData antecedent_shell15_frontier_theorem_data_(const string& tag, string* why) {
    auto cached = g_last_antecedent_shell15_frontier_theorem_data.find(tag);
    if (cached != g_last_antecedent_shell15_frontier_theorem_data.end()) {
        if (why) *why = cached->second.why;
        return cached->second;
    }

    AntecedentShell15FrontierTheoremData d;
    string current_why;
    if (build_current_shell15_frontier_theorem_data_(tag, true, &d, &current_why)) {
        d.why = current_why;
        g_last_antecedent_shell15_frontier_theorem_data[tag] = d;
        if (why) *why = d.why;
        return d;
    }

    d = imported_antecedent_shell15_frontier_theorem_data_legacy_(tag, nullptr);
    auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
    if (state.tag.empty()) reset_shell15_frontier_runtime_audit_state_(tag);
    state.fallback_hit = true;
    state.authoritative_source = "imported_closed_output_shell15_frontier_84";
    state.constructor_name = "imported_authoritative_support8_shell15_frontier_output_84";
    state.raw_candidates = d.raw_candidates;
    state.canonical_candidates = d.canonical_candidates;
    state.outside_bounded_candidates = d.outside_bounded_candidates;
    state.local_exact_survivors = d.local_exact_survivors;
    state.plus_one_survivors = d.plus_one_survivors;
    state.theorem_preserving_survivors = d.theorem_preserving_survivors;
    state.unsupported_local_exact_candidates = d.unsupported_local_exact_candidates;
    state.unsupported_plus_one_candidates = d.unsupported_plus_one_candidates;
    state.imported_counts_fingerprint = antecedent_shell15_frontier_theorem_data_to_fingerprint_(d);
    state.imported_candidate_fingerprint =
        shell15_frontier_fingerprint_from_strings_(legacy_shell15_frontier_candidate_fingerprints_(tag));
    state.blocker = current_why;
    state.caveat = "Current authoritative shell15 frontier path fell back to closed-output 84 theorem data.";
    state.runtime_fingerprint = state.authoritative_source + "|" + state.constructor_name + "|" + state.imported_counts_fingerprint + "|" + state.blocker;
    d.why = current_why.empty() ? d.why : current_why + " ; " + d.why;
    g_last_antecedent_shell15_frontier_theorem_data[tag] = d;
    if (why) *why = d.why;
    return d;
}

static string antecedent_shell15_frontier_theorem_data_fingerprint_(const string& tag, string* why) {
    auto d = antecedent_shell15_frontier_theorem_data_(tag, nullptr);
    if (why) *why = d.why;
    return antecedent_shell15_frontier_theorem_data_to_fingerprint_(d);
}

static bool validate_antecedent_shell15_frontier_theorem_data_(const string& tag, string* why) {
    auto d = antecedent_shell15_frontier_theorem_data_(tag, nullptr);
    bool ok = d.canonical_candidates >= d.outside_bounded_candidates && d.local_exact_survivors >= d.plus_one_survivors && d.plus_one_survivors >= d.theorem_preserving_survivors;
    if (why) {
        const auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
        ostringstream oss;
        oss << "antecedentShell15FrontierData tag=" << tag
            << " raw=" << d.raw_candidates
            << " canonical=" << d.canonical_candidates
            << " outside=" << d.outside_bounded_candidates
            << " localExactSurvivors=" << d.local_exact_survivors
            << " plusOneSurvivors=" << d.plus_one_survivors
            << " theoremPreservingSurvivors=" << d.theorem_preserving_survivors
            << " unsupportedLocalExact=" << d.unsupported_local_exact_candidates
            << " unsupportedPlusOne=" << d.unsupported_plus_one_candidates
            << " fingerprint=" << antecedent_shell15_frontier_theorem_data_fingerprint_(tag, nullptr)
            << " source=" << state.authoritative_source
            << " constructor=" << state.constructor_name
            << " fallbackHit=" << (state.fallback_hit ? 1 : 0)
            << " importedCountEqual=" << (state.imported_count_equality ? 1 : 0)
            << " importedRowSetEqual=" << (state.imported_row_set_equality ? 1 : 0);
        *why = oss.str();
    }
    return ok;
}

static GeneralStructuredSchemaFrontierStats antecedent_plus_twelve_frontier_stats_from_theorem_data_() {
    auto d = antecedent_shell15_frontier_theorem_data_("antecedent_plus_twelve_frontier", nullptr);
    GeneralStructuredSchemaFrontierStats s; s.tag = d.tag; s.raw_candidates = d.raw_candidates; s.canonical_candidates = d.canonical_candidates; s.outside_bounded_candidates = d.outside_bounded_candidates; s.local_exact_survivors = d.local_exact_survivors; s.plus_one_survivors = d.plus_one_survivors; s.theorem_preserving_survivors = d.theorem_preserving_survivors; s.unsupported_local_exact_candidates = d.unsupported_local_exact_candidates; s.unsupported_plus_one_candidates = d.unsupported_plus_one_candidates; s.completed = true; s.why = d.why; return s;
}

static GeneralStructuredSchemaFrontierStats support8_antecedent15_frontier_stats_from_theorem_data_() {
    auto d = antecedent_shell15_frontier_theorem_data_("support8_antecedent15_frontier", nullptr);
    GeneralStructuredSchemaFrontierStats s; s.tag = d.tag; s.raw_candidates = d.raw_candidates; s.canonical_candidates = d.canonical_candidates; s.outside_bounded_candidates = d.outside_bounded_candidates; s.local_exact_survivors = d.local_exact_survivors; s.plus_one_survivors = d.plus_one_survivors; s.theorem_preserving_survivors = d.theorem_preserving_survivors; s.unsupported_local_exact_candidates = d.unsupported_local_exact_candidates; s.unsupported_plus_one_candidates = d.unsupported_plus_one_candidates; s.completed = true; s.why = d.why; return s;
}

static bool current_shell15_frontier_pair_fresh_runtime_generated_() {
    const auto it1 = g_last_shell15_frontier_runtime_audit_state.find("antecedent_plus_twelve_frontier");
    const auto it2 = g_last_shell15_frontier_runtime_audit_state.find("support8_antecedent15_frontier");
    return it1 != g_last_shell15_frontier_runtime_audit_state.end() &&
           it2 != g_last_shell15_frontier_runtime_audit_state.end() &&
           it1->second.fresh_runtime_generated &&
           it2->second.fresh_runtime_generated;
}

static bool build_current_shell15_frontier_theorem_data_(const string& tag,
                                                          bool allow_slow_rebuild,
                                                          AntecedentShell15FrontierTheoremData* out,
                                                          string* why) {
    if (!out) {
        if (why) *why = "no shell15 frontier output buffer provided";
        return false;
    }

    if (load_current_shell15_frontier_runtime_artifact_(tag, out, why)) {
        return true;
    }

    auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
    if (!allow_slow_rebuild) {
        if (why) *why = state.blocker.empty()
                            ? string("shell15 frontier current runtime artifact unavailable tag=") + tag
                            : state.blocker;
        refresh_shell15_frontier_pair_runtime_state_();
        return false;
    }

    reset_shell15_frontier_runtime_audit_state_(tag);
    state = g_last_shell15_frontier_runtime_audit_state[tag];
    state.current_source_fingerprint =
        binary_fingerprint_for_audit_(current_bundle_metadata_().source_path);

    string specs_why;
    auto specs = build_antecedent_shell15_frontier_specs_(
        build_bounded_schema_universe_scope_stats_(nullptr), &specs_why);
    AntecedentShell15FrontierSpec spec;
    bool found = false;
    for (const auto& s : specs) {
        if (s.tag == tag) {
            spec = s;
            found = true;
            break;
        }
    }
    if (!found) {
        state.blocker = string("unknown shell15 frontier tag=") + tag;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }

    size_t raw_count = 0;
    string enum_why;
    auto fresh_candidates =
        enumerate_antecedent_shell15_frontier_candidates_(spec, &raw_count, &enum_why);
    string save_universe_why;
    if (!save_antecedent_shell15_candidate_universe_(tag, fresh_candidates, &save_universe_why)) {
        state.blocker = save_universe_why;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = state.blocker;
        return false;
    }

    AntecedentShell15CandidateTheoremData candidate_data;
    candidate_data.tag = tag;
    candidate_data.raw_candidates = raw_count;
    candidate_data.canonical_candidates = fresh_candidates.size();
    candidate_data.outside_bounded_candidates = fresh_candidates.size();
    for (const auto& schema : fresh_candidates) {
        candidate_data.candidate_fingerprints.push_back(
            canonical_structured_local_schema_fingerprint_(schema));
    }
    sort(candidate_data.candidate_fingerprints.begin(), candidate_data.candidate_fingerprints.end());
    candidate_data.candidate_fingerprints.erase(
        unique(candidate_data.candidate_fingerprints.begin(),
               candidate_data.candidate_fingerprints.end()),
        candidate_data.candidate_fingerprints.end());
    candidate_data.canonical_candidates = candidate_data.candidate_fingerprints.size();
    candidate_data.outside_bounded_candidates = candidate_data.candidate_fingerprints.size();
    candidate_data.why = enum_why + " ; " + save_universe_why;
    {
        ostringstream oss;
        for (size_t i = 0; i < candidate_data.candidate_fingerprints.size(); ++i) {
            if (i) oss << ';';
            oss << candidate_data.candidate_fingerprints[i];
        }
        candidate_data.fingerprint = oss.str();
    }
    g_last_antecedent_shell15_candidate_theorem_data[tag] = candidate_data;
    g_last_antecedent_shell15_frontier_candidates[tag] = fresh_candidates;
    g_last_antecedent_shell15_frontier_local_exact_survivors.erase(tag);
    g_last_antecedent_shell15_local_exact_survivor_theorem_data.erase(tag);

    string scan_why;
    auto scan_stats = scan_antecedent_shell15_frontier_(spec, {}, &scan_why);
    auto current = g_last_antecedent_shell15_frontier_theorem_data[tag];
    auto local_rows =
        load_tagged_shell15_bool_cache_rows_(kAntecedentShell15LocalExactResultCachePath, tag, nullptr);
    auto plus_rows =
        load_tagged_shell15_bool_cache_rows_(kAntecedentShell15PlusOneResultCachePath, tag, nullptr);
    size_t done = 0, total = 0;
    (void)load_tagged_shell15_progress_cache_row_(tag, &done, &total, nullptr);
    auto local_survivors = antecedent_shell15_local_exact_survivors_(tag, nullptr);
    auto survivor_td = antecedent_shell15_local_exact_survivor_theorem_data_(tag, nullptr);
    auto imported = imported_antecedent_shell15_frontier_theorem_data_legacy_(tag, nullptr);

    state.raw_candidates = current.raw_candidates;
    state.canonical_candidates = current.canonical_candidates;
    state.outside_bounded_candidates = current.outside_bounded_candidates;
    state.local_exact_survivors = current.local_exact_survivors;
    state.plus_one_survivors = current.plus_one_survivors;
    state.theorem_preserving_survivors = current.theorem_preserving_survivors;
    state.unsupported_local_exact_candidates = current.unsupported_local_exact_candidates;
    state.unsupported_plus_one_candidates = current.unsupported_plus_one_candidates;
    state.candidate_row_count = candidate_data.candidate_fingerprints.size();
    state.candidate_universe_fingerprint = candidate_data.fingerprint;
    state.local_exact_result_cache_fingerprint = shell15_bool_cache_rows_fingerprint_(local_rows);
    state.local_exact_progress_cache_fingerprint =
        shell15_progress_cache_row_fingerprint_(tag, done, total);
    state.local_exact_survivor_fingerprint =
        to_string(survivor_td.survivor_count) + "|" + survivor_td.fingerprint;
    state.plus_one_result_cache_fingerprint = shell15_bool_cache_rows_fingerprint_(plus_rows);
    state.imported_counts_fingerprint =
        antecedent_shell15_frontier_theorem_data_to_fingerprint_(imported);
    state.imported_candidate_fingerprint =
        shell15_frontier_fingerprint_from_strings_(legacy_shell15_frontier_candidate_fingerprints_(tag));
    state.imported_count_equality =
        antecedent_shell15_frontier_theorem_data_to_fingerprint_(current) ==
        state.imported_counts_fingerprint;
    state.imported_row_set_equality =
        state.candidate_universe_fingerprint == state.imported_candidate_fingerprint;

    const bool progress_complete = (done == total && total == candidate_data.candidate_fingerprints.size());
    const bool local_cache_consistent = local_survivors.size() == count_true_shell15_bool_rows_(local_rows);
    const bool plus_cache_consistent = count_true_shell15_bool_rows_(plus_rows) == current.plus_one_survivors;
    const bool theorem_cache_consistent =
        compute_shell15_theorem_preserving_survivors_(local_survivors, plus_rows) ==
        current.theorem_preserving_survivors;

    if (state.imported_count_equality &&
        state.imported_row_set_equality &&
        progress_complete &&
        local_cache_consistent &&
        plus_cache_consistent &&
        theorem_cache_consistent &&
        scan_stats.completed) {
        state.fresh_runtime_generated = true;
        state.authoritative_source = "current_runtime_shell15_frontier_scan";
        state.constructor_name = "scan_antecedent_shell15_frontier_";
        state.fallback_hit = false;
        state.caveat =
            "Current runtime freshly enumerated the shell15 frontier candidate universe and rebuilt the local-exact and plus-one caches; imported 84 data remains only as compatibility fallback and equality oracle.";
        current.why = state.caveat;
        *out = current;
        state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
        refresh_shell15_frontier_pair_runtime_state_();
        if (why) *why = scan_why;
        return true;
    }

    state.blocker =
        string("current shell15 frontier constructor did not reproduce the authoritative imported shell15 frontier tag=") +
        tag + " countEq=" + (state.imported_count_equality ? "1" : "0") +
        " rowEq=" + (state.imported_row_set_equality ? "1" : "0") +
        " progress=" + (progress_complete ? "1" : "0") +
        " localCache=" + (local_cache_consistent ? "1" : "0") +
        " plusCache=" + (plus_cache_consistent ? "1" : "0") +
        " theoremCache=" + (theorem_cache_consistent ? "1" : "0");
    state.caveat =
        "Current shell15 frontier scan ran, but its theorem object / cache equality checks did not yet justify replacing the imported 84 frontier payload.";
    state.runtime_fingerprint = shell15_frontier_runtime_fingerprint_(state);
    g_last_antecedent_shell15_frontier_theorem_data.erase(tag);
    refresh_shell15_frontier_pair_runtime_state_();
    if (why) *why = state.blocker;
    return false;
}

static bool write_shell15_frontier_generation_audit_files_(string* why) {
    const vector<string> tags = {
        "antecedent_plus_twelve_frontier",
        "support8_antecedent15_frontier"
    };
    for (const auto& tag : tags) {
        if (g_last_shell15_frontier_runtime_audit_state.find(tag) ==
            g_last_shell15_frontier_runtime_audit_state.end()) {
            (void)antecedent_shell15_frontier_theorem_data_(tag, nullptr);
        }
    }

    for (const auto& tag : tags) {
        const auto it = g_last_shell15_frontier_runtime_audit_state.find(tag);
        if (it == g_last_shell15_frontier_runtime_audit_state.end()) {
            if (why) *why = string("missing shell15 runtime state for tag=") + tag;
            return false;
        }
        const auto& state = it->second;
        ofstream out(shell15_frontier_generation_audit_path_(tag));
        if (!out) {
            if (why) *why = string("failed to write shell15 frontier generation audit tag=") + tag;
            return false;
        }
        out << "metric\tvalue\n";
        out << "target_item\t" << tag << "\n";
        out << "current_provenance_label\t"
            << (state.fresh_runtime_generated ? "fresh_current_runtime_generated"
                                              : "current_runtime_validated_imported_data")
            << "\n";
        out << "authoritative_source\t" << sanitize_provenance_tsv_field_(state.authoritative_source) << "\n";
        out << "constructor_name\t" << sanitize_provenance_tsv_field_(state.constructor_name) << "\n";
        out << "fresh_constructor_name\tscan_antecedent_shell15_frontier_\n";
        out << "cache_load_constructor_name\tload_current_shell15_frontier_runtime_artifact_\n";
        out << "current_source_fingerprint\t" << sanitize_provenance_tsv_field_(state.current_source_fingerprint) << "\n";
        out << "raw_candidates\t" << state.raw_candidates << "\n";
        out << "canonical_candidates\t" << state.canonical_candidates << "\n";
        out << "outside_bounded_candidates\t" << state.outside_bounded_candidates << "\n";
        out << "local_exact_survivors\t" << state.local_exact_survivors << "\n";
        out << "plus_one_survivors\t" << state.plus_one_survivors << "\n";
        out << "theorem_preserving_survivors\t" << state.theorem_preserving_survivors << "\n";
        out << "unsupported_local_exact_candidates\t" << state.unsupported_local_exact_candidates << "\n";
        out << "unsupported_plus_one_candidates\t" << state.unsupported_plus_one_candidates << "\n";
        out << "candidate_row_count\t" << state.candidate_row_count << "\n";
        out << "candidate_universe_fingerprint\t" << sanitize_provenance_tsv_field_(state.candidate_universe_fingerprint) << "\n";
        out << "local_exact_result_cache_fingerprint\t" << sanitize_provenance_tsv_field_(state.local_exact_result_cache_fingerprint) << "\n";
        out << "local_exact_progress_cache_fingerprint\t" << sanitize_provenance_tsv_field_(state.local_exact_progress_cache_fingerprint) << "\n";
        out << "local_exact_survivor_fingerprint\t" << sanitize_provenance_tsv_field_(state.local_exact_survivor_fingerprint) << "\n";
        out << "plus_one_result_cache_fingerprint\t" << sanitize_provenance_tsv_field_(state.plus_one_result_cache_fingerprint) << "\n";
        out << "imported_counts_fingerprint\t" << sanitize_provenance_tsv_field_(state.imported_counts_fingerprint) << "\n";
        out << "imported_candidate_fingerprint\t" << sanitize_provenance_tsv_field_(state.imported_candidate_fingerprint) << "\n";
        out << "imported_count_equality\t" << (state.imported_count_equality ? 1 : 0) << "\n";
        out << "imported_row_set_equality\t" << (state.imported_row_set_equality ? 1 : 0) << "\n";
        out << "fallback_reachable\t" << (state.fallback_reachable ? 1 : 0) << "\n";
        out << "fallback_hit\t" << (state.fallback_hit ? 1 : 0) << "\n";
        out << "runtime_fingerprint\t" << sanitize_provenance_tsv_field_(state.runtime_fingerprint) << "\n";
        out << "blocker\t" << sanitize_provenance_tsv_field_(state.blocker) << "\n";
        out << "caveat\t" << sanitize_provenance_tsv_field_(state.caveat) << "\n";
    }

    ofstream summary_out(support8_runtime_paths::runtime_bundle_path_("shell15_frontier_generation_fingerprint_90.tsv"));
    if (!summary_out) {
        if (why) *why = "failed to write shell15 frontier generation fingerprint summary";
        return false;
    }
    summary_out << "metric\tvalue\n";
    summary_out << "pair_fresh_runtime_generated\t"
                << (g_last_shell15_frontier_pair_fresh_runtime_generated ? 1 : 0) << "\n";
    summary_out << "pair_runtime_fingerprint\t"
                << sanitize_provenance_tsv_field_(g_last_shell15_frontier_pair_runtime_fingerprint) << "\n";
    for (const auto& tag : tags) {
        const auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
        summary_out << tag << "_constructor_name\t"
                    << sanitize_provenance_tsv_field_(state.constructor_name) << "\n";
        summary_out << tag << "_authoritative_source\t"
                    << sanitize_provenance_tsv_field_(state.authoritative_source) << "\n";
        summary_out << tag << "_fallback_hit\t" << (state.fallback_hit ? 1 : 0) << "\n";
        summary_out << tag << "_runtime_fingerprint\t"
                    << sanitize_provenance_tsv_field_(state.runtime_fingerprint) << "\n";
    }

    ofstream rowset_out(support8_runtime_paths::runtime_bundle_path_("shell15_frontier_rowset_equality_90.tsv"));
    if (!rowset_out) {
        if (why) *why = "failed to write shell15 frontier row-set equality audit";
        return false;
    }
    rowset_out << "target_item\tcandidate_row_count\tcandidate_universe_fingerprint\timported_candidate_fingerprint\timported_row_set_equal\n";
    for (const auto& tag : tags) {
        const auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
        rowset_out << sanitize_provenance_tsv_field_(tag) << '\t'
                   << state.candidate_row_count << '\t'
                   << sanitize_provenance_tsv_field_(state.candidate_universe_fingerprint) << '\t'
                   << sanitize_provenance_tsv_field_(state.imported_candidate_fingerprint) << '\t'
                   << (state.imported_row_set_equality ? 1 : 0) << "\n";
    }

    ofstream constructor_out(support8_runtime_paths::runtime_bundle_path_("shell15_frontier_constructor_fingerprint_90.tsv"));
    if (!constructor_out) {
        if (why) *why = "failed to write shell15 frontier constructor fingerprint audit";
        return false;
    }
    constructor_out << "metric\tvalue\n";
    constructor_out << "fresh_constructor_name\tscan_antecedent_shell15_frontier_\n";
    constructor_out << "cache_load_constructor_name\tload_current_shell15_frontier_runtime_artifact_\n";
    for (const auto& tag : tags) {
        const auto& state = g_last_shell15_frontier_runtime_audit_state[tag];
        constructor_out << tag << "_current_constructor\t"
                        << sanitize_provenance_tsv_field_(state.constructor_name) << "\n";
        constructor_out << tag << "_current_source\t"
                        << sanitize_provenance_tsv_field_(state.authoritative_source) << "\n";
        constructor_out << tag << "_fallback_hit\t" << (state.fallback_hit ? 1 : 0) << "\n";
    }

    if (why) {
        *why = "wrote shell15 frontier generation audits";
    }
    return true;
}

static vector<string> split_tsv_fields_(const string& line) {
    vector<string> out;
    size_t pos = 0;
    while (true) {
        size_t tab = line.find('\t', pos);
        if (tab == string::npos) {
            out.push_back(line.substr(pos));
            break;
        }
        out.push_back(line.substr(pos, tab - pos));
        pos = tab + 1;
    }
    return out;
}

static vector<map<string, string>> read_tsv_rows_with_header_(const string& path) {
    vector<map<string, string>> rows;
    ifstream fin(path);
    if (!fin) return rows;
    string header_line;
    if (!getline(fin, header_line) || header_line.empty()) return rows;
    auto header = split_tsv_fields_(header_line);
    string line;
    while (getline(fin, line)) {
        if (line.empty()) continue;
        auto fields = split_tsv_fields_(line);
        map<string, string> row;
        for (size_t i = 0; i < header.size(); ++i) {
            row[header[i]] = i < fields.size() ? fields[i] : string();
        }
        rows.push_back(std::move(row));
    }
    return rows;
}

static map<string, string> read_tsv_row_by_item_key_(const string& path, const string& item_key) {
    for (const auto& row : read_tsv_rows_with_header_(path)) {
        auto it = row.find("item_key");
        if (it != row.end() && it->second == item_key) return row;
    }
    return {};
}

static string join_vector_with_delim_(const vector<string>& xs, const string& delim) {
    ostringstream oss;
    for (size_t i = 0; i < xs.size(); ++i) {
        if (i) oss << delim;
        oss << xs[i];
    }
    return oss.str();
}

