static string lower_frontier_counts_fingerprint_(size_t raw_candidates,
                                                 size_t canonical_candidates,
                                                 size_t outside_bounded_candidates,
                                                 size_t local_exact_survivors,
                                                 size_t plus_one_survivors,
                                                 size_t theorem_preserving_survivors,
                                                 size_t unsupported_local_exact_candidates,
                                                 size_t unsupported_plus_one_candidates) {
    ostringstream oss;
    oss << raw_candidates << '|'
        << canonical_candidates << '|'
        << outside_bounded_candidates << '|'
        << local_exact_survivors << '|'
        << plus_one_survivors << '|'
        << theorem_preserving_survivors << '|'
        << unsupported_local_exact_candidates << '|'
        << unsupported_plus_one_candidates;
    return oss.str();
}

static string lower_frontier_expected_counts_fingerprint_(const string& item_key) {
    const auto v = lower_frontier_expected_counts_(item_key);
    if (v.size() != 8) return "";
    return lower_frontier_counts_fingerprint_(v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7]);
}

static size_t count_nonempty_rows_(const string& path) {
    ifstream fin(path);
    if (!fin) return 0;
    size_t rows = 0;
    string line;
    while (getline(fin, line)) {
        if (!line.empty()) ++rows;
    }
    return rows;
}

