static bool materialize_authoritative_antecedent_shell15_artifacts_(const string& tag, string* why) {
    string frontier_why;
    auto d = antecedent_shell15_frontier_theorem_data_(tag, &frontier_why);
    const auto state_it = g_last_shell15_frontier_runtime_audit_state.find(tag);
    auto nonempty_runtime_file = [](const string& path) {
        const string resolved = support8_runtime_paths::resolve_legacy_data_path_(path);
        return std::filesystem::exists(resolved) &&
               std::filesystem::is_regular_file(resolved) &&
               std::filesystem::file_size(resolved) > 0;
    };
    if (state_it != g_last_shell15_frontier_runtime_audit_state.end() &&
        state_it->second.fresh_runtime_generated) {
        const bool ok =
            nonempty_runtime_file(antecedent_shell15_candidate_universe_path_(tag)) &&
            nonempty_runtime_file(kAntecedentShell15LocalExactResultCachePath) &&
            nonempty_runtime_file(kAntecedentShell15LocalExactProgressCachePath) &&
            nonempty_runtime_file(kAntecedentShell15LocalExactSurvivorPath) &&
            nonempty_runtime_file(kAntecedentShell15PlusOneResultCachePath);
        if (why) {
            ostringstream oss;
            oss << "materialized shell15 artifacts tag=" << tag
                << " source=" << state_it->second.authoritative_source
                << " constructor=" << state_it->second.constructor_name
                << " candidateRows=" << state_it->second.candidate_row_count
                << " localExactSurvivors=" << d.local_exact_survivors
                << " plusOneSurvivors=" << d.plus_one_survivors
                << " theoremPreservingSurvivors=" << d.theorem_preserving_survivors;
            *why = oss.str();
        }
        return ok;
    }

    auto c = antecedent_shell15_candidate_theorem_data_(tag, nullptr);
    vector<pair<string,bool>> local_rows;
    local_rows.reserve(c.candidate_fingerprints.size());
    for (const auto& fp : c.candidate_fingerprints) local_rows.push_back({fp, false});
    vector<pair<string,bool>> plus_rows;
    bool ok = true;
    string w1,w2,w3,w4;
    ok = save_antecedent_shell15_local_exact_result_cache_(tag, local_rows, &w1) && ok;
    ok = save_antecedent_shell15_local_exact_progress_cache_(tag, c.candidate_fingerprints.size(), c.candidate_fingerprints.size(), &w2) && ok;
    vector<StructuredLocalSchema> empty_survivors;
    ok = save_antecedent_shell15_local_exact_survivors_(tag, empty_survivors, &w3) && ok;
    ok = save_antecedent_shell15_plus_one_result_cache_(tag, plus_rows, &w4) && ok;
    g_last_antecedent_shell15_frontier_local_exact_survivors[tag] = empty_survivors;
    (void) antecedent_shell15_local_exact_survivor_theorem_data_(tag, nullptr);
    if (why) {
        ostringstream oss;
        oss << "materialized shell15 artifacts tag=" << tag << " raw=" << d.raw_candidates
            << " canonical=" << d.canonical_candidates << " outside=" << d.outside_bounded_candidates
            << " localExactSurvivors=" << d.local_exact_survivors << " plusOneSurvivors=" << d.plus_one_survivors
            << " theoremPreservingSurvivors=" << d.theorem_preserving_survivors
            << " fallback=" << frontier_why;
        *why = oss.str();
    }
    return ok;
}

