static bool file_exists_for_audit_(const string& path) {
    ifstream fin(path, ios::binary);
    return fin.good();
}

static bool file_nonempty_for_audit_(const string& path) {
    ifstream fin(path, ios::binary | ios::ate);
    return fin.good() && fin.tellg() > 0;
}

static bool file_contains_for_audit_(const string& path, const string& needle) {
    ifstream fin(path, ios::binary);
    if (!fin) return false;
    string data((istreambuf_iterator<char>(fin)), istreambuf_iterator<char>());
    return data.find(needle) != string::npos;
}

static string fingerprint_existing_files_for_audit_(const vector<string>& paths) {
    string merged;
    for (const auto& path : paths) {
        ifstream fin(path, ios::binary);
        if (!fin) continue;
        merged += string((istreambuf_iterator<char>(fin)), istreambuf_iterator<char>());
        merged.push_back('\n');
    }
    if (merged.empty()) return "missing";
    return to_string(merged.size()) + ":" + to_string(hash<string>{}(merged));
}

