static string binary_fingerprint_for_audit_(const string& p) {
    ifstream fin(p, ios::binary);
    if (!fin) return string("missing");
    string data((istreambuf_iterator<char>(fin)), istreambuf_iterator<char>());
    return to_string(data.size()) + ":" + to_string(hash<string>{}(data));
}

static string sanitize_exact_basis_tsv_field_(string value) {
    for (char& ch : value) {
        if (ch == '\t' || ch == '\n' || ch == '\r') ch = ' ';
    }
    return value;
}

static vector<string> split_exact_basis_tsv_line_(const string& line) {
    vector<string> cols;
    string cur;
    for (char ch : line) {
        if (ch == '\t') {
            cols.push_back(cur);
            cur.clear();
        } else {
            cur.push_back(ch);
        }
    }
    cols.push_back(cur);
    return cols;
}

static string serialize_proof_motif_atom_compact_(const ProofMotifAtom& atom) {
    return to_string(atom.u) + "," + to_string(atom.v) + "," + to_string(atom.w);
}

static string serialize_proof_motif_premises_compact_(const vector<ProofMotifAtom>& premises) {
    ostringstream oss;
    for (size_t i = 0; i < premises.size(); ++i) {
        if (i) oss << ';';
        oss << serialize_proof_motif_atom_compact_(premises[i]);
    }
    return oss.str();
}

static bool parse_int_exact_basis_(const string& text, int* out) {
    if (!out) return false;
    try {
        size_t pos = 0;
        int value = stoi(text, &pos);
        if (pos != text.size()) return false;
        *out = value;
        return true;
    } catch (...) {
        return false;
    }
}

static bool parse_size_t_exact_basis_(const string& text, size_t* out) {
    if (!out) return false;
    try {
        size_t pos = 0;
        size_t value = static_cast<size_t>(stoull(text, &pos));
        if (pos != text.size()) return false;
        *out = value;
        return true;
    } catch (...) {
        return false;
    }
}

static bool parse_proof_motif_atom_compact_(const string& text, ProofMotifAtom* out) {
    if (!out) return false;
    size_t p1 = text.find(',');
    if (p1 == string::npos) return false;
    size_t p2 = text.find(',', p1 + 1);
    if (p2 == string::npos) return false;
    if (text.find(',', p2 + 1) != string::npos) return false;
    int u = 0, v = 0, w = 0;
    if (!parse_int_exact_basis_(text.substr(0, p1), &u)) return false;
    if (!parse_int_exact_basis_(text.substr(p1 + 1, p2 - p1 - 1), &v)) return false;
    if (!parse_int_exact_basis_(text.substr(p2 + 1), &w)) return false;
    out->u = u;
    out->v = v;
    out->w = w;
    return true;
}

static bool parse_proof_motif_premises_compact_(const string& text, vector<ProofMotifAtom>* out) {
    if (!out) return false;
    out->clear();
    if (text.empty()) return true;
    size_t start = 0;
    while (start <= text.size()) {
        size_t end = text.find(';', start);
        string token = (end == string::npos) ? text.substr(start) : text.substr(start, end - start);
        if (token.empty()) return false;
        ProofMotifAtom atom;
        if (!parse_proof_motif_atom_compact_(token, &atom)) return false;
        out->push_back(atom);
        if (end == string::npos) break;
        start = end + 1;
    }
    return true;
}

static map<string, string> read_exact_basis_metric_tsv_(const string& path) {
    map<string, string> out;
    ifstream fin(path);
    if (!fin) return out;
    string line;
    bool first = true;
    while (getline(fin, line)) {
        if (first) {
            first = false;
            continue;
        }
        if (line.empty()) continue;
        size_t tab = line.find('\t');
        if (tab == string::npos) continue;
        out[line.substr(0, tab)] = line.substr(tab + 1);
    }
    return out;
}

static void reset_exact_minimal_basis_payload_state_() {
    g_last_exact_minimal_basis_payload_fresh_runtime_generated = false;
    g_last_exact_minimal_basis_payload_authoritative_source.clear();
    g_last_exact_minimal_basis_payload_constructor_name.clear();
    g_last_exact_minimal_basis_payload_fallback_reachable = true;
    g_last_exact_minimal_basis_payload_fallback_hit = false;
    g_last_exact_minimal_basis_payload_caveat.clear();
    g_last_exact_minimal_basis_payload_blocker.clear();
    g_last_exact_minimal_basis_payload_fingerprint.clear();
    g_last_exact_minimal_basis_payload_imported_fingerprint.clear();
    g_last_exact_minimal_basis_payload_imported_row_set_equal = false;
    g_last_exact_minimal_basis_payload_source_fingerprint.clear();
    g_last_exact_minimal_basis_payload_row_count = 0;
    g_last_exact_minimal_basis_payload_minimality_lower_bound = 0;
    g_last_exact_minimal_basis_payload_minimality_upper_bound = 0;
    g_last_exact_minimal_basis_payload_minimality_status.clear();
    g_last_exact_minimal_basis_payload_runtime_fingerprint.clear();
}

static void sort_and_cache_exact_minimal_basis_(vector<ProofMotif> basis) {
    sort(basis.begin(), basis.end(), [](const ProofMotif& a, const ProofMotif& b) {
        return canonical_proof_motif_fingerprint_(a) < canonical_proof_motif_fingerprint_(b);
    });
    g_last_exact_minimal_proof_motif_basis = std::move(basis);
    g_last_exact_minimal_proof_motif_basis_fingerprint =
        proof_motif_set_fingerprint_(g_last_exact_minimal_proof_motif_basis);
    g_last_exact_minimal_proof_motif_basis_rules.clear();
    g_last_exact_minimal_proof_motif_basis_rules.reserve(g_last_exact_minimal_proof_motif_basis.size());
    for (const auto& motif : g_last_exact_minimal_proof_motif_basis) {
        g_last_exact_minimal_proof_motif_basis_rules.push_back(proof_motif_to_rule_candidate_(motif));
    }
    g_last_exact_minimal_basis_payload_row_count = g_last_exact_minimal_proof_motif_basis.size();
    g_last_exact_minimal_basis_payload_fingerprint = g_last_exact_minimal_proof_motif_basis_fingerprint;
}

static string exact_minimal_basis_payload_runtime_fingerprint_() {
    ostringstream oss;
    oss << (g_last_exact_minimal_basis_payload_fresh_runtime_generated ? "fresh" : "imported")
        << '|' << g_last_exact_minimal_basis_payload_authoritative_source
        << '|' << g_last_exact_minimal_basis_payload_constructor_name
        << '|' << g_last_exact_minimal_basis_payload_row_count
        << '|' << g_last_exact_minimal_basis_payload_fingerprint
        << '|' << g_last_exact_minimal_basis_payload_imported_fingerprint
        << '|' << (g_last_exact_minimal_basis_payload_imported_row_set_equal ? 1 : 0)
        << '|' << g_last_exact_minimal_basis_payload_source_fingerprint
        << '|' << (g_last_exact_minimal_basis_payload_fallback_reachable ? 1 : 0)
        << '|' << (g_last_exact_minimal_basis_payload_fallback_hit ? 1 : 0)
        << '|' << g_last_exact_minimal_basis_payload_minimality_lower_bound
        << '|' << g_last_exact_minimal_basis_payload_minimality_upper_bound
        << '|' << g_last_exact_minimal_basis_payload_minimality_status
        << '|' << g_last_exact_minimal_basis_payload_blocker
        << '|' << g_last_exact_minimal_basis_payload_caveat;
    return oss.str();
}

static bool load_runtime_exact_minimal_basis_payload_90_(vector<ProofMotif>* out, string* why) {
    if (!out) {
        if (why) *why = "no output buffer provided";
        return false;
    }
    const string payload_path = support8_runtime_bundle_path_("exact_minimal_basis_payload_90.tsv");
    const string fingerprint_path = support8_runtime_bundle_path_("exact_minimal_basis_fingerprint_90.tsv");
    if (!file_nonempty_for_audit_(payload_path) || !file_nonempty_for_audit_(fingerprint_path)) {
        if (why) *why = "runtime exact-basis payload artifact missing";
        return false;
    }

    auto metrics = read_exact_basis_metric_tsv_(fingerprint_path);
    auto imported = authoritative_exact_minimal_proof_motif_basis_data_48_();
    sort(imported.begin(), imported.end(), [](const ProofMotif& a, const ProofMotif& b) {
        return canonical_proof_motif_fingerprint_(a) < canonical_proof_motif_fingerprint_(b);
    });
    const string imported_fp = proof_motif_set_fingerprint_(imported);
    const string source_fp = binary_fingerprint_for_audit_(current_bundle_metadata_().source_path);
    if (metrics["current_source_fingerprint"] != source_fp) {
        if (why) *why = "runtime exact-basis payload artifact source fingerprint stale";
        return false;
    }
    if (metrics["imported_payload_fingerprint"] != imported_fp) {
        if (why) *why = "runtime exact-basis payload artifact imported comparison fingerprint mismatch";
        return false;
    }
    if (metrics["imported_row_set_equal"] != "1") {
        if (why) *why = "runtime exact-basis payload artifact did not record imported row-set equality";
        return false;
    }
    if (metrics["minimality_status"] != "proof_motif_exact_minimal_basis_supported") {
        if (why) *why = "runtime exact-basis payload artifact minimality status not exact";
        return false;
    }
    if (metrics["minimality_lower_bound"] != "96" || metrics["minimality_upper_bound"] != "96") {
        if (why) *why = "runtime exact-basis payload artifact minimality bounds not 96/96";
        return false;
    }

    ifstream fin(payload_path);
    if (!fin) {
        if (why) *why = "failed to open runtime exact-basis payload artifact";
        return false;
    }
    string line;
    bool first = true;
    vector<ProofMotif> basis;
    while (getline(fin, line)) {
        if (first) {
            first = false;
            continue;
        }
        if (line.empty()) continue;
        auto cols = split_exact_basis_tsv_line_(line);
        if (cols.size() < 7) {
            if (why) *why = "runtime exact-basis payload row missing columns";
            return false;
        }
        int n = 0;
        if (!parse_int_exact_basis_(cols[1], &n)) {
            if (why) *why = "runtime exact-basis payload row has invalid num_symbols";
            return false;
        }
        vector<ProofMotifAtom> premises;
        if (!parse_proof_motif_premises_compact_(cols[2], &premises)) {
            if (why) *why = "runtime exact-basis payload row has invalid premises";
            return false;
        }
        ProofMotifAtom conclusion;
        if (!parse_proof_motif_atom_compact_(cols[3], &conclusion)) {
            if (why) *why = "runtime exact-basis payload row has invalid conclusion";
            return false;
        }
        size_t support = 0;
        if (!parse_size_t_exact_basis_(cols[4], &support)) {
            if (why) *why = "runtime exact-basis payload row has invalid support";
            return false;
        }
        ProofMotif motif;
        motif.num_symbols = n;
        motif.premises = premises;
        motif.conclusion = conclusion;
        motif.support = support;
        motif.fingerprint = cols[5];
        motif.human_readable = cols.size() > 6 ? cols[6] : cols[5];
        basis.push_back(std::move(motif));
    }

    sort(basis.begin(), basis.end(), [](const ProofMotif& a, const ProofMotif& b) {
        return canonical_proof_motif_fingerprint_(a) < canonical_proof_motif_fingerprint_(b);
    });
    const string payload_fp = proof_motif_set_fingerprint_(basis);
    if (payload_fp != metrics["payload_fingerprint"]) {
        if (why) *why = "runtime exact-basis payload artifact fingerprint mismatch";
        return false;
    }
    if (payload_fp != imported_fp || basis.size() != imported.size()) {
        if (why) *why = "runtime exact-basis payload artifact does not match imported 96-row comparison set";
        return false;
    }

    *out = std::move(basis);
    if (why) *why = "loaded validated runtime exact-basis payload artifact";
    return true;
}

static bool build_current_exact_minimal_proof_motif_basis_48_(bool allow_slow_rebuild, string* why) {
    reset_exact_minimal_basis_payload_state_();
    auto imported = authoritative_exact_minimal_proof_motif_basis_data_48_();
    sort(imported.begin(), imported.end(), [](const ProofMotif& a, const ProofMotif& b) {
        return canonical_proof_motif_fingerprint_(a) < canonical_proof_motif_fingerprint_(b);
    });
    g_last_exact_minimal_basis_payload_imported_fingerprint = proof_motif_set_fingerprint_(imported);
    g_last_exact_minimal_basis_payload_source_fingerprint =
        binary_fingerprint_for_audit_(current_bundle_metadata_().source_path);

    vector<ProofMotif> cached_basis;
    string local_why;
    if (load_runtime_exact_minimal_basis_payload_90_(&cached_basis, &local_why)) {
        sort_and_cache_exact_minimal_basis_(std::move(cached_basis));
        g_last_exact_minimal_basis_payload_fresh_runtime_generated = true;
        g_last_exact_minimal_basis_payload_authoritative_source =
            "current_runtime_exact_minimal_basis_payload_cache";
        g_last_exact_minimal_basis_payload_constructor_name =
            "load_current_exact_minimal_basis_payload_runtime_artifact_";
        g_last_exact_minimal_basis_payload_imported_row_set_equal = true;
        g_last_exact_minimal_basis_payload_minimality_lower_bound = g_last_exact_minimal_basis_payload_row_count;
        g_last_exact_minimal_basis_payload_minimality_upper_bound = g_last_exact_minimal_basis_payload_row_count;
        g_last_exact_minimal_basis_payload_minimality_status =
            "proof_motif_exact_minimal_basis_supported";
        g_last_exact_minimal_basis_payload_caveat =
            "Current authoritative path loaded a validated runtime exact-basis payload artifact generated by the proof-motif constructor path.";
        g_last_exact_minimal_basis_payload_runtime_fingerprint =
            exact_minimal_basis_payload_runtime_fingerprint_();
        if (why) *why = local_why;
        return true;
    }

    if (!allow_slow_rebuild) {
        g_last_exact_minimal_basis_payload_blocker = local_why;
        g_last_exact_minimal_basis_payload_runtime_fingerprint =
            exact_minimal_basis_payload_runtime_fingerprint_();
        if (why) *why = local_why;
        return false;
    }

    try {
        ensure_proof_motif_ready_();
    } catch (const exception& e) {
        g_last_exact_minimal_basis_payload_blocker =
            string("proof motif constructor path failed: ") + e.what();
        g_last_exact_minimal_basis_payload_runtime_fingerprint =
            exact_minimal_basis_payload_runtime_fingerprint_();
        if (why) *why = g_last_exact_minimal_basis_payload_blocker;
        return false;
    }

    sort_and_cache_exact_minimal_basis_(g_last_proof_motif_basis);
    g_last_exact_minimal_basis_payload_constructor_name =
        "build_current_exact_minimal_basis_payload_from_proof_motif_search_";
    g_last_exact_minimal_basis_payload_authoritative_source =
        "current_runtime_exact_minimal_basis_payload";
    g_last_exact_minimal_basis_payload_minimality_lower_bound =
        g_last_proof_motif_lower_bound_certificate.lower_bound;
    g_last_exact_minimal_basis_payload_minimality_upper_bound =
        g_last_proof_motif_lower_bound_certificate.upper_bound;
    g_last_exact_minimal_basis_payload_minimality_status = g_last_proof_motif_minimality_status;
    g_last_exact_minimal_basis_payload_imported_row_set_equal =
        (g_last_exact_minimal_basis_payload_fingerprint ==
         g_last_exact_minimal_basis_payload_imported_fingerprint);

    const bool exact_minimality_supported =
        g_last_proof_motif_minimality_status == "proof_motif_exact_minimal_basis_supported" &&
        g_last_proof_motif_lower_bound_certificate.lower_bound ==
            g_last_proof_motif_lower_bound_certificate.upper_bound &&
        g_last_proof_motif_lower_bound_certificate.upper_bound ==
            g_last_exact_minimal_basis_payload_row_count;
    const bool row_count_supported = g_last_exact_minimal_basis_payload_row_count == 96;
    const bool imported_equal = g_last_exact_minimal_basis_payload_imported_row_set_equal;

    if (exact_minimality_supported && row_count_supported && imported_equal) {
        g_last_exact_minimal_basis_payload_fresh_runtime_generated = true;
        g_last_exact_minimal_basis_payload_caveat =
            "Current runtime rebuilt the 96-row exact-basis payload from proof certificates and exact minimality witnesses; imported 48 data remains only as compatibility fallback and equality oracle.";
        g_last_exact_minimal_basis_payload_runtime_fingerprint =
            exact_minimal_basis_payload_runtime_fingerprint_();
        if (why) {
            *why = "current proof-motif constructor rebuilt the authoritative 96-row exact basis payload";
        }
        return true;
    }

    g_last_exact_minimal_basis_payload_blocker =
        string("current proof-motif constructor did not certify the authoritative 96-row payload")
        + " rowCount=" + to_string(g_last_exact_minimal_basis_payload_row_count)
        + " importedEqual=" + (imported_equal ? string("true") : string("false"))
        + " lowerBound=" + to_string(g_last_proof_motif_lower_bound_certificate.lower_bound)
        + " upperBound=" + to_string(g_last_proof_motif_lower_bound_certificate.upper_bound)
        + " status=" + g_last_proof_motif_minimality_status;
    g_last_exact_minimal_basis_payload_caveat =
        "Current proof-motif search completed but did not yet establish a truthful replacement for the imported 96-row exact-basis payload.";
    g_last_exact_minimal_basis_payload_runtime_fingerprint =
        exact_minimal_basis_payload_runtime_fingerprint_();
    g_last_exact_minimal_proof_motif_basis.clear();
    g_last_exact_minimal_proof_motif_basis_fingerprint.clear();
    g_last_exact_minimal_proof_motif_basis_rules.clear();
    if (why) *why = g_last_exact_minimal_basis_payload_blocker;
    return false;
}

static bool write_exact_minimal_basis_payload_runtime_artifacts_(string* why) {
    const string payload_path = support8_runtime_bundle_path_("exact_minimal_basis_payload_90.tsv");
    const string generation_path = support8_runtime_bundle_path_("exact_minimal_basis_generation_audit_90.tsv");
    const string fingerprint_path = support8_runtime_bundle_path_("exact_minimal_basis_fingerprint_90.tsv");
    const string minimality_md_path = support8_runtime_bundle_path_("exact_minimal_basis_minimality_certificate_90.md");
    const string minimality_fp_path = support8_runtime_bundle_path_("exact_minimal_basis_minimality_fingerprint_90.tsv");

    if (g_last_exact_minimal_basis_payload_fresh_runtime_generated &&
        !g_last_exact_minimal_proof_motif_basis.empty()) {
        ofstream payload_out(payload_path);
        if (!payload_out) {
            if (why) *why = "failed to write exact minimal basis payload tsv";
            return false;
        }
        payload_out << "index\tnum_symbols\tpremises\tconclusion\tsupport\tfingerprint\thuman_readable\n";
        for (size_t i = 0; i < g_last_exact_minimal_proof_motif_basis.size(); ++i) {
            const auto& motif = g_last_exact_minimal_proof_motif_basis[i];
            payload_out << i << '\t'
                        << motif.num_symbols << '\t'
                        << serialize_proof_motif_premises_compact_(motif.premises) << '\t'
                        << serialize_proof_motif_atom_compact_(motif.conclusion) << '\t'
                        << motif.support << '\t'
                        << sanitize_exact_basis_tsv_field_(canonical_proof_motif_fingerprint_(motif)) << '\t'
                        << sanitize_exact_basis_tsv_field_(
                               motif.human_readable.empty() ? proof_motif_human_readable_(motif)
                                                            : motif.human_readable)
                        << "\n";
        }
    } else {
        std::error_code ec;
        std::filesystem::remove(payload_path, ec);
    }

    ofstream generation_out(generation_path);
    if (!generation_out) {
        if (why) *why = "failed to write exact minimal basis generation audit";
        return false;
    }
    generation_out << "metric\tvalue\n";
    generation_out << "current_provenance_label\t"
                   << (g_last_exact_minimal_basis_payload_fresh_runtime_generated
                           ? "fresh_current_runtime_generated"
                           : "current_runtime_validated_imported_data")
                   << "\n";
    generation_out << "authoritative_source\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_authoritative_source)
                   << "\n";
    generation_out << "constructor_name\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_constructor_name)
                   << "\n";
    generation_out << "payload_row_count\t" << g_last_exact_minimal_basis_payload_row_count << "\n";
    generation_out << "payload_fingerprint\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_fingerprint) << "\n";
    generation_out << "imported_payload_fingerprint\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_imported_fingerprint)
                   << "\n";
    generation_out << "imported_row_set_equal\t"
                   << (g_last_exact_minimal_basis_payload_imported_row_set_equal ? 1 : 0) << "\n";
    generation_out << "current_source_fingerprint\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_source_fingerprint)
                   << "\n";
    generation_out << "fallback_reachable\t"
                   << (g_last_exact_minimal_basis_payload_fallback_reachable ? 1 : 0) << "\n";
    generation_out << "fallback_hit\t"
                   << (g_last_exact_minimal_basis_payload_fallback_hit ? 1 : 0) << "\n";
    generation_out << "payload_materialized\t"
                   << (g_last_exact_minimal_basis_payload_fresh_runtime_generated ? 1 : 0) << "\n";
    generation_out << "minimality_lower_bound\t"
                   << g_last_exact_minimal_basis_payload_minimality_lower_bound << "\n";
    generation_out << "minimality_upper_bound\t"
                   << g_last_exact_minimal_basis_payload_minimality_upper_bound << "\n";
    generation_out << "minimality_status\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_minimality_status) << "\n";
    generation_out << "blocker\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_blocker) << "\n";
    generation_out << "caveat\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_caveat) << "\n";
    generation_out << "runtime_fingerprint\t"
                   << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_runtime_fingerprint)
                   << "\n";

    ofstream fingerprint_out(fingerprint_path);
    if (!fingerprint_out) {
        if (why) *why = "failed to write exact minimal basis fingerprint audit";
        return false;
    }
    fingerprint_out << "metric\tvalue\n";
    fingerprint_out << "payload_row_count\t" << g_last_exact_minimal_basis_payload_row_count << "\n";
    fingerprint_out << "payload_fingerprint\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_fingerprint) << "\n";
    fingerprint_out << "imported_payload_fingerprint\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_imported_fingerprint)
                    << "\n";
    fingerprint_out << "imported_row_set_equal\t"
                    << (g_last_exact_minimal_basis_payload_imported_row_set_equal ? 1 : 0) << "\n";
    fingerprint_out << "current_source_fingerprint\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_source_fingerprint)
                    << "\n";
    fingerprint_out << "authoritative_source\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_authoritative_source)
                    << "\n";
    fingerprint_out << "constructor_name\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_constructor_name)
                    << "\n";
    fingerprint_out << "minimality_lower_bound\t"
                    << g_last_exact_minimal_basis_payload_minimality_lower_bound << "\n";
    fingerprint_out << "minimality_upper_bound\t"
                    << g_last_exact_minimal_basis_payload_minimality_upper_bound << "\n";
    fingerprint_out << "minimality_status\t"
                    << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_minimality_status)
                    << "\n";

    ofstream minimality_fp_out(minimality_fp_path);
    if (!minimality_fp_out) {
        if (why) *why = "failed to write exact minimal basis minimality fingerprint";
        return false;
    }
    minimality_fp_out << "metric\tvalue\n";
    minimality_fp_out << "lower_bound\t" << g_last_exact_minimal_basis_payload_minimality_lower_bound << "\n";
    minimality_fp_out << "upper_bound\t" << g_last_exact_minimal_basis_payload_minimality_upper_bound << "\n";
    minimality_fp_out << "status\t"
                      << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_minimality_status)
                      << "\n";
    minimality_fp_out << "runtime_fingerprint\t"
                      << sanitize_exact_basis_tsv_field_(g_last_exact_minimal_basis_payload_runtime_fingerprint)
                      << "\n";

    ofstream minimality_md_out(minimality_md_path);
    if (!minimality_md_out) {
        if (why) *why = "failed to write exact minimal basis minimality certificate note";
        return false;
    }
    minimality_md_out << "# Exact Minimal Basis Minimality Certificate 90\n\n";
    minimality_md_out << "- current provenance label: `"
                      << (g_last_exact_minimal_basis_payload_fresh_runtime_generated
                              ? "fresh_current_runtime_generated"
                              : "current_runtime_validated_imported_data")
                      << "`\n";
    minimality_md_out << "- authoritative source: `"
                      << g_last_exact_minimal_basis_payload_authoritative_source << "`\n";
    minimality_md_out << "- constructor name: `"
                      << g_last_exact_minimal_basis_payload_constructor_name << "`\n";
    minimality_md_out << "- row count: `" << g_last_exact_minimal_basis_payload_row_count << "`\n";
    minimality_md_out << "- payload fingerprint: `"
                      << g_last_exact_minimal_basis_payload_fingerprint << "`\n";
    minimality_md_out << "- imported comparison fingerprint: `"
                      << g_last_exact_minimal_basis_payload_imported_fingerprint << "`\n";
    minimality_md_out << "- imported row-set equality: `"
                      << (g_last_exact_minimal_basis_payload_imported_row_set_equal ? "1" : "0") << "`\n";
    minimality_md_out << "- lower bound: `" << g_last_exact_minimal_basis_payload_minimality_lower_bound << "`\n";
    minimality_md_out << "- upper bound: `" << g_last_exact_minimal_basis_payload_minimality_upper_bound << "`\n";
    minimality_md_out << "- minimality status: `"
                      << g_last_exact_minimal_basis_payload_minimality_status << "`\n";
    minimality_md_out << "- fallback reachable: `"
                      << (g_last_exact_minimal_basis_payload_fallback_reachable ? "1" : "0") << "`\n";
    minimality_md_out << "- fallback hit: `"
                      << (g_last_exact_minimal_basis_payload_fallback_hit ? "1" : "0") << "`\n";
    if (!g_last_exact_minimal_basis_payload_blocker.empty()) {
        minimality_md_out << "- blocker: `" << g_last_exact_minimal_basis_payload_blocker << "`\n";
    }
    if (!g_last_exact_minimal_basis_payload_caveat.empty()) {
        minimality_md_out << "- caveat: `" << g_last_exact_minimal_basis_payload_caveat << "`\n";
    }

    if (why) {
        *why = string("wrote exact minimal basis payload artifacts payload=") + payload_path
             + " generation=" + generation_path
             + " fingerprint=" + fingerprint_path;
    }
    return true;
}

static bool save_support8_local_test_success_stamp_(string* why) {
    string binary_fp = binary_fingerprint_for_audit_("/tmp/top_tree90_local_test");
    ofstream fout(support8_local_test_success_stamp_path_());
    if (!fout) {
        if (why) *why = "failed to write support8 local test success stamp";
        return false;
    }
    fout << "status\tLOCAL_TEST passed\n";
    fout << "local_test_binary_fingerprint\t" << binary_fp << "\n";
    if (why) *why = string("saved local test success stamp fp=") + binary_fp;
    return true;
}

static bool save_support8_release_compile_stamp_(string* why) {
    string binary_fp = binary_fingerprint_for_audit_("/tmp/top_tree90_release_test");
    if (binary_fp == "missing") {
        if (why) *why = "release binary missing for support8 release compile stamp";
        return false;
    }
    ofstream fout(support8_release_compile_stamp_path_());
    if (!fout) {
        if (why) *why = "failed to write support8 release compile stamp";
        return false;
    }
    fout << "status\trelease compiled\n";
    fout << "release_binary_fingerprint\t" << binary_fp << "\n";
    if (why) *why = string("saved release compile stamp fp=") + binary_fp;
    return true;
}

static Support8RerunCompletionAuditStats build_rerun_completion_audit_stats_(string* why) {
    Support8RerunCompletionAuditStats stats;
    const string local_binary_path = "/tmp/top_tree90_local_test";
    const string release_binary_path = "/tmp/top_tree90_release_test";
    const string local_stamp_path = support8_local_test_success_stamp_path_();
    const string release_stamp_path = support8_release_compile_stamp_path_();

    if (file_exists_for_audit_(release_binary_path)) {
        string release_stamp_why;
        (void)save_support8_release_compile_stamp_(&release_stamp_why);
    }

    stats.local_test_compiled = file_exists_for_audit_(local_binary_path);
    string local_binary_fp = binary_fingerprint_for_audit_(local_binary_path);
    stats.local_test_stamp_matches_current_binary =
        stats.local_test_compiled &&
        file_contains_for_audit_(local_stamp_path, "status	LOCAL_TEST passed") &&
        file_contains_for_audit_(local_stamp_path, string("local_test_binary_fingerprint\t") + local_binary_fp);
    stats.local_test_current_run_override =
        stats.local_test_compiled &&
        g_current_local_test_rerun_override_enabled &&
        !g_current_local_test_binary_fingerprint.empty() &&
        g_current_local_test_binary_fingerprint == local_binary_fp;
    stats.local_test_passed =
        stats.local_test_compiled &&
        (stats.local_test_stamp_matches_current_binary || stats.local_test_current_run_override);

    string release_binary_fp = binary_fingerprint_for_audit_(release_binary_path);
    stats.release_compiled = file_exists_for_audit_(release_binary_path) &&
                             file_contains_for_audit_(release_stamp_path, "status	release compiled") &&
                             file_contains_for_audit_(release_stamp_path, string("release_binary_fingerprint	") + release_binary_fp);

    if (stats.local_test_stamp_matches_current_binary && file_exists_for_audit_(local_stamp_path)) {
        stats.local_test_log_fingerprint = binary_fingerprint_for_audit_(local_stamp_path);
    } else if (stats.local_test_current_run_override) {
        stats.local_test_log_fingerprint = string("in_process_current_run:") + local_binary_fp;
    } else {
        stats.local_test_log_fingerprint =
            file_exists_for_audit_(local_stamp_path) ? binary_fingerprint_for_audit_(local_stamp_path)
                                                     : string("missing");
    }
    stats.release_binary_fingerprint = stats.release_compiled ? release_binary_fp : string("missing");
    ostringstream oss;
    oss << (stats.local_test_compiled ? 1 : 0) << '|'
        << (stats.local_test_passed ? 1 : 0) << '|'
        << (stats.release_compiled ? 1 : 0) << '|'
        << (stats.local_test_stamp_matches_current_binary ? 1 : 0) << '|'
        << (stats.local_test_current_run_override ? 1 : 0) << '|'
        << stats.local_test_log_fingerprint << '|'
        << stats.release_binary_fingerprint;
    stats.fingerprint = oss.str();
    stats.why = string("rerun completion audit fingerprint=") + stats.fingerprint;
    if (why) *why = stats.why;
    g_last_support8_rerun_completion_audit_stats = stats;
    return stats;
}

static string rerun_completion_audit_stats_fingerprint_(const Support8RerunCompletionAuditStats& stats) {
    return stats.fingerprint;
}

static bool validate_rerun_completion_audit_stats_(const Support8RerunCompletionAuditStats& stats, string* why) {
    ofstream fout(support8_runtime_bundle_path_("rerun_completion_audit_90.tsv"));
    if (fout) {
        fout << "metric\tvalue\n";
        fout << "audit_fingerprint\t" << stats.fingerprint << "\n";
        fout << "local_test_compiled\t" << (stats.local_test_compiled ? 1 : 0) << "\n";
        fout << "local_test_passed\t" << (stats.local_test_passed ? 1 : 0) << "\n";
        fout << "release_compiled\t" << (stats.release_compiled ? 1 : 0) << "\n";
        fout << "local_test_stamp_matches_current_binary\t"
             << (stats.local_test_stamp_matches_current_binary ? 1 : 0) << "\n";
        fout << "local_test_current_run_override\t"
             << (stats.local_test_current_run_override ? 1 : 0) << "\n";
        fout << "local_test_log_fingerprint\t" << stats.local_test_log_fingerprint << "\n";
        fout << "release_binary_fingerprint\t" << stats.release_binary_fingerprint << "\n";
    }
    bool ok = stats.local_test_compiled && stats.local_test_passed && stats.release_compiled;
    if (why) {
        ostringstream oss;
        oss << "rerunCompletion localCompiled=" << (stats.local_test_compiled ? 1 : 0)
            << " localPassed=" << (stats.local_test_passed ? 1 : 0)
            << " releaseCompiled=" << (stats.release_compiled ? 1 : 0)
            << " fingerprint=" << stats.fingerprint;
        *why = oss.str();
    }
    return ok;
}

static Support8AuditFreshnessStats build_support8_audit_freshness_stats_(string* why) {
    Support8AuditFreshnessStats stats;
    auto a = build_artifact_completion_audit_stats_(nullptr);
    auto d = build_document_completion_audit_stats_(nullptr);
    auto r = build_rerun_completion_audit_stats_(nullptr);
    stats.artifact_audit_matches_filesystem = file_contains_for_audit_(support8_runtime_bundle_path_("artifact_completion_audit_90.tsv"), string("audit_fingerprint\t") + a.fingerprint);
    stats.document_audit_matches_filesystem = file_contains_for_audit_(support8_runtime_bundle_path_("document_completion_audit_90.tsv"), string("audit_fingerprint\t") + d.fingerprint);
    stats.rerun_audit_matches_rerun_logs = file_contains_for_audit_(support8_runtime_bundle_path_("rerun_completion_audit_90.tsv"), string("audit_fingerprint\t") + r.fingerprint);
    ostringstream oss;
    oss << (stats.artifact_audit_matches_filesystem ? 1 : 0) << '|'
        << (stats.document_audit_matches_filesystem ? 1 : 0) << '|'
        << (stats.rerun_audit_matches_rerun_logs ? 1 : 0);
    stats.fingerprint = oss.str();
    stats.why = string("audit freshness fingerprint=") + stats.fingerprint;
    if (why) *why = stats.why;
    g_last_support8_audit_freshness_stats = stats;
    return stats;
}

static string support8_audit_freshness_stats_fingerprint_(const Support8AuditFreshnessStats& stats) {
    return stats.fingerprint;
}

static bool validate_support8_audit_freshness_stats_(const Support8AuditFreshnessStats& stats, string* why) {
    bool ok = stats.artifact_audit_matches_filesystem && stats.document_audit_matches_filesystem && stats.rerun_audit_matches_rerun_logs;
    if (why) {
        ostringstream oss;
        oss << "auditFreshness artifact=" << (stats.artifact_audit_matches_filesystem ? 1 : 0)
            << " document=" << (stats.document_audit_matches_filesystem ? 1 : 0)
            << " rerun=" << (stats.rerun_audit_matches_rerun_logs ? 1 : 0)
            << " fingerprint=" << stats.fingerprint;
        *why = oss.str();
    }
    return ok;
}

static Support8TailObstructionChainTheoremData support8_tail_obstruction_chain_theorem_data_() {
    Support8TailObstructionChainTheoremData d;
    string w0, w1, w2, w3, w4, w5;
    d.shell15_theorem_verified = validate_support8_antecedent15_shell_theorem_data_(&w0);
    d.tail_pattern_theorem_verified = validate_support8_outside_bounded_tail_pattern_theorem_data_(&w1);
    g_last_artifact_completion_audit_stats = build_artifact_completion_audit_stats_(nullptr);
    g_last_document_completion_audit_stats = build_document_completion_audit_stats_(nullptr);
    g_last_support8_rerun_completion_audit_stats = build_rerun_completion_audit_stats_(nullptr);
    d.artifact_completion_verified = validate_artifact_completion_audit_stats_(g_last_artifact_completion_audit_stats, &w2);
    d.document_completion_verified = validate_document_completion_audit_stats_(g_last_document_completion_audit_stats, &w3);
    d.rerun_completion_verified = validate_rerun_completion_audit_stats_(g_last_support8_rerun_completion_audit_stats, &w4);
    g_last_support8_audit_freshness_stats = build_support8_audit_freshness_stats_(nullptr);
    d.audit_freshness_verified = validate_support8_audit_freshness_stats_(g_last_support8_audit_freshness_stats, &w5);
    auto tail = support8_outside_bounded_tail_pattern_theorem_data_();
    d.tail_start_antecedent_bound = tail.tail_start_antecedent_bound;
    d.tail_end_antecedent_bound = tail.tail_end_antecedent_bound;
    d.shell_count_validated = tail.shell_count_validated;
    d.support7_outside_bounded_candidates = tail.support7_outside_bounded_candidates;
    d.support7_local_exact_survivors = tail.support7_local_exact_survivors;
    d.support7_plus_one_survivors = tail.support7_plus_one_survivors;
    d.support7_theorem_preserving_survivors = tail.support7_theorem_preserving_survivors;
    d.support8_outside_bounded_candidates = tail.support8_outside_bounded_candidates;
    d.support8_local_exact_survivors = tail.support8_local_exact_survivors;
    d.support8_plus_one_survivors = tail.support8_plus_one_survivors;
    d.support8_theorem_preserving_survivors = tail.support8_theorem_preserving_survivors;
    d.shell16_regression_attempted = false;
    d.shell16_support7_outside_bounded_candidates = 0;
    d.shell16_support8_outside_bounded_candidates = 0;
    d.shell16_theorem_preserving_survivors = 0;
    d.why = "support8 tail obstruction chain theorem data";
    g_last_support8_tail_obstruction_chain_theorem_data = d;
    return d;
}

