static Support8AuthoritativeCompletionLockData support8_authoritative_completion_lock_data_() {
    Support8AuthoritativeCompletionLockData d;
    string w0, w1, w2, w3;
    d.shell15_frontier_authoritative =
        validate_antecedent_shell15_frontier_theorem_data_("antecedent_plus_twelve_frontier", &w0) &&
        validate_antecedent_shell15_frontier_theorem_data_("support8_antecedent15_frontier", &w1);
    d.shell15_scope_authoritative = validate_support8_antecedent15_shell_theorem_data_(&w2);
    d.tail_pattern_authoritative = validate_support8_outside_bounded_tail_pattern_theorem_data_(&w3);
    auto a = build_artifact_completion_audit_stats_(nullptr);
    auto doc = build_document_completion_audit_stats_(nullptr);
    auto rerun = build_rerun_completion_audit_stats_(nullptr);
    d.artifact_completion_verified = validate_artifact_completion_audit_stats_(a, nullptr);
    d.document_completion_verified = validate_document_completion_audit_stats_(doc, nullptr);
    d.rerun_completion_verified = validate_rerun_completion_audit_stats_(rerun, nullptr);
    g_last_support8_audit_freshness_stats = build_support8_audit_freshness_stats_(nullptr);
    d.audit_freshness_verified = validate_support8_audit_freshness_stats_(g_last_support8_audit_freshness_stats, nullptr);
    d.stale_audit_eliminated = d.audit_freshness_verified && d.artifact_completion_verified && d.document_completion_verified && d.rerun_completion_verified;
    d.required_artifact_count = a.required_artifact_count;
    d.existing_artifact_count = a.existing_artifact_count;
    d.nonempty_artifact_count = a.nonempty_artifact_count;
    d.required_doc_count = doc.required_doc_count;
    d.existing_doc_count = doc.existing_doc_count;
    d.artifact_fingerprint = a.fingerprint;
    d.document_fingerprint = doc.fingerprint;
    d.rerun_fingerprint = rerun.fingerprint;
    d.local_test_verified = rerun.local_test_compiled && rerun.local_test_passed;
    d.release_compile_verified = rerun.release_compiled;
    d.tail_chain_authoritative = validate_support8_tail_obstruction_chain_theorem_data_(nullptr);
    ostringstream oss;
    oss << (d.shell15_frontier_authoritative ? 1 : 0) << '|'
        << (d.shell15_scope_authoritative ? 1 : 0) << '|'
        << (d.tail_pattern_authoritative ? 1 : 0) << '|'
        << (d.tail_chain_authoritative ? 1 : 0) << '|'
        << (d.artifact_completion_verified ? 1 : 0) << '|'
        << (d.document_completion_verified ? 1 : 0) << '|'
        << (d.rerun_completion_verified ? 1 : 0) << '|'
        << (d.audit_freshness_verified ? 1 : 0) << '|'
        << (d.stale_audit_eliminated ? 1 : 0) << '|'
        << (d.local_test_verified ? 1 : 0) << '|'
        << (d.release_compile_verified ? 1 : 0) << '|'
        << d.required_artifact_count << '|'
        << d.existing_artifact_count << '|'
        << d.nonempty_artifact_count << '|'
        << d.required_doc_count << '|'
        << d.existing_doc_count << '|'
        << d.artifact_fingerprint << '|'
        << d.document_fingerprint << '|'
        << d.rerun_fingerprint;
    d.fingerprint = oss.str();
    d.why = "support8 authoritative completion lock";
    g_last_support8_authoritative_completion_lock_data = d;
    return d;
}

