static TheoremDataProvenanceAuditSummary summarize_theorem_data_provenance_inventory_(
    const vector<TheoremDataProvenanceInventoryItem>& items) {
    TheoremDataProvenanceAuditSummary summary;
    summary.item_count = items.size();
    ostringstream fp;
    for (const auto& item : items) {
        switch (item.validation_status) {
            case ProvenanceValidationStatus::CurrentVerified: ++summary.current_verified_count; break;
            case ProvenanceValidationStatus::CounterexampleFreeUnderTestedRange: ++summary.counterexample_free_under_tested_range_count; break;
            case ProvenanceValidationStatus::ArchivalClaim: ++summary.archival_claim_count; break;
            case ProvenanceValidationStatus::NotAttempted: ++summary.not_attempted_count; break;
        }
        switch (item.provenance_source) {
            case ProvenanceSourceKind::FreshCurrentRuntimeGenerated: ++summary.fresh_current_runtime_generated_count; break;
            case ProvenanceSourceKind::CurrentRuntimeValidatedImportedData: ++summary.current_runtime_validated_imported_data_count; break;
            case ProvenanceSourceKind::ArchivalOnly: ++summary.archival_only_count; break;
            case ProvenanceSourceKind::Mixed: ++summary.mixed_count; break;
            case ProvenanceSourceKind::Unknown: ++summary.unknown_count; break;
        }
        fp << item.item_key << '|'
           << provenance_validation_status_to_string_(item.validation_status) << '|'
           << provenance_source_kind_to_string_(item.provenance_source) << '|'
           << (item.fresh_rederivation ? 1 : 0) << '|'
           << item.imported_from_source_tag << '|'
           << item.current_bundle_version << '\n';
    }
    string fp_text = fp.str();
    summary.fingerprint = to_string(fp_text.size()) + ":" + to_string(hash<string>{}(fp_text));
    g_last_theorem_data_provenance_audit_summary = summary;
    return summary;
}

static string theorem_data_provenance_audit_summary_to_string_(const TheoremDataProvenanceAuditSummary& summary) {
    ostringstream oss;
    oss << "items=" << summary.item_count
        << " currentVerified=" << summary.current_verified_count
        << " counterexampleFree=" << summary.counterexample_free_under_tested_range_count
        << " archivalClaim=" << summary.archival_claim_count
        << " notAttempted=" << summary.not_attempted_count
        << " freshGenerated=" << summary.fresh_current_runtime_generated_count
        << " validatedImported=" << summary.current_runtime_validated_imported_data_count
        << " archivalOnly=" << summary.archival_only_count
        << " mixed=" << summary.mixed_count
        << " unknown=" << summary.unknown_count
        << " fingerprint=" << summary.fingerprint;
    return oss.str();
}

static bool write_theorem_data_provenance_inventory_files_(
    const vector<TheoremDataProvenanceInventoryItem>& items,
    const TheoremDataProvenanceAuditSummary& summary,
    string* why) {
    const string inventory_path = support8_runtime_bundle_path_("theorem_data_provenance_inventory_90.tsv");
    const string summary_path = support8_runtime_bundle_path_("provenance_audit_fingerprint_90.tsv");
    CurrentBundleMetadata current = current_bundle_metadata_();

    ofstream inventory_out(inventory_path);
    if (!inventory_out) {
        if (why) *why = "failed to write theorem-data provenance inventory";
        return false;
    }
    inventory_out << "item_key\tdisplay_name\tvalidation_status\tprovenance_source\tcurrent_bundle_version\tcurrent_bundle_source_path\tcurrent_bundle_summary_path\truntime_note_path\truntime_artifact_path\tarchival_note_path\timported_from_source_tag\timported_from_version\timported_from_path\tfresh_rederivation\tcaveat\n";
    for (const auto& item : items) {
        inventory_out
            << sanitize_provenance_tsv_field_(item.item_key) << '\t'
            << sanitize_provenance_tsv_field_(item.display_name) << '\t'
            << sanitize_provenance_tsv_field_(provenance_validation_status_to_string_(item.validation_status)) << '\t'
            << sanitize_provenance_tsv_field_(provenance_source_kind_to_string_(item.provenance_source)) << '\t'
            << item.current_bundle_version << '\t'
            << sanitize_provenance_tsv_field_(item.current_bundle_source_path) << '\t'
            << sanitize_provenance_tsv_field_(item.current_bundle_summary_path) << '\t'
            << sanitize_provenance_tsv_field_(item.runtime_note_path) << '\t'
            << sanitize_provenance_tsv_field_(item.runtime_artifact_path) << '\t'
            << sanitize_provenance_tsv_field_(item.archival_note_path) << '\t'
            << sanitize_provenance_tsv_field_(item.imported_from_source_tag) << '\t'
            << sanitize_provenance_tsv_field_(item.imported_from_version) << '\t'
            << sanitize_provenance_tsv_field_(item.imported_from_path) << '\t'
            << (item.fresh_rederivation ? 1 : 0) << '\t'
            << sanitize_provenance_tsv_field_(item.caveat) << "\n";
    }

    ofstream summary_out(summary_path);
    if (!summary_out) {
        if (why) *why = "failed to write provenance audit summary";
        return false;
    }
    summary_out << "metric\tvalue\n";
    summary_out << "audit_fingerprint\t" << summary.fingerprint << "\n";
    summary_out << "item_count\t" << summary.item_count << "\n";
    summary_out << "current_verified_count\t" << summary.current_verified_count << "\n";
    summary_out << "counterexample_free_under_tested_range_count\t" << summary.counterexample_free_under_tested_range_count << "\n";
    summary_out << "archival_claim_count\t" << summary.archival_claim_count << "\n";
    summary_out << "not_attempted_count\t" << summary.not_attempted_count << "\n";
    summary_out << "fresh_current_runtime_generated_count\t" << summary.fresh_current_runtime_generated_count << "\n";
    summary_out << "current_runtime_validated_imported_data_count\t" << summary.current_runtime_validated_imported_data_count << "\n";
    summary_out << "archival_only_count\t" << summary.archival_only_count << "\n";
    summary_out << "mixed_count\t" << summary.mixed_count << "\n";
    summary_out << "unknown_count\t" << summary.unknown_count << "\n";
    summary_out << "current_bundle_version\t" << current.version << "\n";
    summary_out << "current_bundle_role\t" << current.role << "\n";
    summary_out << "current_bundle_source_path\t" << current.source_path << "\n";
    summary_out << "current_bundle_summary_path\t" << current.archival_summary_path << "\n";
    summary_out << "runtime_summary_path\t" << current.runtime_summary_path << "\n";
    summary_out << "workspace_root\t" << current.workspace_root << "\n";
    summary_out << "branch4_root\t" << current.branch4_root << "\n";
    summary_out << "archival_bundle_root\t" << current.archival_bundle_root << "\n";
    summary_out << "runtime_data_root\t" << current.runtime_data_root << "\n";
    summary_out << "imported_catalog_summary\t" << sanitize_provenance_tsv_field_(imported_provenance_catalog_summary_()) << "\n";

    if (why) {
        *why = string("wrote provenance inventory path=") + inventory_path +
               " summaryPath=" + summary_path +
               " " + theorem_data_provenance_audit_summary_to_string_(summary);
    }
    return true;
}

static bool write_basis_family_generation_audit_files_(
    const ExactTheoremAuditStats& exact,
    const FamilyChainTheoremAuditStats& family,
    string* why) {
    const string basis_path = support8_runtime_bundle_path_("basis_only_generation_audit_90.tsv");
    const string family_path = support8_runtime_bundle_path_("family_chain_generation_audit_90.tsv");
    const string summary_path = support8_runtime_bundle_path_("basis_family_generation_fingerprint_90.tsv");
    const string family_constructor_path = support8_runtime_bundle_path_("family_chain_constructor_audit_90.tsv");
    const string family_constructor_fingerprint_path = support8_runtime_bundle_path_("family_chain_constructor_fingerprint_90.tsv");

    ofstream basis_out(basis_path);
    if (!basis_out) {
        if (why) *why = "failed to write basis-only generation audit";
        return false;
    }
    basis_out << "metric\tvalue\n";
    basis_out << "target_subset\tbasis_only_theorem_chain\n";
    basis_out << "previous_provenance_label\tcurrent_runtime_validated_imported_data\n";
    basis_out << "current_provenance_label\t"
              << (g_last_exact_theorem_audit_fresh_runtime_generated ? "fresh_current_runtime_generated"
                                                                     : "current_runtime_validated_imported_data")
              << "\n";
    basis_out << "generation_path\t" << g_last_exact_theorem_audit_authoritative_source << "\n";
    basis_out << "basis_payload_source\t" << g_last_exact_theorem_audit_basis_payload_source << "\n";
    basis_out << "basis_payload_constructor\t"
              << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_constructor_name) << "\n";
    basis_out << "basis_payload_row_count\t" << g_last_exact_minimal_basis_payload_row_count << "\n";
    basis_out << "basis_payload_fingerprint\t" << exact_minimal_proof_motif_basis_fingerprint_() << "\n";
    basis_out << "basis_payload_imported_fingerprint\t"
              << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_imported_fingerprint) << "\n";
    basis_out << "basis_payload_imported_row_set_equal\t"
              << (g_last_exact_minimal_basis_payload_imported_row_set_equal ? 1 : 0) << "\n";
    basis_out << "basis_payload_source_fingerprint\t"
              << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_source_fingerprint) << "\n";
    basis_out << "basis_payload_fallback_reachable\t"
              << (g_last_exact_minimal_basis_payload_fallback_reachable ? 1 : 0) << "\n";
    basis_out << "basis_payload_fallback_hit\t"
              << (g_last_exact_minimal_basis_payload_fallback_hit ? 1 : 0) << "\n";
    basis_out << "basis_payload_minimality_lower_bound\t"
              << g_last_exact_minimal_basis_payload_minimality_lower_bound << "\n";
    basis_out << "basis_payload_minimality_upper_bound\t"
              << g_last_exact_minimal_basis_payload_minimality_upper_bound << "\n";
    basis_out << "basis_payload_minimality_status\t"
              << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_minimality_status) << "\n";
    basis_out << "basis_payload_blocker\t"
              << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_blocker) << "\n";
    basis_out << "runtime_generation_fingerprint\t" << g_last_exact_theorem_audit_runtime_fingerprint << "\n";
    basis_out << "exact_n5_instances_checked\t" << exact.exact_n5_instances_checked << "\n";
    basis_out << "bounded_n6_c5_instances_checked\t" << exact.bounded_n6_c5_instances_checked << "\n";
    basis_out << "bounded_n7_c3_instances_checked\t" << exact.bounded_n7_c3_instances_checked << "\n";
    basis_out << "exact_n5_verified\t" << (exact.exact_n5_verified ? 1 : 0) << "\n";
    basis_out << "bounded_n6_c5_verified\t" << (exact.bounded_n6_c5_verified ? 1 : 0) << "\n";
    basis_out << "bounded_n7_c3_verified\t" << (exact.bounded_n7_c3_verified ? 1 : 0) << "\n";
    basis_out << "basis_size_item_current_provenance\t"
              << (g_last_exact_minimal_basis_payload_fresh_runtime_generated
                      ? "fresh_current_runtime_generated"
                      : "current_runtime_validated_imported_data")
              << "\n";
    basis_out << "basis_size_promoted_this_round\t"
              << (g_last_exact_minimal_basis_payload_fresh_runtime_generated ? 1 : 0) << "\n";
    basis_out << "caveat\t"
              << sanitize_provenance_tsv_field_(
                     g_last_exact_minimal_basis_payload_fresh_runtime_generated
                         ? "The basis-only theorem trio is now anchored on a fresh current-runtime exact-basis payload constructor."
                         : "Fresh theorem reruns still rely on the imported 96-basis payload; this round did not freshly rederive the basis payload itself.")
              << "\n";

    ofstream family_out(family_path);
    if (!family_out) {
        if (why) *why = "failed to write family-chain generation audit";
        return false;
    }
    family_out << "metric\tvalue\n";
    family_out << "target_subset\tfamily_chain_output_57\n";
    family_out << "previous_provenance_label\tcurrent_runtime_validated_imported_data\n";
    family_out << "current_provenance_label\t"
               << (g_last_family_chain_theorem_audit_fresh_runtime_generated ? "fresh_current_runtime_generated"
                                                                             : "current_runtime_validated_imported_data")
               << "\n";
    family_out << "generation_path\t" << g_last_family_chain_theorem_audit_authoritative_source << "\n";
    family_out << "runtime_generation_fingerprint\t" << g_last_family_chain_theorem_audit_runtime_fingerprint << "\n";
    family_out << "single_family_regions\t" << family.single_family_regions << "\n";
    family_out << "pair_regions\t" << family.pair_regions << "\n";
    family_out << "triple_regions\t" << family.triple_regions << "\n";
    family_out << "quadruple_regions\t" << family.quadruple_regions << "\n";
    family_out << "quintuple_regions\t" << family.quintuple_regions << "\n";
    family_out << "sextuple_regions\t" << family.sextuple_regions << "\n";
    family_out << "septuple_regions\t" << family.septuple_regions << "\n";
    family_out << "self_verified\t" << (family.self_verified ? 1 : 0) << "\n";
    family_out << "blocker\t" << sanitize_provenance_tsv_field_(g_last_family_chain_theorem_audit_blocker) << "\n";
    family_out << "constructor_name\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_name) << "\n";
    family_out << "fallback_hit\t" << (g_last_family_chain_constructor_fallback_hit ? 1 : 0) << "\n";
    family_out << "caveat\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_caveat) << "\n";

    ofstream summary_out(summary_path);
    if (!summary_out) {
        if (why) *why = "failed to write basis/family generation summary";
        return false;
    }
    summary_out << "metric\tvalue\n";
    summary_out << "basis_generation_label\t"
                << (g_last_exact_theorem_audit_fresh_runtime_generated ? "fresh_current_runtime_generated"
                                                                       : "current_runtime_validated_imported_data")
                << "\n";
    summary_out << "family_generation_label\t"
                << (g_last_family_chain_theorem_audit_fresh_runtime_generated ? "fresh_current_runtime_generated"
                                                                              : "current_runtime_validated_imported_data")
                << "\n";
    summary_out << "basis_generation_fingerprint\t" << g_last_exact_theorem_audit_runtime_fingerprint << "\n";
    summary_out << "family_generation_fingerprint\t" << g_last_family_chain_theorem_audit_runtime_fingerprint << "\n";
    summary_out << "basis_promoted_item_count\t"
                << (g_last_exact_theorem_audit_fresh_runtime_generated
                        ? (g_last_exact_minimal_basis_payload_fresh_runtime_generated ? 4 : 3)
                        : 0)
                << "\n";
    summary_out << "family_promoted_item_count\t" << (g_last_family_chain_theorem_audit_fresh_runtime_generated ? 2 : 0) << "\n";
    summary_out << "basis_payload_constructor\t"
                << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_constructor_name) << "\n";
    summary_out << "basis_payload_fallback_hit\t"
                << (g_last_exact_minimal_basis_payload_fallback_hit ? 1 : 0) << "\n";
    summary_out << "basis_payload_minimality_status\t"
                << sanitize_provenance_tsv_field_(g_last_exact_minimal_basis_payload_minimality_status) << "\n";
    summary_out << "family_constructor_name\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_name) << "\n";
    summary_out << "family_constructor_fallback_hit\t" << (g_last_family_chain_constructor_fallback_hit ? 1 : 0) << "\n";
    summary_out << "family_constructor_caveat\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_caveat) << "\n";

    ofstream family_constructor_out(family_constructor_path);
    if (!family_constructor_out) {
        if (why) *why = "failed to write family-chain constructor audit";
        return false;
    }
    family_constructor_out << "metric\tvalue\n";
    family_constructor_out << "target_subset\tfamily_chain_output_57\n";
    family_constructor_out << "constructor_name\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_name) << "\n";
    family_constructor_out << "used_current_constructor\t" << (g_last_family_chain_theorem_audit_fresh_runtime_generated ? 1 : 0) << "\n";
    family_constructor_out << "fallback_hit\t" << (g_last_family_chain_constructor_fallback_hit ? 1 : 0) << "\n";
    family_constructor_out << "authoritative_source\t" << sanitize_provenance_tsv_field_(g_last_family_chain_theorem_audit_authoritative_source) << "\n";
    family_constructor_out << "constructor_caveat\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_caveat) << "\n";
    family_constructor_out << "theorem_runtime_fingerprint\t" << sanitize_provenance_tsv_field_(g_last_family_chain_theorem_audit_runtime_fingerprint) << "\n";
    family_constructor_out << "support_theorem\t" << sanitize_provenance_tsv_field_(
        support_bounded_schema_universe_obstruction_theorem_to_string_(g_last_support_bounded_schema_universe_obstruction_theorem)) << "\n";
    family_constructor_out << "unified_theorem\t" << sanitize_provenance_tsv_field_(
        unified_bounded_schema_universe_obstruction_theorem_to_string_(g_last_unified_bounded_schema_universe_obstruction_theorem)) << "\n";

    ofstream family_constructor_fp_out(family_constructor_fingerprint_path);
    if (!family_constructor_fp_out) {
        if (why) *why = "failed to write family-chain constructor fingerprint";
        return false;
    }
    family_constructor_fp_out << "metric\tvalue\n";
    family_constructor_fp_out << "constructor_name\t" << sanitize_provenance_tsv_field_(g_last_family_chain_constructor_name) << "\n";
    family_constructor_fp_out << "used_current_constructor\t" << (g_last_family_chain_theorem_audit_fresh_runtime_generated ? 1 : 0) << "\n";
    family_constructor_fp_out << "fallback_hit\t" << (g_last_family_chain_constructor_fallback_hit ? 1 : 0) << "\n";
    family_constructor_fp_out << "runtime_fingerprint\t" << sanitize_provenance_tsv_field_(g_last_family_chain_theorem_audit_runtime_fingerprint) << "\n";

    if (why) {
        *why = string("wrote basis/family generation audits basisPath=") + basis_path +
               " familyPath=" + family_path + " summaryPath=" + summary_path +
               " constructorPath=" + family_constructor_path;
    }
    return true;
}

