static void ensure_high_family_expansion_ready_slow_() {
    if (g_last_unified_bounded_schema_universe_status == "support_bounded_schema_universe_obstruction_chain_theorem_supported" ||
        g_last_unified_bounded_schema_universe_status == "bounded_high_family_expansion_promising") return;
    string why;
    if (!ensure_unified_bounded_schema_universe_obstruction_ready_(&why)) {
        throw runtime_error(string("unified bounded obstruction theorem data unavailable\n") + why);
    }
    if (!ensure_quintuple_family_expansion_ready_fast_(false, &why)) {
        throw runtime_error(string("authoritative quintuple-family theorem data unavailable\n") + why);
    }
    auto families = authoritative_exact_minimal_basis_plus_one_failure_family_summaries_data_49_();
    auto pool = exact_minimal_basis_global_schema_candidate_pool_();
    g_last_sextuple_family_expansion_region_specs = build_sextuple_family_expansion_region_specs_(families, &why);
    g_last_septuple_family_expansion_region_specs = build_septuple_family_expansion_region_specs_(families, &why);
    g_last_sextuple_family_expansion_stats.clear();
    g_last_sextuple_family_expansion_candidates.clear();
    g_last_septuple_family_expansion_stats.clear();
    g_last_septuple_family_expansion_candidates.clear();
    g_last_out_of_pool_schema_validation_cache.clear();
#ifdef LOCAL_TEST
    cerr << "stage: sextuple-family expansion\n";
#endif
    for (size_t idx = 0; idx < g_last_sextuple_family_expansion_region_specs.size(); ++idx) {
        const auto& spec = g_last_sextuple_family_expansion_region_specs[idx];
        vector<const ProofMotifPlusOneFailureFamilySummary*> found;
        for (const auto& fp : spec.source_family_fingerprints) {
            const ProofMotifPlusOneFailureFamilySummary* fam = nullptr;
            for (const auto& f : families) if (f.family_fingerprint == fp) { fam = &f; break; }
            if (!fam) throw runtime_error("sextuple_merged spec refers to missing family");
            found.push_back(fam);
        }
        string enum_why;
        auto out = enumerate_out_of_pool_sextuple_family_candidates_(*found[0],*found[1],*found[2],*found[3],*found[4],*found[5],spec.symbol_bound,spec.antecedent_bound,pool,&enum_why);
#ifdef LOCAL_TEST
        cerr << "stage: sextuple-family region " << (idx + 1) << "/" << g_last_sextuple_family_expansion_region_specs.size() << " " << spec.fingerprint << " out=" << out.size() << "\n";
#endif
        auto stats = scan_out_of_pool_bounded_expansion_region_detailed_(spec.fingerprint, spec.symbol_bound, spec.antecedent_bound, out.size(), out, {}, &g_last_sextuple_family_expansion_candidates, &why);
        if (!enum_why.empty()) stats.why = enum_why + " ; " + stats.why;
        g_last_sextuple_family_expansion_stats.push_back(stats);
    }
#ifdef LOCAL_TEST
    cerr << "stage: septuple-family expansion\n";
#endif
    for (size_t idx = 0; idx < g_last_septuple_family_expansion_region_specs.size(); ++idx) {
        const auto& spec = g_last_septuple_family_expansion_region_specs[idx];
        string enum_why;
        auto out = enumerate_out_of_pool_septuple_family_candidates_(families, spec.symbol_bound, spec.antecedent_bound, pool, &enum_why);
#ifdef LOCAL_TEST
        cerr << "stage: septuple-family region " << (idx + 1) << "/" << g_last_septuple_family_expansion_region_specs.size() << " " << spec.fingerprint << " out=" << out.size() << "\n";
#endif
        auto stats = scan_out_of_pool_bounded_expansion_region_detailed_(spec.fingerprint, spec.symbol_bound, spec.antecedent_bound, out.size(), out, {}, &g_last_septuple_family_expansion_candidates, &why);
        if (!enum_why.empty()) stats.why = enum_why + " ; " + stats.why;
        g_last_septuple_family_expansion_stats.push_back(stats);
    }
    auto count_unique = [](const vector<OutOfPoolExpansionCandidate>& candidates) {
        set<string> uniq;
        for (const auto& cand : candidates) uniq.insert(canonical_structured_local_schema_fingerprint_(cand.schema));
        return uniq.size();
    };
    g_last_sextuple_family_theorem_data = {};
    g_last_sextuple_family_theorem_data.region_count = g_last_sextuple_family_expansion_stats.size();
    for (const auto& e : g_last_sextuple_family_expansion_stats) {
        g_last_sextuple_family_theorem_data.raw_candidates += e.raw_candidates;
        g_last_sextuple_family_theorem_data.canonical_candidates += e.canonical_candidates;
        g_last_sextuple_family_theorem_data.local_exact_survivors += e.local_exact_survivors;
        g_last_sextuple_family_theorem_data.plus_one_survivors += e.plus_one_survivors;
        g_last_sextuple_family_theorem_data.theorem_preserving_survivors += e.theorem_preserving_survivors;
    }
    g_last_sextuple_family_theorem_data.deduplicated_candidates = count_unique(g_last_sextuple_family_expansion_candidates);
    g_last_sextuple_family_theorem_data.why = "slow sextuple-family frontier rebuild completed";

    g_last_septuple_family_theorem_data = {};
    g_last_septuple_family_theorem_data.region_count = g_last_septuple_family_expansion_stats.size();
    for (const auto& e : g_last_septuple_family_expansion_stats) {
        g_last_septuple_family_theorem_data.raw_candidates += e.raw_candidates;
        g_last_septuple_family_theorem_data.canonical_candidates += e.canonical_candidates;
        g_last_septuple_family_theorem_data.local_exact_survivors += e.local_exact_survivors;
        g_last_septuple_family_theorem_data.plus_one_survivors += e.plus_one_survivors;
        g_last_septuple_family_theorem_data.theorem_preserving_survivors += e.theorem_preserving_survivors;
    }
    g_last_septuple_family_theorem_data.deduplicated_candidates = count_unique(g_last_septuple_family_expansion_candidates);
    g_last_septuple_family_theorem_data.why = "slow septuple-family frontier rebuild completed";

    vector<OutOfPoolExpansionCandidate> all = g_last_sextuple_family_expansion_candidates;
    all.insert(all.end(), g_last_septuple_family_expansion_candidates.begin(), g_last_septuple_family_expansion_candidates.end());
    string aggr_why;
    g_last_high_family_candidate_aggregate_stats = build_high_family_candidate_aggregate_stats_(all, g_last_sextuple_family_expansion_stats.size() + g_last_septuple_family_expansion_stats.size(), &aggr_why);
    g_last_high_family_candidate_aggregate_stats.raw_candidates = 0;
    for (const auto& e : g_last_sextuple_family_expansion_stats) g_last_high_family_candidate_aggregate_stats.raw_candidates += e.raw_candidates;
    for (const auto& e : g_last_septuple_family_expansion_stats) g_last_high_family_candidate_aggregate_stats.raw_candidates += e.raw_candidates;
    g_last_high_family_candidate_aggregate_stats.why = "combined sextuple and septuple frontier aggregate";
    g_last_high_family_theorem_data = {};
    g_last_high_family_theorem_data.sextuple_region_count = g_last_sextuple_family_theorem_data.region_count;
    g_last_high_family_theorem_data.septuple_region_count = g_last_septuple_family_theorem_data.region_count;
    g_last_high_family_theorem_data.region_count_total = g_last_high_family_candidate_aggregate_stats.region_count;
    g_last_high_family_theorem_data.raw_candidates = g_last_high_family_candidate_aggregate_stats.raw_candidates;
    g_last_high_family_theorem_data.canonical_candidates = g_last_high_family_candidate_aggregate_stats.canonical_candidates;
    g_last_high_family_theorem_data.deduplicated_candidates = g_last_high_family_candidate_aggregate_stats.deduplicated_candidates;
    g_last_high_family_theorem_data.local_exact_survivors = g_last_high_family_candidate_aggregate_stats.local_exact_survivors;
    g_last_high_family_theorem_data.plus_one_survivors = g_last_high_family_candidate_aggregate_stats.plus_one_survivors;
    g_last_high_family_theorem_data.theorem_preserving_survivors = g_last_high_family_candidate_aggregate_stats.theorem_preserving_survivors;
    g_last_high_family_theorem_data.why = "combined sextuple and septuple frontier aggregate";
    string status_why;
    g_last_unified_bounded_schema_universe_status = classify_unified_bounded_schema_universe_status_(g_last_unified_bounded_schema_universe_obstruction_theorem,
                                                                                                      &g_last_high_family_candidate_aggregate_stats,
                                                                                                      &status_why);
    g_last_unified_bounded_schema_universe_ledger = build_unified_bounded_schema_universe_ledger_(g_last_unified_bounded_schema_universe_obstruction_theorem,
                                                                                                   &g_last_high_family_candidate_aggregate_stats,
                                                                                                   g_last_unified_bounded_schema_universe_status);
}

static bool ensure_high_family_expansion_ready_fast_(bool allow_slow_rebuild,
                                                     string* why) {
    if (g_last_high_family_theorem_data.region_count_total != 0) {
        if (why) *why = high_family_expansion_theorem_data_to_string_(g_last_high_family_theorem_data);
        return true;
    }
    reset_high_family_expansion_theorem_data_57_state_();
    string w1, w2;
    if (!ensure_unified_bounded_schema_universe_obstruction_ready_(&w1) ||
        !ensure_septuple_family_expansion_ready_fast_(false, &w2)) {
        if (why) *why = w1 + "\n" + w2;
        return false;
    }

    string current_why;
    if (load_current_high_family_expansion_theorem_data_57_runtime_artifact_(&current_why)) {
        if (why) *why = current_why;
        return true;
    }
#ifdef LOCAL_TEST
    cerr << "stage: build high-family expansion theorem data 57 current artifact\n";
#endif
    if (build_current_high_family_expansion_theorem_data_57_from_septuple57_ready_aggregate_scan_(&current_why)) {
        if (why) *why = current_why;
        return true;
    }

    string theorem_why;
    if (validate_authoritative_high_family_expansion_data_(&theorem_why)) {
        install_imported_high_family_expansion_theorem_data_57_fallback_(
            current_why.empty() ? theorem_why : current_why);
        if (why) *why = current_why.empty() ? theorem_why : current_why;
        return true;
    }
    if (!allow_slow_rebuild) {
        if (why) *why = current_why + "\n" + theorem_why;
        return false;
    }
    ensure_high_family_expansion_ready_slow_();
    if (why) *why = "slow high-family rebuild completed";
    return true;
}

static void ensure_high_family_expansion_ready_() {
    string why;
    if (!ensure_high_family_expansion_ready_fast_(false, &why)) {
        throw runtime_error(string("authoritative high-family theorem data unavailable\n") + why);
    }
}

static vector<LocalityObstructionCertificate> search_single_schema_obstructions_() {
    vector<LocalityObstructionCertificate> out;
    int support_bound = single_structured_local_schema_().num_symbols;
    if (g_last_single_schema_bounded_n6_c3_failure.instance.n > 0 && !g_last_single_schema_bounded_n6_c3_failure.missing_forced_pairs.empty()) {
        string why;
        out.push_back(build_locality_obstruction_certificate_(g_last_single_schema_bounded_n6_c3_failure.instance,
                                                              g_last_single_schema_bounded_n6_c3_failure.missing_forced_pairs.front(),
                                                              support_bound, &why));
    }
    if (g_last_single_schema_bounded_n6_c4_failure.instance.n > 0 && !g_last_single_schema_bounded_n6_c4_failure.missing_forced_pairs.empty()) {
        string why;
        auto cert = build_locality_obstruction_certificate_(g_last_single_schema_bounded_n6_c4_failure.instance,
                                                            g_last_single_schema_bounded_n6_c4_failure.missing_forced_pairs.front(),
                                                            support_bound, &why);
        bool dup = false;
        for (const auto& c : out) if (c.instance_fingerprint == cert.instance_fingerprint && c.target_fingerprint == cert.target_fingerprint) dup = true;
        if (!dup) out.push_back(cert);
    }
    return out;
}

