static SparseRuleCandidate make_explicit_sparse_rule_(initializer_list<SparseLcaConstraint> ants,
                                                      const SparseLcaConstraint& cons) {
    SparseRuleCandidate r;
    r.antecedents.assign(ants.begin(), ants.end());
    r.consequent = cons;
    return canonicalize_rule_candidate_(r);
}

