static void ensure_single_schema_theorem_ready_() {
    string why;
    auto solver_schemas = current_solver_schema_rules_();

    g_last_retained_first_wave_repair_rules = retained_first_wave_repair_rules_();
    g_last_retained_second_wave_repair_rules = retained_second_wave_repair_rules_();
    g_last_retained_all_repair_rules = retained_all_repair_rules_();
    g_last_retained_third_wave_repair_rules = retained_third_wave_repair_rules_();

    g_last_structured_local_schema_families = generalize_third_wave_to_structured_local_schemas_(g_last_retained_third_wave_repair_rules);
    g_last_structured_local_schemas.clear();
    for (const auto& fam : g_last_structured_local_schema_families) g_last_structured_local_schemas.push_back(fam.representative);

    g_last_single_structured_local_schema = single_structured_local_schema_();
    g_last_single_structured_local_schema_fp = g_last_single_structured_local_schema.fingerprint;

    if (g_last_structured_local_schema_families.size() != 1) {
        throw runtime_error("ensure_single_schema: structured local family count is not 1");
    }
    if (g_last_structured_local_schema_families.front().fingerprint != g_last_single_structured_local_schema_fp) {
        throw runtime_error("ensure_single_schema: explicit single schema fingerprint mismatch with derived family");
    }

    g_last_structured_local_theorem_stats = {};
    g_last_structured_local_theorem_stats.schema_family_count = g_last_structured_local_schema_families.size();
    for (const auto& schema : g_last_structured_local_schemas) {
        string local_why;
        bool local_ok = validate_structured_local_schema_local_exact_(schema, &local_why);
        if (local_ok) ++g_last_structured_local_theorem_stats.local_exact_pass_count;
        bool plus_one_ok = false;
        if (local_ok) plus_one_ok = validate_structured_local_schema_plus_one_exact_(schema, &local_why);
        if (plus_one_ok) ++g_last_structured_local_theorem_stats.plus_one_pass_count;
        bool attempt_plus_two = schema.num_symbols <= 5;
        if (attempt_plus_two) {
            ++g_last_structured_local_theorem_stats.plus_two_attempted_count;
            if (validate_structured_local_schema_plus_two_exact_(schema, &local_why)) ++g_last_structured_local_theorem_stats.plus_two_pass_count;
        }
        if (!local_why.empty() && g_last_structured_local_theorem_stats.why.empty()) g_last_structured_local_theorem_stats.why = local_why;
    }

    g_last_single_schema_theorem_stats = {};
    g_last_single_schema_theorem_stats.local_exact_pass = validate_structured_local_schema_local_exact_(g_last_single_structured_local_schema, &why);
    if (!g_last_single_schema_theorem_stats.local_exact_pass) {
        g_last_single_schema_theorem_stats.why = why;
        return;
    }
    g_last_single_schema_theorem_stats.plus_one_pass = validate_structured_local_schema_plus_one_exact_(g_last_single_structured_local_schema, &why);
    if (!why.empty() && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    g_last_single_schema_theorem_stats.plus_two_pass = validate_structured_local_schema_plus_two_exact_(g_last_single_structured_local_schema, &why);
    if (!why.empty() && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    g_last_single_schema_theorem_stats.plus_three_attempted = true;
#ifdef LOCAL_TEST
    cerr << "stage: single schema plus-three\n";
#endif
    g_last_single_schema_theorem_stats.plus_three_pass = validate_single_schema_plus_three_exact_(g_last_single_structured_local_schema, &why);
    g_last_single_schema_theorem_stats.plus_three_why = why;

    if (g_last_single_schema_exact_n5_stats.canonical_instances == 0) {
        SolverSaturationResult failure;
        if (!scan_structured_local_schema_exhaustive_n5_({}, solver_schemas,
                                                         g_last_retained_first_wave_repair_rules,
                                                         g_last_retained_second_wave_repair_rules,
                                                         {g_last_single_structured_local_schema},
                                                         &g_last_single_schema_exact_n5_stats,
                                                         &failure,
                                                         &why)) {
            throw runtime_error("ensure_single_schema: exact n5 failed\n" + why);
        }
        g_last_single_schema_exact_n5_failure = failure;
    }
    g_last_structured_local_exact_n5_stats = g_last_single_schema_exact_n5_stats;
    g_last_structured_local_exact_n5_failure = g_last_single_schema_exact_n5_failure;
    g_last_structured_local_theorem_stats.exact_n5_full_matches = g_last_single_schema_exact_n5_stats.full_match_instances;
    g_last_structured_local_theorem_stats.exact_n5_mismatches = g_last_single_schema_exact_n5_stats.mismatch_instances;

    #ifdef LOCAL_TEST
    cerr << "stage: single schema bounded n6 c3\n";
#endif
    if (g_last_single_schema_bounded_n6_c3_stats.canonical_instances == 0) {
        if (!scan_single_schema_bounded_exact_n6_constraint3_({}, solver_schemas,
                                                              g_last_retained_first_wave_repair_rules,
                                                              g_last_retained_second_wave_repair_rules,
                                                              &g_last_single_schema_bounded_n6_c3_stats,
                                                              &g_last_single_schema_bounded_n6_c3_failure,
                                                              &why)) {
            throw runtime_error("ensure_single_schema: bounded n6 c3 failed\n" + why);
        }
    }
    #ifdef LOCAL_TEST
    if (kSingleSchemaAttemptBoundedExactN6Constraint4) cerr << "stage: single schema bounded n6 c4\n";
#endif
    if (kSingleSchemaAttemptBoundedExactN6Constraint4 && g_last_single_schema_bounded_n6_c4_stats.canonical_instances == 0) {
        if (!scan_single_schema_bounded_exact_n6_constraint4_({}, solver_schemas,
                                                              g_last_retained_first_wave_repair_rules,
                                                              g_last_retained_second_wave_repair_rules,
                                                              &g_last_single_schema_bounded_n6_c4_stats,
                                                              &g_last_single_schema_bounded_n6_c4_failure,
                                                              &why)) {
            throw runtime_error("ensure_single_schema: bounded n6 c4 failed\n" + why);
        }
    }
    g_last_structured_local_bounded_exact_n6_stats = g_last_single_schema_bounded_n6_c3_stats;
    g_last_structured_local_bounded_exact_n6_failure = g_last_single_schema_bounded_n6_c3_failure;
    g_last_structured_local_theorem_stats.bounded_n6_full_matches = g_last_single_schema_bounded_n6_c3_stats.full_match_instances;
    g_last_structured_local_theorem_stats.bounded_n6_mismatches = g_last_single_schema_bounded_n6_c3_stats.mismatch_instances;

    #ifdef LOCAL_TEST
    cerr << "stage: single schema sampled n9\n";
#endif
    if (kSingleSchemaRandomizedN9NumTrees > 0 && kSingleSchemaRandomizedN9SubsetsPerTree > 0 && g_last_single_schema_sampled_n9_stats.canonical_instances == 0) {
        if (!scan_single_schema_randomized_n9_({}, solver_schemas,
                                               g_last_retained_first_wave_repair_rules,
                                               g_last_retained_second_wave_repair_rules,
                                               &g_last_single_schema_sampled_n9_stats,
                                               &g_last_single_schema_sampled_n9_failure,
                                               &why)) {
            throw runtime_error("ensure_single_schema: sampled n9 failed\n" + why);
        }
    }
    #ifdef LOCAL_TEST
    cerr << "stage: single schema sampled n10\n";
#endif
    if (kSingleSchemaAttemptRandomizedN10 && g_last_single_schema_sampled_n10_stats.canonical_instances == 0 && kSingleSchemaRandomizedN10NumTrees > 0 && kSingleSchemaRandomizedN10SubsetsPerTree > 0) {
        if (!scan_single_schema_randomized_n10_({}, solver_schemas,
                                                g_last_retained_first_wave_repair_rules,
                                                g_last_retained_second_wave_repair_rules,
                                                &g_last_single_schema_sampled_n10_stats,
                                                &g_last_single_schema_sampled_n10_failure,
                                                &why)) {
            throw runtime_error("ensure_single_schema: sampled n10 failed\n" + why);
        }
    }

    int support_bound = 0;
    for (const auto& r : retained_all_repair_rules_()) support_bound = max(support_bound, repair_principle_support_size_(r));
    for (const auto& r : retained_third_wave_repair_rules_()) support_bound = max(support_bound, repair_principle_support_size_(r));
    if (g_last_bounded_local_horn_rule_universe.empty()) {
        string local_why;
        g_last_bounded_local_horn_rule_universe = enumerate_relevant_locally_exact_sound_rules_up_to_support_(support_bound, kBoundedLocalRelevantRuleLimit, &local_why);
        g_last_bounded_local_horn_envelope_stats.support_bound = support_bound;
        g_last_bounded_local_horn_envelope_stats.locally_exact_sound_rules = g_last_bounded_local_horn_rule_universe.size();
        size_t considered = retained_all_repair_rules_().size() + retained_third_wave_repair_rules_().size();
        considered += (kBoundedLocalRelevantRuleLimit ? min(kBoundedLocalRelevantRuleLimit, g_last_repaired_theorem_mismatch_family_summaries.size()) : g_last_repaired_theorem_mismatch_family_summaries.size());
        g_last_bounded_local_horn_envelope_stats.candidate_rules_considered = considered;
        g_last_bounded_local_horn_envelope_stats.why = local_why;
    }
    if (g_last_bounded_local_envelope_exact_n5_stats.canonical_instances == 0) {
        if (!scan_bounded_local_horn_envelope_exhaustive_n5_({}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                             &g_last_bounded_local_envelope_exact_n5_stats,
                                                             &g_last_bounded_local_envelope_exact_n5_failure,
                                                             &why)) {
            throw runtime_error("ensure_single_schema: envelope exact n5 failed\n" + why);
        }
        g_last_bounded_local_horn_envelope_stats.exact_n5_full_matches = g_last_bounded_local_envelope_exact_n5_stats.full_match_instances;
        g_last_bounded_local_horn_envelope_stats.exact_n5_mismatches = g_last_bounded_local_envelope_exact_n5_stats.mismatch_instances;
    }
    if (g_last_bounded_local_envelope_bounded_n6_c3_stats.canonical_instances == 0) {
        if (!scan_bounded_local_horn_envelope_bounded_exact_n6_(kSingleSchemaBoundedExactN6Constraint3,
                                                                 {}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                                 &g_last_bounded_local_envelope_bounded_n6_c3_stats,
                                                                 &g_last_bounded_local_envelope_bounded_n6_c3_failure,
                                                                 &why)) {
            throw runtime_error("ensure_single_schema: envelope bounded n6 c3 failed\n" + why);
        }
    }
    if (kSingleSchemaAttemptBoundedExactN6Constraint4 && g_last_bounded_local_envelope_bounded_n6_c4_stats.canonical_instances == 0) {
        if (!scan_bounded_local_horn_envelope_bounded_exact_n6_(kSingleSchemaBoundedExactN6Constraint4,
                                                                 {}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                                 &g_last_bounded_local_envelope_bounded_n6_c4_stats,
                                                                 &g_last_bounded_local_envelope_bounded_n6_c4_failure,
                                                                 &why)) {
            throw runtime_error("ensure_single_schema: envelope bounded n6 c4 failed\n" + why);
        }
    }
    if (kSingleSchemaRandomizedN9NumTrees > 0 && kSingleSchemaRandomizedN9SubsetsPerTree > 0 && g_last_bounded_local_envelope_sampled_n9_stats.canonical_instances == 0) {
        string pool_why;
        auto instances = build_shared_sampled_instance_pool_(9, single_schema_randomized_n9_seeds_(),
                                                             kSingleSchemaRandomizedN9NumTrees, kSingleSchemaRandomizedN9SubsetsPerTree,
                                                             &pool_why);
        if (!scan_bounded_local_horn_envelope_on_instances_(instances,
                                                             {}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                             "envelope_sampled_n9",
                                                             &g_last_bounded_local_envelope_sampled_n9_stats,
                                                             &g_last_bounded_local_envelope_sampled_n9_failure,
                                                             &why)) {
            throw runtime_error("ensure_single_schema: envelope sampled n9 failed\n" + why);
        }
    }
    if (kSingleSchemaAttemptRandomizedN10 && g_last_bounded_local_envelope_sampled_n10_stats.canonical_instances == 0 && kSingleSchemaRandomizedN10NumTrees > 0 && kSingleSchemaRandomizedN10SubsetsPerTree > 0) {
        string pool_why;
        auto instances = build_shared_sampled_instance_pool_(10, single_schema_randomized_n10_seeds_(),
                                                             kSingleSchemaRandomizedN10NumTrees, kSingleSchemaRandomizedN10SubsetsPerTree,
                                                             &pool_why);
        if (!scan_bounded_local_horn_envelope_on_instances_(instances,
                                                             {}, solver_schemas, g_last_bounded_local_horn_rule_universe,
                                                             "envelope_sampled_n10",
                                                             &g_last_bounded_local_envelope_sampled_n10_stats,
                                                             &g_last_bounded_local_envelope_sampled_n10_failure,
                                                             &why)) {
            throw runtime_error("ensure_single_schema: envelope sampled n10 failed\n" + why);
        }
    }

    #ifdef LOCAL_TEST
    cerr << "stage: single schema vs local envelope\n";
#endif
    g_last_single_schema_theorem_stats.exact_n5_equal_envelope = compare_single_schema_vs_local_envelope_n5_(&why);
    if (!g_last_single_schema_theorem_stats.exact_n5_equal_envelope && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    g_last_single_schema_theorem_stats.bounded_n6_c3_equal_envelope = compare_single_schema_vs_local_envelope_bounded_n6_(kSingleSchemaBoundedExactN6Constraint3,
                                                                                                                             g_last_single_schema_bounded_n6_c3_stats,
                                                                                                                             g_last_bounded_local_envelope_bounded_n6_c3_stats,
                                                                                                                             &why);
    if (!g_last_single_schema_theorem_stats.bounded_n6_c3_equal_envelope && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    if (kSingleSchemaAttemptBoundedExactN6Constraint4) {
        g_last_single_schema_theorem_stats.bounded_n6_c4_equal_envelope = compare_single_schema_vs_local_envelope_bounded_n6_(kSingleSchemaBoundedExactN6Constraint4,
                                                                                                                             g_last_single_schema_bounded_n6_c4_stats,
                                                                                                                             g_last_bounded_local_envelope_bounded_n6_c4_stats,
                                                                                                                             &why);
        if (!g_last_single_schema_theorem_stats.bounded_n6_c4_equal_envelope && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    } else {
        g_last_single_schema_theorem_stats.bounded_n6_c4_equal_envelope = true;
    }
    if (kSingleSchemaRandomizedN9NumTrees > 0 && kSingleSchemaRandomizedN9SubsetsPerTree > 0) {
        g_last_single_schema_theorem_stats.sampled_n9_equal_envelope = compare_single_schema_vs_local_envelope_randomized_(9,
                                                                                                                         kSchemaRandomizedSeed,
                                                                                                                         kSingleSchemaRandomizedN9NumTrees,
                                                                                                                         kSingleSchemaRandomizedN9SubsetsPerTree,
                                                                                                                         g_last_single_schema_sampled_n9_stats,
                                                                                                                         g_last_bounded_local_envelope_sampled_n9_stats,
                                                                                                                         &why);
        if (!g_last_single_schema_theorem_stats.sampled_n9_equal_envelope && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    } else {
        g_last_single_schema_theorem_stats.sampled_n9_equal_envelope = false;
    }
    if (kSingleSchemaAttemptRandomizedN10) {
        g_last_single_schema_theorem_stats.sampled_n10_equal_envelope = compare_single_schema_vs_local_envelope_randomized_(10,
                                                                                                                          kSchemaRandomizedSeed,
                                                                                                                          kSingleSchemaRandomizedN10NumTrees,
                                                                                                                          kSingleSchemaRandomizedN10SubsetsPerTree,
                                                                                                                          g_last_single_schema_sampled_n10_stats,
                                                                                                                          g_last_bounded_local_envelope_sampled_n10_stats,
                                                                                                                          &why);
        if (!g_last_single_schema_theorem_stats.sampled_n10_equal_envelope && g_last_single_schema_theorem_stats.why.empty()) g_last_single_schema_theorem_stats.why = why;
    } else {
        g_last_single_schema_theorem_stats.sampled_n10_equal_envelope = false;
    }

    g_last_locality_obstruction_certificates = build_locality_obstruction_certificates_from_failures_(
        g_last_bounded_local_envelope_exact_n5_failure,
        g_last_bounded_local_envelope_bounded_exact_n6_failure,
        support_bound);
    g_last_single_schema_obstruction_certificates = search_single_schema_obstructions_();
    g_last_local_envelope_obstruction_certificates = search_local_envelope_obstructions_();

    g_last_structured_local_sampled_n9_stats = g_last_single_schema_sampled_n9_stats;
    g_last_structured_local_sampled_n9_failure = g_last_single_schema_sampled_n9_failure;

    g_last_single_schema_sampled_support_n9 = build_single_schema_sampled_support_stats_(9,
                                                                                         single_schema_randomized_n9_seeds_(),
                                                                                         kSingleSchemaRandomizedN9NumTrees,
                                                                                         kSingleSchemaRandomizedN9SubsetsPerTree,
                                                                                         g_last_single_schema_sampled_n9_stats,
                                                                                         g_last_single_schema_theorem_stats.sampled_n9_equal_envelope,
                                                                                         g_last_single_schema_obstruction_certificates.size(),
                                                                                         g_last_single_schema_sampled_n9_failure.why);
    if (kSingleSchemaAttemptRandomizedN10) {
        g_last_single_schema_sampled_support_n10 = build_single_schema_sampled_support_stats_(10,
                                                                                              single_schema_randomized_n10_seeds_(),
                                                                                              kSingleSchemaRandomizedN10NumTrees,
                                                                                              kSingleSchemaRandomizedN10SubsetsPerTree,
                                                                                              g_last_single_schema_sampled_n10_stats,
                                                                                              g_last_single_schema_theorem_stats.sampled_n10_equal_envelope,
                                                                                              g_last_single_schema_obstruction_certificates.size(),
                                                                                              g_last_single_schema_sampled_n10_failure.why);
    } else {
        g_last_single_schema_sampled_support_n10 = {};
    }

    g_last_structured_local_vs_nonlocal_decision = classify_structured_local_vs_nonlocal_(g_last_structured_local_theorem_stats,
                                                                                          g_last_bounded_local_horn_envelope_stats,
                                                                                          g_last_locality_obstruction_certificates,
                                                                                          &why);
    g_last_structured_local_vs_nonlocal_ledger = build_local_vs_nonlocal_decision_ledger_(g_last_structured_local_theorem_stats,
                                                                                           g_last_structured_local_exact_n5_stats,
                                                                                           g_last_structured_local_bounded_exact_n6_stats,
                                                                                           g_last_bounded_local_horn_envelope_stats,
                                                                                           g_last_bounded_local_envelope_exact_n5_stats,
                                                                                           g_last_bounded_local_envelope_bounded_exact_n6_stats,
                                                                                           g_last_locality_obstruction_certificates,
                                                                                           g_last_structured_local_vs_nonlocal_decision);

    #ifdef LOCAL_TEST
    cerr << "stage: single schema final classification\n";
#endif
    g_last_single_schema_theorem_stats.status = classify_single_schema_theorem_status_(g_last_single_schema_theorem_stats,
                                                                                       g_last_single_schema_exact_n5_stats,
                                                                                       g_last_single_schema_bounded_n6_c3_stats,
                                                                                       g_last_single_schema_bounded_n6_c4_stats,
                                                                                       g_last_single_schema_sampled_n9_stats,
                                                                                       g_last_single_schema_sampled_n10_stats);
    g_last_single_schema_theorem_ledger = build_single_schema_theorem_ledger_(g_last_single_schema_theorem_stats,
                                                                              g_last_single_schema_exact_n5_stats,
                                                                              g_last_single_schema_bounded_n6_c3_stats,
                                                                              g_last_single_schema_bounded_n6_c4_stats,
                                                                              g_last_single_schema_sampled_n9_stats,
                                                                              g_last_single_schema_sampled_n10_stats,
                                                                              g_last_bounded_local_envelope_exact_n5_stats,
                                                                              g_last_bounded_local_envelope_bounded_n6_c3_stats,
                                                                              g_last_bounded_local_envelope_bounded_n6_c4_stats,
                                                                              g_last_bounded_local_envelope_sampled_n9_stats,
                                                                              g_last_bounded_local_envelope_sampled_n10_stats,
                                                                              g_last_single_schema_obstruction_certificates,
                                                                              g_last_local_envelope_obstruction_certificates);
}


static void ensure_single_schema_proof_ready_() {
    if (kSingleSchemaFocusedSampledOnly) {
        prime_single_schema_verified_baselines_();
        ensure_single_schema_theorem_ready_();
        prime_single_schema_proof_verified_baselines_();
    } else {
        ensure_single_schema_theorem_ready_();
    }
    string why;
    auto reduced_rules = reduced_local_envelope_rule_universe_();
    (void)reduced_rules;
    if (g_last_single_schema_subsumption_exact_n5_stats.instances_checked == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: single schema proof n5\n";
#endif
        SparseLcaInstance failure;
        if (!scan_single_schema_subsumes_local_envelope_exhaustive_n5_({}, g_last_single_structured_local_schema,
                                                                       &g_last_single_schema_subsumption_exact_n5_stats,
                                                                       &failure,
                                                                       &why)) {
            g_last_envelope_only_counterexample = failure;
            g_last_envelope_only_counterexample_fingerprint = failure.n > 0 ? canonical_envelope_only_counterexample_fingerprint_(failure) : string();
        }
    }
    if (g_last_single_schema_subsumption_bounded_n6_c4_stats.instances_checked == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: single schema proof n6 c4\n";
#endif
        SparseLcaInstance failure;
        if (!scan_single_schema_subsumes_local_envelope_bounded_exact_n6_(kSingleSchemaBoundedExactN6Constraint4, {}, g_last_single_structured_local_schema,
                                                                          &g_last_single_schema_subsumption_bounded_n6_c4_stats,
                                                                          &failure,
                                                                          &why)) {
            if (g_last_envelope_only_counterexample.n == 0) {
                g_last_envelope_only_counterexample = failure;
                g_last_envelope_only_counterexample_fingerprint = failure.n > 0 ? canonical_envelope_only_counterexample_fingerprint_(failure) : string();
            }
        }
    }
    if (kSingleSchemaAttemptBoundedExactN6Constraint5 && g_last_single_schema_subsumption_bounded_n6_c5_stats.instances_checked == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: single schema proof n6 c5\n";
#endif
        SparseLcaInstance failure;
        if (!scan_single_schema_subsumes_local_envelope_bounded_exact_n6_constraint5_({}, g_last_single_structured_local_schema,
                                                                                       &g_last_single_schema_subsumption_bounded_n6_c5_stats,
                                                                                       &failure,
                                                                                       &why)) {
            if (g_last_envelope_only_counterexample.n == 0) {
                g_last_envelope_only_counterexample = failure;
                g_last_envelope_only_counterexample_fingerprint = failure.n > 0 ? canonical_envelope_only_counterexample_fingerprint_(failure) : string();
            }
        }
    }
    if (kSingleSchemaAttemptBoundedExactN7Constraint3 && g_last_single_schema_subsumption_bounded_n7_c3_stats.instances_checked == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: single schema proof n7 c3\n";
#endif
        SparseLcaInstance failure;
        if (!scan_single_schema_subsumes_local_envelope_bounded_exact_n7_constraint3_({}, g_last_single_structured_local_schema,
                                                                                       &g_last_single_schema_subsumption_bounded_n7_c3_stats,
                                                                                       &failure,
                                                                                       &why)) {
            if (g_last_envelope_only_counterexample.n == 0) {
                g_last_envelope_only_counterexample = failure;
                g_last_envelope_only_counterexample_fingerprint = failure.n > 0 ? canonical_envelope_only_counterexample_fingerprint_(failure) : string();
            }
        }
    }
#ifdef LOCAL_TEST
    cerr << "stage: envelope rule elimination\n";
#endif
    if (g_last_envelope_rule_elimination_combined_certs.empty()) {
        if (g_last_envelope_rule_elimination_n5_certs.empty()) {
            validate_envelope_rule_elimination_on_tested_domains_(reduced_local_envelope_rule_universe_(), {}, g_last_single_structured_local_schema,
                                                                  5, -1, &g_last_envelope_rule_elimination_n5_certs, &why);
        }
        if (g_last_envelope_rule_elimination_n6_c4_certs.empty()) {
            validate_envelope_rule_elimination_on_tested_domains_(reduced_local_envelope_rule_universe_(), {}, g_last_single_structured_local_schema,
                                                                  6, kSingleSchemaBoundedExactN6Constraint4,
                                                                  &g_last_envelope_rule_elimination_n6_c4_certs, &why);
        }
        g_last_envelope_rule_elimination_combined_certs = merge_envelope_rule_elimination_certificates_(g_last_envelope_rule_elimination_n5_certs,
                                                                                                          g_last_envelope_rule_elimination_n6_c4_certs);
    }
    if (kSingleSchemaAttemptEnvelopeEliminationN6Constraint5 && g_last_envelope_rule_elimination_n6_c5_stats.rules_in_universe == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: envelope elimination n6 c5 regression\n";
#endif
        validate_envelope_rule_elimination_on_exact_constraint_size_(reduced_local_envelope_rule_universe_(), {}, g_last_single_structured_local_schema,
                                                                     6, kSingleSchemaBoundedExactN6Constraint5,
                                                                     &g_last_envelope_rule_elimination_n6_c5_certs, &why);
        g_last_envelope_rule_elimination_combined_certs = merge_envelope_rule_elimination_certificates_(g_last_envelope_rule_elimination_combined_certs,
                                                                                                          g_last_envelope_rule_elimination_n6_c5_certs);
        g_last_envelope_rule_elimination_n6_c5_stats = build_envelope_rule_elimination_stats_(6, kSingleSchemaBoundedExactN6Constraint5, g_last_envelope_rule_elimination_n6_c5_certs, true, why.empty() ? string("verified on exact constraint-size 5 domain") : why);
    }
    if (kSingleSchemaAttemptEnvelopeEliminationN7Constraint3 && g_last_envelope_rule_elimination_n7_c3_stats.rules_in_universe == 0) {
#ifdef LOCAL_TEST
        cerr << "stage: envelope elimination n7 c3\n";
#endif
        scan_envelope_rule_elimination_bounded_exact_n7_constraint3_(reduced_local_envelope_rule_universe_(), {}, g_last_single_structured_local_schema,
                                                                     &g_last_envelope_rule_elimination_n7_c3_stats,
                                                                     &g_last_envelope_rule_elimination_n7_c3_certs,
                                                                     &why);
        g_last_envelope_rule_elimination_combined_certs = merge_envelope_rule_elimination_certificates_(g_last_envelope_rule_elimination_combined_certs,
                                                                                                          g_last_envelope_rule_elimination_n7_c3_certs);
    }
    if (!kSingleSchemaAttemptEnvelopeEliminationN7Constraint3 && g_last_envelope_rule_elimination_n7_c3_stats.rules_in_universe == 0) {
        g_last_envelope_rule_elimination_n7_c3_stats.n = 7;
        g_last_envelope_rule_elimination_n7_c3_stats.max_constraints = kSingleSchemaBoundedExactN7Constraint3;
        g_last_envelope_rule_elimination_n7_c3_stats.rules_in_universe = reduced_local_envelope_rule_universe_().size();
        g_last_envelope_rule_elimination_n7_c3_stats.completed = false;
        g_last_envelope_rule_elimination_n7_c3_stats.why = "not attempted";
    }
    g_last_single_schema_proof_status = classify_single_schema_proof_kernel_status_(g_last_single_schema_subsumption_exact_n5_stats,
                                                                                     g_last_single_schema_subsumption_bounded_n6_c4_stats,
                                                                                     kSingleSchemaAttemptBoundedExactN6Constraint5 ? &g_last_single_schema_subsumption_bounded_n6_c5_stats : nullptr,
                                                                                     kSingleSchemaAttemptBoundedExactN7Constraint3 ? &g_last_single_schema_subsumption_bounded_n7_c3_stats : nullptr,
                                                                                     kSingleSchemaAttemptEnvelopeEliminationN6Constraint5 ? &g_last_envelope_rule_elimination_n6_c5_stats : nullptr,
                                                                                     kSingleSchemaAttemptEnvelopeEliminationN7Constraint3 ? &g_last_envelope_rule_elimination_n7_c3_stats : nullptr,
                                                                                     g_last_envelope_only_counterexample);
    g_last_single_schema_proof_ledger = build_single_schema_proof_ledger_(g_last_single_schema_subsumption_exact_n5_stats,
                                                                          g_last_single_schema_subsumption_bounded_n6_c4_stats,
                                                                          kSingleSchemaAttemptBoundedExactN6Constraint5 ? &g_last_single_schema_subsumption_bounded_n6_c5_stats : nullptr,
                                                                          kSingleSchemaAttemptBoundedExactN7Constraint3 ? &g_last_single_schema_subsumption_bounded_n7_c3_stats : nullptr,
                                                                          g_last_envelope_rule_elimination_combined_certs,
                                                                          g_last_envelope_only_counterexample);
}

