static void test_solver_mismatch_family_classifier_smoke() {
    ensure_solver_theorem_baseline_ready_();
    auto schemas = current_solver_schema_rules_();
    string why;
    g_last_solver_mismatch_witnesses = collect_solver_mismatch_witnesses_(5, {}, schemas, 0, &why);
    if (!why.empty()) throw runtime_error("collect solver mismatch witnesses failed\n" + why);
    g_last_solver_mismatch_family_summaries = classify_solver_mismatch_families_(g_last_solver_mismatch_witnesses);
    size_t total_support = 0;
    for (const auto& fam : g_last_solver_mismatch_family_summaries) total_support += fam.witness_count;
    assert(total_support == g_last_solver_mismatch_witnesses.size());
    assert(!g_last_solver_mismatch_witnesses.empty());
    assert(!g_last_solver_mismatch_family_summaries.empty());
}

